/// The accessors of one status a user endpoint slot keeps in a
/// [`crate::status::StatusLedger`] (DDS 1.4 §2.2.4.1): the record as it
/// stands, the record with its change fields reset (`get_*_status`), the
/// record with the moves for a listener, and the acknowledgement of a
/// record a listener was handed. The second form makes the last alone.
macro_rules! status_ledger_access {
    ($slot:ident, $field:ident, $record:ty, $get:ident, $take:ident, $observe:ident, $ack:ident,
     $name:literal) => {
        #[doc = concat!("`", $name, "` of the local user endpoint `eid` as it stands, ")]
        #[doc = "change fields included (DDS 1.4 §2.2.4.1). `None` for an unknown entity id."]
        #[must_use]
        pub fn $get(&self, eid: EntityId) -> Option<$record> {
            self.$slot(eid)
                .and_then(|arc| arc.lock().ok().map(|s| s.$field.record()))
        }

        #[doc = concat!("`get_", $name, "_status` of the local user endpoint `eid`: ")]
        #[doc = "the status, whose change fields this read resets (DDS 1.4 §2.2.4.1)."]
        #[must_use]
        pub fn $take(&self, eid: EntityId) -> Option<$record> {
            self.$slot(eid)
                .and_then(|arc| arc.lock().ok().map(|mut s| s.$field.take()))
        }

        #[doc = concat!("`", $name, "` of the local user endpoint `eid` with its ")]
        #[doc = "StatusChangedFlag, read together: whether it changed since it was last "]
        #[doc = "read or handed to a listener (DDS 1.4 §2.2.4.1)."]
        #[must_use]
        pub fn $observe(&self, eid: EntityId) -> Option<(bool, $record, u64)> {
            self.$slot(eid)
                .and_then(|arc| arc.lock().ok().map(|s| s.$field.observe()))
        }

        status_ledger_access! { $slot, $field, $record, $ack, $name }
    };
    ($slot:ident, $field:ident, $record:ty, $ack:ident, $name:literal) => {
        #[doc = concat!("`reported` (", $name, ") was handed to a listener of the local ")]
        #[doc = "user endpoint `eid`: its changes are no longer pending (DDS 1.4 §2.2.4.1)."]
        pub fn $ack(&self, eid: EntityId, reported: &$record, reads: u64) {
            if let Some(arc) = self.$slot(eid) {
                if let Ok(mut s) = arc.lock() {
                    s.$field.acknowledge(reported, reads);
                }
            }
        }
    };
}

/// What changed between the matched endpoints an endpoint was last seen
/// with and those it has now (PUBLICATION_MATCHED, SUBSCRIPTION_MATCHED,
/// DDS 1.4 §2.2.4.1).
struct MatchChange {
    /// How many joined.
    joined: i32,
    /// How many left.
    left: i32,
    /// How many there are now.
    current: i32,
    /// The last that joined, or else the last that left.
    last: crate::instance_handle::InstanceHandle,
}

impl MatchChange {
    /// The change from `seen` to `now`, `None` without one; `seen` holds
    /// `now` afterwards.
    fn between(
        seen: &mut Vec<crate::instance_handle::InstanceHandle>,
        now: &[crate::instance_handle::InstanceHandle],
    ) -> Option<Self> {
        let joined: Vec<_> = now.iter().filter(|h| !seen.contains(h)).copied().collect();
        let left: Vec<_> = seen.iter().filter(|h| !now.contains(h)).copied().collect();
        let last = joined.last().or(left.last()).copied()?;
        *seen = now.to_vec();
        Some(Self {
            joined: i32::try_from(joined.len()).unwrap_or(i32::MAX),
            left: i32::try_from(left.len()).unwrap_or(i32::MAX),
            current: i32::try_from(now.len()).unwrap_or(i32::MAX),
            last,
        })
    }
}

/// Default tick period of the event loop.
///
/// This is the worst-case quantization for sub-tick-driven tasks
/// (SEDP heartbeats, reliable-writer resends, ACKNACK emit). Short enough
/// for sub-ms round-trip latency (5 ms = 100 Hz tick rate), long enough
/// to keep idle CPU cost small.
///
/// Phase-3 migration: this tick loop is replaced by a deadline heap +
/// condvar worker (`scheduler.rs`) — then this value is only the
/// idle-floor sleep (no quantization tax for events).
pub const DEFAULT_TICK_PERIOD: Duration = Duration::from_millis(5);

/// Default SPDP announce period: 30 s, "SPDPbuiltinParticipantWriter.
/// resendPeriod = {30, 0}" (DDSI-RTPS 2.5 §9.6.2.4, §8.5.3.1, §8.5.3.3).
pub const DEFAULT_SPDP_PERIOD: Duration = Duration::from_secs(30);

/// How long a writer/reader pair whose peer type is not in the registry
/// waits for the TypeLookup round trip before XTypes 1.3 §7.6.3.4.2 is
/// decided on what is at hand.
///
/// Until the object arrives the pair is not wired: a match made before
/// the verdict delivers samples the verdict may forbid. Measured on the
/// OMG `dds-xtypes` suite before this existed: a `@final` writer and an
/// `@appendable` reader of a different type were wired on the miss path
/// and the reader took 19 samples in 20 seconds, with no
/// INCONSISTENT_TOPIC on either side. A peer that serves TypeLookup
/// answers within a round trip; one that announces a hash and serves
/// nothing never answers, and for that peer the clause's own fallback
/// applies once the grace has passed: Step 2, the type names, "as in
/// \[DDS\] prior to this specification".
pub const TYPE_RESOLUTION_GRACE: Duration = Duration::from_secs(3);

/// Largest RTPS message a writer builds before it must put it on the wire.
///
/// DDSI-RTPS 2.5 §8.3.3 puts no bound on the number of submessages in one
/// message; the bound is the transport's. A UDP datagram larger than the link
/// MTU is fragmented by IP and reassembled by the receiving kernel, so the
/// cost of going past 1472 bytes is that one lost IP fragment loses the whole
/// message — every sample in it — while the gain is one `sendto` for as many
/// samples as fit.
///
/// 14 720 is what CycloneDDS uses (`Internal/MaxMessageSize`), and it is the
/// number this tree was measured against: `ddsperf pub size 1024` puts 13.0
/// samples in each `sendmsg` (148 798 `sendmsg` for 1 933 000 samples), which
/// is exactly 13 × 1092 = 14 196 bytes under this cap. The same cap is used
/// here so a ZeroDDS writer and a Cyclone writer produce the same number of
/// datagrams for the same stream, and the comparison is about the send path
/// rather than about two different packet sizes.
pub const DEFAULT_MAX_MESSAGE_SIZE: usize = 14_720;

/// Capacity of the KEEP_ALL cache a reliable reader keeps per writer proxy
/// while an earlier SequenceNumber is still missing (RTPS 2.5 §8.4.12.1
/// in-order delivery).
///
/// This is the number the reader can buffer before
/// `ReliableReader::handle_data` has to roll the SN back to MISSING and ask
/// for it again. It is a runtime setting with an env override
/// (`reader.max_samples_per_proxy`), so a measurement can move it without a
/// rebuild. A RELIABLE KEEP_ALL DataReader whose RESOURCE_LIMITS bound it
/// lowers it to its own limit (`ReaderRoom`): what it cannot take is then
/// not acknowledged.
///
/// **65 536 and not 256.** Measured on a quiet host (load 3.75, 23.5 % busy,
/// RELIABLE/KEEP_ALL, 1 kB, own domain): 256 loses 1.78–6.69 % of a
/// 114.7 kS/s stream and loses it bimodally; 65 536 loses **0.00 %** in the
/// same cells. At 128 kS/s, 256 samples is 2.0 ms of buffer — less than one
/// scheduling hiccup — and a reliable reader that drops under sustained load
/// is worth more memory than it saves.
///
/// What it costs, stated rather than glossed: the cap is per **writer proxy**,
/// so a reader matched to four writers can hold four of these. At 1 kB a full
/// one is 64 MB. It is a cap and not a reservation — [`HistoryCache`](zerodds_rtps::history_cache::HistoryCache) holds a
/// `BTreeMap` that grows with what arrives — so the cost appears only while an
/// earlier SequenceNumber is genuinely missing and samples pile up behind it.
/// A stream with no gap holds nothing.
///
/// Lower it per participant with `reader.max_samples_per_proxy` where
/// memory is the tighter constraint.
pub const DEFAULT_MAX_SAMPLES_PER_PROXY: usize = 65_536;

/// Fallback cap for `UserReaderSlot::instance_key_holders` — the
/// per-instance canonical key holder cache a keyed reader keeps so a later
/// hash-only lifecycle marker can still be filled with a key holder — when
/// RESOURCE_LIMITS.max_instances is `LENGTH_UNLIMITED` (the policy
/// default). A cache has to have some bound and the QoS declining to name
/// one is not a licence to grow without one, the same reasoning
/// [`DEFAULT_MAX_SAMPLES_PER_PROXY`] documents for the receive cache.
pub const DEFAULT_MAX_INSTANCE_KEY_HOLDERS: usize = 65_536;

/// Datagrams the user receive loop asks for per
/// [`zerodda_transport_recv_batch`](zerodds_transport::Transport::recv_batch)
/// call.
///
/// 32 is `recv_batch::DEFAULT_BATCH_SIZE` in `zerodds-transport-udp`, which
/// caps the `recvmmsg` header arrays; asking for more than the transport can
/// deliver in one syscall buys nothing.
pub const DEFAULT_RECV_BATCH_SIZE: usize = 32;

/// Default number of SPDP announces sent at the fast initial-burst cadence
/// (C3 WiFi-robust discovery) before falling back to [`DEFAULT_SPDP_PERIOD`].
/// Analogous to Fast DDS `initial_announcements`.
pub const DEFAULT_INITIAL_ANNOUNCE_COUNT: u32 = 10;

/// Default period between initial-announcement-burst SPDP sends.
pub const DEFAULT_INITIAL_ANNOUNCE_PERIOD: Duration = Duration::from_millis(200);

/// Default of [`RuntimeConfig::writer_linger`]: 1 s, the default of Cyclone
/// DDS's `Internal/WriterLingerDuration`. Ten periodic HEARTBEATs of a
/// writer ([`zerodds_rtps::reliable_writer::DEFAULT_HEARTBEAT_PERIOD`]).
pub const DEFAULT_WRITER_LINGER: Duration = Duration::from_secs(1);

/// Deadline/lease compat check (DDS 1.4 §2.2.3.7, §2.2.3.11): "offered
/// deadline period <= requested deadline period". `None` is INFINITE, the
/// longest: a reader that requests INFINITE accepts every writer, a writer
/// that offers INFINITE satisfies only a reader that requests INFINITE. A
/// period of 0 is the shortest. It was the sentinel for INFINITE as well,
/// so a request of 0 accepted every offer.
fn deadline_compat(offered: Option<u64>, requested: Option<u64>) -> bool {
    match (offered, requested) {
        (_, None) => true,
        (None, Some(_)) => false,
        (Some(o), Some(r)) => o <= r,
    }
}

/// A duration of an RxO policy for [`deadline_compat`]: `None` for
/// INFINITE, else nanoseconds, 0 included.
fn rxo_nanos(d: zerodds_qos::Duration) -> Option<u64> {
    (!d.is_infinite()).then(|| u64::try_from(d.to_nanos()).unwrap_or(u64::MAX))
}

/// The request-offered (RxO) policies of one endpoint, DDS 1.4 §2.2.3.
#[derive(Clone, Copy)]
struct RxoView {
    durability: zerodds_qos::DurabilityKind,
    reliability: zerodds_qos::ReliabilityKind,
    deadline: Option<u64>,
    liveliness_kind: zerodds_qos::LivelinessKind,
    liveliness_lease: Option<u64>,
    latency_budget: zerodds_qos::LatencyBudgetQosPolicy,
    destination_order: zerodds_qos::DestinationOrderQosPolicy,
    ownership: zerodds_qos::OwnershipKind,
    presentation: zerodds_qos::PresentationQosPolicy,
}

impl RxoView {
    fn reliability_of(reliable: bool) -> zerodds_qos::ReliabilityKind {
        if reliable {
            zerodds_qos::ReliabilityKind::Reliable
        } else {
            zerodds_qos::ReliabilityKind::BestEffort
        }
    }

    fn of_writer(slot: &UserWriterSlot) -> Self {
        Self {
            durability: slot.durability,
            reliability: Self::reliability_of(slot.reliable),
            deadline: rxo_nanos(slot.deadline_period),
            liveliness_kind: slot.liveliness_kind,
            liveliness_lease: rxo_nanos(slot.liveliness_lease),
            latency_budget: slot.latency_budget,
            destination_order: slot.destination_order,
            ownership: slot.ownership,
            presentation: slot.presentation,
        }
    }

    fn of_reader(slot: &UserReaderSlot) -> Self {
        Self {
            durability: slot.durability,
            reliability: Self::reliability_of(slot.reliable),
            deadline: rxo_nanos(slot.deadline_period),
            liveliness_kind: slot.liveliness_kind,
            liveliness_lease: rxo_nanos(slot.liveliness_lease),
            latency_budget: slot.latency_budget,
            destination_order: slot.destination_order,
            ownership: slot.ownership,
            presentation: slot.presentation,
        }
    }

    /// What the Topic QoS says as an endpoint of its fictitious persistence
    /// service (DDS 1.4 §2.2.3.4): the policies the Topic and the endpoints
    /// both carry. The Topic has no PRESENTATION; the other endpoint's is
    /// taken, so that it never differs.
    fn of_topic(
        topic: &crate::qos::TopicQos,
        presentation: zerodds_qos::PresentationQosPolicy,
    ) -> Self {
        Self {
            durability: topic.durability.kind,
            reliability: topic.reliability.kind,
            deadline: rxo_nanos(topic.deadline.period),
            liveliness_kind: topic.liveliness.kind,
            liveliness_lease: rxo_nanos(topic.liveliness.lease_duration),
            latency_budget: topic.latency_budget,
            destination_order: topic.destination_order,
            ownership: topic.ownership.kind,
            presentation,
        }
    }

    fn of_publication(p: &zerodds_rtps::publication_data::PublicationBuiltinTopicData) -> Self {
        Self {
            durability: p.durability,
            reliability: p.reliability.kind,
            deadline: rxo_nanos(p.deadline.period),
            liveliness_kind: p.liveliness.kind,
            liveliness_lease: rxo_nanos(p.liveliness.lease_duration),
            latency_budget: p.latency_budget,
            destination_order: p.destination_order,
            ownership: p.ownership,
            presentation: p.presentation,
        }
    }

    fn of_subscription(s: &zerodds_rtps::subscription_data::SubscriptionBuiltinTopicData) -> Self {
        Self {
            durability: s.durability,
            reliability: s.reliability.kind,
            deadline: rxo_nanos(s.deadline.period),
            liveliness_kind: s.liveliness.kind,
            liveliness_lease: rxo_nanos(s.liveliness.lease_duration),
            latency_budget: s.latency_budget,
            destination_order: s.destination_order,
            ownership: s.ownership,
            presentation: s.presentation,
        }
    }
}

/// The first RxO policy `offered` (a writer) does not satisfy for
/// `requested` (a reader), as a DDS 1.4 Tab. 2.13 QosPolicyId; `None` when
/// the pair is compatible. One rule for every match path: remote reader,
/// remote writer, and a writer and reader of the same runtime.
fn first_incompatible_policy(offered: &RxoView, requested: &RxoView) -> Option<u32> {
    use crate::psm_constants::qos_policy_id as qid;
    // Volatile < TransientLocal < Transient < Persistent; BestEffort <
    // Reliable; Automatic < ManualByParticipant < ManualByTopic.
    if (offered.durability as u8) < (requested.durability as u8) {
        return Some(qid::DURABILITY);
    }
    if offered.reliability < requested.reliability {
        return Some(qid::RELIABILITY);
    }
    if !deadline_compat(offered.deadline, requested.deadline) {
        return Some(qid::DEADLINE);
    }
    if (offered.liveliness_kind as u8) < (requested.liveliness_kind as u8)
        || !deadline_compat(offered.liveliness_lease, requested.liveliness_lease)
    {
        return Some(qid::LIVELINESS);
    }
    if !offered
        .latency_budget
        .is_compatible_with(requested.latency_budget)
    {
        return Some(qid::LATENCY_BUDGET);
    }
    if !offered
        .destination_order
        .is_compatible_with(requested.destination_order)
    {
        return Some(qid::DESTINATION_ORDER);
    }
    if offered.ownership != requested.ownership {
        return Some(qid::OWNERSHIP);
    }
    if !offered
        .presentation
        .is_compatible_with(requested.presentation)
    {
        return Some(qid::PRESENTATION);
    }
    None
}

/// Partition matching: both sides have at least one common partition OR
/// both are empty (default partition "").
/// Enforces a per-instance KeepLast depth over a TransientLocal retained-sample
/// buffer (DDS 1.4 §2.2.3.18). Keeps at most `depth` *Alive* entries per
/// instance key (oldest evicted first), preserving order; terminal lifecycle
/// markers (dispose/unregister) are never counted against the depth and are
/// always retained so a late joiner observes the final NOT_ALIVE state.
/// A BEST_EFFORT writer at a RESOURCE_LIMITS bound discards its oldest
/// samples (DDS 1.4 §2.2.3.18); the retained replay buffer drops the ones
/// the RTPS cache drops ([`UserWriterSlot::apply_cache_history`]).
fn enforce_retained_limits(
    retained: &mut alloc::collections::VecDeque<RetainedSample>,
    limits: &zerodds_qos::ResourceLimitsQosPolicy,
) {
    if let Some(cap) = resource_cap(limits.max_samples_per_instance) {
        enforce_retained_depth(retained, cap);
    }
    if let Some(cap) = resource_cap(limits.max_samples) {
        while retained.iter().filter(|s| s.lifecycle.is_none()).count() > cap {
            let Some(oldest) = retained.iter().position(|s| s.lifecycle.is_none()) else {
                break;
            };
            retained.remove(oldest);
        }
    }
}

fn enforce_retained_depth(
    retained: &mut alloc::collections::VecDeque<RetainedSample>,
    depth: usize,
) {
    use alloc::collections::BTreeMap;
    // Count alive samples per key.
    let mut alive_per_key: BTreeMap<[u8; 16], usize> = BTreeMap::new();
    for s in retained.iter() {
        if s.lifecycle.is_none() {
            *alive_per_key.entry(s.key_hash).or_insert(0) += 1;
        }
    }
    // Determine how many to drop per key.
    let mut to_drop: BTreeMap<[u8; 16], usize> = BTreeMap::new();
    for (k, count) in &alive_per_key {
        if *count > depth {
            to_drop.insert(*k, count - depth);
        }
    }
    if to_drop.is_empty() {
        return;
    }
    retained.retain(|s| {
        if s.lifecycle.is_some() {
            return true;
        }
        if let Some(rem) = to_drop.get_mut(&s.key_hash) {
            if *rem > 0 {
                *rem -= 1;
                return false; // evict this (oldest) alive sample for the key
            }
        }
        true
    });
}

/// PARTITION matching for writer/reader pairing (DDS 1.4 §2.2.3.13.6).
///
/// Delegates to the canonical [`zerodds_qos::partitions_compatible`] so the
/// runtime never disagrees with [`PartitionQosPolicy::is_compatible_with`]:
/// an empty list is the default partition `""` (`[]`, `[""]` and mixes all
/// match), and named partitions match via **symmetric fnmatch** glob
/// patterns (`*`, `?`, `[...]`), not exact string equality.
fn partitions_overlap(offered: &[String], requested: &[String]) -> bool {
    zerodds_qos::partitions_compatible(offered, requested)
}

/// Materializes the locator address that we announce in the SPDP beacon
/// from an UdpTransport bound to UNSPECIFIED.
///
/// Binding to `0.0.0.0` yields `local_addr() == 0.0.0.0:port`, which is
/// not routable for peers. Via a UDP connect probe to a non-routable
/// address we resolve the outbound interface address (no traffic —
/// `connect()` on a UDP socket only sets the routing information). Falls
/// back to `multicast_interface` (RuntimeConfig) if the probe fails, or
/// to the unchanged locator as a last resort.
#[cfg(feature = "std")]
fn announce_locator(uc: &(dyn Transport + Send + Sync), hint: Ipv4Addr) -> Locator {
    let raw = uc.local_locator();
    // Keep the port from the bound socket.
    let port = raw.port;
    // V6 resolution: with a `::` bind, announce `::1` (loopback) as a
    // sensible default reachability. Cross-host v6 is its own sprint
    // (needs a v6 interface probe analogous to the v4 path below).
    if raw.kind == LocatorKind::UdpV6 || raw.kind == LocatorKind::Tcpv6 {
        let all_zero = raw.address.iter().all(|b| *b == 0);
        if all_zero {
            let mut loopback_addr = [0u8; 16];
            loopback_addr[15] = 1;
            return match raw.kind {
                LocatorKind::Tcpv6 => Locator::tcp_v6(loopback_addr, port),
                _ => Locator::udp_v6(loopback_addr, port),
            };
        }
        return raw;
    }
    // V4 resolution: only meaningful for UDPv4/TCPv4 locators with an
    // UNSPECIFIED bind. For SHM, return raw — the locator kind has its
    // own pairing resolution (its own sprint).
    if raw.kind != LocatorKind::UdpV4 && raw.kind != LocatorKind::Tcpv4 {
        return raw;
    }
    // Extract the address — only the last 4 bytes are the IPv4.
    let ip = Ipv4Addr::new(
        raw.address[12],
        raw.address[13],
        raw.address[14],
        raw.address[15],
    );
    if !ip.is_unspecified() {
        return raw;
    }
    // Helper: construct a locator with the original kind (UdpV4 or
    // Tcpv4) and the now-resolved v4 address.
    let to_locator = |octets: [u8; 4]| -> Locator {
        match raw.kind {
            LocatorKind::Tcpv4 => Locator::tcp_v4(octets, port),
            _ => Locator::udp_v4(octets, port),
        }
    };
    // Interface pinning: an explicitly set interface
    // (`transport.interface` / `RuntimeConfig.multicast_interface`) takes
    // **precedence over the route probe**. On multi-homed hosts (VPN/
    // Docker/macOS bridge100) the probe might otherwise pick the wrong
    // source IP and announce an unreachable address → discovery fails.
    if !hint.is_unspecified() {
        return to_locator(hint.octets());
    }
    // Probe: temporary socket, "connect" to 192.0.2.1 (RFC 5737
    // TEST-NET-1, guaranteed non-routable). connect only sets the routing
    // table — no packet goes out.
    if let Ok(probe) =
        std::net::UdpSocket::bind(std::net::SocketAddrV4::new(Ipv4Addr::UNSPECIFIED, 0))
    {
        if probe
            .connect(std::net::SocketAddrV4::new(Ipv4Addr::new(192, 0, 2, 1), 7))
            .is_ok()
        {
            if let Ok(std::net::SocketAddr::V4(local)) = probe.local_addr() {
                let resolved = local.ip();
                if !resolved.is_unspecified() {
                    return to_locator(resolved.octets());
                }
            }
        }
    }
    // Fallback: loopback (the pin hint is already handled above). Not
    // ideal, but better than 0.0.0.0 as a locator (at least routable on
    // the same host).
    to_locator([127, 0, 0, 1])
}

/// Materializes the **full** set of unicast locators to announce for a
/// `0.0.0.0`-bound socket (#27).
///
/// On a multi-homed host the single [`announce_locator`] probe resolves only
/// the default-route source address, which can diverge from the interface a
/// given peer actually shares — the peer then learns one unreachable locator
/// and discovery half-completes (participant discovered, endpoints never
/// match). Instead, in automatic mode this announces **every** eligible
/// unicast interface address at the socket's bound port, so a peer on any
/// shared segment finds a reachable one and can fan out to all of them.
///
/// An explicit interface (`transport.interface` / `RuntimeConfig`) keeps its
/// deterministic single-interface behaviour. Non-UDPv4 locators, and the case
/// where interface enumeration yields nothing, fall back to the single
/// [`announce_locator`] result — the announced list is never empty.
#[cfg(feature = "std")]
fn announce_locators(uc: &(dyn Transport + Send + Sync), hint: Ipv4Addr) -> Vec<Locator> {
    let raw = uc.local_locator();
    let single = announce_locator(uc, hint);
    // Explicit pin, or a non-UDPv4 locator (V6/SHM/TCP), or an already-concrete
    // bound address → keep the single deterministic locator.
    let ip = Ipv4Addr::new(
        raw.address[12],
        raw.address[13],
        raw.address[14],
        raw.address[15],
    );
    if !hint.is_unspecified() || raw.kind != LocatorKind::UdpV4 || !ip.is_unspecified() {
        return alloc::vec![single];
    }
    // Automatic: one locator per eligible interface, deterministic order
    // (already sorted by ip in the enumerator), deduplicated by address.
    let port = raw.port;
    let mut locs: Vec<Locator> = Vec::new();
    for e in zerodds_transport_udp::eligible_ipv4_interfaces() {
        let loc = Locator::udp_v4(e.ipv4.octets(), port);
        if !locs.contains(&loc) {
            locs.push(loc);
        }
    }
    // Guarantee the probe-resolved address is present even if enumeration
    // missed it, and never announce an empty list.
    if locs.is_empty() {
        return alloc::vec![single];
    }
    if !locs.contains(&single) && zerodds_rtps::participant_data::locator_looks_routable(&single) {
        locs.push(single);
    }
    locs
}

/// Whether a datagram to `loc` stays on this host: a loopback address, or
/// one of `local` — this host's interface addresses, which a peer on the same
/// host announces as its own and the kernel then delivers over `lo`. Only a
/// UDP locator is either; anything else answers `false` and keeps the
/// Ethernet-safe fragment size.
fn locator_stays_on_host(loc: &Locator, local: &[[u8; 4]]) -> bool {
    match loc.kind {
        LocatorKind::UdpV4 => {
            let v4 = [
                loc.address[12],
                loc.address[13],
                loc.address[14],
                loc.address[15],
            ];
            v4[0] == 127 || local.contains(&v4)
        }
        LocatorKind::UdpV6 => loc.address == std::net::Ipv6Addr::LOCALHOST.octets(),
        _ => false,
    }
}

/// Converts a `core::time::Duration` (std) to a `zerodds_qos::Duration`
/// (spec 2^-32 fraction encoding). Saturates on overflow — `i32::MAX`
/// seconds suffices for over 60 years of lease.
fn qos_duration_from_std(d: Duration) -> QosDuration {
    let secs = i32::try_from(d.as_secs()).unwrap_or(i32::MAX);
    // The spec fraction is 2^-32 s, rounded to the nearest.
    QosDuration::from_sec_nanosec(secs, d.subsec_nanos())
}

/// Converts a `zerodds_qos::Duration` to nanoseconds (0 = INFINITE,
/// "no monitoring"). `seconds` is i32 — we clamp to non-negative.
fn qos_duration_to_nanos(d: zerodds_qos::Duration) -> u64 {
    if d.is_infinite() {
        return 0;
    }
    // Rounded to the nearest nanosecond (`Duration::to_nanos`); a
    // negative duration is 0.
    u64::try_from(d.to_nanos()).unwrap_or(u64::MAX)
}

/// A LIVELINESS policy's lease as a [`Duration`]; `None` is INFINITE.
fn lease_of(policy: &zerodds_qos::LivelinessQosPolicy) -> Option<Duration> {
    match qos_duration_to_nanos(policy.lease_duration) {
        0 => None,
        nanos => Some(Duration::from_nanos(nanos)),
    }
}

/// Human-readable name of a QoS policy id (Spec OMG DDS 1.4 §2.2.3,
/// PSM ids from [`crate::psm_constants::qos_policy_id`]). Used for the
/// C2 "loud instead of silent" log on an incompatible QoS match, so that
/// it states in plain text *which* policy prevented the match.
#[must_use]
fn qos_policy_id_name(pid: u32) -> &'static str {
    use crate::psm_constants::qos_policy_id as qid;
    match pid {
        qid::DURABILITY => "DURABILITY",
        qid::PRESENTATION => "PRESENTATION",
        qid::DEADLINE => "DEADLINE",
        qid::LATENCY_BUDGET => "LATENCY_BUDGET",
        qid::OWNERSHIP => "OWNERSHIP",
        qid::OWNERSHIP_STRENGTH => "OWNERSHIP_STRENGTH",
        qid::LIVELINESS => "LIVELINESS",
        qid::PARTITION => "PARTITION",
        qid::RELIABILITY => "RELIABILITY",
        qid::DESTINATION_ORDER => "DESTINATION_ORDER",
        qid::DURABILITY_SERVICE => "DURABILITY_SERVICE",
        qid::TYPE_CONSISTENCY_ENFORCEMENT => "TYPE_CONSISTENCY_ENFORCEMENT",
        qid::DATA_REPRESENTATION => "DATA_REPRESENTATION",
        _ => "OTHER",
    }
}

/// RTPS serialized-payload header for user samples: `CDR_LE`
/// (PLAIN_CDR / XCDR1, little-endian) + options=0. Spec OMG RTPS 2.5
/// §9.4.2.13.
///
/// Prepended to every user payload before it goes into the DATA
/// submessage — without this header, vendor readers (Cyclone / Fast-DDS)
/// refuse to deliver the sample.
///
/// **Why `0x01` (XCDR1) and not `0x07` (XCDR2):** this is the default for
/// the byte-oriented write path, which hands `zerodds_writer_write` bytes a
/// caller already encoded and has no type to ask an XCDR version of. A
/// typed writer with a `CompleteTypeObject` (`zerodds_writer_create_typed`)
/// declares its own representation via `zerodds_writer_set_wire_extensibility`
/// instead — see `crates/cpp/include/zerodds/dds.hpp`'s `TypedWriter<T>` —
/// and is not affected by this constant. Whichever version a caller's
/// bytes are actually in, the encapsulation header must declare that
/// honestly, or the peer reads the body at the wrong alignment (e.g.
/// OpenDDS' `dds_demarshal` fails); XCDR1/XCDR2 alignment itself is
/// `zerodds::wire::max_alignment` (`runtime/cpp/include/zerodds/wire.hpp`)
/// on the C++ side, one column among several the codec is implemented in.
pub const USER_PAYLOAD_ENCAP: [u8; 4] = [0x00, 0x01, 0x00, 0x00];

/// The encapsulation header of the XML Data Representation (DDS-XTypes 1.3
/// Table 60, DDSI-RTPS 2.5 Table 10.3: `XML`, `{0x00, 0x04}`).
pub const XML_ENCAP: [u8; 4] = [0x00, 0x04, 0x00, 0x00];

/// Whether `encap` is the header of an XML sample in either table:
/// `{0x00, 0x04}` (Table 60) or `{0x01, 0x00}` (DDS-XTypes 1.3 Table 39).
#[must_use]
fn is_xml_encap(encap: &[u8; 4]) -> bool {
    matches!(encap[..2], [0x00, 0x04] | [0x01, 0x00])
}

/// `encap`, a header of Table 60 (what [`user_payload_encap`] answers), as
/// the header the table `ids` names.
///
/// DDS-XTypes 1.3 gives the identifiers of version 2 and of XML twice, in
/// Table 39 (§7.4.3.4) and in Table 60 (§7.6.3.1.2). The runtime writes
/// Table 60's, which the measured vendors write, unless
/// [`RuntimeConfig::encapsulation_ids`] names Table 39. A header of version
/// 1 is the same in both and is returned as it is.
#[must_use]
fn encap_in_table(ids: zerodds_wire_codec::value::EncapsulationIds, encap: [u8; 4]) -> [u8; 4] {
    use zerodds_wire_codec::value::EncapsulationIds;
    if ids == EncapsulationIds::Table60 {
        return encap;
    }
    let [high, low] = if encap[..2] == [0x00, 0x04] {
        ids.xml_identifier()
    } else if let Some((encoding, endianness)) =
        zerodds_wire_codec::value::encapsulation_form([encap[0], encap[1]])
    {
        ids.identifier(encoding, endianness)
    } else {
        [encap[0], encap[1]]
    };
    [high, low, encap[2], encap[3]]
}

/// Tells the observability sink of every message or submessage the RTPS
/// decoders refuse, cut short or skip (event `rtps.decode.rejected`, with the
/// kind, the submessage, its offset, the sender's VendorId and the reason),
/// next to the counters `refused_messages`, `invalid_message_rests` and
/// `skipped_must_understand_submessages`. The decoders belong to the
/// process, so the sink of the first runtime started takes them. Rate:
/// the first 32 events, then one a second with the number left out since.
fn install_rejection_events(sink: &zerodds_foundation::observability::SharedSink) {
    if REJECTION_EVENTS
        .set(RejectionEvents::new(sink.clone()))
        .is_ok()
    {
        let _ = zerodds_rtps::datagram::set_rejection_hook(report_rejection);
    }
}

/// The sink and the rate state of [`install_rejection_events`].
struct RejectionEvents {
    sink: zerodds_foundation::observability::SharedSink,
    seen: AtomicU64,
    last_ms: AtomicU64,
    left_out: AtomicU64,
    started: std::time::Instant,
}

impl RejectionEvents {
    fn new(sink: zerodds_foundation::observability::SharedSink) -> Self {
        Self {
            sink,
            seen: AtomicU64::new(0),
            last_ms: AtomicU64::new(0),
            left_out: AtomicU64::new(0),
            started: std::time::Instant::now(),
        }
    }
}

static REJECTION_EVENTS: std::sync::OnceLock<RejectionEvents> = std::sync::OnceLock::new();

fn report_rejection(r: &zerodds_rtps::datagram::Rejection) {
    use zerodds_foundation::observability::{Component, Event, Level};
    let Some(ev) = REJECTION_EVENTS.get() else {
        return;
    };
    let n = ev.seen.fetch_add(1, Ordering::Relaxed);
    if n >= 32 {
        let now_ms = u64::try_from(ev.started.elapsed().as_millis()).unwrap_or(u64::MAX);
        let last = ev.last_ms.load(Ordering::Relaxed);
        if now_ms < last.saturating_add(1000)
            || ev
                .last_ms
                .compare_exchange(last, now_ms, Ordering::Relaxed, Ordering::Relaxed)
                .is_err()
        {
            ev.left_out.fetch_add(1, Ordering::Relaxed);
            return;
        }
    }
    let submessage = r.submessage_id.map_or_else(
        || String::from("none"),
        |id| {
            zerodds_rtps::submessage_header::SubmessageId::from_u8(id).map_or_else(
                |_| alloc::format!("0x{id:02x}"),
                |known| alloc::format!("{known:?} (0x{id:02x})"),
            )
        },
    );
    ev.sink.record(
        &Event::new(Level::Warn, Component::Dcps, "rtps.decode.rejected")
            .with_attr("kind", r.kind.as_str())
            .with_attr("submessage", submessage)
            .with_attr("offset", r.offset.to_string())
            .with_attr(
                "vendor",
                alloc::format!("{:02x}{:02x}", r.vendor_id[0], r.vendor_id[1]),
            )
            .with_attr("reason", alloc::format!("{}", r.reason))
            .with_attr(
                "left_out",
                ev.left_out.swap(0, Ordering::Relaxed).to_string(),
            ),
    );
}

/// Encapsulation header for the user payload, based on the negotiated
/// DataRepresentation (`offer_first`: the **first** element of the
/// writer's offer list = the wire format actually emitted by the writer)
/// and the type extensibility. The header MUST honestly declare the body
/// encoding produced by the codegen, otherwise the peer (e.g.
/// FastDDS/OpenDDS XCDR2-only reader) reads the body with the wrong
/// alignment or wrongly expects a DHEADER.
///
/// DDSI-RTPS 2.5 §10.5 / XTypes 1.3 Table 60 (little-endian variant):
///   XCDR1 final/appendable -> CDR_LE        `0x0001`
///   XCDR1 mutable          -> PL_CDR_LE      `0x0003`
///   XCDR2 final            -> PLAIN_CDR2_LE  `0x0007`
///   XCDR2 appendable       -> D_CDR2_LE      `0x0009`
///   XCDR2 mutable          -> PL_CDR2_LE     `0x000b`
///
/// XML is `{0x00, 0x04}` whatever the extensibility and the byte order
/// (DDS-XTypes 1.3 Table 60, DDSI-RTPS 2.5 Table 10.3); its body is the
/// document of [`crate::xml_data`], which the caller builds from the CDR
/// body it was handed. `wire.encapsulation_ids` turns the XCDR2 and XML
/// headers into those of Table 39 and DDSI-RTPS Table 10.3 (`encap_in_table`).
///
/// `None` for an offer that is none of XCDR1, XCDR2 and XML.
#[must_use]
fn user_payload_encap(
    offer_first: i16,
    ext: zerodds_types::qos::ExtensibilityForRepr,
    big_endian: bool,
) -> Option<[u8; 4]> {
    use zerodds_rtps::publication_data::data_representation as dr;
    use zerodds_types::qos::ExtensibilityForRepr::{Appendable, Final, Mutable};
    if offer_first == dr::XML {
        return Some(XML_ENCAP);
    }
    let id: u8 = match (offer_first, ext) {
        (dr::XCDR2, Final) => 0x07,
        (dr::XCDR2, Appendable) => 0x09,
        (dr::XCDR2, Mutable) => 0x0b,
        // XCDR1: appendable is treated like final (Table 60: XCDR1 has no
        // dedicated APPENDABLE encoding).
        (dr::XCDR, Mutable) => 0x03,
        (dr::XCDR, Final | Appendable) => 0x01,
        _ => return None,
    };
    // RTPS 2.5 §10.5: the `_LE` representation ids are odd, the matching `_BE`
    // ones are the even predecessor (CDR_BE 0x00, CDR2_BE 0x06, D_CDR2_BE 0x08,
    // PL_CDR2_BE 0x0a). Clearing the low bit converts LE -> BE.
    let id = if big_endian { id & 0xFE } else { id };
    Some([0x00, id, 0x00, 0x00])
}

/// A writer's offer has to start with a representation the runtime emits.
///
/// The first element (the representation the writer emits) has to be
/// XCDR1, XCDR2 or XML; an empty list is XCDR1 (XTypes 1.3 §7.6.3.1.1).
/// The body this runtime is handed is CDR; for XML it is converted to the
/// document of [`crate::xml_data`] before it is framed.
///
/// # Errors
/// `Unsupported` when the first element is another representation: a QoS
/// value the service does not support (DDS 1.4 §2.2.2.1.1.1).
fn check_emittable_offer(offer: Option<&[i16]>) -> Result<()> {
    use zerodds_rtps::publication_data::data_representation as dr;
    match offer.and_then(|v| v.first().copied()) {
        None => Ok(()),
        Some(first) if first == dr::XCDR || first == dr::XCDR2 || first == dr::XML => Ok(()),
        Some(_) => Err(DdsError::Unsupported {
            feature: "DATA_REPRESENTATION other than XCDR1, XCDR2 and XML (DDS 1.4 §2.2.2.1.1.1)",
        }),
    }
}

/// The zero padding a user payload gets after its serialized data, and
/// the encapsulation header that says so.
///
/// DDS-XTypes 1.3 §7.6.3.1.2: "Implementations of this specification
/// shall set the least significant two bits in the second byte of the
/// options field to a value that encodes the number of padding bytes
/// needed after the end of the serialized payload in order to reach the
/// next 4-byte aligned offset. Specifically, the least significant two
/// bits shall be set to binary 00 if no padding bits would be needed and
/// binary 01, 10, or 11 if, respectively, there would be one, two, or
/// three bytes of padding needed." §7.4.1.1 adds that "any padding bytes
/// added at the end of the serialized data shall be set to zero". The
/// RTPS message builder does not pad a submessage body, so the padding
/// is part of the serialized payload the writer stages: `payload_len` is
/// the length of the serialized data after the four-octet header.
///
/// Returns the header with the count in its options and the number of
/// zero octets to append.
#[must_use]
fn pad_user_payload(encap: &[u8; 4], payload_len: usize) -> ([u8; 4], usize) {
    let padding = (4 - payload_len % 4) % 4;
    let mut header = *encap;
    // `padding` is 0..=3, so it fits the two bits.
    header[3] = (header[3] & !0x03) | (padding as u8);
    (header, padding)
}

/// Stack PoolBuffer cap for the small-sample path in
/// [`DcpsRuntime::write_user_sample`]. A 1.5 KiB payload + 4 B encap
/// header fit through the framing without touching the heap.
const SMALL_FRAME_CAP: usize = 1536;

/// Small-sample hot-path helper: frames `USER_PAYLOAD_ENCAP` + payload
/// into a stack `PoolBuffer<SMALL_FRAME_CAP>` and hands the slice to the
/// writer. No Vec/Box/Rc/Arc allocation in this function — verified by
/// the `dds_no_realloc_in_hot_path` lint.
///
/// zerodds-lint: hot-path-realloc-free
#[allow(clippy::too_many_arguments)]
fn write_user_sample_pooled(
    writer: &mut ReliableWriter,
    payload: &[u8],
    now: Duration,
    encap: &[u8; 4],
    source_ts_override: Option<zerodds_rtps::header_extension::HeTimestamp>,
    key_hash: Option<[u8; 16]>,
    inline_qos: Option<zerodds_rtps::parameter_list::ParameterList>,
    time_source: &dyn crate::time_source::TimeSource,
) -> Result<(
    Vec<zerodds_rtps::message_builder::OutboundDatagram>,
    zerodds_rtps::header_extension::HeTimestamp,
)> {
    let (encap, padding) = pad_user_payload(encap, payload.len());
    let mut frame = zerodds_foundation::PoolBuffer::<SMALL_FRAME_CAP>::new();
    frame
        .extend_from_slice(&encap)
        .map_err(|_| DdsError::WireError {
            message: String::from("user encap framing"),
        })?;
    frame
        .extend_from_slice(payload)
        .map_err(|_| DdsError::WireError {
            message: String::from("user payload framing"),
        })?;
    frame
        .extend_from_slice(&[0u8; 3][..padding])
        .map_err(|_| DdsError::WireError {
            message: String::from("user payload padding"),
        })?;
    // Hot path: only DATA, NO HEARTBEAT. Cyclone DDS rate-limits the
    // HB piggyback (≥100 µs spacing, or a packet boundary) — so it does
    // NOT send an HB per write. At 14k writes/sec this would fire 14k
    // unnecessary submessages and (with an unaligned payload) 14k extra
    // sendto syscalls. Periodic HBs are handled by the tick loop (every
    // `heartbeat_period` ms, default 100 ms); we no longer attach `_now`
    // to `last_heartbeat`, because we emit nothing.
    let _ = now;
    // RTPS-F1: attach the source timestamp so the peer can populate
    // SampleInfo.source_timestamp + honour DESTINATION_ORDER = BY_SOURCE_TIMESTAMP
    // (DDSI-RTPS §8.7.3). The writer prepends an INFO_TS before the DATA. A
    // routing service that preserves the input's source timestamp passes it as
    // the override; otherwise the writer stamps the current wall clock — C2(6)'s
    // pluggable `time_source` (`RuntimeConfig::time_source`, config `time.source`),
    // the system clock by default.
    let source_ts =
        source_ts_override.unwrap_or_else(|| crate::time::time_to_he_timestamp(time_source.now()));
    let dgs = writer
        .write_sample_with_inline_qos(frame.as_slice(), Some(source_ts), key_hash, inline_qos)
        .map_err(|_| DdsError::WireError {
            message: String::from("user writer encode"),
        })?;
    Ok((dgs, source_ts))
}

/// Choice of transport for DCPS user traffic. Discovery (SPDP/SEDP)
/// remains UDPv4 multicast independently of this.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum UserTransportKind {
    /// UDP IPv4 (default).
    UdpV4,
    /// UDP IPv6.
    UdpV6,
    /// TCP IPv4 (DDS-TCP-PSM `LOCATOR_KIND_TCPV4`).
    TcpV4,
    /// TCP IPv6 (DDS-TCP-PSM `LOCATOR_KIND_TCPV6`).
    TcpV6,
    /// POSIX shared memory (same-host). Only with the `same-host-shm`
    /// feature.
    #[cfg(feature = "same-host-shm")]
    Shm,
    /// Unix domain socket (same-host, container-friendly). Only with the
    /// `same-host-uds` feature.
    #[cfg(feature = "same-host-uds")]
    Uds,
    /// TSN L2 transport (AF_PACKET, RTPS direct on Ethernet, EtherType
    /// 0x88B5). Only with the `tsn-live` feature on Linux. Interface/VLAN/
    /// PCP via [`RuntimeConfig::tsn_interface`]/[`RuntimeConfig::tsn_vlan`]/
    /// [`RuntimeConfig::tsn_pcp`] (config `tsn.interface`/`_VLAN`/`_PCP`).
    #[cfg(all(feature = "tsn-live", target_os = "linux"))]
    Tsn,
}

/// A CPU list for `threads.recv_cpus` / `threads.tick_cpus`: comma-separated
/// CPU indices. `None` when any entry is not an index or the list is empty.
fn parse_cpu_list(value: &str) -> Option<Vec<usize>> {
    let cpus = value
        .split(',')
        .map(str::trim)
        .filter(|v| !v.is_empty())
        .map(|v| v.parse::<usize>().ok().filter(|&c| c < 4096))
        .collect::<Option<Vec<_>>>()?;
    (!cpus.is_empty()).then_some(cpus)
}

/// C2(2) — `threads.recv_policy` / `threads.tick_policy`: the Linux
/// scheduler class a worker thread group asks for (`sched(7)`). Applied via
/// `zerodds-rt-linux` (feature `rt`); off it, requesting anything but the
/// absent key makes [`DcpsRuntime::start`] fail rather than run untuned.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ThreadSchedPolicy {
    /// `SCHED_OTHER` (CFS), requested explicitly. Distinct from leaving the
    /// key unset: unset means "no `sched_setattr` call at all, whatever the
    /// process inherited"; `other` means "make sure it is CFS."
    Other,
    /// `SCHED_FIFO` — needs `threads.*_priority` (1..=99).
    Fifo,
    /// `SCHED_RR` — needs `threads.*_priority` (1..=99).
    RoundRobin,
    /// `SCHED_DEADLINE` — needs `threads.*_deadline`.
    Deadline,
}

impl ThreadSchedPolicy {
    /// Parses `threads.recv_policy` / `threads.tick_policy`:
    /// `other`, `fifo`, `rr` or `deadline`.
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        match value.trim() {
            "other" => Some(Self::Other),
            "fifo" => Some(Self::Fifo),
            "rr" => Some(Self::RoundRobin),
            "deadline" => Some(Self::Deadline),
            _ => None,
        }
    }

    /// The config-file spelling, as `parse` reads it back.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Other => "other",
            Self::Fifo => "fifo",
            Self::RoundRobin => "rr",
            Self::Deadline => "deadline",
        }
    }
}

/// C2(2) — `threads.recv_deadline` / `threads.tick_deadline`: the
/// `SCHED_DEADLINE` `(runtime, deadline, period)` triple, all in
/// nanoseconds (`sched_setattr(2)`: `sched_runtime`/`sched_deadline`/
/// `sched_period`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ThreadDeadlineSpec {
    /// Worst-case execution time per period (ns).
    pub runtime_ns: u64,
    /// Soft deadline from the start of the period (ns).
    pub deadline_ns: u64,
    /// Repetition period (ns).
    pub period_ns: u64,
}

impl ThreadDeadlineSpec {
    /// Parses `<runtime>,<deadline>,<period>` in nanoseconds. `None` if a
    /// field fails to parse, there are not exactly three fields, or
    /// `runtime <= deadline <= period` does not hold (`sched_setattr(2)`'s
    /// own precondition — the kernel refuses the same shape with `EINVAL`).
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        let mut parts = value.split(',').map(str::trim);
        let runtime_ns = parts.next()?.parse::<u64>().ok()?;
        let deadline_ns = parts.next()?.parse::<u64>().ok()?;
        let period_ns = parts.next()?.parse::<u64>().ok()?;
        if parts.next().is_some() {
            return None;
        }
        (runtime_ns <= deadline_ns && deadline_ns <= period_ns).then_some(Self {
            runtime_ns,
            deadline_ns,
            period_ns,
        })
    }
}

/// C2(2) — the resolved real-time scheduling request for one worker thread
/// group (recv or tick), after reconciling `threads.*_policy` /
/// `threads.*_priority` / `threads.*_deadline` (see `resolve_thread_sched`).
/// Carries exactly what a worker's own thread hands to
/// `zerodds_rt_linux::scheduler::SchedulerProfile::apply_to_current_thread`
/// (feature `rt`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ThreadSchedRequest {
    /// `SCHED_OTHER`, requested explicitly (`threads.*_policy=other`).
    Other,
    /// `SCHED_FIFO`. Also what a bare `threads.*_priority` means, unchanged
    /// from the setting's pre-C2(2) behaviour.
    Fifo {
        /// `sched_priority` (1..=99).
        priority: u8,
    },
    /// `SCHED_RR`.
    RoundRobin {
        /// `sched_priority` (1..=99).
        priority: u8,
    },
    /// `SCHED_DEADLINE`.
    Deadline {
        /// Worst-case execution time per period (ns).
        runtime_ns: u64,
        /// Soft deadline from the start of the period (ns).
        deadline_ns: u64,
        /// Repetition period (ns).
        period_ns: u64,
    },
}

impl ThreadSchedRequest {
    /// Human-readable form for an error message or an observability event —
    /// not a config spelling (`ThreadSchedPolicy::as_str` is that).
    fn describe(self) -> String {
        match self {
            Self::Other => String::from("SCHED_OTHER (explicit)"),
            Self::Fifo { priority } => alloc::format!("SCHED_FIFO priority {priority}"),
            Self::RoundRobin { priority } => alloc::format!("SCHED_RR priority {priority}"),
            Self::Deadline {
                runtime_ns,
                deadline_ns,
                period_ns,
            } => alloc::format!(
                "SCHED_DEADLINE runtime={runtime_ns}ns deadline={deadline_ns}ns period={period_ns}ns"
            ),
        }
    }

    /// Maps to the `zerodds-rt-linux` request type. Feature `rt` only — the
    /// mapping does not exist in a build that cannot apply it.
    #[cfg(feature = "rt")]
    fn as_scheduler_profile(self) -> zerodds_rt_linux::scheduler::SchedulerProfile {
        use zerodds_rt_linux::scheduler::SchedulerProfile;
        match self {
            Self::Other => SchedulerProfile::Default,
            Self::Fifo { priority } => SchedulerProfile::RealtimeFifo { priority },
            Self::RoundRobin { priority } => SchedulerProfile::RealtimeRoundRobin { priority },
            Self::Deadline {
                runtime_ns,
                deadline_ns,
                period_ns,
            } => SchedulerProfile::Deadline {
                runtime_ns,
                deadline_ns,
                period_ns,
            },
        }
    }
}

/// One `threads.*` combination refusal: which key is at fault, and why —
/// `sched(7)`/`sched_setattr(2)`: a priority means something only under
/// `SCHED_FIFO`/`SCHED_RR`, a `(runtime, deadline, period)` triple only
/// under `SCHED_DEADLINE`. Returned by [`resolve_thread_sched`].
#[derive(Debug)]
struct ThreadSchedConfigError {
    /// The exact setting path the refusal is about
    /// (`threads.recv_policy`/`_priority`/`_deadline`, or the tick
    /// equivalents) — never a bundle of "one of these three."
    key: &'static str,
    /// The refusal, naming the values involved.
    message: String,
}

/// C2(2) — resolves one thread group's real-time scheduling request from its
/// three keys (`threads.<group>_policy` / `_priority` / `_deadline`), or
/// names the key that makes the combination inconsistent. `Ok(None)` means
/// nothing was requested at all — today's meaning: the OS default scheduler,
/// no `sched_setattr` call.
///
/// Rules (checked here, nowhere else, so the two callers below cannot
/// drift apart):
/// * A priority without a policy keeps the pre-C2(2) meaning: `fifo`.
/// * A priority with `policy=other` or `policy=deadline` is refused, naming
///   the priority key.
/// * A deadline triple with `policy=fifo`/`rr`/`other`, or without
///   `policy=deadline`, is refused, naming the deadline key.
/// * `policy=fifo`/`rr` without a priority is refused, naming the priority
///   key. `policy=deadline` without a deadline triple is refused, naming the
///   deadline key.
///
/// Shared by [`ConfigSource::runtime_findings`] (parses raw file/env
/// strings before `RuntimeConfig` exists) and [`DcpsRuntime::start`] (defends
/// a `RuntimeConfig` a caller built by hand, bypassing `from_source` and
/// therefore this same check) — see `docs/silent-drop-sweep.md`: a setting
/// nobody could make sense of must abort, not fall back to "nothing
/// requested."
fn resolve_thread_sched(
    policy: Option<ThreadSchedPolicy>,
    priority: Option<i32>,
    deadline: Option<ThreadDeadlineSpec>,
    policy_key: &'static str,
    priority_key: &'static str,
    deadline_key: &'static str,
) -> core::result::Result<Option<ThreadSchedRequest>, ThreadSchedConfigError> {
    let valid_priority = |p: i32| u8::try_from(p).ok().filter(|p| (1..=99).contains(p));
    match policy {
        None => match (priority, deadline) {
            (None, None) => Ok(None),
            (Some(p), None) => match valid_priority(p) {
                Some(p) => Ok(Some(ThreadSchedRequest::Fifo { priority: p })),
                None => Err(ThreadSchedConfigError {
                    key: priority_key,
                    message: alloc::format!("{priority_key} must be 1..=99, got `{p}`"),
                }),
            },
            (None, Some(_)) => Err(ThreadSchedConfigError {
                key: deadline_key,
                message: alloc::format!("{deadline_key} is set without {policy_key}=deadline"),
            }),
            (Some(_), Some(_)) => Err(ThreadSchedConfigError {
                key: policy_key,
                message: alloc::format!(
                    "{priority_key} and {deadline_key} are both set; {policy_key} must say which one applies"
                ),
            }),
        },
        Some(ThreadSchedPolicy::Other) => {
            if let Some(p) = priority {
                return Err(ThreadSchedConfigError {
                    key: priority_key,
                    message: alloc::format!(
                        "{priority_key}=`{p}` is set with {policy_key}=other, which takes no priority"
                    ),
                });
            }
            if deadline.is_some() {
                return Err(ThreadSchedConfigError {
                    key: deadline_key,
                    message: alloc::format!(
                        "{deadline_key} is set with {policy_key}=other, which takes no deadline"
                    ),
                });
            }
            Ok(Some(ThreadSchedRequest::Other))
        }
        Some(fifo_or_rr @ (ThreadSchedPolicy::Fifo | ThreadSchedPolicy::RoundRobin)) => {
            if deadline.is_some() {
                return Err(ThreadSchedConfigError {
                    key: deadline_key,
                    message: alloc::format!(
                        "{deadline_key} is set with {policy_key}={}, which takes a priority, not a deadline",
                        fifo_or_rr.as_str()
                    ),
                });
            }
            let Some(p) = priority else {
                return Err(ThreadSchedConfigError {
                    key: priority_key,
                    message: alloc::format!(
                        "{policy_key}={} needs {priority_key}",
                        fifo_or_rr.as_str()
                    ),
                });
            };
            let Some(p) = valid_priority(p) else {
                return Err(ThreadSchedConfigError {
                    key: priority_key,
                    message: alloc::format!("{priority_key} must be 1..=99, got `{p}`"),
                });
            };
            Ok(Some(if fifo_or_rr == ThreadSchedPolicy::Fifo {
                ThreadSchedRequest::Fifo { priority: p }
            } else {
                ThreadSchedRequest::RoundRobin { priority: p }
            }))
        }
        Some(ThreadSchedPolicy::Deadline) => {
            if let Some(p) = priority {
                return Err(ThreadSchedConfigError {
                    key: priority_key,
                    message: alloc::format!(
                        "{priority_key}=`{p}` is set with {policy_key}=deadline, which takes a deadline triple, not a priority"
                    ),
                });
            }
            let Some(d) = deadline else {
                return Err(ThreadSchedConfigError {
                    key: deadline_key,
                    message: alloc::format!("{policy_key}=deadline needs {deadline_key}"),
                });
            };
            Ok(Some(ThreadSchedRequest::Deadline {
                runtime_ns: d.runtime_ns,
                deadline_ns: d.deadline_ns,
                period_ns: d.period_ns,
            }))
        }
    }
}

/// What an endpoint that announces no `TypeConsistencyEnforcement`
/// (PID `0x0074`) is taken to request: `xtypes.type_consistency_absent`.
///
/// DDS-XTypes 1.3 §7.6.3.4.1: "if it observes that no
/// TypeConsistencyEnforcementQosPolicy value is provided (as would be the
/// case when communicating with a Service implementation not in
/// conformance with this specification), it shall assume a kind of
/// DISALLOW_TYPE_COERCION" — `Disallow`, the default. `Allow` reads the
/// absent policy as the policy's own default, ALLOW_TYPE_COERCION, for a
/// peer that does not announce the PID and is to be matched by
/// assignability all the same.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum AbsentTypeConsistency {
    /// DISALLOW_TYPE_COERCION: the clause.
    #[default]
    Disallow,
    /// ALLOW_TYPE_COERCION with the policy's defaults.
    Allow,
}

impl AbsentTypeConsistency {
    /// The setting's spelling.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Disallow => "disallow",
            Self::Allow => "allow",
        }
    }

    /// Reads the spelling.
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        match value.trim() {
            "disallow" => Some(Self::Disallow),
            "allow" => Some(Self::Allow),
            _ => None,
        }
    }
}

/// `wire.data_representation_match`: `strict` or `tolerant`.
fn parse_data_rep_match(
    value: &str,
) -> Option<zerodds_rtps::publication_data::data_representation::DataRepMatchMode> {
    use zerodds_rtps::publication_data::data_representation::DataRepMatchMode as M;
    match value.trim() {
        "strict" => Some(M::Strict),
        "tolerant" => Some(M::Tolerant),
        _ => None,
    }
}

/// How a coherent set is presented under PRESENTATION `access_scope`
/// INSTANCE. DDS 1.4 words it twice: the table of §2.2.3.6 (p. 106) says
/// "order and coherent changes apply to each instance separately", and the
/// text under it (p. 115) says that `begin_coherent_change` and
/// `end_coherent_change` have "no effect on how the subscriber can access the
/// data" with that scope. The two differ for a coherent set within one
/// instance. The setting `dcps.presentation_instance_coherence` (env
/// `ZERODDS_PRESENTATION_INSTANCE_COHERENCE`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum PresentationInstanceCoherence {
    /// The table: the changes of a set to one instance are presented
    /// together, once the set is closed. The default; the OMG dds-rtps cases
    /// `Test_CoherentSets_10` and `_19` check this against the other vendors.
    #[default]
    PerInstance,
    /// The text: under INSTANCE scope a coherent set is not held back; the
    /// samples are presented as they arrive.
    None,
}

impl PresentationInstanceCoherence {
    /// The spelling of `dcps.presentation_instance_coherence`:
    /// `per_instance` or `none`. Anything else is `None`, and the setting is
    /// refused.
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        match value.trim() {
            "per_instance" => Some(Self::PerInstance),
            "none" => Some(Self::None),
            _ => None,
        }
    }
}

/// The clock a DataReader's TIME_BASED_FILTER measures
/// `minimum_separation` on. DDS 1.4 §2.2.3.12 leaves it open: "at most one
/// change every minimum_separation period". The setting
/// `reader.time_based_filter_clock` (env
/// `ZERODDS_READER_TIME_BASED_FILTER_CLOCK`).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum TimeBasedFilterClock {
    /// The time of the change, the writer's source timestamp (INFO_TS); the
    /// reception time for a sample without one. The default: a writer that
    /// filters for the reader itself (InterCom DDS 4.3.1) loses no sample
    /// to the jitter of the network, and the result does not depend on
    /// when the samples arrive.
    #[default]
    Sender,
    /// The reader's clock when the sample arrived (OpenDDS 3.35
    /// `DataReaderImpl::time_based_filter_instance`).
    Receiver,
}

impl TimeBasedFilterClock {
    /// The spelling of `reader.time_based_filter_clock`: `sender` or
    /// `receiver`. Anything else is `None`, and the setting is refused.
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        match value.trim() {
            "sender" => Some(Self::Sender),
            "receiver" => Some(Self::Receiver),
            _ => None,
        }
    }

    /// The time `minimum_separation` is measured on for a sample with the
    /// source timestamp `source` that arrived at `reception`.
    #[must_use]
    pub fn time_of(
        self,
        source: Option<crate::time::Time>,
        reception: crate::time::Time,
    ) -> crate::time::Time {
        match self {
            Self::Sender => source.unwrap_or(reception),
            Self::Receiver => reception,
        }
    }
}

/// How a writer hands samples to its readers (`zerodds-delivery-modes-1.0`
/// §4). The participant default is the setting `delivery.mode` (env
/// `ZERODDS_DELIVERY_MODE`); a writer can override it with the C-API setters.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum DeliveryMode {
    /// Serialized over RTPS; works across hosts and vendors. The default.
    #[default]
    Portable,
    /// Same-host shared memory, no wire.
    RawSameHost,
    /// Same-host through iceoryx2.
    Iceoryx,
}

impl DeliveryMode {
    /// The spelling of `delivery.mode`: `portable`, `raw-same-host`,
    /// `iceoryx`. Anything else is `None`, and the setting is refused.
    #[must_use]
    pub fn parse(value: &str) -> Option<Self> {
        match value.trim() {
            "portable" => Some(Self::Portable),
            "raw-same-host" => Some(Self::RawSameHost),
            "iceoryx" => Some(Self::Iceoryx),
            _ => None,
        }
    }

    /// The C-API number: 0 Portable, 1 RawSameHost, 2 Iceoryx.
    #[must_use]
    pub fn as_c(self) -> i32 {
        match self {
            Self::Portable => 0,
            Self::RawSameHost => 1,
            Self::Iceoryx => 2,
        }
    }
}

/// One entry of `ros2.time_based_filter` (env `ZERODDS_TIME_BASED_FILTER`):
/// `<seconds>` for every subscription, or `<topic>=<seconds>` for one ROS
/// topic. ROS 2's `rmw_qos_profile_t` has no TIME_BASED_FILTER field, so the
/// RMW reads it from here (DDS 1.4 §2.2.3.12).
#[derive(Debug, Clone, PartialEq)]
pub struct TimeBasedFilterEntry {
    /// The ROS topic (`/scan`), or `None` for the default of every topic.
    pub topic: Option<String>,
    /// Minimum separation; zero disables the filter.
    pub min_separation: Duration,
}

/// Parses a `ros2.time_based_filter` value, a comma list of entries.
/// `None` for any entry that is not a finite, non-negative number of seconds
/// — a filter that silently does not apply is a rate nobody asked for.
#[must_use]
pub fn parse_time_based_filter(value: &str) -> Option<Vec<TimeBasedFilterEntry>> {
    let seconds = |text: &str| -> Option<Duration> {
        let secs = text.trim().parse::<f64>().ok()?;
        (secs.is_finite() && secs >= 0.0).then(|| Duration::from_secs_f64(secs))
    };
    value
        .split(',')
        .map(str::trim)
        .filter(|entry| !entry.is_empty())
        .map(|entry| match entry.split_once('=') {
            Some((topic, secs)) if !topic.trim().is_empty() => Some(TimeBasedFilterEntry {
                topic: Some(topic.trim().to_string()),
                min_separation: seconds(secs)?,
            }),
            Some(_) => None,
            None => Some(TimeBasedFilterEntry {
                topic: None,
                min_separation: seconds(entry)?,
            }),
        })
        .collect()
}

/// Maps the `transport.user_transport` file setting to a [`UserTransportKind`].
/// `None` if unset or unknown — the caller then falls back to UDPv4.
fn parse_user_transport(value: &str) -> Option<UserTransportKind> {
    match value {
        "UDPv4" => Some(UserTransportKind::UdpV4),
        "UDPv6" => Some(UserTransportKind::UdpV6),
        "TCPv4" => Some(UserTransportKind::TcpV4),
        "TCPv6" => Some(UserTransportKind::TcpV6),
        #[cfg(feature = "same-host-shm")]
        "SHM" => Some(UserTransportKind::Shm),
        #[cfg(feature = "same-host-uds")]
        "UDS" => Some(UserTransportKind::Uds),
        #[cfg(all(feature = "tsn-live", target_os = "linux"))]
        "TSN" => Some(UserTransportKind::Tsn),
        _ => None,
    }
}

/// Result of [`select_user_transport`]: the user-traffic transport plus
/// an optional `TcpTransport` accept handle (only for TCP).
type UserTransportSelection = (
    Arc<dyn Transport + Send + Sync>,
    Option<Arc<zerodds_transport_tcp::TcpTransport>>,
);

/// Binds the user-traffic transport for the selected
/// [`UserTransportKind`]. Discovery (SPDP/SEDP) runs separately over
/// UDPv4 multicast; this transport carries only the DCPS user traffic.
///
/// Additionally returns an optional `TcpTransport` accept handle: TCP has
/// no implicit accept thread in the constructor, so the caller starts an
/// `accept_one` worker for it.
// `guid_prefix`/`domain_id` are only read by the SHM/UDS arms, `config` only
// by the TSN arm — a build without those features has no use for them.
#[cfg_attr(
    not(all(
        any(feature = "same-host-shm", feature = "same-host-uds"),
        feature = "tsn-live",
        target_os = "linux"
    )),
    allow(unused_variables)
)]
fn select_user_transport(
    kind: UserTransportKind,
    guid_prefix: GuidPrefix,
    domain_id: i32,
    pinned: Ipv4Addr,
    udp_port: u16,
    config: &RuntimeConfig,
) -> Result<UserTransportSelection> {
    match kind {
        UserTransportKind::UdpV4 => {
            // Interface pinning: bind to the pinned IPv4 (egress + receive
            // on exactly this interface), otherwise `0.0.0.0` (auto).
            // DDSI-RTPS 2.5 §9.6.2.3: the user-traffic unicast port of the
            // participant, `PB + DG * domainId + d3 + PG * participantId`
            // (`udp_port`; 0 asks for none). A port that is taken is
            // counted and logged, and the socket takes an ephemeral port.
            let udp = if udp_port == 0 {
                UdpTransport::bind_v4_with_config(pinned, 0, config.udp.clone())
            } else {
                UdpTransport::bind_v4_with_config(pinned, udp_port, config.udp.clone()).or_else(
                    |error| {
                        USER_PORT_FALLBACKS.fetch_add(1, core::sync::atomic::Ordering::Relaxed);
                        config.observability.record(
                            &zerodds_foundation::observability::Event::new(
                                zerodds_foundation::observability::Level::Warn,
                                zerodds_foundation::observability::Component::Dcps,
                                "transport.user_unicast.port_taken",
                            )
                            .with_attr("port", alloc::format!("{udp_port}").as_str())
                            .with_attr("error", alloc::format!("{error:?}").as_str()),
                        );
                        UdpTransport::bind_v4_with_config(pinned, 0, config.udp.clone())
                    },
                )
            }
            .map_err(|_| DdsError::TransportError {
                label: "user unicast bind (UDPv4)",
            })?
            .with_timeout(Some(Duration::from_secs(1)))
            .map_err(|_| DdsError::TransportError {
                label: "user unicast set_timeout (UDPv4)",
            })?;
            Ok((Arc::new(udp), None))
        }
        UserTransportKind::UdpV6 => {
            let udp = UdpTransport::bind_v6_with_config(
                std::net::Ipv6Addr::UNSPECIFIED,
                0,
                config.udp.clone(),
            )
            .map_err(|_| DdsError::TransportError {
                label: "user unicast bind (UDPv6)",
            })?
            .with_timeout(Some(Duration::from_secs(1)))
            .map_err(|_| DdsError::TransportError {
                label: "user unicast set_timeout (UDPv6)",
            })?;
            Ok((Arc::new(udp), None))
        }
        UserTransportKind::TcpV4 => {
            // Interface pinning analogous to UDPv4.
            let tcp = zerodds_transport_tcp::TcpTransport::bind_v4(pinned, 0).map_err(|_| {
                DdsError::TransportError {
                    label: "user unicast bind (TCPv4)",
                }
            })?;
            let arc = Arc::new(tcp);
            let dynamic: Arc<dyn Transport + Send + Sync> = arc.clone();
            Ok((dynamic, Some(arc)))
        }
        UserTransportKind::TcpV6 => {
            let tcp =
                zerodds_transport_tcp::TcpTransport::bind_v6(std::net::Ipv6Addr::UNSPECIFIED, 0)
                    .map_err(|_| DdsError::TransportError {
                        label: "user unicast bind (TCPv6)",
                    })?;
            let arc = Arc::new(tcp);
            let dynamic: Arc<dyn Transport + Send + Sync> = arc.clone();
            Ok((dynamic, Some(arc)))
        }
        #[cfg(feature = "same-host-shm")]
        UserTransportKind::Shm => {
            // local_id = guid_prefix (12 bytes) + 4-byte domain id so that
            // separate domains get separate segments (no cross-domain
            // collisions).
            let mut local_id = [0u8; 16];
            local_id[..12].copy_from_slice(&guid_prefix.to_bytes());
            local_id[12..].copy_from_slice(&(domain_id as u32).to_be_bytes());
            let shm = crate::shm_user::ShmUserTransport::new(
                local_id,
                zerodds_transport_shm::posix::ShmConfig::default(),
            );
            Ok((Arc::new(shm), None))
        }
        #[cfg(feature = "same-host-uds")]
        UserTransportKind::Uds => {
            // local_id = guid_prefix (12 bytes) + 4-byte domain id — the
            // peer resolves this id from the announced UDS locator into the
            // same socket path.
            let mut local_id = [0u8; 16];
            local_id[..12].copy_from_slice(&guid_prefix.to_bytes());
            local_id[12..].copy_from_slice(&(domain_id as u32).to_be_bytes());
            // recv_timeout analogous to the UDP path: the recv loop must
            // periodically check the stop flag (otherwise a thread hang on
            // shutdown on a blocking recv).
            let uds_cfg = zerodds_transport_uds::UdsConfig {
                recv_timeout: Some(Duration::from_secs(1)),
                ..zerodds_transport_uds::UdsConfig::default()
            };
            let uds =
                zerodds_transport_uds::UdsTransport::bind(local_id, uds_cfg).map_err(|_| {
                    DdsError::TransportError {
                        label: "user unicast bind (UDS)",
                    }
                })?;
            Ok((Arc::new(uds), None))
        }
        #[cfg(all(feature = "tsn-live", target_os = "linux"))]
        UserTransportKind::Tsn => {
            // Interface/VLAN/PCP from the config (TSN needs a concrete
            // interface; not bindable to 0.0.0.0 like UDP/TCP). recv_timeout 1s
            // analogous to UDP for the stop-flag check.
            let iface = config
                .tsn_interface
                .as_deref()
                .ok_or(DdsError::TransportError {
                    label: "ZERODDS_TSN_IFACE not set (TSN transport)",
                })?;
            let tsn = zerodds_transport_tsn::socket::TsnTransport::bind(
                iface,
                config.tsn_vlan,
                config.tsn_pcp,
                Some(Duration::from_secs(1)),
            )
            .map_err(|_| DdsError::TransportError {
                label: "user unicast bind (TSN)",
            })?;
            Ok((Arc::new(tsn), None))
        }
    }
}

/// Compiled default datagram limit for the same-host SHM path.
pub const DEFAULT_SHM_MAX_DATAGRAM: usize = 64 * 1024;

/// Configuration for the runtime. Exposed via DomainParticipant factory
/// methods.
#[derive(Clone)]
pub struct RuntimeConfig {
    /// Tick period of the event loop. Default 50 ms.
    pub tick_period: Duration,
    /// Largest RTPS message a writer builds before it must put it on the wire,
    /// in bytes. Default [`DEFAULT_MAX_MESSAGE_SIZE`], env
    /// `transport.max_message_size`. See there for what the number buys and
    /// what it costs.
    pub max_message_size: usize,
    /// Same-host SHM datagram cap, from `transport.shm_max_datagram`.
    /// Capacity grows with this cap. The SHM feature must be enabled to use it.
    pub shm_max_datagram: usize,
    /// Whether a writer and a reader on the same host move user samples
    /// through a shared-memory segment (feature `same-host-shm`,
    /// `zerodds-zero-copy-1.0` §6) or through the user transport like any
    /// other pair. `transport.same_host_shm`, env `ZERODDS_SAME_HOST_SHM`;
    /// **default: on when the `same-host-shm` feature is built in, off
    /// otherwise**; on without the feature, [`DcpsRuntime::start`] refuses. Off, every same-host pair takes the UDP fallback
    /// the segment open takes when it fails. A process that has to share
    /// the wire with a peer of another implementation on its host, and a
    /// measurement that compares transports, are the two that need it off.
    pub same_host_shm: bool,

    /// Whether the participant joins the SPDP multicast group on the
    /// user-traffic multicast port `PB + DG * domainId + d2` of DDSI-RTPS 2.5
    /// §9.6.2.3, receives user traffic there and announces the locator as
    /// its default multicast locator. `transport.user_multicast`, env
    /// `ZERODDS_USER_MULTICAST`; default `true` (the default locators of
    /// §9.6.2.3 include the user multicast port d2); `false` for a host without
    /// multicast: a peer then sends user traffic to it by unicast. Writers of
    /// ZeroDDS send to the unicast locators of a peer only. A failed join is
    /// logged and the participant runs without it.
    pub user_multicast: bool,

    /// The name the participant announces as `PID_ENTITY_NAME`
    /// (`EntityName_t`, DDSI-RTPS 2.5 Table 9.18). `discovery.participant_name`,
    /// env `ZERODDS_PARTICIPANT_NAME`; unset: `zerodds:` and the GUID prefix in
    /// hex.
    pub participant_name: Option<String>,
    /// Capacity of the per-writer-proxy KEEP_ALL cache a reliable reader holds
    /// while it waits out an in-order gap, in samples. Default
    /// [`DEFAULT_MAX_SAMPLES_PER_PROXY`], env
    /// `reader.max_samples_per_proxy`.
    pub max_samples_per_proxy: usize,
    /// How many datagrams the user receive loop asks for per
    /// [`zerodds_transport::Transport::recv_batch`] call. Default
    /// [`DEFAULT_RECV_BATCH_SIZE`], config `transport.recv_batch`. `1` reproduces
    /// the single-`recv()` loop.
    pub recv_batch_size: usize,
    /// Let a writer batch even at a LATENCY_BUDGET of zero, by handing the
    /// message to the scheduler tick instead of sending it inline. **Default
    /// `false`, and it is a measurement switch, not a tuning knob**
    /// (config `transport.batch_at_zero_budget`).
    ///
    /// §2.2.3.9 permits coalescing a backlog that exists anyway even at a zero
    /// budget — CycloneDDS does exactly that. What it does not permit is
    /// creating one, and in this tree the two are the same act: a synchronous
    /// `write()` has no backlog until the send is moved off the calling
    /// thread, and once it is, the writer outruns the receiver. Measured on
    /// the Linux test host, 1 kB, own domain: 602 kS/s written against 450 kS/s drained,
    /// BEST_EFFORT losing 20-32 % and RELIABLE 38-92 %, with `RcvbufErrors`
    /// counting the difference. The switch exists so that verdict can be
    /// re-measured against a faster receive path without a rebuild.
    pub batch_at_zero_budget: bool,
    /// SPDP announce period. Default 5 s.
    pub spdp_period: Duration,
    /// Number of SPDP announces at the fast [`Self::initial_announce_period`]
    /// cadence while no peer is discovered yet, and of directed SPDP responses
    /// to a newly discovered participant at that cadence (the first at once).
    /// Default [`DEFAULT_INITIAL_ANNOUNCE_COUNT`]. `0` turns the fast announces
    /// off and leaves the one response.
    pub initial_announce_count: u32,
    /// Period between initial-announcement-burst SPDP sends. Default
    /// [`DEFAULT_INITIAL_ANNOUNCE_PERIOD`].
    pub initial_announce_period: Duration,
    /// SPDP multicast group (IPv4). Default 239.255.0.1 (Spec §9.6.1.4.1).
    pub spdp_multicast_group: Ipv4Addr,
    /// Interface address for the multicast join and send. Default 0.0.0.0:
    /// the group is joined, and SPDP sent, on every eligible interface
    /// ([`zerodds_transport_udp::eligible_ipv4_interfaces`]), and on the
    /// kernel's choice only when there is none.
    pub multicast_interface: Ipv4Addr,

    /// Opt-in multicast allowlist (IPv4 groups). When non-empty, ZeroDDS joins
    /// only multicast groups on this list — any other group, including a
    /// `spdp_multicast_group` not on the list, is refused at participant
    /// creation. Empty = no restriction (default).
    ///
    /// Defense-in-depth: announced multicast locators are already never used as
    /// send targets (they are dropped when a reader proxy is built, see
    /// `ReaderProxy::new(.., Vec::new(), ..)` on the SEDP match path), so ZeroDDS
    /// only ever touches its own `spdp_multicast_group`. This allowlist turns
    /// that implicit code property into an enforced, auditable config.
    /// config: `discovery.multicast_allowlist` (comma-separated IPv4).
    pub multicast_allowlist: Vec<Ipv4Addr>,

    /// C1: whether SPDP beacons are sent via multicast. Default `true`
    /// (spec behavior). `false` (config `discovery.no_multicast`) → pure
    /// unicast discovery via [`Self::initial_peers`], not a single
    /// multicast packet — for networks that drop multicast (WiFi/cloud
    /// VPC), and for a rigorous multicast-free discovery proof.
    pub spdp_multicast_send: bool,

    /// A1: **discovery-server** mode. When `true`, this participant relays the
    /// raw SPDP (participant-locator) announcements between the clients that
    /// point their [`Self::initial_peers`] at it — so N clients discover each
    /// other through one well-known address instead of an O(N²) peer list or
    /// multicast. Crucially it relays **only SPDP** (participant discovery);
    /// SEDP (endpoint discovery, incl. dynamically-created ROS-2 Action
    /// endpoints) then happens **directly peer-to-peer** between the real
    /// participants — which is exactly why ROS-2 Actions work over it, unlike a
    /// SEDP-proxying discovery server. Default `false`. Plain discovery only
    /// (DDS-Security secured discovery-server relay is a follow-up).
    pub discovery_server: bool,

    /// C3: max reassemblable sample size (DoS cap of the fragment
    /// assembler). Larger samples are silently discarded. The rtps
    /// default was 1 MiB (the phase-1 assumption "large images = no
    /// use case") — too small for ROS PointCloud2/Image (often several
    /// MB). Default here 16 MiB; config `reader.max_reassembly_sample_bytes` (bytes)
    /// overrides. Still a deliberate DoS guard, just ROS-realistic.
    pub max_reassembly_sample_bytes: usize,

    /// C1 multicast-free discovery: unicast initial-peer locators to
    /// which SPDP beacons are sent **in addition** to multicast. Default
    /// empty (= pure multicast behavior as before). [`DcpsRuntime::start`]
    /// appends the expansion of [`Self::initial_peer_specs`] (env
    /// `discovery.peers`) to this list: an `ip` without a port becomes the
    /// well-known SPDP unicast ports of participant indices
    /// `0..`[`Self::initial_peer_max_participants`] (see
    /// `expand_initial_peer`).
    pub initial_peers: Vec<Locator>,

    /// Transport for DCPS user traffic. Default from the env var
    /// `transport.user_transport`; `None` (unset, or a spelling this build has
    /// no transport for) → UDPv4. Discovery
    /// (SPDP/SEDP) remains UDPv4 multicast independently of this. Ignored when
    /// [`Self::user_transports`] is non-empty.
    pub user_transport: Option<UserTransportKind>,

    /// Preference-ordered set of transports for DCPS user traffic. When
    /// non-empty, the runtime builds a [`LayeredUserTransport`](crate::layered_transport::LayeredUserTransport)
    /// over all of them: each datagram is routed to the first transport whose
    /// locator kind matches the destination (so list the fast/local transport
    /// first — e.g. `[Shm, UdpV4]` — and the fallback last), and receives are
    /// multiplexed from all of them. Empty (default) → single-transport via
    /// [`Self::user_transport`].
    pub user_transports: alloc::vec::Vec<UserTransportKind>,

    /// Optional security gate. Active only with the `security` feature.
    /// When set, UDP outbound messages are pulled through
    /// `zerodds_security_runtime::SharedSecurityGate::transform_outbound`, and inbound messages
    /// through `SharedSecurityGate::transform_inbound_from` (peer key
    /// from RTPS header bytes 8..20).
    #[cfg(feature = "security")]
    pub security: Option<std::sync::Arc<zerodds_security_runtime::SharedSecurityGate>>,
    /// Optional LoggingPlugin for security events. Called by the inbound
    /// path when packets are dropped due to a policy violation, tampering
    /// or a legacy block.
    #[cfg(feature = "security")]
    pub security_logger: Option<std::sync::Arc<dyn zerodds_security_runtime::LoggingPlugin>>,
    /// Optional DataTagging plugin (DDS-Security 1.2 §9.7, §10.1
    /// `DDS:Tagging:DDS_Discovery`). When set, the runtime registers the
    /// `data_tags` of every user DataWriter and DataReader with it at
    /// creation, announces the tags the plugin returns for the endpoint in
    /// `PID_DATA_TAGS`, registers the tags of a discovered endpoint under its
    /// GUID, and removes an endpoint's tags when it goes. Without a plugin
    /// the tags of the QoS are announced as they are.
    #[cfg(feature = "security")]
    pub security_data_tagging: Option<
        std::sync::Arc<std::sync::Mutex<dyn zerodds_security::data_tagging::DataTaggingPlugin>>,
    >,

    /// Multi-interface bindings. Empty → `user_unicast` is the only
    /// outbound socket (legacy behavior). Non-empty →
    /// `DcpsRuntime::start` builds a dedicated UDP socket per spec and the
    /// writer tick loop routes to the matching socket per destination
    /// locator.
    #[cfg(feature = "security")]
    pub interface_bindings: Vec<InterfaceBindingSpec>,

    /// DDS-Security §7.4.3 identity-adjusted participant GUID prefix.
    /// `None` (default) → the participant constructor picks a random
    /// prefix (`random_guid_prefix` in `crate::participant`), same as the
    /// unsecured path. `Some(prefix)` → the constructor MUST start the
    /// runtime with exactly this prefix instead of a random one, so that
    /// the SPDP beacon, handshake `c.pdata` and all entity GUIDs are
    /// derived from the identity cert — a random wire GUID fails a
    /// peer's §7.4.3 check. Set by [`Self::with_security_bundle`] from
    /// [`zerodds_security_runtime::SecurityProfile::adjusted_participant_guid`]
    /// (mirrors what `zerodds-c-api::security_ffi::finish_secure_runtime`
    /// already does for the FFI path).
    #[cfg(feature = "security")]
    pub security_guid_prefix: Option<GuidPrefix>,

    /// `true` → the SPDP beacon additionally announces the 12 secure
    /// discovery bits (16..27, DDS-Security 1.2 §7.4.7.1). Default
    /// `false` — only standard bits are announced. Set by the DCPS
    /// factory once a PolicyEngine is configured. This flag is available
    /// even without the `security` feature, so that tests can check bit
    /// presence without activating the whole crypto crate.
    pub announce_secure_endpoints: bool,

    /// The reliable secure SPDP channel (0xff0101c2/c7,
    /// `ENTITYID_SPDP_RELIABLE_BUILTIN_PARTICIPANT_SECURE_*`, DDS-Security
    /// 1.1 §7.4.1.4). A secured participant announces this writer and reader
    /// in `PID_BUILTIN_ENDPOINT_SET` whether or not it runs them, and Fast DDS
    /// takes the announcement at its word: it matches the secure SEDP
    /// endpoints of a peer only after that peer's participant data arrived
    /// on this channel, whatever the governance protects. With the channel
    /// off, no secured pair with Fast DDS matched; with it on, the 13
    /// governance profiles of the security deep matrix match ZeroDDS with
    /// Fast DDS and Cyclone in both directions. Runs on a secured
    /// participant when this is `true`, the default; `security.secure_spdp:
    /// false` (`ZERODDS_SECURE_SPDP=0`) turns it off.
    pub enable_secure_spdp: bool,

    /// DDS-Security 1.2 §9.8.9.5 step 6 and §9.8.10.4: how long the
    /// participant waits, after it sent the revised key material, for the
    /// matched authenticated participants to acknowledge it before it calls
    /// `activate_key_revision` ("or else until sufficient time has
    /// elapsed"). The specification gives no value; the default is five
    /// seconds. A programmatic setting, not a key of the configuration file.
    pub key_revision_ack_timeout: Duration,

    /// WLP-Tick-Periode (Writer-Liveliness-Protocol, RTPS 2.5 §8.4.13).
    /// `Duration::ZERO` → default `participant_lease_duration / 3`
    /// (spec recommendation: three misses before the reader marks the
    /// writer as not-alive). A direct override enables aggressive
    /// tests.
    pub wlp_period: Duration,

    /// `W::nackResponseDelay` of every user writer (DDSI-RTPS 2.5
    /// §8.4.7.1): a repair goes out once the NACK that asked for it has
    /// waited this long. `writer.nack_response_delay_ms`, env
    /// `ZERODDS_NACK_RESPONSE_DELAY_MS`; default 200 ms, the spec's
    /// ([`zerodds_rtps::reliable_writer::DEFAULT_NACK_RESPONSE_DELAY`]);
    /// 0 answers on the next tick. The built-in discovery writers keep the
    /// default.
    pub nack_response_delay: Duration,

    /// `W::heartbeatPeriod` of every user writer (DDSI-RTPS 2.5 §8.4.7.1):
    /// how often a writer announces its history to a reader that has not
    /// acknowledged it. `writer.heartbeat_period_ms`, env
    /// `ZERODDS_WRITER_HEARTBEAT_PERIOD_MS`; default 100 ms
    /// ([`zerodds_rtps::reliable_writer::DEFAULT_HEARTBEAT_PERIOD`]).
    pub writer_heartbeat_period: Duration,

    /// `R::heartbeatResponseDelay` of every user reader (DDSI-RTPS 2.5
    /// §8.4.10.1): how long a reader waits after a HEARTBEAT before it
    /// answers. `reader.heartbeat_response_delay_ms`, env
    /// `ZERODDS_READER_HEARTBEAT_RESPONSE_DELAY_MS`; default 500 ms, the
    /// spec's ([`zerodds_rtps::reliable_reader::DEFAULT_HEARTBEAT_RESPONSE_DELAY`]);
    /// 0 answers on the next tick. The built-in discovery readers keep the
    /// default.
    pub reader_heartbeat_response_delay: Duration,

    /// `R::heartbeatSuppressionDuration` of every user reader (DDSI-RTPS 2.5
    /// §8.4.10.1): a HEARTBEAT that arrives less than this long after the
    /// previous one of its writer is ignored.
    /// `reader.heartbeat_suppression_duration_ms`, env
    /// `ZERODDS_READER_HEARTBEAT_SUPPRESSION_DURATION_MS`; default 0, the
    /// specification's value.
    pub reader_heartbeat_suppression_duration: Duration,

    /// Whether a user reader refuses a SerializedPayload beyond the
    /// `dataMaxSizeSerialized` a matched writer announced (DDSI-RTPS 2.5
    /// §8.4.10.4, Table 8.72: "the maximum size of any SerializedPayload
    /// that may be sent by the matched Writer"). `false` takes the payload
    /// whatever the announcement says: Fast DDS 3.6.1 announces 160 octets
    /// for the OMG dds-rtps `ShapeType` and sends samples of 100 036
    /// (`Test_LargeData_0`). `reader.honor_data_max_size_serialized`, env
    /// `ZERODDS_READER_HONOR_DATA_MAX_SIZE_SERIALIZED`; default `true`.
    pub reader_honor_data_max_size_serialized: bool,

    /// Whether a user reader takes a lifecycle marker that carries both the
    /// DisposedFlag and the UnregisteredFlag of PID_STATUS_INFO (DDSI-RTPS
    /// 2.5 §9.6.3.9) as a dispose and an unregister. `false` takes it as an
    /// unregister only, so the instance goes to NOT_ALIVE_NO_WRITERS once its
    /// last writer is gone: the state the OMG dds-rtps suite expects in
    /// `Test_FinalInstanceState_2` of a publisher that disposes and
    /// unregisters its instances in one marker when its writer is deleted
    /// (DDS 1.4 §2.2.2.4.1.6 and §2.2.3.21; OpenDDS 3.35.0-dev, measured).
    /// `reader.dispose_with_unregister`, env
    /// `ZERODDS_READER_DISPOSE_WITH_UNREGISTER`; default `true`.
    pub reader_dispose_with_unregister: bool,

    /// `W::nackSuppressionDuration` of every user writer (DDSI-RTPS 2.5
    /// §8.4.7.1): a NACK for a change that went out less than this long
    /// ago is ignored. `writer.nack_suppression_duration_ms`, env
    /// `ZERODDS_NACK_SUPPRESSION_DURATION_MS`; default 0, the spec's.
    pub nack_suppression_duration: Duration,

    /// Flow-control window of every user writer with reliable readers:
    /// octets of serialized payload written and not yet acknowledged by
    /// all of them. A write that would go past it waits for
    /// acknowledgements up to RELIABILITY `max_blocking_time`, then goes
    /// out past it. `writer.unacked_window_bytes`, env
    /// `ZERODDS_WRITER_UNACKED_WINDOW`; default
    /// [`zerodds_rtps::reliable_writer::DEFAULT_UNACKED_WINDOW`], `0` for
    /// none.
    pub writer_unacked_window: usize,

    /// Whether deleting a DataWriter unregisters its instances — and, with
    /// WRITER_DATA_LIFECYCLE `autodispose_unregistered_instances`, disposes
    /// them — on the wire, as DDS 1.4 §2.2.2.4.1.6 and §2.2.3.21 have it.
    /// `false` sends neither: readers take the instances to
    /// NOT_ALIVE_NO_WRITERS when the SEDP dispose of the publication
    /// arrives, the state a reader ends in with Connext 7.7.0, Fast DDS
    /// 3.6.1, CoreDX 6.15.3 and HDDS 1.4.6 as the publisher (OMG dds-rtps
    /// `Test_FinalInstanceState_2`). `writer.unregister_on_delete`, env
    /// `ZERODDS_WRITER_UNREGISTER_ON_DELETE`; default `true`.
    pub writer_unregister_on_delete: bool,

    /// Accept an ACKNACK whose `readerSNState` is empty with `bitmapBase` 0.
    /// DDSI-RTPS 2.5 §9.4.2.6 requires `bitmapBase >= 1`, so by default such
    /// an ACKNACK is invalid and the rest of its message with it. OpenDDS
    /// 3.34.0 and RTI Connext 7.7.0 send it as the ACKNACK of a reader that
    /// holds nothing (recorded sessions under
    /// `tools/wire-capture/rtps-sessions`). The decoders have no participant,
    /// so the setting holds for the process: the runtime sets it at start
    /// when this field is `true` and never clears it, so one runtime that turns
    /// it on turns it on for every runtime in the process.
    /// `wire.accept_empty_acknack_base_zero`, env
    /// `ZERODDS_WIRE_ACCEPT_EMPTY_ACKNACK_BASE_ZERO`; default `false`.
    pub accept_empty_acknack_base_zero: bool,

    /// `CLOCK_SKEW_DETECTED` of DDSI-RTPS 2.5 §8.3.7.4: the largest
    /// difference, in seconds, between the time a message was received and
    /// the `rtpsSendTimestamp` of its HeaderExtension. A message beyond it
    /// sets `clockSkewDetected`, and the InfoTimestamp after it is moved by
    /// the difference (§8.3.8.11). The spec gives no threshold: `0` is off,
    /// and off is the default. `wire.clock_skew_threshold_s`, env
    /// `ZERODDS_WIRE_CLOCK_SKEW_THRESHOLD_S`.
    pub clock_skew_threshold_s: u32,

    /// Every SPDP announcement carries a new sequence number. DDSI-RTPS 2.5
    /// §8.5.3.1 has the SPDP writer's HistoryCache hold one data-object that
    /// `unsent_changes_reset` resends each period, so by default the number
    /// changes only with the participant data. Cyclone DDS and OpenDDS send a
    /// new one each period (recorded sessions under
    /// `tools/wire-capture/rtps-sessions`); `true` does the same.
    /// `discovery.spdp_new_sequence_per_period`, env
    /// `ZERODDS_SPDP_NEW_SEQUENCE_PER_PERIOD`; default `false`.
    pub spdp_new_sequence_per_period: bool,

    /// How long deleting a reliable DataWriter waits for its reliable
    /// readers to acknowledge what it sent — the unregister and dispose
    /// markers of DDS 1.4 §2.2.2.4.1.6 among it — before the writer goes
    /// and its SEDP dispose is sent ([`DcpsRuntime::linger_user_writer`]).
    /// A writer whose readers have acknowledged everything goes at once.
    /// `writer.linger_ms`, env `ZERODDS_WRITER_LINGER_MS`; default
    /// [`DEFAULT_WRITER_LINGER`], `0` to remove the writer at once.
    pub writer_linger: Duration,

    /// Whether a GROUP-scope publisher's writers put
    /// `PID_GROUP_COHERENT_SET` on the DATA of a group coherent set, as
    /// DDSI-RTPS 2.5 §8.7.6 requires. `false` leaves it out for every
    /// reader: HDDS 1.4.8 and Connext 7.7.0 read their sets right only
    /// without it (OMG dds-rtps `Test_CoherentSets_12`, `_18`, `_21`), and a
    /// ZeroDDS subscriber no longer knows a group coherent set's members.
    /// For one peer only, see [`DcpsRuntime::set_peer_rtps_behaviour`] with
    /// [`zerodds_rtps::dialect::GroupCoherentSetPid`].
    /// `writer.group_coherent_set_pid`, env
    /// `ZERODDS_WRITER_GROUP_COHERENT_SET_PID`; default `true`.
    pub writer_group_coherent_set_pid: bool,

    /// Whether a GROUP-scope publisher's writers send the group information
    /// of DDSI-RTPS 2.5 §8.7.5/§8.7.6 (`PID_GROUP_SEQ_NUM`,
    /// `PID_WRITER_GROUP_INFO`, `PID_GROUP_COHERENT_SET`, the GroupInfoFlag
    /// of HEARTBEAT and GAP). `false` sends each writer's coherent set as at
    /// TOPIC scope, the form HDDS and zzdds send and Connext, HDDS and zzdds
    /// read; a ZeroDDS subscriber then orders by writer, not by group. For
    /// one peer only, see [`DcpsRuntime::set_peer_rtps_behaviour`] with
    /// [`zerodds_rtps::dialect::GroupWireForm`].
    /// `writer.group_info_on_wire`, env `ZERODDS_WRITER_GROUP_INFO_ON_WIRE`;
    /// default `true`.
    pub writer_group_info_on_wire: bool,

    /// Send the dispose and unregister of a writer of a topic without a key
    /// (NO_KEY) on the wire. DDSI-RTPS 2.5 §8.2.10.1 gives both "no effect if
    /// the topicKind==NO_KEY", so by default the writer's own instance state
    /// changes (DDS 1.4 §2.2.1.2.2: one instance) and no marker is sent;
    /// `true` sends the marker, status bits only, for a peer that expects
    /// it. `writer.keyless_lifecycle_on_wire`, env
    /// `ZERODDS_WRITER_KEYLESS_LIFECYCLE_ON_WIRE`; default `false`.
    pub keyless_lifecycle_on_wire: bool,

    /// Leave `writerSet` and `secureWriterSet` out of the HEARTBEAT with
    /// group information: the form of the figure of DDSI-RTPS 2.5 §9.4.5.7,
    /// for a peer that does not skip trailing octets of a HEARTBEAT by its
    /// `submessageLength`. `wire.omit_heartbeat_group_digests`, env
    /// `ZERODDS_WIRE_OMIT_HEARTBEAT_GROUP_DIGESTS`; default `false` (Table
    /// 8.44 and §8.7.5 ask for the sets).
    pub omit_heartbeat_group_digests: bool,

    /// Lease duration announced in the SPDP beacon as
    /// `PARTICIPANT_LEASE_DURATION` (spec default 100 s). Also used as the
    /// basis for the AUTOMATIC WLP tick (`wlp_period =
    /// participant_lease_duration / 3` if `wlp_period == Duration::ZERO`).
    pub participant_lease_duration: Duration,

    /// USER_DATA bytes of the participant (DDS 1.4 §2.2.3.1
    /// `UserDataQosPolicy`). Announced in the SPDP beacon as PID_USER_DATA
    /// (DDSI-RTPS §9.6.3.2) and exposed on the receiver side in
    /// `ParticipantBuiltinTopicData.user_data`. Default empty.
    pub user_data: Vec<u8>,

    /// The `PropertyQosPolicy` entries of the participant that go out in
    /// the SPDP beacon as `PID_PROPERTY_LIST` (DDS-Security 1.2 §7.3.21,
    /// §7.5.1.4): only those with `propagate = TRUE`, see
    /// [`crate::qos::propagated_properties`]. Default empty.
    pub participant_properties: zerodds_rtps::property_list::WirePropertyList,

    /// Whether the participant announces itself over SPDP from its start.
    /// A `DomainParticipant` created disabled (DDS 1.4 §2.2.3.20 of its
    /// factory) starts with `false` and turns it on with its `enable`
    /// ([`DcpsRuntime::set_discoverable`]); "the status of a disabled
    /// entity never changes" (§2.2.2.1.1.7). Default `true`.
    pub discoverable: bool,

    /// Observability sink. Default is `null_sink()` — each event emit is
    /// then a direct return without allocation on the consumer side.
    /// Consumers inject e.g.
    /// [`zerodds_foundation::observability::StderrJsonSink`] (JSON lines
    /// for Vector/fluentd/Datadog) or their own OTLP bridge.
    pub observability: zerodds_foundation::observability::SharedSink,

    /// C2(6) — the wall clock behind SOURCE_TIMESTAMP, DESTINATION_ORDER=
    /// BY_SOURCE_TIMESTAMP, `write_w_timestamp` defaults, and the reader's
    /// LIFESPAN/BY_RECEPTION_TIMESTAMP reception clock
    /// ([`crate::time_source::TimeSource`]). File `time.source`: `system`
    /// (default, unchanged — [`crate::time_source::SystemClock`]) or `tai`
    /// (Linux-only [`crate::time_source::TaiClock`], `CLOCK_TAI`); env
    /// `ZERODDS_TIME_SOURCE`. Programmatic sources
    /// ([`crate::time_source::TimeServiceClock`], a
    /// [`crate::time_source::TestClock`], or any other
    /// `Arc<dyn TimeSource>`) are set directly on this field — it has no
    /// file spelling because they are not nameable from a config string.
    pub time_source: Arc<dyn crate::time_source::TimeSource>,

    /// Sprint D.5d lever C, extended by C2(2) — RT pinning + priority.
    /// Linux-only; feature `rt` (`zerodds-rt-linux`). Without that feature a
    /// non-empty request here (or in [`Self::recv_thread_policy`]/
    /// [`Self::recv_thread_deadline`]/[`Self::recv_thread_cpus`]) makes
    /// [`DcpsRuntime::start`] fail — never a silent no-op. On non-Linux
    /// targets, even with `rt` built in, a request fails with `Unsupported`.
    ///
    /// SCHED_FIFO priority (1-99) for the recv worker threads (SPDP MC,
    /// metatraffic, user data, extra recv workers). `None` alongside
    /// [`Self::recv_thread_policy`] `== None` = default scheduler (CFS), no
    /// `sched_setattr` call at all — today's meaning, unchanged.
    /// `None` alongside `recv_thread_policy == Some(Fifo)` or
    /// `Some(RoundRobin)` is a config error (see `resolve_thread_sched`).
    /// `Some(80)` **without** a policy keeps the pre-C2(2) meaning:
    /// `SCHED_FIFO` priority 80 — the spec recommendation for real-time
    /// paths. Requires `CAP_SYS_NICE` or an `RLIMIT_RTPRIO`-permitted user.
    pub recv_thread_priority: Option<i32>,

    /// Like [`Self::recv_thread_priority`], but for the tick worker.
    pub tick_thread_priority: Option<i32>,

    /// C2(2) — `threads.recv_policy`: explicit scheduler class for the recv
    /// worker threads (`other`/`fifo`/`rr`/`deadline`, `sched(7)`). `None`
    /// with [`Self::recv_thread_priority`] set keeps the pre-C2(2) meaning
    /// (`fifo`); `None` with nothing else set either is today's default
    /// (CFS, unchanged). See `resolve_thread_sched` for the full
    /// consistency rules between this field, the priority and the deadline
    /// triple.
    pub recv_thread_policy: Option<ThreadSchedPolicy>,

    /// Like [`Self::recv_thread_policy`], but for the tick worker.
    pub tick_thread_policy: Option<ThreadSchedPolicy>,

    /// C2(2) — `threads.recv_deadline`: the `SCHED_DEADLINE`
    /// `(runtime, deadline, period)` triple for the recv worker threads.
    /// Only meaningful with `recv_thread_policy ==
    /// Some(ThreadSchedPolicy::Deadline)`; any other combination is a
    /// config error (see `resolve_thread_sched`).
    pub recv_thread_deadline: Option<ThreadDeadlineSpec>,

    /// Like [`Self::recv_thread_deadline`], but for the tick worker.
    pub tick_thread_deadline: Option<ThreadDeadlineSpec>,

    /// CPU affinity mask for the recv workers. `None` = no affinity (the
    /// kernel schedules freely). A list of CPU indices, e.g.
    /// `vec![2, 3]` for cores 2+3. Set via `sched_setaffinity` (feature
    /// `rt`); all recv threads share the same mask. An index that is not
    /// one of the host's CPUs is a startup error, never silently skipped.
    pub recv_thread_cpus: Option<Vec<usize>>,

    /// Like [`Self::recv_thread_cpus`], but for the tick worker.
    pub tick_thread_cpus: Option<Vec<usize>>,

    /// Opt-3 (Spec `zerodds-zero-copy-1.0` §9): number of additional
    /// user-data recv workers that listen on the same port as
    /// `user_unicast` via `SO_REUSEPORT`. `0` (default) = only the primary
    /// `recv_user_data_loop` worker. Under high recv load the pool scales
    /// linearly with cores (kernel flow hashing distributes incoming
    /// datagrams). Recommended values: 1-3 additional workers per CPU
    /// core.
    pub extra_recv_threads: usize,

    /// D.5g — default DataRepresentation list announced in SEDP
    /// PublicationData and SEDP SubscriptionData, when not overridden
    /// per-writer/reader (UserWriterConfig/UserReaderConfig).
    ///
    /// **Important**: per strict spec (XTypes 1.3 §7.6.3.1.2) the first
    /// element is the writer's "offered" and must be in the reader's
    /// "accepted" list for a match to happen. Default `[XCDR1]`, the default
    /// of §7.6.3.1.1; `[XCDR1, XCDR2]` (the ROS profiles) and `[XCDR2]` or
    /// `[XCDR2, XCDR1]` are settings.
    ///
    /// Empty (`vec![]`) is interpreted per spec as `[XCDR1]`.
    pub data_representation_offer: Vec<i16>,

    /// D.5g — default match mode for DataRepresentation negotiation.
    ///
    /// `Strict` (XTypes 1.3 §7.6.3.1.2 normative): writer.first ∈
    /// reader.list = match. `Tolerant` (industry norm): any overlap =
    /// match, picks the first overlap as the wire format.
    ///
    /// Default `Strict`, the clause: §7.6.3.1.1 makes an offer compatible
    /// with a request exactly when the writer's offered representation is
    /// in the reader's sequence. `Tolerant` is what Cyclone DDS and Fast DDS
    /// do and is selected with `ZERODDS_DATA_REPR_MATCH=tolerant` or the
    /// configuration file when a peer needs it.
    pub data_rep_match_mode: zerodds_rtps::publication_data::data_representation::DataRepMatchMode,
    /// `transport.tcp_locator_kinds`, env `ZERODDS_TCP_LOCATOR_KINDS`:
    /// `false` (`vendor`, default) sends TCP locators with ZeroDDS's own
    /// kinds in the vendor range of DDSI-RTPS 2.5 §9.3.2.4 (`0x01F0_0004`,
    /// `0x01F0_0005`); `true` (`fast-dds`) sends 4 and 8, the values of Fast
    /// DDS, for TCP interoperation with it. Reading accepts both. The
    /// setting is the process's and is only ever turned on at `start`.
    pub tcp_locator_kinds_fast_dds: bool,
    /// XTypes 1.3 Table 19 key-member bullets: `enforced` (the clause,
    /// default) or `ignored`. File: `xtypes.key_member_bounds`; see
    /// `zerodds_types::assignability::KeyMemberBounds`.
    pub key_member_bounds: zerodds_types::assignability::KeyMemberBounds,
    /// XTypes 1.3 §7.2.4.3 strong assignability: `equivalence` (the clause,
    /// default) or `names_ignored`. File: `xtypes.strong_assignability`; see
    /// `zerodds_types::assignability::StrongAssignability`.
    pub strong_assignability: zerodds_types::assignability::StrongAssignability,
    /// What a remote reader that announces no `TypeConsistencyEnforcement`
    /// is taken to request: `disallow` (the clause, §7.6.3.4.1; default) or
    /// `allow` for a peer that does not write PID `0x0074` and is to be
    /// matched by assignability. File: `xtypes.type_consistency_absent`.
    pub absent_type_consistency: AbsentTypeConsistency,
    /// The order of the parameters of a `CompleteAnnotationType`:
    /// `member-index` (DDS-XTypes 1.3 §7.3.4.5, the declaration order; the
    /// default) or `name` (the comment in Annex B). Process-wide; see
    /// `zerodds_types::type_object::complete::AnnotationParameterOrder`.
    /// File: `xtypes.annotation_parameter_order`.
    pub annotation_parameter_order: zerodds_types::type_object::complete::AnnotationParameterOrder,

    /// Writers encode big-endian (`*_BE` encapsulation) instead of
    /// little-endian. A measurement and interop switch; default `false`.
    /// File: `wire.big_endian`; env `ZERODDS_WIRE_BIG_ENDIAN`.
    pub wire_big_endian: bool,

    /// Endpoints announce their type also as the `TypeObjectV1` of
    /// DDS-XTypes 1.1 Annex B (`type`, `PID` 0x0072) and its `TypeIdV1`
    /// (`type_id`, 0x0069), the optional members of the built-in topic data
    /// of XTypes 1.3 Annex D, beside the `TypeInformation` they always
    /// announce. A type that has no form in Annex B of 1.1 (a bit set with
    /// bit fields, `int8`, a type that refers to itself) is announced
    /// without them. Default `false`: the 1.3 peers this project is
    /// measured against do not read them. File: `discovery.type_object_v1`;
    /// env `ZERODDS_TYPE_OBJECT_V1`.
    pub type_object_v1: bool,

    /// Root directory of the on-disk store a PERSISTENT writer creates.
    /// `None` = `std::env::temp_dir().join("zerodds-durability")`.
    /// File: `durability.dir`; env `ZERODDS_DURABILITY_DIR`.
    pub durability_dir: Option<std::path::PathBuf>,

    /// SROS2 enclave directory (`identity_ca.cert.pem`, `cert.pem`,
    /// `key.pem`, `permissions_ca.cert.pem`, `governance.p7s`,
    /// `permissions.p7s`). Set, every participant is secured from it: the
    /// Rust `DomainParticipantFactory`, the ROS 2 RMW and
    /// `zerodds_runtime_create_secure_from_env`; a build without the
    /// `security` feature and the C-API's plain constructors refuse it. A
    /// set directory that does not load is an error, never a plain
    /// participant. File: `security.enclave_dir`; env
    /// `ZERODDS_SECURITY_DIR`.
    pub security_enclave_dir: Option<std::path::PathBuf>,

    /// The vendor-form settings of the security plugins (`security.*`),
    /// resolved over the environment and the files: the participant's
    /// security profile reads them from here.
    pub security_vendor_settings: SecurityVendorSettings,

    /// DDSI-RTPS 2.5 §8.5.3.2 `domainTag`. Not empty, it goes out in
    /// `PID_DOMAIN_TAG`; a participant whose tag differs — the absent PID
    /// being the empty tag — is not discovered. File: `discovery.domain_tag`;
    /// env `ZERODDS_DOMAIN_TAG`. Default empty.
    pub domain_tag: String,

    /// Participant default of the delivery mode. File: `delivery.mode`; env
    /// `ZERODDS_DELIVERY_MODE`.
    pub delivery_mode: DeliveryMode,

    /// The clock the TIME_BASED_FILTER of this participant's readers
    /// measures on. File: `reader.time_based_filter_clock`; env
    /// `ZERODDS_READER_TIME_BASED_FILTER_CLOCK`; default `sender`.
    pub reader_time_based_filter_clock: TimeBasedFilterClock,

    /// Whether a coherent set is held back under PRESENTATION
    /// `access_scope` INSTANCE ([`PresentationInstanceCoherence`]). File:
    /// `dcps.presentation_instance_coherence`; env
    /// `ZERODDS_PRESENTATION_INSTANCE_COHERENCE`; default `per_instance`.
    pub presentation_instance_coherence: PresentationInstanceCoherence,

    /// TIME_BASED_FILTER for ROS 2 subscriptions, see
    /// [`TimeBasedFilterEntry`]. File: `ros2.time_based_filter` (a list);
    /// env `ZERODDS_TIME_BASED_FILTER` (a comma list).
    pub ros2_time_based_filter: Vec<TimeBasedFilterEntry>,

    /// zerodds-async-1.0 §4 — when `true`, `start()` does **not** spawn the
    /// dedicated `zdds-tick` std::thread. The periodic tick (SPDP announce,
    /// SEDP/WLP, deadline/lifespan/liveliness) must then be driven externally
    /// via [`DcpsRuntime::tick_driver`]. Used by the async API's
    /// `spawn_in_tokio`, which multiplexes many participants' tick loops onto
    /// a tokio runtime instead of one thread each. Default `false` (internal
    /// thread, unchanged behaviour). The recv worker threads are unaffected —
    /// they block on socket recv and stay regardless.
    pub external_tick: bool,

    /// Per-peer RTPS behaviour ([`zerodds_rtps::dialect`]): which dispose
    /// form the SEDP writers send, whether every datagram states its
    /// destination prefix, and where the directed SPDP response goes.
    ///
    /// The table carries a participant-wide default plus per-peer overrides.
    /// The default comes from `wire.rtps_dialect`: `cyclone`, `fastdds`,
    /// `opendds` or `maximally-interoperable`, the vendor names spelled as
    /// [`zerodds_ast_layout::Dialect::parse`] spells them for the codec
    /// layout. Unset means [`RtpsDialect::MaximallyInteroperable`], which is
    /// what ZeroDDS sent before the switch existed: a switch that shifts the
    /// wire when it is not set would be worse than no switch.
    ///
    /// An override for one peer is explicit and stays with the integrator —
    /// [`DcpsRuntime::set_peer_rtps_dialect`]. Nothing infers a dialect from
    /// a `vendorId`, which is a field the remote controls; the few places that
    /// read a `vendorId` for a vendor-defined format are listed in
    /// [`zerodds_rtps::dialect`].
    pub rtps_behaviour: BehaviourTable,

    /// D.5e Phase 3 — when `true`, `start()` drives the periodic tick via the
    /// event-driven deadline scheduler ([`crate::scheduler`]) instead of the
    /// fixed-`tick_period` poll: the worker parks until the next due deadline
    /// (SPDP announce, or a fine floor while user endpoints/QoS timers are
    /// active) or until a write/recv `raise` wakes it — no busy-poll, lower idle
    /// CPU, lower tail latency. The work done per wake is the **unchanged**
    /// `run_tick_iteration` (identical wire output + cadence — cross-vendor
    /// safe). **Default `true`**; set `runtime.scheduler_tick=0` or this field
    /// to `false` for the classic fixed-period `tick_loop`. Mutually exclusive
    /// with `external_tick` (external wins).
    pub scheduler_tick: bool,

    /// The `wire.rtps_dialect` spelling that named no dialect, if there was
    /// one. [`Self::rtps_behaviour`] then carries
    /// [`RtpsDialect::MaximallyInteroperable`] — a participant that refuses to
    /// start over a configuration typo takes a running system down for a wire
    /// detail. It is not silent about it either: [`DcpsRuntime::start`] records
    /// `config.rtps_dialect.unknown` with this spelling and the four that
    /// exist, so the deployment that asked to speak to a peer learns it is not
    /// speaking to that peer. `None` (the programmatic default) = nothing to
    /// complain about.
    pub rtps_dialect_unknown: Option<String>,

    /// The CDR dialect the runtime's reflective codecs read and write in:
    /// the bodies and keys `SerializedTypeSupport` checks and derives for a
    /// language binding, and, through [`DcpsRuntime::codec_dialect`], the
    /// dynamic codecs of the bridges and the ROS 2 shim.
    ///
    /// `wire.codec_dialect`, spelled as `zerodds_ast_layout::Dialect::parse`
    /// spells it and `zerodds-idlc generate --dialect` takes it; the
    /// default is `specification`. It is the dialect the application's types
    /// were generated in: a binding generated with `--dialect fastdds` writes
    /// Fast DDS's PL_CDR1 framing, and a runtime checking its bodies in the
    /// specification's reports every one of them as malformed. Like the RTPS
    /// dialect, it is configured and never inferred from a peer's vendor id.
    pub codec_dialect: zerodds_ast_layout::Dialect,

    /// The `wire.codec_dialect` spelling that named no dialect, if there was
    /// one. [`Self::codec_dialect`] is then the specification's, and
    /// [`DcpsRuntime::start`] records `config.codec_dialect.unknown`, as for
    /// [`Self::rtps_dialect_unknown`].
    pub codec_dialect_unknown: Option<String>,

    /// Which table the identifiers of the encapsulation header of a user
    /// sample are taken from.
    ///
    /// DDS-XTypes 1.3 names the identifiers of encoding version 2 and of
    /// XML in two tables that do not agree: Table 39 (§7.4.3.4,
    /// `ENC_HEADER`, repeated by DDSI-RTPS 2.5 Table 10.3) has
    /// `{0x00, 0x10}` to `{0x00, 0x15}` and `{0x01, 0x00}`, Table 60
    /// (§7.6.3.1.2) has `{0x00, 0x06}` to `{0x00, 0x0b}` and
    /// `{0x00, 0x04}`. The default is
    /// [`EncapsulationIds::Table60`](zerodds_wire_codec::value::EncapsulationIds),
    /// which Cyclone DDS, RTI Connext and Fast DDS were measured writing;
    /// `Table39` makes the runtime write the other. A reader takes both in
    /// either setting. Programmatic only: there is no configuration key.
    pub encapsulation_ids: zerodds_wire_codec::value::EncapsulationIds,

    /// The PL_CDR1 header policy the reflective codecs use in place of the
    /// one of [`Self::codec_dialect`]; `None` keeps the dialect's.
    /// `wire.pl_cdr1_headers`, env `ZERODDS_WIRE_PL_CDR1_HEADERS`; `dialect`
    /// (the default) or a name of `zerodds_ast_layout::PlCdr1HeaderPolicy`.
    /// The XTypes 1.3 §7.4.1.2 length (exact) is the specification
    /// dialect's; `short-rounded-length` is DDSI-RTPS 2.5 §9.4.2.11's.
    /// One setting for the process: the codecs read it where no runtime is
    /// at hand, and the first runtime that sets it sets it for all.
    pub pl_cdr1_headers: Option<zerodds_ast_layout::PlCdr1HeaderPolicy>,

    /// Whether the reflective PL_CDR1 reader takes a stream another
    /// implementation framed (XTypes 1.3 §7.4.1.2.1, §7.4.1.2.2).
    /// `wire.pl_cdr1_reading`, env `ZERODDS_WIRE_PL_CDR1_READING`; `strict`
    /// (default) or `tolerant`. One setting for the process, as
    /// [`Self::pl_cdr1_headers`].
    pub pl_cdr1_reading: zerodds_ast_layout::PlCdr1Reading,

    /// The encoding the TypeLookup service writes its requests and replies
    /// in. [`TypeLookupEncoding::Xcdr2`](zerodds_types::type_lookup::TypeLookupEncoding)
    /// (`CDR2_LE`) is the default: XTypes 1.4 Beta 1 §7.6.3.3.3 makes the
    /// data representation of these endpoints encoding version 2 (OMG issue
    /// DDSXTY14-29), the form the measured vendors send. `xcdr1` writes
    /// `CDR_LE`, the reading of XTypes 1.3, which names no representation for
    /// them (§7.6.3.1.1, Table 60), and of DDSI-RTPS 2.5 §10.4 Table 10.2. A
    /// received sample is read in the encoding its identifier names, in
    /// either setting. `wire.type_lookup_encoding`, env
    /// `ZERODDS_WIRE_TYPE_LOOKUP_ENCODING`; `xcdr2` (default) or `xcdr1`.
    pub type_lookup_encoding: zerodds_types::type_lookup::TypeLookupEncoding,

    /// Interface the TSN user transport binds to (AF_PACKET needs a concrete
    /// interface; it is not bindable to `0.0.0.0` like UDP/TCP). Default from
    /// the config `tsn.interface`; `None` makes
    /// `user_transport = Some(UserTransportKind::Tsn)` fail at
    /// [`DcpsRuntime::start`]. Only read for that transport kind.
    pub tsn_interface: Option<String>,

    /// VLAN id of the TSN user transport. Default from the env
    /// `tsn.vlan`, otherwise `0`. Only read for
    /// `UserTransportKind::Tsn`.
    pub tsn_vlan: u16,

    /// PCP (priority code point) of the TSN user transport. Default from the
    /// config `tsn.pcp`, otherwise `0`. Only read for
    /// `UserTransportKind::Tsn`.
    pub tsn_pcp: u8,

    /// C1 multicast-free discovery: unexpanded initial-peer specs (`ip` or
    /// `ip:port`), default from the config `discovery.peers` (comma list).
    /// [`DcpsRuntime::start`] expands them domain-aware — the SPDP unicast port
    /// depends on the domain id, which a `RuntimeConfig` does not know — and
    /// appends the result to [`Self::initial_peers`]. A caller that already has
    /// locators uses `initial_peers` directly; this field is for the spec form
    /// an operator writes.
    pub initial_peer_specs: Vec<String>,

    /// Number of participant indices a port-less entry of
    /// [`Self::initial_peer_specs`] is expanded to (Cyclone equivalent:
    /// `MaxAutoParticipantIndex`). The beacon thereby reaches the first N
    /// participants of the peer host via their well-known SPDP unicast ports.
    /// Default `INITIAL_PEER_MAX_PARTICIPANTS` (10), env
    /// `discovery.max_peer_participants` (e.g. for dense multi-robot / >10
    /// participants-per-host scenarios), clamped to `1..=120` (= the
    /// well-known-port allocation window).
    pub initial_peer_max_participants: u32,

    /// The port-mapping parameters PB, DG, PG, d0..d3 of DDSI-RTPS 2.5
    /// §9.6.2.3, which an implementation must expose. `ports.port_base`,
    /// `ports.domain_gain`, `ports.participant_gain`, `ports.d0` to
    /// `ports.d3` (env `ZERODDS_PORT_BASE`, `ZERODDS_PORT_DOMAIN_GAIN`,
    /// `ZERODDS_PORT_PARTICIPANT_GAIN`, `ZERODDS_PORT_D0` to
    /// `ZERODDS_PORT_D3`). Default: the values of the spec. The runtime
    /// binds d0, d1 and, with `transport.user_multicast`, d2; the
    /// user-traffic unicast sockets take an ephemeral port, which the
    /// participant announces, so d3 is carried in the mapping unbound.
    pub port_mapping: zerodds_rtps::wire_types::PortMapping,

    /// Print the transport error of a failed user-traffic send on stderr.
    /// Default `false`, config `diagnostics.trace_send_errors=1`. A send that fails is
    /// otherwise dropped where it happens — RTPS repairs a lost datagram, so
    /// the per-send error is diagnostic, not an event.
    pub trace_send_err: bool,

    /// Dump the accumulated phase-latency counters on stderr when the runtime
    /// is dropped. Default `false`, config `diagnostics.phase_dump=1`. Only useful
    /// together with [`Self::phase_timing`], which is what fills them.
    pub phase_dump: bool,

    /// Take `Instant::now()` around the sub-phases of the send and receive hot
    /// paths and accumulate them into `PHASE_*` counters. Default `false`, env
    /// `diagnostics.phase_timing=1`. Off in production: a per-phase
    /// `Instant::now()` costs ~50 ns, which at a 6 µs send is 1 % overhead and
    /// skews the very measurement it is taken for.
    pub phase_timing: bool,

    /// Socket options and the connected-socket cache of every UDP socket the
    /// runtime binds. Files: `transport.udp.connected_cache`,
    /// `transport.udp.cache_max_entries`, `transport.udp.cache_sndbuf`,
    /// `transport.udp.recv_buffer`, `transport.udp.dont_route`; env
    /// `ZERODDS_UDP_CACHE_ENABLE`, `ZERODDS_UDP_CACHE_MAX`,
    /// `ZERODDS_UDP_CACHE_SNDBUF`, `ZERODDS_UDP_RCVBUF`,
    /// `ZERODDS_UDP_DONTROUTE`. A buffer size of 0 leaves the kernel default.
    pub udp: UdpTransportConfig,
}

/// Configuration entry for a physical or logical network interface.
///
/// A binding describes an outbound socket: which IP/port it binds to,
/// which `NetInterface` class the interface represents, and which IP
/// range counts as "associated peers" (routing match).
#[cfg(feature = "security")]
#[derive(Clone, Debug)]
pub struct InterfaceBindingSpec {
    /// Name for diagnostics + log attribution (e.g. `"eth0"`, `"tun0"`,
    /// `"lo"`).
    pub name: String,
    /// Bind address. `0.0.0.0` leaves the interface to the kernel.
    pub bind_addr: Ipv4Addr,
    /// Bind port. `0` = ephemeral.
    pub bind_port: u16,
    /// Interface class — feeds into the PolicyEngine context.
    pub kind: NetInterface,
    /// Destination IP range this binding is responsible for. Example:
    /// `127.0.0.0/8` for loopback. A target whose IP lies in this range is
    /// routed to this binding.
    pub subnet: IpRange,
    /// If `true`: this binding is used when **no** other subnet match
    /// applies. Exactly one entry should have `default = true` (usually
    /// the WAN binding).
    pub default: bool,
}

/// Fully bound interface with its UDP socket.
#[cfg(feature = "security")]
struct InterfaceBinding {
    spec: InterfaceBindingSpec,
    socket: Arc<UdpTransport>,
}

/// Pool of per-interface UDP sockets with target-based routing.
///
/// Decision:
/// 1. Iterates over all bindings; the first whose subnet contains the
///    target wins.
/// 2. If no match and a default binding exists → default path.
/// 3. No match + no default → `None`, the caller drops.
#[cfg(feature = "security")]
struct OutboundSocketPool {
    bindings: Vec<InterfaceBinding>,
    default_idx: Option<usize>,
}

#[cfg(feature = "security")]
impl OutboundSocketPool {
    fn bind_all(specs: &[InterfaceBindingSpec], udp: &UdpTransportConfig) -> Result<Self> {
        let mut bindings = Vec::with_capacity(specs.len());
        for spec in specs {
            let socket =
                UdpTransport::bind_v4_with_config(spec.bind_addr, spec.bind_port, udp.clone())
                    .map_err(|_| DdsError::TransportError {
                        label: "interface-binding bind_v4 failed",
                    })?;
            // Short read timeout so that the per-interface inbound poll in
            // the event loop becomes non-blocking. 5 ms is small enough not
            // to create latency elsewhere (the tick period defaults to
            // 50 ms), but large enough to amortize context switches.
            let socket = socket
                .with_timeout(Some(Duration::from_millis(5)))
                .map_err(|_| DdsError::TransportError {
                    label: "interface-binding set_timeout failed",
                })?;
            bindings.push(InterfaceBinding {
                spec: spec.clone(),
                socket: Arc::new(socket),
            });
        }
        let default_idx = bindings.iter().position(|b| b.spec.default);
        Ok(Self {
            bindings,
            default_idx,
        })
    }

    /// Returns `(socket, NetInterface class)` for a destination locator.
    /// `None` if neither a subnet match nor a default binding exists.
    fn route(&self, target: &Locator) -> Option<(&Arc<UdpTransport>, NetInterface)> {
        let ip = ipv4_from_locator(target)?;
        let addr = core::net::IpAddr::V4(core::net::Ipv4Addr::from(ip));
        for b in &self.bindings {
            if b.spec.subnet.contains(&addr) {
                return Some((&b.socket, b.spec.kind.clone()));
            }
        }
        let idx = self.default_idx?;
        let b = self.bindings.get(idx)?;
        Some((&b.socket, b.spec.kind.clone()))
    }
}

/// True if the locator is routable over the user-data transport
/// (trait object). Accepts UDPv4, UDPv6, TCPv4, Shm. The concrete
/// transport (UdpTransport/TcpTransport/ShmUserTransport) then returns
/// `UnsupportedLocator` for kinds it does not itself speak;
/// the filter here only prevents sending to clearly non-IP/SHM
/// locators like UDS (for which we have no transport plugin).
fn is_routable_user_locator(loc: &Locator) -> bool {
    matches!(
        loc.kind,
        LocatorKind::UdpV4
            | LocatorKind::UdpV6
            | LocatorKind::Tcpv4
            | LocatorKind::Tcpv6
            | LocatorKind::Shm
            | LocatorKind::Uds
            | LocatorKind::Tsn
    )
}

/// Unicast targets for the WLP heartbeat fan-out (M-2): per discovered peer the
/// `metatraffic_unicast_locators` (fallback `default_unicast_locators`), filtered
/// to routable kinds. WLP is metatraffic (DDSI-RTPS §8.4.13); in multicast-
/// free environments (container/cloud) the pure multicast pulse never reaches the
/// peer reader → the lease expires although the peer is alive. The additional
/// unicast fan-out follows the SEDP locator model.
/// The initial peers (`discovery.peers`) that none of the `discovered`
/// participants' metatraffic locators already is: the ones the SPDP beacon
/// still has to go to as an initial peer ([`DcpsRuntime::send_spdp_unicast`]).
fn uncovered_initial_peers<'a>(
    initial: &'a [Locator],
    discovered: &'a [Locator],
) -> impl Iterator<Item = &'a Locator> + 'a {
    initial
        .iter()
        .filter(move |peer| !discovered.contains(peer))
}

fn wlp_unicast_targets(peers: &[zerodds_discovery::spdp::DiscoveredParticipant]) -> Vec<Locator> {
    // #27 fan-out: a peer may advertise several metatraffic locators (multi-
    // homed). UDP cannot tell which one is reachable, so send the WLP pulse to
    // every deduplicated usable one — the reachable locator delivers, the rest
    // fall on the floor.
    let mut out: Vec<Locator> = Vec::new();
    for dp in peers {
        for loc in dp.data.metatraffic_or_default_unicast_locators() {
            if is_routable_user_locator(&loc) && !out.contains(&loc) {
                out.push(loc);
            }
        }
    }
    out
}

/// Sends the ACKNACKs that answer remote WLP writers' HEARTBEATs in
/// `input` ([`crate::wlp::WlpEndpoint::heartbeat_responses`]), each to the
/// metatraffic locators of the participant whose writer sent it. A
/// participant not (yet) discovered has no locator to answer at; its next
/// HEARTBEAT after discovery is answered.
fn answer_wlp_heartbeats(rt: &DcpsRuntime, input: &[u8], source: Option<&Locator>) {
    let context = receive_context(rt, source);
    let replies = rt
        .wlp
        .lock()
        .map(|mut wlp| wlp.heartbeat_responses_in(input, &context))
        .unwrap_or_default();
    if replies.is_empty() {
        return;
    }
    let peers = rt.discovered_participants();
    for (prefix, bytes) in replies {
        let Some(peer) = peers.iter().find(|p| p.sender_prefix == prefix) else {
            continue;
        };
        let Some(secured) = protect_wlp_outbound(rt, &bytes) else {
            continue;
        };
        for loc in wlp_unicast_targets(core::slice::from_ref(peer)) {
            let _ = rt.send_metatraffic(&loc, &secured);
        }
    }
}

/// Targets of the directed SPDP response to a newly discovered participant.
///
/// The axis is [`SpdpResponseTargets`]; this function is only the place the
/// participant's value is read. Which value that is, and why the default is
/// the wider one, is documented at the axis.
fn directed_spdp_targets(
    peer: &zerodds_discovery::spdp::DiscoveredParticipant,
    reply_to: Option<&Locator>,
    targets_axis: SpdpResponseTargets,
) -> Vec<Locator> {
    let mut targets = wlp_unicast_targets(core::slice::from_ref(peer));
    if targets_axis.answers_beacon_source() {
        if let Some(src) = reply_to {
            if is_routable_user_locator(src) && !targets.contains(src) {
                targets.push(*src);
            }
        }
    }
    targets
}

/// Extracts the IPv4 address from a `Locator` (UDP-V4).
/// `None` for SHM/UDS/IPv6.
#[cfg(feature = "security")]
fn ipv4_from_locator(loc: &Locator) -> Option<[u8; 4]> {
    if loc.kind != LocatorKind::UdpV4 {
        return None;
    }
    Some([
        loc.address[12],
        loc.address[13],
        loc.address[14],
        loc.address[15],
    ])
}

