/// The vendor-form settings of the security plugins, as the text the
/// security crates parse: `security.kx_key_fallback`,
/// `security.compatibility_check`, `security.algo_name_nul`,
/// `security.algorithm_names`, `security.subject_name_form` and
/// `security.origin_authentication_fallback`. Each default is the
/// specification's value.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SecurityVendorSettings {
    /// `security.kx_key_fallback`: `spec` or `accept`.
    pub kx_key_fallback: String,
    /// `security.compatibility_check`: `spec` or `ignore`.
    pub compatibility_check: String,
    /// `security.algo_name_nul`: `spec`, `omit`, `mirror` or `by_vendor`.
    pub algo_name_nul: String,
    /// `security.algorithm_names`: `auto`, `1.2` or `1.1`.
    pub algorithm_names: String,
    /// `security.subject_name_form`: `rfc4514`, `x509_name_oneline` or
    /// `xn_flag_oneline`.
    pub subject_name_form: String,
    /// `security.origin_authentication_fallback`: `spec` or `accept`.
    pub origin_authentication_fallback: String,
}

impl Default for SecurityVendorSettings {
    fn default() -> Self {
        Self {
            kx_key_fallback: String::from("spec"),
            compatibility_check: String::from("spec"),
            algo_name_nul: String::from("spec"),
            algorithm_names: String::from("1.2"),
            subject_name_form: String::from("rfc4514"),
            origin_authentication_fallback: String::from("spec"),
        }
    }
}

impl SecurityVendorSettings {
    fn from_source(source: &ConfigSource) -> Self {
        let d = Self::default();
        let get = |name: &str, default: String| source.var(name).unwrap_or(default);
        Self {
            kx_key_fallback: get("ZERODDS_SEC_KX_KEY_FALLBACK", d.kx_key_fallback),
            compatibility_check: get("ZERODDS_SEC_COMPATIBILITY_CHECK", d.compatibility_check),
            algo_name_nul: get("ZERODDS_SEC_ALGO_NAME_NUL", d.algo_name_nul),
            algorithm_names: get("ZERODDS_SEC_ALGORITHM_NAMES", d.algorithm_names),
            subject_name_form: get("ZERODDS_SEC_SUBJECT_NAME_FORM", d.subject_name_form),
            origin_authentication_fallback: get(
                "ZERODDS_SEC_ORIGIN_AUTHENTICATION_FALLBACK",
                d.origin_authentication_fallback,
            ),
        }
    }

    /// The value of the variable `name` (`ZERODDS_SEC_*`) as the security
    /// crates ask for it; `None` for any other name.
    #[must_use]
    pub fn lookup(&self, name: &str) -> Option<String> {
        match name {
            "ZERODDS_SEC_KX_KEY_FALLBACK" => Some(self.kx_key_fallback.clone()),
            "ZERODDS_SEC_COMPATIBILITY_CHECK" => Some(self.compatibility_check.clone()),
            "ZERODDS_SEC_ALGO_NAME_NUL" => Some(self.algo_name_nul.clone()),
            "ZERODDS_SEC_ALGORITHM_NAMES" => Some(self.algorithm_names.clone()),
            "ZERODDS_SEC_SUBJECT_NAME_FORM" => Some(self.subject_name_form.clone()),
            "ZERODDS_SEC_ORIGIN_AUTHENTICATION_FALLBACK" => {
                Some(self.origin_authentication_fallback.clone())
            }
            _ => None,
        }
    }
}

/// The layered source a [`RuntimeConfig`] is read from.
///
/// Lowest first: compiled-in defaults, the process environment under the
/// names of [`SETTINGS`], the files (the platform's
/// [`zerodds_config::SystemLayout`] or the base `--config` names, with
/// drop-ins and includes), and `--set path=value` on the command line.
/// A file therefore overrides an environment variable, and a flag overrides
/// both. [`Self::origin_of`] says which layer a value came from.
#[derive(Debug, Default, Clone)]
pub struct ConfigSource {
    files: Option<zerodds_config::Config>,
}

