    /// The OMG `shape_main` type this fix was measured against:
    /// `@appendable struct ShapeType { @key string<128> color; long x; long
    /// y; long shapesize; }` — the shape Eclipse Cyclone 11.0.1 and RTI
    /// Connext 7.7.0 were captured with, not the richer
    /// `zerodds_dcps::interop::ShapeType` (which also carries
    /// `additional_payload_size`).
    fn shapetype_type_object() -> zerodds_types::TypeObject {
        let ast = alloc::sync::Arc::new(
            zerodds_wire_probe::encode::model_from_idl(
                "@appendable struct ShapeType { @key string<128> color; long x; long y; long \
                 shapesize; };",
                "keyed-shapetype.idl",
            )
            .expect("model"),
        );
        let type_ = zerodds_types::dynamic::DynamicType::find(&ast, "ShapeType").expect("type");
        zerodds_types::TypeObject::Complete(
            zerodds_types::from_ast::complete_type_object(&ast, type_.id()).expect("object"),
        )
    }

    fn shapetype_support() -> alloc::sync::Arc<crate::serialized_type::SerializedTypeSupport> {
        let object = shapetype_type_object();
        let bytes = object.to_bytes_le().expect("encode object");
        crate::serialized_type::SerializedTypeSupport::from_type_object(
            "ShapeType",
            &bytes,
            true,
            1,
        )
        .expect("support")
    }

    /// The KeyHash a full ALIVE `ShapeType` sample with the given `color`
    /// gets — hand-encoded PLAIN_CDR1-LE (natural CDR alignment: the
    /// 4-byte string length, the string bytes incl. NUL, padding to the
    /// next 4-byte boundary, then the three `long` members), independent
    /// of any dispose/key-only decode path. `x`/`y`/`shapesize` are
    /// arbitrary — XTypes 1.3 §7.6.8's Key Holder is built from `@key`
    /// members only, so they must not move the hash.
    fn shapetype_alive_hash(
        support: &crate::serialized_type::SerializedTypeSupport,
        color: &str,
    ) -> [u8; 16] {
        let mut body = alloc::vec::Vec::new();
        let name = color.as_bytes();
        let len = u32::try_from(name.len() + 1).expect("short test string");
        body.extend_from_slice(&len.to_le_bytes());
        body.extend_from_slice(name);
        body.push(0);
        while body.len() % 4 != 0 {
            body.push(0);
        }
        body.extend_from_slice(&1i32.to_le_bytes());
        body.extend_from_slice(&2i32.to_le_bytes());
        body.extend_from_slice(&30i32.to_le_bytes());
        let sample = support
            .read_body(&body, 0, false)
            .expect("decode alive body");
        support.key_material(&sample).expect("keyed").0
    }

    /// The writer's `serializedKey` is decoded in ITS OWN
    /// representation and byte order, not forced to the canonical
    /// big-endian PLAIN_CDR2 Key Holder (XTypes 1.3 §7.6.8 fixes that only
    /// for the hash *computation*, not for what a writer puts on the
    /// wire). Both vectors below are measured against Eclipse Cyclone
    /// 11.0.1 (`shape_main`, topic `Square`, a dispose DATA with the K
    /// flag, `PID_STATUS_INFO=0x00000001`, no `PID_KEY_HASH`, key
    /// `color="BLUE"`) and must decode to the same hash an ALIVE
    /// `color="BLUE"` sample gets, not the hash of `"BLUE1"`.
    #[test]
    fn lifecycle_key_hash_honours_the_writers_own_wire_representation() {
        let support = shapetype_support();
        let alive_blue = shapetype_alive_hash(&support, "BLUE");
        let alive_blue1 = shapetype_alive_hash(&support, "BLUE1");
        assert_ne!(
            alive_blue, alive_blue1,
            "different keys must hash differently"
        );

        // Eclipse Cyclone 11.0.1, XCDR1: CDR_LE, options = 3 padding octets.
        let xcdr1: alloc::vec::Vec<u8> = alloc::vec![
            0x00, 0x01, 0x00, 0x03, 0x05, 0x00, 0x00, 0x00, 0x42, 0x4c, 0x55, 0x45, 0x00, 0x00,
            0x00, 0x00,
        ];
        // Eclipse Cyclone 11.0.1, XCDR2: D_CDR2_LE, options = 3 padding
        // octets, inner DHEADER = 9.
        let xcdr2: alloc::vec::Vec<u8> = alloc::vec![
            0x00, 0x09, 0x00, 0x03, 0x09, 0x00, 0x00, 0x00, 0x05, 0x00, 0x00, 0x00, 0x42, 0x4c,
            0x55, 0x45, 0x00, 0x00, 0x00, 0x00,
        ];
        for wire in [xcdr1, xcdr2] {
            let sample = zerodds_rtps::reliable_reader::DeliveredSample {
                writer_guid: Guid::new(GuidPrefix::from_bytes([9; 12]), EntityId::PARTICIPANT),
                sequence_number: zerodds_rtps::wire_types::SequenceNumber(1),
                payload: zerodds_rtps::payload::Payload::from(wire.clone().into_boxed_slice()),
                kind: zerodds_rtps::history_cache::ChangeKind::NotAliveDisposed,
                key_hash: None,
                source_timestamp: None,
                coherent_set_sn: None,
                coherent_set_end: false,
                related_sample_identity: None,
                eprosima_related_sample_identity: None,
                group: None,
                coherent_set_complete: None,
                original_writer: None,
                forwarded_by: None,
                non_standard_payload: false,
                inline_qos_override: Default::default(),
            };
            let (item, outcome) = delivered_to_user_sample(
                &sample,
                &Default::default(),
                &Default::default(),
                &|_| false,
                true,
                Some(&support),
                &mut InstanceKeyHolders {
                    map: &mut alloc::collections::BTreeMap::new(),
                    max: usize::MAX,
                },
            );
            assert!(
                matches!(outcome, KeyHashComputation::Computed),
                "{wire:02x?} must compute, not fall back"
            );
            match item {
                Some(UserSample::Lifecycle { key_hash, .. }) => {
                    assert_eq!(
                        key_hash, alive_blue,
                        "{wire:02x?} must match the Alive BLUE hash"
                    );
                }
                other => panic!("{wire:02x?}: expected Lifecycle, got {other:?}"),
            }
        }

        // Whenever the wire carries `PID_KEY_HASH` (ZeroDDS' own writer
        // always sends it, alongside the K flag and `serializedKey` when
        // it has the instance's key) `key_hash` is already `Some`, so it
        // is used unchanged and this decode path is never reached.
        let zerodds_own = zerodds_rtps::reliable_reader::DeliveredSample {
            writer_guid: Guid::new(GuidPrefix::from_bytes([9; 12]), EntityId::PARTICIPANT),
            sequence_number: zerodds_rtps::wire_types::SequenceNumber(2),
            payload: zerodds_rtps::payload::Payload::from(
                alloc::vec::Vec::new().into_boxed_slice(),
            ),
            kind: zerodds_rtps::history_cache::ChangeKind::NotAliveDisposed,
            key_hash: Some(alive_blue),
            source_timestamp: None,
            coherent_set_sn: None,
            coherent_set_end: false,
            related_sample_identity: None,
            eprosima_related_sample_identity: None,
            group: None,
            coherent_set_complete: None,
            original_writer: None,
            forwarded_by: None,
            non_standard_payload: false,
            inline_qos_override: Default::default(),
        };
        let (item, outcome) = delivered_to_user_sample(
            &zerodds_own,
            &Default::default(),
            &Default::default(),
            &|_| false,
            true,
            Some(&support),
            &mut InstanceKeyHolders {
                map: &mut alloc::collections::BTreeMap::new(),
                max: usize::MAX,
            },
        );
        assert!(matches!(outcome, KeyHashComputation::NotNeeded));
        match item {
            Some(UserSample::Lifecycle { key_hash, .. }) => assert_eq!(key_hash, alive_blue),
            other => panic!("expected Lifecycle, got {other:?}"),
        }
    }

    /// The `serializedKey` bytes RTI Connext 7.7.0 sent for a ShapeType
    /// dispose of `color="BLUE"` (`Test_FinalInstanceState_1`), D_CDR2_LE:
    /// a 4-byte encapsulation header (`D_CDR2_LE`, 3 padding octets), a
    /// 4-byte DHEADER, then the one `@key` member (`color`) as a CDR2
    /// string — `len=5, "BLUE\0"` — padded to a 4-byte boundary.
    fn rti_shapetype_blue_serialized_key() -> alloc::vec::Vec<u8> {
        alloc::vec![
            0x00, 0x09, 0x00, 0x03, 0x09, 0x00, 0x00, 0x00, 0x05, 0x00, 0x00, 0x00, 0x42, 0x4c,
            0x55, 0x45, 0x00, 0x00, 0x00, 0x00,
        ]
    }

    /// ZeroDDS' own writer's dispose and unregister DATA for a real,
    /// `CompleteTypeObject`-resolved ShapeType instance (`color="BLUE"`),
    /// compared against RTI Connext 7.7.0's own capture
    /// (`Test_FinalInstanceState_1`) — the only one of the three measured
    /// dispose forms Eclipse Cyclone 11.0.1, Fast DDS 3.6.1 and OpenDDS
    /// 3.35 also accepted (4/4 each there; the previous `PID_KEY_HASH`-
    /// only, K-clear marker got 0/4 on all three).
    ///
    /// Exercises the same two production calls
    /// [`DcpsRuntime::write_user_lifecycle`] makes —
    /// [`UserWriterSlot::resolve_key_hash_support`] +
    /// [`crate::serialized_type::SerializedTypeSupport::write_key_only`]
    /// through a real registered `CompleteTypeObject`, then
    /// `ReliableWriter::write_lifecycle` — directly, because
    /// `write_user_lifecycle` sends over a live transport rather than
    /// returning the datagram bytes.
    ///
    /// Not compared against the capture: the SN and the writerId, which
    /// are this test's own fixture values (RTI's capture was 800 samples
    /// into its own run, with its own writer entity id) — the timestamp
    /// is compared, because this test sets it to RTI's own captured
    /// value.
    #[test]
    fn lifecycle_datagram_matches_the_rti_shapetype_capture() {
        let object = shapetype_type_object();
        let hash = zerodds_types::compute_hash(&object).expect("hash");
        let type_identifier = zerodds_types::TypeIdentifier::EquivalenceHashComplete(hash);
        let support = shapetype_support();
        let alive_body = {
            let mut body = alloc::vec::Vec::new();
            body.extend_from_slice(&5u32.to_le_bytes());
            body.extend_from_slice(b"BLUE");
            body.push(0);
            body.extend_from_slice(&[0, 0, 0]);
            body.extend_from_slice(&1i32.to_le_bytes());
            body.extend_from_slice(&2i32.to_le_bytes());
            body.extend_from_slice(&30i32.to_le_bytes());
            body
        };
        let alive = support
            .read_body(&alive_body, 0, false)
            .expect("decode alive body");
        let (blue_hash, blue_holder) = support.key_material(&alive).expect("keyed");
        // RTI's own capture: `cac217c3 18363f8e f1160eee def9e886`.
        // XTypes 1.3 §7.6.8's KeyHash is MD5 of the canonical
        // PLAIN_CDR2-BE key holder whenever the key's max size exceeds 16
        // bytes (`string<128> color` does) — a spec-defined function of
        // the key value alone, so a conformant computation of it gives
        // the same 16 bytes regardless of implementation.
        assert_eq!(
            blue_hash,
            [
                0xca, 0xc2, 0x17, 0xc3, 0x18, 0x36, 0x3f, 0x8e, 0xf1, 0x16, 0x0e, 0xee, 0xde, 0xf9,
                0xe8, 0x86,
            ],
            "ZeroDDS' own KeyHash for color=\"BLUE\" must match RTI's captured PID_KEY_HASH"
        );

        let rt = ShutsDown(
            DcpsRuntime::start(
                9,
                GuidPrefix::from_bytes([0xDA; 12]),
                RuntimeConfig::default(),
            )
            .expect("start runtime"),
        );
        rt.register_type_object(object).expect("register type");
        let eid = rt
            .register_user_writer_kind(
                UserWriterConfig {
                    topic_name: "Square".into(),
                    type_name: "ShapeType".into(),
                    type_identifier,
                    data_representation_offer: Some(alloc::vec![
                        zerodds_rtps::publication_data::data_representation::XCDR2,
                    ]),
                    ..Default::default()
                },
                true,
            )
            .expect("writer");

        let ts = zerodds_rtps::header_extension::HeTimestamp {
            seconds: 0x7f3a_b56a,
            fraction: 0x4d6c_ccaf,
        };
        let (dispose_bytes, unregister_bytes) = {
            let slot_arc = rt.writer_slot(eid).expect("slot");
            let mut slot = slot_arc.lock().expect("lock");
            slot.writer
                .add_reader_proxy(zerodds_rtps::reader_proxy::ReaderProxy::new(
                    Guid::new(
                        GuidPrefix::from_bytes([0xDB; 12]),
                        EntityId::user_reader_with_key([9, 9, 9]),
                    ),
                    alloc::vec![Locator::udp_v4([127, 0, 0, 1], 7410)],
                    Vec::new(),
                    true,
                ));
            let serialized_key = rt
                .lifecycle_serialized_key(&mut slot, &blue_holder)
                .expect("serialized key")
                .expect("writer's type must resolve — it was just registered");
            assert_eq!(
                serialized_key,
                rti_shapetype_blue_serialized_key(),
                "the writer's own serializedKey must match RTI's capture byte for byte"
            );
            let dispose = slot
                .writer
                .write_lifecycle(
                    blue_hash,
                    &serialized_key,
                    zerodds_rtps::inline_qos::status_info::DISPOSED,
                    Some(ts),
                )
                .expect("write_lifecycle dispose");
            let unregister = slot
                .writer
                .write_lifecycle(
                    blue_hash,
                    &serialized_key,
                    zerodds_rtps::inline_qos::status_info::UNREGISTERED,
                    Some(ts),
                )
                .expect("write_lifecycle unregister");
            (dispose[0].bytes.clone(), unregister[0].bytes.clone())
        };

        for (bytes, expected_status) in [
            (
                dispose_bytes,
                zerodds_rtps::inline_qos::status_info::DISPOSED,
            ),
            (
                unregister_bytes,
                zerodds_rtps::inline_qos::status_info::UNREGISTERED,
            ),
        ] {
            let parsed = decode_datagram(&bytes).expect("decode");
            match (
                &parsed.submessages[0].submessage,
                &parsed.submessages[1].submessage,
            ) {
                (ParsedSubmessage::InfoTimestamp(its), ParsedSubmessage::Data(d)) => {
                    assert_eq!(
                        its.timestamp, ts,
                        "INFO_TS must carry RTI's own capture timestamp"
                    );
                    assert!(d.key_flag, "K flag must be set — RTI's own accepted form");
                    assert!(!d.data_flag);
                    let qos = d.inline_qos.as_ref().expect("inline QoS present");
                    let key_hash_param = qos
                        .find(zerodds_rtps::parameter_list::pid::KEY_HASH)
                        .expect("PID_KEY_HASH present");
                    assert_eq!(key_hash_param.value, blue_hash.to_vec());
                    let status_param = qos
                        .find(zerodds_rtps::parameter_list::pid::STATUS_INFO)
                        .expect("PID_STATUS_INFO present");
                    assert_eq!(status_param.value.len(), 4);
                    let status_value = u32::from_be_bytes(
                        status_param.value[0..4]
                            .try_into()
                            .expect("4-byte status word"),
                    );
                    assert_eq!(status_value, expected_status);
                    assert_eq!(
                        d.serialized_payload.as_ref(),
                        rti_shapetype_blue_serialized_key().as_slice(),
                        "serializedKey bytes must match RTI's own capture"
                    );
                }
                other => panic!("expected [InfoTimestamp, Data], got {other:?}"),
            }
        }
    }

    /// DDSI-RTPS 2.5 §8.2.10.1: dispose and unregister of a NO_KEY writer
    /// "have no effect": no marker is sent and `keyless_lifecycle_not_sent`
    /// counts it. A keyed writer is not affected, and
    /// `writer.keyless_lifecycle_on_wire` sends the marker of a NO_KEY writer.
    #[test]
    fn dispose_and_unregister_of_a_no_key_writer_send_no_marker_unless_asked_for() {
        let cfg_for = |topic: &str| UserWriterConfig {
            topic_name: topic.into(),
            type_name: "NoKeyLifecycleType".into(),
            ..Default::default()
        };
        let run = |on_wire: bool, keyed: bool, prefix: u8| {
            let rt = DcpsRuntime::start(
                9,
                GuidPrefix::from_bytes([prefix; 12]),
                RuntimeConfig {
                    keyless_lifecycle_on_wire: on_wire,
                    ..RuntimeConfig::default()
                },
            )
            .expect("start");
            let eid = rt
                .register_user_writer_kind(cfg_for("NoKeyLifecycleTopic"), keyed)
                .expect("writer");
            for bits in [
                zerodds_rtps::inline_qos::status_info::DISPOSED,
                zerodds_rtps::inline_qos::status_info::UNREGISTERED,
            ] {
                rt.write_user_lifecycle(eid, [0u8; 16], None, bits, None)
                    .expect("lifecycle");
            }
            let counted = rt.keyless_lifecycle_not_sent();
            rt.shutdown();
            counted
        };
        assert_eq!(run(false, false, 0xE1), 2, "no key, by default: not sent");
        assert_eq!(run(true, false, 0xE2), 0, "no key, asked for: sent");
        assert_eq!(run(false, true, 0xE3), 0, "keyed: sent");
    }

    /// `write_user_lifecycle`'s hash-only fallback (`PID_KEY_HASH` alone,
    /// K clear) is not silent: RTI Connext 7.7.0 and CoreDX 6.15.3 act on
    /// that form (`Test_FinalInstanceState_1`, 4/4 disposed), but Eclipse
    /// Cyclone 11.0.1, Fast DDS 3.6.1 and OpenDDS 3.35 do not (0/4) — a
    /// peer running one of those three silently never learns of the
    /// dispose/unregister at all. Exercises both fallback reasons: a
    /// writer whose type is never registered as a `CompleteTypeObject`
    /// (`TypeIdentifier::None`, the default — a hand-written `DdsType`
    /// with no `type_object()` override) disposes twice, and a second
    /// writer disposes/unregisters twice with `key_holder: None` (the
    /// untyped C-FFI vendor-extension surface, which never has a key
    /// value at all) — mirrors
    /// `keyed_reader_without_type_info_reports_unavailable_once`'s check
    /// that `reader.key_hash.unavailable` fires once per (reader, writer),
    /// not once per sample.
    #[test]
    fn writer_lifecycle_fallback_reports_serialized_key_unavailable_once() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::{Component, Level, VecSink};

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt =
            DcpsRuntime::start(9, GuidPrefix::from_bytes([0xDC; 12]), cfg).expect("start runtime");

        // Writer A: type never registered as a CompleteTypeObject.
        let writer_a = rt
            .register_user_writer_kind(
                UserWriterConfig {
                    topic_name: "UnresolvedTypeTopic".into(),
                    type_name: "UnresolvedTestType".into(),
                    ..Default::default()
                },
                true,
            )
            .expect("writer a");
        let holder = alloc::vec![0u8, 0, 0, 7];
        rt.write_user_lifecycle(
            writer_a,
            [0xAAu8; 16],
            Some(&holder),
            zerodds_rtps::inline_qos::status_info::DISPOSED,
            None,
        )
        .expect("dispose a");
        rt.write_user_lifecycle(
            writer_a,
            [0xAAu8; 16],
            Some(&holder),
            zerodds_rtps::inline_qos::status_info::UNREGISTERED,
            None,
        )
        .expect("unregister a");

        // Writer B: the untyped C-FFI vendor-extension surface, which
        // never has a key holder to pass at all.
        let writer_b = rt
            .register_user_writer(UserWriterConfig {
                topic_name: "NoHolderTopic".into(),
                type_name: "NoHolderType".into(),
                ..Default::default()
            })
            .expect("writer b");
        rt.write_user_lifecycle(
            writer_b,
            [0xBBu8; 16],
            None,
            zerodds_rtps::inline_qos::status_info::DISPOSED,
            None,
        )
        .expect("dispose b");
        rt.write_user_lifecycle(
            writer_b,
            [0xBBu8; 16],
            None,
            zerodds_rtps::inline_qos::status_info::UNREGISTERED,
            None,
        )
        .expect("unregister b");

        rt.shutdown();

        let events: alloc::vec::Vec<_> = sink
            .snapshot()
            .into_iter()
            .filter(|e| e.name == "writer.lifecycle.serialized_key_unavailable")
            .collect();
        assert_eq!(
            events.len(),
            2,
            "one event per writer, not per dispose/unregister call: got {events:?}"
        );
        for event in &events {
            assert_eq!(event.level, Level::Warn);
            assert_eq!(event.component, Component::Dcps);
            assert!(
                event.attrs.iter().any(|a| a.key == "topic"),
                "topic attr missing: {event:?}"
            );
            assert!(
                event.attrs.iter().any(|a| a.key == "type"),
                "type attr missing: {event:?}"
            );
            assert!(
                event.attrs.iter().any(|a| a.key == "reason"),
                "reason attr missing: {event:?}"
            );
        }
        let topics: alloc::collections::BTreeSet<_> = events
            .iter()
            .filter_map(|e| {
                e.attrs
                    .iter()
                    .find(|a| a.key == "topic")
                    .map(|a| a.value.clone())
            })
            .collect();
        assert!(topics.contains("UnresolvedTypeTopic"));
        assert!(topics.contains("NoHolderTopic"));
    }

    /// A runtime with a keyed writer of `object` on `topic` and a reader
    /// proxy at a local socket, for the lifecycle markers the writer sends.
    fn lifecycle_marker_rig(
        object: zerodds_types::TypeObject,
        type_name: &str,
        topic: &str,
        prefix: u8,
        sink: alloc::sync::Arc<zerodds_foundation::observability::VecSink>,
    ) -> (ShutsDown, EntityId, std::net::UdpSocket) {
        let hash = zerodds_types::compute_hash(&object).expect("hash");
        let cfg = RuntimeConfig {
            observability: sink,
            ..RuntimeConfig::default()
        };
        let rt = ShutsDown(
            DcpsRuntime::start(9, GuidPrefix::from_bytes([prefix; 12]), cfg).expect("start"),
        );
        rt.register_type_object(object).expect("register type");
        let eid = rt
            .register_user_writer_kind(
                UserWriterConfig {
                    topic_name: topic.into(),
                    type_name: type_name.into(),
                    reliable: false,
                    type_identifier: zerodds_types::TypeIdentifier::EquivalenceHashComplete(hash),
                    data_representation_offer: Some(alloc::vec![
                        zerodds_rtps::publication_data::data_representation::XCDR,
                    ]),
                    ..Default::default()
                },
                true,
            )
            .expect("writer");
        let socket = std::net::UdpSocket::bind("127.0.0.1:0").expect("bind");
        socket
            .set_read_timeout(Some(core::time::Duration::from_secs(2)))
            .expect("timeout");
        let port = socket.local_addr().expect("addr").port();
        rt.writer_slot(eid)
            .expect("slot")
            .lock()
            .expect("lock")
            .writer
            .add_reader_proxy(zerodds_rtps::reader_proxy::ReaderProxy::new(
                Guid::new(
                    GuidPrefix::from_bytes([prefix.wrapping_add(1); 12]),
                    EntityId::user_reader_with_key([9, 9, 9]),
                ),
                alloc::vec![Locator::udp_v4([127, 0, 0, 1], u32::from(port))],
                Vec::new(),
                false,
            ));
        (rt, eid, socket)
    }

    /// The next lifecycle marker on `socket`: its K flag and its payload.
    fn next_lifecycle_marker(socket: &std::net::UdpSocket) -> (bool, alloc::vec::Vec<u8>) {
        let mut buf = [0u8; 2048];
        loop {
            let (n, _) = socket.recv_from(&mut buf).expect("a datagram");
            let parsed = decode_datagram(&buf[..n]).expect("decode");
            for sub in &parsed.submessages {
                if let ParsedSubmessage::Data(d) = &sub.submessage {
                    if !d.data_flag {
                        return (d.key_flag, d.serialized_payload.to_vec());
                    }
                }
            }
        }
    }

    /// A hash-only dispose of an instance the writer never wrote — a Zenoh
    /// `delete` or a DDS-AMQP dispose for an instance another writer put on
    /// the bus — carries the `serializedKey` when the key fits in the
    /// KeyHash: the hash is the key holder itself (DDSI-RTPS 2.5
    /// §9.6.4.8). It went out as `PID_KEY_HASH` alone, the form Cyclone
    /// 11.0.1, Fast DDS 3.6.1 and OpenDDS 3.35 do not act on.
    #[test]
    fn a_hash_only_dispose_of_an_unwritten_instance_reads_the_key_from_the_hash() {
        let ast = alloc::sync::Arc::new(
            zerodds_wire_probe::encode::model_from_idl(
                "@final struct KeyedPointA { @key long id; long value; };",
                "keyed-point.idl",
            )
            .expect("model"),
        );
        let type_ = zerodds_types::dynamic::DynamicType::find(&ast, "KeyedPointA").expect("type");
        let object = zerodds_types::TypeObject::Complete(
            zerodds_types::from_ast::complete_type_object(&ast, type_.id()).expect("object"),
        );
        let bytes = object.to_bytes_le().expect("encode object");
        // `@final`: extensibility 0.
        let support = crate::serialized_type::SerializedTypeSupport::from_type_object(
            "KeyedPointA",
            &bytes,
            true,
            0,
        )
        .expect("support");
        let mut body = alloc::vec::Vec::new();
        body.extend_from_slice(&9i32.to_le_bytes());
        body.extend_from_slice(&0i32.to_le_bytes());
        let (hash, holder) = support
            .key_material(&support.read_body(&body, 0, false).expect("decode"))
            .expect("keyed");
        let mut spelled = [0u8; 16];
        spelled[..4].copy_from_slice(&9i32.to_be_bytes());
        assert_eq!(
            hash, spelled,
            "a long key: the KeyHash is its big-endian octets"
        );

        let sink = alloc::sync::Arc::new(zerodds_foundation::observability::VecSink::new());
        let (rt, eid, socket) =
            lifecycle_marker_rig(object, "KeyedPointA", "KeyedPoint", 0xD4, sink.clone());
        let expected_key = {
            let slot_arc = rt.writer_slot(eid).expect("slot");
            let mut slot = slot_arc.lock().expect("lock");
            rt.lifecycle_serialized_key(&mut slot, &holder)
                .expect("serialized key")
                .expect("the writer's type resolves")
        };
        rt.write_user_lifecycle(
            eid,
            hash,
            None,
            zerodds_rtps::inline_qos::status_info::DISPOSED,
            None,
        )
        .expect("dispose");
        let (key_flag, payload) = next_lifecycle_marker(&socket);
        assert!(key_flag, "the dispose must carry the serializedKey");
        assert_eq!(payload, expected_key);
        assert!(
            !sink
                .snapshot()
                .iter()
                .any(|e| e.name == "writer.lifecycle.serialized_key_unavailable"),
            "nothing to report"
        );
    }

    /// A key that can exceed 16 octets is hashed with MD5, and nothing can
    /// be read back from the hash. A bridge that carried the instance's
    /// sample the other way records its key with
    /// `remember_user_writer_instance`, and the hash-only dispose that
    /// comes back carries it.
    #[test]
    fn a_remembered_instance_gives_a_hash_only_dispose_its_key() {
        let support = shapetype_support();
        let alive_body = {
            let mut body = alloc::vec::Vec::new();
            body.extend_from_slice(&4u32.to_le_bytes());
            body.extend_from_slice(b"RED");
            body.push(0);
            body.extend_from_slice(&1i32.to_le_bytes());
            body.extend_from_slice(&2i32.to_le_bytes());
            body.extend_from_slice(&30i32.to_le_bytes());
            body
        };
        let (red_hash, red_holder) = support
            .key_material(&support.read_body(&alive_body, 0, false).expect("decode"))
            .expect("keyed");

        let sink = alloc::sync::Arc::new(zerodds_foundation::observability::VecSink::new());
        let (rt, eid, socket) = lifecycle_marker_rig(
            shapetype_type_object(),
            "ShapeType",
            "Square",
            0xD6,
            sink.clone(),
        );
        let expected_key = {
            let slot_arc = rt.writer_slot(eid).expect("slot");
            let mut slot = slot_arc.lock().expect("lock");
            rt.lifecycle_serialized_key(&mut slot, &red_holder)
                .expect("serialized key")
                .expect("the writer's type resolves")
        };
        // Without the record: only the hash.
        rt.write_user_lifecycle(
            eid,
            red_hash,
            None,
            zerodds_rtps::inline_qos::status_info::DISPOSED,
            None,
        )
        .expect("dispose");
        assert!(
            !next_lifecycle_marker(&socket).0,
            "an MD5 hash spells nothing"
        );

        rt.remember_user_writer_instance(eid, Some(red_hash), &alive_body, 0, false)
            .expect("remember");
        rt.write_user_lifecycle(
            eid,
            red_hash,
            None,
            zerodds_rtps::inline_qos::status_info::DISPOSED,
            None,
        )
        .expect("dispose");
        let (key_flag, payload) = next_lifecycle_marker(&socket);
        assert!(key_flag, "the remembered key goes out");
        assert_eq!(payload, expected_key);
    }

    /// A dispose whose caller holds only the key hash — the C-FFI, a
    /// Zenoh or DDS-AMQP bridge — still carries the `serializedKey`: the
    /// writer took the instance's key from the instance's first sample.
    /// After `unregister` the writer no longer manages the instance, so a
    /// later hash-only dispose of it falls back to the hash-only form and
    /// says so.
    #[test]
    fn a_hash_only_dispose_carries_the_key_the_writer_recorded() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::VecSink;

        let object = shapetype_type_object();
        let hash = zerodds_types::compute_hash(&object).expect("hash");
        let type_identifier = zerodds_types::TypeIdentifier::EquivalenceHashComplete(hash);
        let support = shapetype_support();
        let alive_body = {
            let mut body = alloc::vec::Vec::new();
            body.extend_from_slice(&5u32.to_le_bytes());
            body.extend_from_slice(b"BLUE");
            body.push(0);
            body.extend_from_slice(&[0, 0, 0]);
            body.extend_from_slice(&1i32.to_le_bytes());
            body.extend_from_slice(&2i32.to_le_bytes());
            body.extend_from_slice(&30i32.to_le_bytes());
            body
        };
        let alive = support
            .read_body(&alive_body, 0, false)
            .expect("decode alive body");
        let (blue_hash, blue_holder) = support.key_material(&alive).expect("keyed");

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt =
            DcpsRuntime::start(9, GuidPrefix::from_bytes([0xDE; 12]), cfg).expect("start runtime");
        rt.register_type_object(object).expect("register type");
        let eid = rt
            .register_user_writer_kind(
                UserWriterConfig {
                    topic_name: "Square".into(),
                    type_name: "ShapeType".into(),
                    reliable: false,
                    type_identifier,
                    data_representation_offer: Some(alloc::vec![
                        zerodds_rtps::publication_data::data_representation::XCDR,
                    ]),
                    ..Default::default()
                },
                true,
            )
            .expect("writer");

        let socket = std::net::UdpSocket::bind("127.0.0.1:0").expect("bind");
        socket
            .set_read_timeout(Some(core::time::Duration::from_secs(2)))
            .expect("timeout");
        let port = socket.local_addr().expect("addr").port();
        {
            let slot_arc = rt.writer_slot(eid).expect("slot");
            let mut slot = slot_arc.lock().expect("lock");
            slot.writer
                .add_reader_proxy(zerodds_rtps::reader_proxy::ReaderProxy::new(
                    Guid::new(
                        GuidPrefix::from_bytes([0xDF; 12]),
                        EntityId::user_reader_with_key([9, 9, 9]),
                    ),
                    alloc::vec![Locator::udp_v4([127, 0, 0, 1], u32::from(port))],
                    Vec::new(),
                    false,
                ));
        }
        let expected_key = {
            let slot_arc = rt.writer_slot(eid).expect("slot");
            let mut slot = slot_arc.lock().expect("lock");
            rt.lifecycle_serialized_key(&mut slot, &blue_holder)
                .expect("serialized key")
                .expect("the writer's type resolves")
        };
        assert!(!expected_key.is_empty());

        // The dispose marker, as the next datagram on the socket that
        // carries a DATA with the K flag.
        let next_marker = || -> (bool, alloc::vec::Vec<u8>) {
            let mut buf = [0u8; 2048];
            loop {
                let (n, _) = socket.recv_from(&mut buf).expect("a datagram");
                let parsed = decode_datagram(&buf[..n]).expect("decode");
                for sub in &parsed.submessages {
                    if let ParsedSubmessage::Data(d) = &sub.submessage {
                        if !d.data_flag {
                            return (d.key_flag, d.serialized_payload.to_vec());
                        }
                    }
                }
            }
        };

        rt.write_user_sample_keyed(eid, &alive_body, blue_hash, None)
            .expect("write");
        rt.write_user_lifecycle(
            eid,
            blue_hash,
            None,
            zerodds_rtps::inline_qos::status_info::DISPOSED,
            None,
        )
        .expect("dispose");
        let (key_flag, payload) = next_marker();
        assert!(
            key_flag,
            "the hash-only dispose must carry the serializedKey"
        );
        assert_eq!(payload, expected_key);

        rt.write_user_lifecycle(
            eid,
            blue_hash,
            None,
            zerodds_rtps::inline_qos::status_info::UNREGISTERED,
            None,
        )
        .expect("unregister");
        let (key_flag, payload) = next_marker();
        assert!(
            key_flag,
            "the hash-only unregister must carry the serializedKey"
        );
        assert_eq!(payload, expected_key);
        assert!(
            !sink
                .snapshot()
                .iter()
                .any(|e| e.name == "writer.lifecycle.serialized_key_unavailable"),
            "no fallback while the writer knows the instance"
        );

        // Unregistered: the writer no longer knows the instance.
        rt.write_user_lifecycle(
            eid,
            blue_hash,
            None,
            zerodds_rtps::inline_qos::status_info::DISPOSED,
            None,
        )
        .expect("dispose after unregister");
        let (key_flag, _) = next_marker();
        assert!(!key_flag, "after unregister only the hash is left");
        rt.shutdown();
        assert!(
            sink.snapshot()
                .iter()
                .any(|e| e.name == "writer.lifecycle.serialized_key_unavailable"),
            "the fallback is reported"
        );
    }

    /// A sample whose key does not hash to the key hash its caller
    /// supplied leaves nothing recorded and is reported once.
    #[test]
    fn a_key_hash_that_does_not_match_the_sample_is_reported() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::VecSink;

        let object = shapetype_type_object();
        let hash = zerodds_types::compute_hash(&object).expect("hash");
        let type_identifier = zerodds_types::TypeIdentifier::EquivalenceHashComplete(hash);
        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt =
            DcpsRuntime::start(9, GuidPrefix::from_bytes([0xE0; 12]), cfg).expect("start runtime");
        rt.register_type_object(object).expect("register type");
        let eid = rt
            .register_user_writer_kind(
                UserWriterConfig {
                    topic_name: "Square".into(),
                    type_name: "ShapeType".into(),
                    reliable: false,
                    type_identifier,
                    data_representation_offer: Some(alloc::vec![
                        zerodds_rtps::publication_data::data_representation::XCDR,
                    ]),
                    ..Default::default()
                },
                true,
            )
            .expect("writer");
        let mut body = alloc::vec::Vec::new();
        body.extend_from_slice(&4u32.to_le_bytes());
        body.extend_from_slice(b"RED");
        body.push(0);
        body.extend_from_slice(&1i32.to_le_bytes());
        body.extend_from_slice(&2i32.to_le_bytes());
        body.extend_from_slice(&30i32.to_le_bytes());
        for _ in 0..3 {
            rt.write_user_sample_keyed(eid, &body, [0x11; 16], None)
                .expect("write");
        }
        let recorded = {
            let slot_arc = rt.writer_slot(eid).expect("slot");
            let slot = slot_arc.lock().expect("lock");
            slot.instance_key_holders.get(&[0x11; 16]).cloned()
        };
        rt.shutdown();
        assert_eq!(
            recorded,
            Some(alloc::vec::Vec::new()),
            "an empty marker, no key"
        );
        let reports = sink
            .snapshot()
            .into_iter()
            .filter(|e| e.name == "writer.instance.key_unreadable")
            .count();
        assert_eq!(reports, 1, "reported once per writer");
    }

    /// A `@final` type's key-only payload decodes in
    /// the writer's own representation now, not only in the canonical
    /// big-endian PLAIN_CDR2 form: `serialized_key` reads exactly the
    /// `@key` members in declaration order, framed by the type's own
    /// (here: no) extensibility header, so little-endian XCDR1 works
    /// the same as any other representation. This replaces an earlier
    /// version of this test that asserted the opposite — refusing a
    /// non-canonical `@final` representation — back when
    /// `read_key_only` had no real decode for it and the canonical form
    /// was the only one it could tell from a truncated-sample guess.
    #[test]
    fn final_type_lifecycle_key_hash_decodes_a_non_canonical_representation() {
        let support = keyed_final_support();
        // id=7 as little-endian XCDR1 — not the big-endian PLAIN_CDR2
        // `SerializedTypeSupport::decode_key_holder` alone would assume.
        let mut wire = alloc::vec![0x00u8, 0x01, 0x00, 0x00];
        wire.extend_from_slice(&7i32.to_le_bytes());
        let sample = zerodds_rtps::reliable_reader::DeliveredSample {
            writer_guid: Guid::new(GuidPrefix::from_bytes([9; 12]), EntityId::PARTICIPANT),
            sequence_number: zerodds_rtps::wire_types::SequenceNumber(4),
            payload: zerodds_rtps::payload::Payload::from(wire.into_boxed_slice()),
            kind: zerodds_rtps::history_cache::ChangeKind::NotAliveDisposed,
            key_hash: None,
            source_timestamp: None,
            coherent_set_sn: None,
            coherent_set_end: false,
            related_sample_identity: None,
            eprosima_related_sample_identity: None,
            group: None,
            coherent_set_complete: None,
            original_writer: None,
            forwarded_by: None,
            non_standard_payload: false,
            inline_qos_override: Default::default(),
        };
        let (item, outcome) = delivered_to_user_sample(
            &sample,
            &Default::default(),
            &Default::default(),
            &|_| false,
            true,
            Some(&support),
            &mut InstanceKeyHolders {
                map: &mut alloc::collections::BTreeMap::new(),
                max: usize::MAX,
            },
        );
        assert!(matches!(outcome, KeyHashComputation::Computed));
        let alive_body = keyed_final_wire(7, 42);
        let alive_sample = support
            .read_body(&alive_body[4..], 2, false)
            .expect("decode body");
        let alive_hash = { support.key_material(&alive_sample).expect("keyed").0 };
        match item {
            Some(UserSample::Lifecycle { key_hash, .. }) => assert_eq!(key_hash, alive_hash),
            other => panic!("expected Lifecycle, got {other:?}"),
        }
    }

    /// `@appendable struct A { long x; @key long id; long y; };` — the
    /// key is declared second, not first. Support for
    /// `shapetype_alive_hash`-style full-sample construction, kept
    /// close to the measured vectors that exercise it.
    fn keyed_a_support() -> alloc::sync::Arc<crate::serialized_type::SerializedTypeSupport> {
        let ast = alloc::sync::Arc::new(
            zerodds_wire_probe::encode::model_from_idl(
                "@appendable struct A { long x; @key long id; long y; };",
                "keyed-a.idl",
            )
            .expect("model"),
        );
        let type_ = zerodds_types::dynamic::DynamicType::find(&ast, "A").expect("type");
        let object = zerodds_types::TypeObject::Complete(
            zerodds_types::from_ast::complete_type_object(&ast, type_.id()).expect("object"),
        );
        let bytes = object.to_bytes_le().expect("encode object");
        crate::serialized_type::SerializedTypeSupport::from_type_object("A", &bytes, true, 1)
            .expect("support")
    }

    /// `@mutable struct M { long x; @key long id; };` — mutable, and the
    /// key is declared second.
    fn keyed_m_support() -> alloc::sync::Arc<crate::serialized_type::SerializedTypeSupport> {
        let ast = alloc::sync::Arc::new(
            zerodds_wire_probe::encode::model_from_idl(
                "@mutable struct M { long x; @key long id; };",
                "keyed-m.idl",
            )
            .expect("model"),
        );
        let type_ = zerodds_types::dynamic::DynamicType::find(&ast, "M").expect("type");
        let object = zerodds_types::TypeObject::Complete(
            zerodds_types::from_ast::complete_type_object(&ast, type_.id()).expect("object"),
        );
        let bytes = object.to_bytes_le().expect("encode object");
        crate::serialized_type::SerializedTypeSupport::from_type_object("M", &bytes, true, 2)
            .expect("support")
    }

    fn keyed_lifecycle_sample(
        payload: alloc::vec::Vec<u8>,
    ) -> zerodds_rtps::reliable_reader::DeliveredSample {
        zerodds_rtps::reliable_reader::DeliveredSample {
            writer_guid: Guid::new(GuidPrefix::from_bytes([9; 12]), EntityId::PARTICIPANT),
            sequence_number: zerodds_rtps::wire_types::SequenceNumber(5),
            payload: zerodds_rtps::payload::Payload::from(payload.into_boxed_slice()),
            kind: zerodds_rtps::history_cache::ChangeKind::NotAliveDisposed,
            key_hash: None,
            source_timestamp: None,
            coherent_set_sn: None,
            coherent_set_end: false,
            related_sample_identity: None,
            eprosima_related_sample_identity: None,
            group: None,
            coherent_set_complete: None,
            original_writer: None,
            forwarded_by: None,
            non_standard_payload: false,
            inline_qos_override: Default::default(),
        }
    }

    /// End to end through `compute_lifecycle_key_hash`
    /// — `A`'s `@key long id` is declared *second*, not first. The
    /// earlier `read_body`-first `read_key_only` decoded these same
    /// vectors' four key-only bytes as `x` (the first declared member)
    /// with `id` defaulted to 0: a wrong KeyHash, produced silently.
    /// Both vectors measured against Eclipse Cyclone 11.0.1
    /// (`ddsi_serdata_from_sample(sertype, SDK_KEY, &sample)` +
    /// `ddsi_serdata_to_ser`), `id = 7`, must name the same instance as
    /// an ALIVE `x=1, id=7, y=2` sample.
    #[test]
    fn a_key_not_first_end_to_end_through_compute_lifecycle_key_hash() {
        let support = keyed_a_support();
        let alive_body: alloc::vec::Vec<u8> = {
            let mut b = alloc::vec![0x00u8, 0x09, 0x00, 0x00];
            b.extend_from_slice(&12i32.to_le_bytes()); // DHEADER: 3 longs.
            b.extend_from_slice(&1i32.to_le_bytes());
            b.extend_from_slice(&7i32.to_le_bytes());
            b.extend_from_slice(&2i32.to_le_bytes());
            b
        };
        let alive_sample = support
            .read_body(&alive_body[4..], 2, false)
            .expect("decode alive");
        let expected = support.key_material(&alive_sample).expect("keyed").0;

        // Eclipse Cyclone 11.0.1, XCDR1.
        let xcdr1 =
            keyed_lifecycle_sample(alloc::vec![0x00, 0x01, 0x00, 0x00, 0x07, 0x00, 0x00, 0x00,]);
        // Eclipse Cyclone 11.0.1, XCDR2: D_CDR2_LE, DHEADER = 4.
        let xcdr2 = keyed_lifecycle_sample(alloc::vec![
            0x00, 0x09, 0x00, 0x00, 0x04, 0x00, 0x00, 0x00, 0x07, 0x00, 0x00, 0x00,
        ]);
        for sample in [xcdr1, xcdr2] {
            let (item, outcome) = delivered_to_user_sample(
                &sample,
                &Default::default(),
                &Default::default(),
                &|_| false,
                true,
                Some(&support),
                &mut InstanceKeyHolders {
                    map: &mut alloc::collections::BTreeMap::new(),
                    max: usize::MAX,
                },
            );
            assert!(matches!(outcome, KeyHashComputation::Computed));
            match item {
                Some(UserSample::Lifecycle { key_hash, .. }) => assert_eq!(key_hash, expected),
                other => panic!("expected Lifecycle, got {other:?}"),
            }
        }
    }

    /// End to end — `M` is `@mutable`, and its
    /// `@key long id` is declared second. Its wire `serializedKey`
    /// carries an EMHEADER naming `id`'s true position in the full type
    /// (1), not a position renumbered over the key-only survivors (which
    /// would be 0) — `plan_aggregate`'s member-id numbering bug this
    /// round of the review also found and fixed.
    #[test]
    fn m_mutable_key_not_first_end_to_end_through_compute_lifecycle_key_hash() {
        let support = keyed_m_support();
        // Eclipse Cyclone 11.0.1, XCDR1 (PL_CDR1: an EMHEADER per
        // member, `id`'s true position 1 in the full type — see
        // `plan_aggregate`'s member-id numbering fix this round of the
        // review made) and XCDR2 (one EMHEADER, `id=7`).
        //
        // The independent full-sample oracle
        // (`crates/wire-codec/tests/serialized_key_measured.rs`'s
        // `m_mutable_key_not_first_xcdr1_and_xcdr2`, computed straight
        // from `{"x": 1, "id": 7}` via `Emit::KeyHash`, no wire bytes at
        // all) already checks `serialized_key` gets the right 16 bytes
        // for exactly these two vectors; this test is the dcps-level
        // wiring on top of it — encapsulation stripping,
        // representation/endianness detection, `compute_lifecycle_key_hash`
        // — so what it can check on its own is that XCDR1 and XCDR2, two
        // structurally unrelated wire forms for the same `id = 7`, name
        // the same instance through that wiring.
        let xcdr1 =
            keyed_lifecycle_sample(hex_vec("00030000017f0800010000000400000007000000027f0000"));
        let xcdr2 = keyed_lifecycle_sample(hex_vec("000b0000080000000100002007000000"));
        let mut hashes = alloc::vec::Vec::with_capacity(2);
        for sample in [xcdr1, xcdr2] {
            let (item, outcome) = delivered_to_user_sample(
                &sample,
                &Default::default(),
                &Default::default(),
                &|_| false,
                true,
                Some(&support),
                &mut InstanceKeyHolders {
                    map: &mut alloc::collections::BTreeMap::new(),
                    max: usize::MAX,
                },
            );
            assert!(matches!(outcome, KeyHashComputation::Computed));
            match item {
                Some(UserSample::Lifecycle { key_hash, .. }) => hashes.push(key_hash),
                other => panic!("expected Lifecycle, got {other:?}"),
            }
        }
        assert_eq!(
            hashes[0], hashes[1],
            "M's XCDR1 and XCDR2 serializedKey for id=7 must name the same instance"
        );
    }

    fn hex_vec(s: &str) -> alloc::vec::Vec<u8> {
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex byte"))
            .collect()
    }

    /// A keyless reader is unaffected: no computation is attempted,
    /// `key_hash` stays `None` on an ALIVE sample, and a lifecycle marker
    /// keeps the first-16-bytes fallback.
    #[test]
    fn keyless_reader_key_hash_computation_is_unaffected() {
        let (item, outcome) = delivered_to_user_sample(
            &keyed_delivered_alive(keyed_final_wire(7, 42)),
            &Default::default(),
            &Default::default(),
            &|_| false,
            false,
            None,
            &mut InstanceKeyHolders {
                map: &mut alloc::collections::BTreeMap::new(),
                max: usize::MAX,
            },
        );
        assert!(matches!(outcome, KeyHashComputation::NotNeeded));
        match item {
            Some(UserSample::Alive { key_hash, .. }) => assert_eq!(key_hash, None),
            other => panic!("expected Alive, got {other:?}"),
        }

        let key_only = alloc::vec![0x00u8, 0x06, 0x00, 0x00, 0xAA, 0xBB, 0xCC, 0xDD];
        let sample = zerodds_rtps::reliable_reader::DeliveredSample {
            writer_guid: Guid::new(GuidPrefix::from_bytes([9; 12]), EntityId::PARTICIPANT),
            sequence_number: zerodds_rtps::wire_types::SequenceNumber(3),
            payload: zerodds_rtps::payload::Payload::from(key_only.clone().into_boxed_slice()),
            kind: zerodds_rtps::history_cache::ChangeKind::NotAliveDisposed,
            key_hash: None,
            source_timestamp: None,
            coherent_set_sn: None,
            coherent_set_end: false,
            related_sample_identity: None,
            eprosima_related_sample_identity: None,
            group: None,
            coherent_set_complete: None,
            original_writer: None,
            forwarded_by: None,
            non_standard_payload: false,
            inline_qos_override: Default::default(),
        };
        let (item, outcome) = delivered_to_user_sample(
            &sample,
            &Default::default(),
            &Default::default(),
            &|_| false,
            false,
            None,
            &mut InstanceKeyHolders {
                map: &mut alloc::collections::BTreeMap::new(),
                max: usize::MAX,
            },
        );
        assert!(matches!(outcome, KeyHashComputation::NotNeeded));
        match item {
            Some(UserSample::Lifecycle { key_hash, .. }) => {
                assert_eq!(key_hash, fallback_lifecycle_key_hash(&key_only));
            }
            other => panic!("expected Lifecycle, got {other:?}"),
        }
    }

    /// A keyed reader whose `type_identifier` never resolves (the
    /// default `TypeIdentifier::None` — an untyped C-FFI/rmw reader, or one
    /// created before a `getTypes` reply arrived) reports
    /// `reader.key_hash.unavailable` once for the writer it could not
    /// compute a hash for, not once per sample.
    #[test]
    fn keyed_reader_without_type_info_reports_unavailable_once() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::{Component, Level, VecSink};

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt =
            DcpsRuntime::start(9, GuidPrefix::from_bytes([0xD7; 12]), cfg).expect("start runtime");
        let (eid, _rx) = rt
            .register_user_reader_kind(
                UserReaderConfig {
                    topic_name: "UnavailableTypeTopic".into(),
                    type_name: "UnavailableTestType".into(),
                    ..Default::default()
                },
                true,
            )
            .expect("reader");
        let arc = rt.reader_slot(eid).expect("slot");
        let writer_a = Guid::new(GuidPrefix::from_bytes([1; 12]), EntityId::PARTICIPANT);
        let writer_b = Guid::new(GuidPrefix::from_bytes([2; 12]), EntityId::PARTICIPANT);
        for writer_guid in [writer_a, writer_a, writer_b] {
            let mut slot = arc.lock().expect("slot lock");
            let (keyed, key_hash_support) = reader_key_hash_context(&rt, &mut slot);
            assert!(keyed, "the reader was registered WithKey");
            assert!(
                key_hash_support.is_none(),
                "TypeIdentifier::None resolves to no support"
            );
            let mut sample = keyed_delivered_alive(keyed_final_wire(1, 1));
            sample.writer_guid = writer_guid;
            let _ = deliver_sample_with_key_hash(
                &rt,
                &mut slot,
                keyed,
                key_hash_support.as_deref(),
                &sample,
            );
        }
        rt.shutdown();

        let events: alloc::vec::Vec<_> = sink
            .snapshot()
            .into_iter()
            .filter(|e| e.name == "reader.key_hash.unavailable")
            .collect();
        assert_eq!(
            events.len(),
            2,
            "one event per (reader, writer) pair, not per sample: got {events:?}"
        );
        for event in &events {
            assert_eq!(event.level, Level::Warn);
            assert_eq!(event.component, Component::Dcps);
            assert!(
                event
                    .attrs
                    .iter()
                    .any(|a| a.key == "reason" && a.value == "no type known for this reader"),
                "reason attr missing: {event:?}"
            );
        }
    }

    /// A reader created before its type reaches the
    /// TypeLookup registry (a slow `getTypes` reply, or a type registered
    /// after the reader) is not stuck with the first miss:
    /// `KeyHashSupport::Unavailable` records the registry's
    /// `TypeRegistry::generation` at the failed attempt, and
    /// `resolve_key_hash_support` retries once that number has moved. The
    /// first sample reports `reader.key_hash.unavailable`; once the type
    /// registers, the next sample gets the computed hash and
    /// `reader.key_hash.available` fires exactly once (not once per
    /// sample thereafter).
    #[test]
    fn key_hash_support_retries_after_the_type_registers_later() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::VecSink;

        let object = keyed_final_type_object();
        let hash = zerodds_types::compute_hash(&object).expect("hash");
        let type_identifier = zerodds_types::TypeIdentifier::EquivalenceHashComplete(hash);
        let expected_hash = {
            let support = keyed_final_support();
            let body = keyed_final_wire(1, 1);
            let sample = support.read_body(&body[4..], 2, false).expect("decode");
            support.key_material(&sample).expect("keyed").0
        };

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt =
            DcpsRuntime::start(9, GuidPrefix::from_bytes([0xD8; 12]), cfg).expect("start runtime");
        let (eid, _rx) = rt
            .register_user_reader_kind(
                UserReaderConfig {
                    topic_name: "LateJoinerLifecycleTopic".into(),
                    type_name: "KeyedFinal".into(),
                    type_identifier,
                    ..Default::default()
                },
                true,
            )
            .expect("reader");
        let arc = rt.reader_slot(eid).expect("slot");
        let writer_guid = Guid::new(GuidPrefix::from_bytes([3; 12]), EntityId::PARTICIPANT);

        // First sample: the registry does not have the type yet.
        {
            let mut slot = arc.lock().expect("slot lock");
            let (keyed, support) = reader_key_hash_context(&rt, &mut slot);
            assert!(keyed);
            assert!(support.is_none(), "not registered yet");
            let mut sample = keyed_delivered_alive(keyed_final_wire(1, 1));
            sample.writer_guid = writer_guid;
            let item =
                deliver_sample_with_key_hash(&rt, &mut slot, keyed, support.as_deref(), &sample);
            match item {
                Some(UserSample::Alive { key_hash, .. }) => assert_eq!(key_hash, None),
                other => panic!("expected Alive, got {other:?}"),
            }
        }
        assert_eq!(
            sink.snapshot()
                .iter()
                .filter(|e| e.name == "reader.key_hash.unavailable")
                .count(),
            1
        );
        assert_eq!(
            sink.snapshot()
                .iter()
                .filter(|e| e.name == "reader.key_hash.available")
                .count(),
            0
        );

        // The type arrives — this bumps the registry's generation.
        rt.register_type_object(object).expect("register");

        // Second sample: the cached miss must be retried, not reused.
        {
            let mut slot = arc.lock().expect("slot lock");
            let (keyed, support) = reader_key_hash_context(&rt, &mut slot);
            assert!(
                support.is_some(),
                "must resolve now that the type registered"
            );
            let mut sample = keyed_delivered_alive(keyed_final_wire(1, 1));
            sample.writer_guid = writer_guid;
            let item =
                deliver_sample_with_key_hash(&rt, &mut slot, keyed, support.as_deref(), &sample);
            match item {
                Some(UserSample::Alive { key_hash, .. }) => {
                    assert_eq!(key_hash, Some(expected_hash));
                }
                other => panic!("expected Alive, got {other:?}"),
            }
        }
        rt.shutdown();
        assert_eq!(
            sink.snapshot()
                .iter()
                .filter(|e| e.name == "reader.key_hash.available")
                .count(),
            1,
            "exactly one availability event, not one per sample afterwards"
        );
    }

    /// The Fast DDS 3.6 SPDP capture below, with its `PID_DOMAIN_ID`
    /// (205, the domain it was recorded on) set to `to`; every other
    /// octet stays as captured. A participant of another domain is not
    /// discovered, so a test that hands the capture to a runtime on
    /// another domain has to move it.
    fn fastdds_spdp_moved_to(mut bytes: Vec<u8>, to: u32) -> Vec<u8> {
        const CAPTURED: [u8; 8] = [0x0f, 0x00, 0x04, 0x00, 0xcd, 0x00, 0x00, 0x00];
        let at: Vec<usize> = bytes
            .windows(CAPTURED.len())
            .enumerate()
            .filter(|(_, window)| *window == CAPTURED)
            .map(|(at, _)| at)
            .collect();
        assert_eq!(at.len(), 1, "the capture carries one PID_DOMAIN_ID of 205");
        bytes[at[0] + 4..at[0] + 8].copy_from_slice(&to.to_le_bytes());
        bytes
    }

    /// FU1 diagnosis: inject a REAL FastDDS-3.6 SPDP datagram (domain 205,
    /// the Linux test host capture 2026-05-29) directly into handle_spdp_datagram
    /// — does the runtime register FastDDS as a peer? Separates the
    /// receive problem (socket) from the handle problem (parse/insert/filter).
    ///
    /// The runtime binds domain 100, not the capture's 205: the datagram
    /// is handed to `handle_spdp_datagram` directly, and domain 205's SPDP
    /// port (58650) falls inside the Linux ephemeral port range — where
    /// the bind fails as soon as any other process holds that port. As
    /// captured, the beacon names domain 205 and is ignored; with its
    /// `PID_DOMAIN_ID` moved to 100 it is discovered.
    #[test]
    fn handle_spdp_registers_real_fastdds_participant() {
        fn hx(s: &str) -> Vec<u8> {
            (0..s.len())
                .step_by(2)
                .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
                .collect()
        }
        const FASTDDS_SPDP: &str = "";
        let bytes = hx(FASTDDS_SPDP);
        let prefix = GuidPrefix::from_bytes([0x99; 12]);
        let rt =
            ShutsDown(DcpsRuntime::start(100, prefix, RuntimeConfig::default()).expect("rt start"));
        assert_eq!(rt.discovered_participants().len(), 0, "fresh: no peers");
        handle_spdp_datagram_for_test(&rt, &bytes);
        assert_eq!(
            rt.discovered_participants().len(),
            0,
            "the capture announces domain 205; this runtime is on 100"
        );
        assert_eq!(rt.ignored_spdp_samples(), 1);
        handle_spdp_datagram_for_test(&rt, &fastdds_spdp_moved_to(bytes, 100));
        let n = rt.discovered_participants().len();
        assert_eq!(
            n, 1,
            "FastDDS must be registered after handle_spdp_datagram (got {n})"
        );
    }

    /// OpenSplice answers a new participant with one datagram that announces
    /// all five participants its DDSI2 service hosts, sources switched by
    /// INFO_SRC; the one with the SEDP detectors stands last. Only the first
    /// used to be discovered, so the SEDP writers had no proxy to announce a
    /// local writer to until OpenSplice's next periodic beacon.
    #[test]
    fn every_participant_of_an_opensplice_spdp_bundle_is_discovered() {
        let fixture = include_str!("../../rtps/tests/fixtures/opensplice/spdp_bundle.hex");
        let hex: String = fixture
            .lines()
            .map(|line| line.split('#').next().unwrap_or(""))
            .collect::<Vec<_>>()
            .concat()
            .split_whitespace()
            .collect();
        let bytes: Vec<u8> = (0..hex.len() / 2)
            .map(|i| u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).unwrap())
            .collect();
        let lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x9B; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        handle_spdp_datagram_for_test(&rt, &bytes);
        // The participants differ in the prefix's eighth octet.
        let mut known: Vec<u8> = rt
            .discovered_participants()
            .iter()
            .map(|p| p.data.guid.prefix.to_bytes()[7])
            .collect();
        known.sort_unstable();
        assert_eq!(known, vec![0x04, 0x58, 0x7d, 0x81, 0xd0]);
        let sedp = rt.sedp.lock().unwrap();
        let detectors: Vec<Guid> = sedp
            .pub_writer()
            .inner()
            .reader_proxies()
            .iter()
            .map(|p| p.remote_reader_guid)
            .collect();
        assert_eq!(detectors.len(), 1, "{detectors:?}");
        assert_eq!(detectors[0].prefix.to_bytes()[7], 0x81);
        assert_eq!(
            detectors[0].entity_id,
            EntityId::SEDP_BUILTIN_PUBLICATIONS_READER
        );
        drop(sedp);
        rt.shutdown();
    }

    /// The TypeLookup service answers a peer at the metatraffic locator it
    /// announced (DDSI-RTPS 2.5 §8.5.3.2), not at the source address of its
    /// datagram: the socket a peer sends from need not be one it receives
    /// on, and OpenDDS 3.34 sends from an ephemeral port. The source used to
    /// become the channel's locator for the peer, and every reply,
    /// ACKNACK and HEARTBEAT to it was refused.
    #[test]
    fn the_type_lookup_channel_answers_a_known_peer_at_its_metatraffic_locator() {
        fn hx(s: &str) -> Vec<u8> {
            (0..s.len())
                .step_by(2)
                .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
                .collect()
        }
        // The Fast DDS 3.6 SPDP of `handle_spdp_registers_real_fastdds_participant`:
        // prefix 010fa72bbbebc90100000000, metatraffic unicast
        // 192.0.2.115:58660.
        const FASTDDS_SPDP: &str = "";
        let lease = zerodds_test_domains::lease_domain();
        let local = GuidPrefix::from_bytes([0x9A; 12]);
        let rt = DcpsRuntime::start(lease.id(), local, RuntimeConfig::default()).expect("start");
        let leased = u32::try_from(lease.id()).expect("a leased id is not negative");
        handle_spdp_datagram_for_test(&rt, &fastdds_spdp_moved_to(hx(FASTDDS_SPDP), leased));
        let peer = GuidPrefix::from_bytes([
            0x01, 0x0f, 0xa7, 0x2b, 0xbb, 0xeb, 0xc9, 0x01, 0x00, 0x00, 0x00, 0x00,
        ]);
        let metatraffic = Locator::udp_v4([192, 168, 178, 115], 58660);
        assert_eq!(
            rt.peer_type_lookup_locator(peer).unwrap(),
            Some(metatraffic)
        );

        let mut remote =
            crate::type_lookup_transport::TypeLookupTransport::new(peer, Duration::from_secs(5));
        let reply = remote
            .write(
                false,
                local,
                metatraffic,
                &[0, 7, 0, 0],
                None,
                Duration::ZERO,
            )
            .unwrap();
        let source = Locator::udp_v4([192, 168, 178, 115], 40123);
        assert!(dispatch_type_lookup_datagram(&rt, &reply[0].bytes, &source));
        let locators = rt.type_lookup_transport.lock().unwrap().locators_of(peer);
        assert_eq!(locators, alloc::vec![metatraffic]);
        rt.shutdown();
    }

