    #[test]
    fn strip_user_encap_xcdr2_le() {
        let payload = [0x00, 0x07, 0x00, 0x00, 1, 2, 3];
        assert_eq!(strip_user_encap(&payload), Some(alloc::vec![1, 2, 3]));
    }

    #[test]
    fn strip_user_encap_xcdr1_le() {
        // Cyclone default for simple types.
        let payload = [0x00, 0x01, 0x00, 0x00, 0xAA];
        assert_eq!(strip_user_encap(&payload), Some(alloc::vec![0xAA]));
    }

    #[test]
    fn strip_user_encap_rejects_unknown_scheme() {
        let payload = [0xFF, 0xFF, 0x00, 0x00, 1];
        assert_eq!(strip_user_encap(&payload), None);
    }

    #[test]
    fn strip_user_encap_rejects_short() {
        assert_eq!(strip_user_encap(&[0x00, 0x07]), None);
    }

    #[test]
    fn strip_user_encap_drops_the_padding_the_options_name() {
        // CDR_LE with options 0x0002: two padding octets bring the two-octet
        // body to a multiple of four.
        let payload = [0x00, 0x01, 0x00, 0x02, 0xAA, 0xBB, 0x00, 0x00];
        assert_eq!(strip_user_encap(&payload), Some(alloc::vec![0xAA, 0xBB]));
        // A count larger than the body is refused:
        // `strip_user_encap_refuses_padding_the_body_cannot_hold`.
    }

    /// OpenDDS 3.34 counts padding it does not append: the `RichF` sample of
    /// cross-vendor-rich with a 50-octet blob arrives as a 70-octet payload,
    /// options 0x0002, and the DATA submessage ends after the blob's last
    /// octet. The two octets the count names are the sample's own; cutting
    /// them made the blob's declared length run past the body and every such
    /// sample failed to decode. A payload whose length is not a multiple of
    /// four carries no padding.
    #[test]
    fn strip_user_encap_keeps_a_body_whose_counted_padding_is_absent() {
        let mut payload = alloc::vec![0x00, 0x07, 0x00, 0x02, 0x01, 0x00, 0x00, 0x00];
        payload.extend_from_slice(&[0x18, 0x2d, 0x44, 0x54, 0xfb, 0x21, 0x09, 0x40]);
        payload.extend_from_slice(&[0x32, 0x00, 0x00, 0x00]);
        payload.extend(0u8..50);
        assert_eq!(payload.len(), 70);
        let body = strip_user_encap(&payload).expect("a known scheme");
        assert_eq!(body.len(), 66);
        assert_eq!(body[body.len() - 2..], [0x30, 0x31]);
    }

    /// A header counting three padding octets behind a one-octet body
    /// counts octets the payload does not have: refused, like an unknown
    /// scheme, and not read as a body of one.
    #[test]
    fn strip_user_encap_refuses_padding_the_body_cannot_hold() {
        assert_eq!(strip_user_encap(&[0x00, 0x07, 0x00, 0x03, 0xAB]), None);
        assert_eq!(strip_user_encap(&[0x00, 0x07, 0x00, 0x01]), None);
        assert_eq!(
            strip_user_encap(&[0x00, 0x07, 0x00, 0x03, 0xAB, 0x00, 0x00, 0x00]),
            Some(alloc::vec![0xAB])
        );
    }

    /// DDS-XTypes 1.3 Table 39 (§7.4.3.4) names PLAIN_CDR2, PL_CDR2 and
    /// DELIMIT_CDR2 `{0x00, 0x10}` to `{0x00, 0x15}` (big-endian even,
    /// little-endian odd); DDSI-RTPS 2.5 Table 10.3 uses them too. A payload
    /// that carries them is read, like the identifiers of Table 60.
    #[test]
    fn the_encapsulation_identifiers_of_table_39_are_read() {
        for id in 0x10u8..=0x15 {
            let frame = [0x00, id, 0x00, 0x00, 0xAA, 0xBB, 0xCC, 0xDD];
            assert_eq!(
                strip_user_encap(&frame).expect("a known scheme"),
                alloc::vec![0xAAu8, 0xBB, 0xCC, 0xDD],
                "identifier 0x{id:02x}"
            );
            assert_eq!(encap_representation(&frame), 1, "0x{id:02x} is XCDR2");
            assert_eq!(
                encap_big_endian(&frame),
                id % 2 == 0,
                "0x{id:02x}: even is big-endian"
            );
        }
        // The identifiers between the two tables stay unknown.
        for id in [0x04u8, 0x05, 0x0c, 0x0f, 0x16] {
            assert!(
                strip_user_encap(&[0x00, id, 0x00, 0x00, 1, 2, 3, 4]).is_none(),
                "0x{id:02x}"
            );
        }
    }

    /// DDS-XTypes 1.3 §7.6.3.1.2: the two least significant bits of the
    /// second options byte encode the number of padding bytes needed after
    /// the serialized payload to reach the next 4-byte offset (00, 01, 10,
    /// 11 for none, one, two, three), and the receiver "determines where
    /// the serialized data exactly ended" from them. The padding is zero.
    #[test]
    fn a_user_payload_names_its_padding_in_the_options() {
        for (len, expected) in [
            (0usize, 0usize),
            (1, 3),
            (2, 2),
            (3, 1),
            (4, 0),
            (5, 3),
            (23, 1),
        ] {
            let (header, padding) = pad_user_payload(&USER_PAYLOAD_ENCAP, len);
            assert_eq!(padding, expected, "payload of {len} octets");
            assert_eq!(
                header[3] & 0x03,
                expected as u8,
                "the options of a payload of {len} octets"
            );
            assert_eq!(&header[..3], &[0x00, 0x01, 0x00], "the scheme is untouched");

            let mut frame = header.to_vec();
            frame.extend(core::iter::repeat_n(0x7Au8, len));
            frame.extend(core::iter::repeat_n(0u8, padding));
            assert_eq!(frame.len() % 4, 0, "the frame ends on a 4-byte offset");
            assert_eq!(
                strip_user_encap(&frame).expect("a known scheme"),
                alloc::vec![0x7Au8; len],
                "the receiver drops exactly the padding the options name"
            );
        }
    }

    #[test]
    fn user_payload_encap_is_cdr_le() {
        // CDR_LE (PLAIN_CDR / XCDR1, Little-Endian) — ehrliche
        // Declaration of the body encoding generated by codegen.
        assert_eq!(USER_PAYLOAD_ENCAP, [0x00, 0x01, 0x00, 0x00]);
    }

    #[test]
    fn data_repr_offer_str_uses_spec_ids() {
        use zerodds_rtps::publication_data::data_representation as dr;
        // XCDR1 -> Spec-Id 0 (NICHT 1 = XML); XCDR2 -> 2.
        assert_eq!(parse_data_repr_offer_str("XCDR1"), Some(vec![dr::XCDR]));
        assert_eq!(parse_data_repr_offer_str("XCDR2"), Some(vec![dr::XCDR2]));
        assert_eq!(parse_data_repr_offer_str("xcdr2"), Some(vec![dr::XCDR2]));
        assert_eq!(
            parse_data_repr_offer_str("XCDR2,XCDR1"),
            Some(vec![dr::XCDR2, dr::XCDR])
        );
        assert_eq!(parse_data_repr_offer_str("bogus"), None);
        assert_eq!(parse_data_repr_offer_str(""), None);
        // XCDR1 must NOT map to the XML id (1); XML has a name of its own.
        assert_ne!(parse_data_repr_offer_str("XCDR1"), Some(vec![dr::XML]));
        assert_eq!(
            parse_data_repr_offer_str("XML,XCDR2"),
            Some(vec![dr::XML, dr::XCDR2])
        );
    }

    /// A DataReader requests XCDR2 and XCDR (DDS-XTypes 1.3 §7.6.3.1.1, readers
    /// from XTYPES 1.2 on); without XCDR1 in the set a CycloneDDS writer of a
    /// `@final` type fails the DataRepresentation RxO check and never
    /// delivers (Bug DR1).
    #[test]
    fn reader_accept_repr_requests_xcdr2_and_xcdr() {
        use zerodds_rtps::publication_data::data_representation as dr;
        let both = alloc::vec![dr::XCDR2, dr::XCDR];
        // The offers of the writers do not narrow the reader.
        assert_eq!(reader_accept_repr(&[dr::XCDR]), both);
        assert_eq!(reader_accept_repr(&[]), both);
        assert_eq!(reader_accept_repr(&[dr::XCDR2]), both);
        assert_eq!(reader_accept_repr(&[dr::XCDR, dr::XCDR2]), both);
        // An element that is neither follows.
        assert_eq!(
            reader_accept_repr(&[dr::XML, dr::XCDR]),
            alloc::vec![dr::XCDR2, dr::XCDR, dr::XML]
        );
    }

    /// The document of a `KeyedFinal` and the header an XML writer puts
    /// in front of it (DDS-XTypes 1.3 §7.4.4, Table 60).
    fn keyed_final_xml_wire(document: &str, kind_padding: bool) -> alloc::vec::Vec<u8> {
        let (header, padding) = pad_user_payload(&XML_ENCAP, document.len());
        let mut wire = header.to_vec();
        wire.extend_from_slice(document.as_bytes());
        if kind_padding {
            wire.resize(wire.len() + padding, 0);
        }
        wire
    }

    /// A sample under the XML header reaches the reader as the XCDR2 body
    /// the same sample has under CDR, padding the options word counts
    /// included.
    #[test]
    fn an_xml_sample_reaches_the_reader_as_its_cdr_body() {
        let support = keyed_final_support();
        let document = "<KeyedFinal><id>7</id><value>42</value></KeyedFinal>";
        let sample = keyed_delivered_alive(keyed_final_xml_wire(document, true));
        let converted = xml_sample_as_cdr(&support, &sample).expect("converted");
        assert_eq!(&converted.payload[..], &keyed_final_wire(7, 42)[..]);

        let (item, outcome) = delivered_to_user_sample(
            &converted,
            &Default::default(),
            &Default::default(),
            &|_| false,
            true,
            Some(&support),
            &mut InstanceKeyHolders {
                map: &mut alloc::collections::BTreeMap::new(),
                max: usize::MAX,
            },
        );
        assert!(matches!(outcome, KeyHashComputation::Computed));
        let Some(UserSample::Alive {
            payload,
            representation,
            ..
        }) = item
        else {
            panic!("expected Alive");
        };
        assert_eq!(representation, 1);
        assert_eq!(&payload[..], &keyed_final_wire(7, 42)[4..]);
    }

    /// A document that is no document of the type is refused and not
    /// handed on as something else.
    #[test]
    fn an_xml_sample_that_is_no_document_of_the_type_is_refused() {
        let support = keyed_final_support();
        for document in [
            "<Other><id>7</id></Other>",
            "<KeyedFinal><id>seven</id></KeyedFinal>",
            "<KeyedFinal><nope>1</nope></KeyedFinal>",
            "<KeyedFinal><id>7</id>",
            "not xml",
        ] {
            let sample = keyed_delivered_alive(keyed_final_xml_wire(document, true));
            assert!(
                xml_sample_as_cdr(&support, &sample).is_err(),
                "`{document}` must be refused"
            );
        }
    }

    /// A dispose under the XML header carries the document of the key
    /// members; it yields the KeyHash the CDR form of the same key yields.
    #[test]
    fn an_xml_dispose_carries_the_instance_key() {
        let support = keyed_final_support();
        let alive = support
            .read_body(&keyed_final_wire(7, 42)[4..], 2, false)
            .expect("decode body");
        let (expected_hash, _) = support.key_material(&alive).expect("keyed");
        let mut dispose = keyed_delivered_alive(keyed_final_xml_wire(
            "<KeyedFinal><id>7</id></KeyedFinal>",
            true,
        ));
        dispose.kind = zerodds_rtps::history_cache::ChangeKind::NotAliveDisposed;
        let converted = xml_sample_as_cdr(&support, &dispose).expect("converted");
        let (hash, _) = compute_lifecycle_key_material(&support, &converted.payload)
            .expect("key of the converted payload");
        assert_eq!(hash, expected_hash);
    }

    /// A writer whose first representation is XML frames the document of
    /// the XCDR1 body it was handed under `{0x00, 0x04}`; the key of a
    /// dispose is the document of the key members.
    #[test]
    fn an_xml_writer_sends_the_document_of_the_sample() {
        use zerodds_rtps::publication_data::data_representation as dr;
        let rt = DcpsRuntime::start(
            14,
            GuidPrefix::from_bytes([0xC9; 12]),
            RuntimeConfig::default(),
        )
        .expect("start runtime");
        let cfg = UserWriterConfig {
            topic_name: "XmlKeyed".into(),
            type_name: "KeyedFinal".into(),
            durability: zerodds_qos::DurabilityKind::TransientLocal,
            data_representation_offer: Some(alloc::vec![dr::XML]),
            ..Default::default()
        };
        let eid = rt.register_user_writer(cfg).expect("writer");
        let support = keyed_final_support();
        rt.set_user_writer_key_support(eid, Arc::clone(&support))
            .expect("type for the writer");
        // XCDR1 little-endian body of KeyedFinal { 7, 42 }.
        let mut body = alloc::vec::Vec::new();
        body.extend_from_slice(&7i32.to_le_bytes());
        body.extend_from_slice(&42i32.to_le_bytes());
        rt.write_user_sample(eid, body).expect("write");
        let slot_arc = rt.writer_slot(eid).expect("slot");
        let mut slot = slot_arc.lock().expect("slot lock");
        let change = slot
            .writer
            .cache()
            .get(zerodds_rtps::wire_types::SequenceNumber(1))
            .expect("the sample is in the cache");
        let document = "<KeyedFinal><id>7</id><value>42</value></KeyedFinal>";
        assert_eq!(
            &change.payload[..],
            &keyed_final_xml_wire(document, true)[..]
        );
        // The key of a dispose.
        let sample = support
            .read_body(&keyed_final_wire(7, 42)[4..], 2, false)
            .expect("decode body");
        let (_, holder) = support.key_material(&sample).expect("keyed");
        let key = rt
            .lifecycle_serialized_key(&mut slot, &holder)
            .expect("key")
            .expect("type resolves");
        assert_eq!(
            key,
            keyed_final_xml_wire("<KeyedFinal><id>7</id></KeyedFinal>", true)
        );
        drop(slot);
        rt.shutdown();
    }

    /// DDSI-RTPS 2.5 §10.7: the SerializedPayload of the Topic "Square" with
    /// the @final type { @key string<64> color; long x; long y; long size; }
    /// and the sample ("BLUE", 34, 100, 24) in PLAIN_CDR version 1, little
    /// endian: header CDR_LE with options 0, then the body. The octets are
    /// those printed in the spec.
    #[test]
    fn the_example_of_10_7_has_the_header_and_body_of_the_spec() {
        use zerodds_rtps::publication_data::data_representation as dr;
        use zerodds_types::qos::ExtensibilityForRepr as Ext;
        let spec: [u8; 28] = [
            0x00, 0x01, 0x00, 0x00, // CDR_LE, options 0
            0x05, 0x00, 0x00, 0x00, // CDR_Serialization("BLUE").length = 5
            0x42, 0x4C, 0x55, 0x45, 0x00, 0x00, 0x00, 0x00, // "BLUE\0" and padding
            0x22, 0x00, 0x00, 0x00, // x = 34
            0x64, 0x00, 0x00, 0x00, // y = 100
            0x18, 0x00, 0x00, 0x00, // size = 24
        ];
        // The header a @final XCDR1 writer puts in front of a payload.
        assert_eq!(
            user_payload_encap(dr::XCDR, Ext::Final, false),
            Some([spec[0], spec[1], spec[2], spec[3]])
        );
        // The receiver reads the body behind the header: 24 octets, the
        // string with its length, the three longs after it.
        let body = strip_user_encap(&spec).expect("CDR_LE is a known scheme");
        assert_eq!(body.len(), 24);
        assert_eq!(&body[..], &spec[4..]);
        assert_eq!(encap_representation(&spec), 0, "version 1 of CDR");
        assert!(!encap_big_endian(&spec), "little endian");
        let long =
            |at: usize| i32::from_le_bytes([body[at], body[at + 1], body[at + 2], body[at + 3]]);
        assert_eq!(long(0), 5);
        assert_eq!(&body[4..8], b"BLUE");
        assert_eq!((long(12), long(16), long(20)), (34, 100, 24));
    }

    /// A writer under `RuntimeConfig::encapsulation_ids = Table39` stamps
    /// the identifiers of DDS-XTypes 1.3 Table 39 (§7.4.3.4): `{0x00,
    /// 0x11}` for PLAIN_CDR2 little endian and `{0x01, 0x00}` for XML,
    /// where the default is Table 60's `{0x00, 0x07}` and `{0x00, 0x04}`.
    #[test]
    fn a_writer_stamps_the_identifiers_of_table_39_when_the_runtime_is_set_to_them() {
        use zerodds_rtps::publication_data::data_representation as dr;
        use zerodds_wire_codec::value::EncapsulationIds;
        let writer_config = |offer: i16| UserWriterConfig {
            topic_name: "Table39".into(),
            type_name: "KeyedFinal".into(),
            durability: zerodds_qos::DurabilityKind::TransientLocal,
            data_representation_offer: Some(alloc::vec![offer]),
            ..Default::default()
        };
        for (ids, offer, expected) in [
            (EncapsulationIds::Table39, dr::XCDR2, [0x00, 0x11]),
            (EncapsulationIds::Table60, dr::XCDR2, [0x00, 0x07]),
            (EncapsulationIds::Table39, dr::XML, [0x01, 0x00]),
            (EncapsulationIds::Table60, dr::XML, [0x00, 0x04]),
        ] {
            let lease = zerodds_test_domains::lease_domain();
            let rt = DcpsRuntime::start(
                lease.id(),
                GuidPrefix::from_bytes([0xC8; 12]),
                RuntimeConfig {
                    encapsulation_ids: ids,
                    ..RuntimeConfig::default()
                },
            )
            .expect("start runtime");
            let eid = rt
                .register_user_writer(writer_config(offer))
                .expect("writer");
            let support = keyed_final_support();
            rt.set_user_writer_key_support(eid, Arc::clone(&support))
                .expect("type for the writer");
            let mut body = alloc::vec::Vec::new();
            body.extend_from_slice(&7i32.to_le_bytes());
            body.extend_from_slice(&42i32.to_le_bytes());
            rt.write_user_sample(eid, body).expect("write");
            let slot_arc = rt.writer_slot(eid).expect("slot");
            let mut slot = slot_arc.lock().expect("slot lock");
            let change = slot
                .writer
                .cache()
                .get(zerodds_rtps::wire_types::SequenceNumber(1))
                .expect("the sample is in the cache");
            assert_eq!(
                &change.payload[..2],
                &expected,
                "{ids:?}, offer {offer}: {:02x?}",
                &change.payload[..4]
            );
            if offer == dr::XML {
                // The reader takes the document under either identifier.
                assert!(crate::xml_data::is_xml_payload(&change.payload));
                let sample = support
                    .read_body(&keyed_final_wire(7, 42)[4..], 2, false)
                    .expect("decode body");
                let (_, holder) = support.key_material(&sample).expect("keyed");
                let key = rt
                    .lifecycle_serialized_key(&mut slot, &holder)
                    .expect("key")
                    .expect("type resolves");
                assert_eq!(&key[..2], &expected, "the key of a dispose, {ids:?}");
            }
            drop(slot);
            rt.shutdown();
        }
    }

    /// The identifiers of Table 60 map onto Table 39's, and the
    /// identifiers of encoding version 1 are the same in both.
    #[test]
    fn encap_in_table_maps_table_60_onto_table_39() {
        use zerodds_wire_codec::value::EncapsulationIds;
        let table39 = EncapsulationIds::Table39;
        for (from, to) in [
            ([0x00, 0x06], [0x00, 0x10]),
            ([0x00, 0x07], [0x00, 0x11]),
            ([0x00, 0x08], [0x00, 0x14]),
            ([0x00, 0x09], [0x00, 0x15]),
            ([0x00, 0x0a], [0x00, 0x12]),
            ([0x00, 0x0b], [0x00, 0x13]),
            ([0x00, 0x00], [0x00, 0x00]),
            ([0x00, 0x01], [0x00, 0x01]),
            ([0x00, 0x02], [0x00, 0x02]),
            ([0x00, 0x03], [0x00, 0x03]),
            ([0x00, 0x04], [0x01, 0x00]),
        ] {
            assert_eq!(
                encap_in_table(table39, [from[0], from[1], 0x00, 0x03]),
                [to[0], to[1], 0x00, 0x03],
                "{from:02x?}"
            );
            assert_eq!(
                encap_in_table(EncapsulationIds::Table60, [from[0], from[1], 0, 0]),
                [from[0], from[1], 0, 0]
            );
        }
        assert!(is_xml_encap(&[0x00, 0x04, 0, 0]));
        assert!(is_xml_encap(&[0x01, 0x00, 0, 0]));
        assert!(!is_xml_encap(&[0x00, 0x07, 0, 0]));
    }

    /// A sample under the XML identifier of Table 39 reaches the reader as
    /// the XCDR2 body the same sample has under Table 60's.
    #[test]
    fn an_xml_sample_under_the_identifier_of_table_39_reaches_the_reader() {
        let support = keyed_final_support();
        let document = "<KeyedFinal><id>7</id><value>42</value></KeyedFinal>";
        let mut wire = keyed_final_xml_wire(document, true);
        wire[..2].copy_from_slice(&[0x01, 0x00]);
        assert!(crate::xml_data::is_xml_payload(&wire));
        let sample = keyed_delivered_alive(wire);
        let converted = xml_sample_as_cdr(&support, &sample).expect("converted");
        assert_eq!(&converted.payload[..], &keyed_final_wire(7, 42)[..]);
    }

    #[test]
    fn user_payload_encap_maps_repr_and_extensibility() {
        use zerodds_rtps::publication_data::data_representation as dr;
        use zerodds_types::qos::ExtensibilityForRepr as Ext;
        // DDSI-RTPS 2.5 §10.5 / XTypes 1.3 Table 60 Encapsulation-IDs
        // (2-byte repr-id BE + 2-byte options=0), little-endian variant:
        //   XCDR1 final/appendable -> CDR_LE        0x0001
        //   XCDR1 mutable          -> PL_CDR_LE      0x0003
        //   XCDR2 final            -> PLAIN_CDR2_LE  0x0007
        //   XCDR2 appendable       -> D_CDR2_LE      0x0009
        //   XCDR2 mutable          -> PL_CDR2_LE     0x000b
        assert_eq!(
            user_payload_encap(dr::XCDR, Ext::Final, false),
            Some([0x00, 0x01, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XCDR, Ext::Appendable, false),
            Some([0x00, 0x01, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XCDR, Ext::Mutable, false),
            Some([0x00, 0x03, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XCDR2, Ext::Final, false),
            Some([0x00, 0x07, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XCDR2, Ext::Appendable, false),
            Some([0x00, 0x09, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XCDR2, Ext::Mutable, false),
            Some([0x00, 0x0b, 0x00, 0x00])
        );
        // The default const is exactly the (XCDR1, Final) case.
        assert_eq!(
            user_payload_encap(dr::XCDR, Ext::Final, false),
            Some(USER_PAYLOAD_ENCAP)
        );
        // XML is {0x00, 0x04} (DDS-XTypes 1.3 Table 60, DDSI-RTPS 2.5
        // Table 10.3), whatever the extensibility and the byte order; an
        // unknown id has no header.
        assert_eq!(
            user_payload_encap(dr::XML, Ext::Final, false),
            Some([0x00, 0x04, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XML, Ext::Mutable, true),
            Some(XML_ENCAP)
        );
        assert_eq!(user_payload_encap(99, Ext::Final, false), None);
        // big_endian=true selects the `_BE` variant (the even predecessor of
        // the odd `_LE` id): CDR_BE 0x00, PL_CDR_BE 0x02, PLAIN_CDR2_BE 0x06,
        // D_CDR2_BE 0x08, PL_CDR2_BE 0x0a (RTPS 2.5 §10.5). Used by the
        // durability service to replay a big-endian peer's stored sample.
        assert_eq!(
            user_payload_encap(dr::XCDR, Ext::Final, true),
            Some([0x00, 0x00, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XCDR, Ext::Mutable, true),
            Some([0x00, 0x02, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XCDR2, Ext::Final, true),
            Some([0x00, 0x06, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XCDR2, Ext::Appendable, true),
            Some([0x00, 0x08, 0x00, 0x00])
        );
        assert_eq!(
            user_payload_encap(dr::XCDR2, Ext::Mutable, true),
            Some([0x00, 0x0a, 0x00, 0x00])
        );
    }

    /// `RuntimeConfig::default()` has to honour `diagnostics.observability`,
    /// because the clients that need a sink most — the interop clients —
    /// build their participant from a `DomainParticipantQos` and never
    /// see a `RuntimeConfig`. The classification is tested rather than
    /// the env read: one process-global variable cannot be held by two
    /// tests of the same binary at once.
    #[test]
    fn the_observability_env_var_names_a_sink() {
        use ObservabilitySinkKind::{Null, StderrJson, Unknown};
        assert_eq!(observability_sink_kind(None), Null);
        for off in ["", "0", "off", "none", "null", "false", "  OFF  "] {
            assert_eq!(observability_sink_kind(Some(off)), Null, "`{off}`");
        }
        for on in [
            "1",
            "on",
            "true",
            "stderr",
            "json",
            "stderr-json",
            "  Stderr-JSON ",
        ] {
            assert_eq!(observability_sink_kind(Some(on)), StderrJson, "`{on}`");
        }
        // A value this build has no sink for is named, not silently
        // treated as "off": an operator who typed it believes telemetry
        // is on.
        assert_eq!(observability_sink_kind(Some("otlp")), Unknown);
        assert_eq!(observability_sink_kind(Some("syslog")), Unknown);
    }

    /// A discovered publication that this reader does not wire must say
    /// which of the refusal paths it took. Measured motivation: against
    /// RTI Connext 7.7.0 a subscriber logged `participants=1
    /// publications=1 matched=0` for a whole run and no line named the
    /// reason, because every one of those paths was a bare `return`.
    #[test]
    fn a_publication_without_a_reachable_locator_names_that_as_the_refusal() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::{Level, VecSink};

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt = DcpsRuntime::start(76, GuidPrefix::from_bytes([0xB1; 12]), cfg).expect("start");
        let (reader_eid, _rx) = rt
            .register_user_reader(refusal_reader_config(Vec::new()))
            .expect("register reader");

        // No PID_UNICAST_LOCATOR on the publication, and its participant
        // is not in the discovered cache — so no default locator either.
        // This is the shape RTI announces (it omits every parameter whose
        // value is its default), minus the SPDP beacon.
        let pubd = refusal_publication(Vec::new(), Vec::new());
        rt.wire_reader_to_remote_writer(reader_eid, &pubd);
        rt.shutdown();

        let refusals: Vec<_> = sink
            .snapshot()
            .into_iter()
            .filter(|e| e.name == "match.refused")
            .collect();
        assert_eq!(
            refusals.len(),
            1,
            "exactly one refusal expected, got {refusals:?}"
        );
        assert_eq!(refusals[0].level, Level::Warn);
        let reason = attr_of(&refusals[0], "reason");
        assert!(
            reason.contains("no reachable locator"),
            "reason was `{reason}`"
        );
        assert_eq!(attr_of(&refusals[0], "topic"), "RefusalTopic");
    }

    /// A match raised for a local reader that was deleted since is not a
    /// refusal: a chain of 21 processes filed 16 to 30 `match.refused`
    /// warnings per run while it shut down.
    #[test]
    fn a_match_for_a_deleted_local_reader_is_not_a_refusal() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::VecSink;

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt = DcpsRuntime::start(78, GuidPrefix::from_bytes([0xB3; 12]), cfg).expect("start");
        let (reader_eid, _rx) = rt
            .register_user_reader(refusal_reader_config(Vec::new()))
            .expect("register reader");
        rt.remove_user_reader(reader_eid);
        let pubd = refusal_publication(
            alloc::vec![Locator::udp_v4([127, 0, 0, 1], 7998)],
            Vec::new(),
        );
        rt.wire_reader_to_remote_writer(reader_eid, &pubd);
        rt.shutdown();

        let all = sink.snapshot();
        assert!(
            !all.iter().any(|e| e.name == "match.refused"),
            "all events: {all:?}"
        );
    }

    /// The second half of the same guarantee: a *different* refusal path
    /// carries a *different* reason. Without this the first test passes
    /// on a single hard-coded string.
    #[test]
    fn a_partition_mismatch_names_itself_as_the_refusal() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::VecSink;

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt = DcpsRuntime::start(77, GuidPrefix::from_bytes([0xB2; 12]), cfg).expect("start");
        let (reader_eid, _rx) = rt
            .register_user_reader(refusal_reader_config(alloc::vec!["left".to_string()]))
            .expect("register reader");

        // Reachable this time, so the locator gate passes and the run
        // reaches the PARTITION gate.
        let pubd = refusal_publication(
            alloc::vec![Locator::udp_v4([127, 0, 0, 1], 7999)],
            alloc::vec!["right".to_string()],
        );
        rt.wire_reader_to_remote_writer(reader_eid, &pubd);
        rt.shutdown();

        let all = sink.snapshot();
        let refusals: Vec<_> = all.iter().filter(|e| e.name == "match.refused").collect();
        assert_eq!(refusals.len(), 1, "all events: {all:?}");
        let reason = attr_of(refusals[0], "reason");
        assert!(reason.contains("PARTITION"), "reason was `{reason}`");
    }

    fn attr_of(event: &zerodds_foundation::observability::Event, key: &str) -> String {
        event
            .attrs
            .iter()
            .find(|a| a.key == key)
            .map(|a| a.value.clone())
            .unwrap_or_default()
    }

    /// The unicast initial peers an operator states as `ip`/`ip:port` reach
    /// the runtime through [`RuntimeConfig::initial_peer_specs`], expanded
    /// with the domain id `start` was given. Nothing here sets
    /// `discovery.peers`: two tests in one binary cannot hold a process-global
    /// env var at once, so before this field the expansion had no unit test
    /// at all.
    /// A reader on a ContentFilteredTopic announces the filter in its SEDP
    /// subscription (`PID_CONTENT_FILTER_PROPERTY`, DDSI-RTPS 2.5 §9.6.3.4),
    /// and announces it again with new parameters.
    #[test]
    fn the_content_filter_travels_in_the_subscription_and_is_reannounced() {
        use zerodds_rtps::subscription_data::ContentFilterProperty;
        let domain_lease = zerodds_test_domains::lease_domain();
        let domain = domain_lease.id();
        let rt = DcpsRuntime::start(
            domain,
            GuidPrefix::from_bytes([0xCF; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let _stop_rt = StopOnDrop(Arc::clone(&rt));
        let filter = |parameter: &str| ContentFilterProperty {
            content_filtered_topic_name: "HighScores".into(),
            related_topic_name: "Scores".into(),
            filter_class_name: "DDSSQL".into(),
            filter_expression: "score > %0".into(),
            expression_parameters: alloc::vec![parameter.into()],
        };
        let (eid, _rx) = rt
            .register_user_reader(UserReaderConfig {
                topic_name: "Scores".into(),
                type_name: "Score".into(),
                content_filter: Some(filter("9")),
                ..Default::default()
            })
            .expect("reader");
        let announced = |rt: &DcpsRuntime| {
            let subs = rt.announced_subs.lock().unwrap();
            let mine: Vec<_> = subs.iter().filter(|s| s.key.entity_id == eid).collect();
            assert_eq!(mine.len(), 1, "one announcement per reader");
            mine[0].content_filter.clone()
        };
        assert_eq!(announced(&rt), Some(filter("9")));
        rt.update_user_reader_content_filter(eid, Some(filter("40")))
            .expect("re-announce");
        assert_eq!(announced(&rt), Some(filter("40")));
        rt.remove_user_reader(eid);
        assert!(rt.update_user_reader_content_filter(eid, None).is_err());
        rt.shutdown();
    }

    /// A short lease shortens the beacon period it was not given: three
    /// beacons a lease. A period of its own stays, and the default lease
    /// keeps the spec's 30 s period (§9.6.2.4).
    #[test]
    fn a_short_lease_without_a_period_beacons_three_times_a_lease() {
        assert_eq!(
            super::default_spdp_period_for(Duration::from_secs(100)),
            DEFAULT_SPDP_PERIOD
        );
        assert_eq!(DEFAULT_SPDP_PERIOD, Duration::from_secs(30));
        assert_eq!(
            super::default_spdp_period_for(Duration::from_secs(10)),
            Duration::from_millis(3333) + Duration::from_nanos(333_333)
        );
        assert_eq!(
            super::default_spdp_period_for(Duration::from_millis(150)),
            Duration::from_millis(100)
        );
        let source_of = |yaml: &str, tag: &str| {
            let path = std::env::temp_dir().join(alloc::format!(
                "zerodds-config-lease-{}-{tag}.yaml",
                std::process::id()
            ));
            std::fs::write(&path, yaml).expect("write");
            let source = ConfigSource::from_path(&path).expect("loads");
            std::fs::remove_file(&path).expect("remove");
            RuntimeConfig::from_source(&source).expect("valid")
        };
        let short = source_of(
            "discovery:\n  participant_lease_duration_ms: 10000\n",
            "short",
        );
        assert_eq!(short.participant_lease_duration, Duration::from_secs(10));
        assert!(short.spdp_period * 3 <= short.participant_lease_duration);
        let own = source_of(
            "discovery:\n  participant_lease_duration_ms: 10000\n  spdp_period_ms: 4000\n",
            "own",
        );
        assert_eq!(own.spdp_period, Duration::from_secs(4));
    }

    #[test]
    fn initial_peer_specs_reach_the_runtime_without_touching_the_environment() {
        let domain_lease = zerodds_test_domains::lease_domain();
        let domain = domain_lease.id() as u32;
        let path = std::env::temp_dir().join(alloc::format!(
            "zerodds-config-start-{}-{domain}.yaml",
            std::process::id()
        ));
        std::fs::write(&path, "runtime:\n  tick_period_ms: 9\ndiscovery:\n  no_multicast: true\n  max_peer_participants: 3\n  peers:\n    - 10.9.8.7\n    - 10.9.8.6:7411\n").expect("runtime base file");
        let source = ConfigSource::from_path(&path).expect("explicit file loads");
        std::fs::remove_file(&path).expect("remove this test's base file");
        let cfg = RuntimeConfig::from_source(&source).expect("typed runtime values");
        let rt = DcpsRuntime::start(domain as i32, GuidPrefix::from_bytes([0xE1; 12]), cfg)
            .expect("start");
        let _stop_rt = StopOnDrop(Arc::clone(&rt));
        let peers = rt.config.initial_peers.clone();
        assert_eq!(rt.config.tick_period, Duration::from_millis(9));
        assert!(!rt.config.spdp_multicast_send);
        rt.shutdown();

        // `ip` without a port → the well-known SPDP unicast ports of the
        // participant indices 0..3; `ip:port` → exactly that one locator.
        assert_eq!(peers.len(), 4, "peers: {peers:?}");
        for pid in 0..3u32 {
            let want = Locator::udp_v4([10, 9, 8, 7], super::spdp_unicast_port(domain, pid));
            assert!(peers.contains(&want), "missing {want:?} in {peers:?}");
        }
        assert!(peers.contains(&Locator::udp_v4([10, 9, 8, 6], 7411)));
    }

    /// A `wire.rtps_dialect` spelling that names no dialect is carried as
    /// [`RuntimeConfig::rtps_dialect_unknown`] and reported from there — so
    /// the report is testable by filling the struct, without the env var the
    /// value originally came from.
    #[test]
    fn an_unknown_rtps_dialect_is_reported_from_the_config() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::{Level, VecSink};

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            rtps_dialect_unknown: Some("cylcone".to_string()),
            ..RuntimeConfig::default()
        };
        let domain_lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(domain_lease.id(), GuidPrefix::from_bytes([0xE2; 12]), cfg)
            .expect("start");
        let _stop_rt = StopOnDrop(Arc::clone(&rt));
        rt.shutdown();

        let events: Vec<_> = sink
            .snapshot()
            .into_iter()
            .filter(|e| e.name == "config.rtps_dialect.unknown")
            .collect();
        assert_eq!(events.len(), 1, "events: {events:?}");
        assert_eq!(events[0].level, Level::Warn);
        assert_eq!(attr_of(&events[0], "value"), "cylcone");
        assert_eq!(
            attr_of(&events[0], "applied"),
            RtpsDialect::MaximallyInteroperable.as_str()
        );
    }

    /// A `wire.codec_dialect` spelling that names no dialect leaves the
    /// specification's and is reported, as `wire.rtps_dialect`'s is.
    #[test]
    fn an_unknown_codec_dialect_is_reported_and_the_specification_applies() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::{Level, VecSink};

        assert_eq!(
            codec_dialect_value(Some("fastdd")),
            (
                zerodds_ast_layout::Dialect::Specification,
                Some("fastdd".to_string())
            )
        );
        assert_eq!(
            codec_dialect_value(Some(" fastdds ")),
            (zerodds_ast_layout::Dialect::FastDds, None)
        );
        assert_eq!(
            codec_dialect_value(None),
            (zerodds_ast_layout::Dialect::Specification, None)
        );

        let sink = StdArc::new(VecSink::new());
        let lease = zerodds_test_domains::lease_domain();
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            codec_dialect_unknown: Some("fastdd".to_string()),
            ..RuntimeConfig::default()
        };
        let rt =
            DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([0xE4; 12]), cfg).expect("start");
        assert_eq!(
            rt.codec_dialect(),
            zerodds_ast_layout::Dialect::Specification
        );
        rt.shutdown();
        let events: Vec<_> = sink
            .snapshot()
            .into_iter()
            .filter(|e| e.name == "config.codec_dialect.unknown")
            .collect();
        assert_eq!(events.len(), 1, "events: {events:?}");
        assert_eq!(events[0].level, Level::Warn);
        assert_eq!(attr_of(&events[0], "value"), "fastdd");
        assert_eq!(attr_of(&events[0], "applied"), "specification");
    }

    /// A well-formed dialect leaves nothing to complain about, so the same
    /// report stays silent — without this the test above passes on a
    /// hard-coded event that is always emitted.
    #[test]
    fn a_config_without_an_unknown_dialect_reports_nothing() {
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::VecSink;

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            rtps_dialect_unknown: None,
            ..RuntimeConfig::default()
        };
        let domain_lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(domain_lease.id(), GuidPrefix::from_bytes([0xE3; 12]), cfg)
            .expect("start");
        let _stop_rt = StopOnDrop(Arc::clone(&rt));
        rt.shutdown();

        assert!(
            !sink
                .snapshot()
                .iter()
                .any(|e| e.name == "config.rtps_dialect.unknown"),
            "no dialect complaint expected"
        );
    }

    /// The diagnostic switches are per-participant config, not a
    /// process-global env read: two runtimes in one process can disagree on
    /// them. `phase_timing` in particular used to be a `static` cache that
    /// answered the same for the whole process no matter what a test wanted.
    #[test]
    fn the_diagnostic_switches_are_per_runtime_config() {
        let on = RuntimeConfig {
            trace_send_err: true,
            phase_dump: true,
            phase_timing: true,
            ..RuntimeConfig::default()
        };
        let off = RuntimeConfig {
            trace_send_err: false,
            phase_dump: false,
            phase_timing: false,
            ..RuntimeConfig::default()
        };
        let domain_lease = zerodds_test_domains::lease_domain();
        let domain = domain_lease.id();
        let a = DcpsRuntime::start(domain, GuidPrefix::from_bytes([0xE4; 12]), on).expect("a");
        let _stop_a = StopOnDrop(Arc::clone(&a));
        let b = DcpsRuntime::start(domain, GuidPrefix::from_bytes([0xE5; 12]), off).expect("b");
        let _stop_b = StopOnDrop(Arc::clone(&b));
        assert!(a.config.trace_send_err && a.config.phase_dump && a.config.phase_timing);
        assert!(!b.config.trace_send_err && !b.config.phase_dump && !b.config.phase_timing);
        b.shutdown();
        a.shutdown();
    }

    /// `expand_initial_peer_specs` is the whole `discovery.peers` grammar as a
    /// pure function of the config field: a bare `ip` fans out to
    /// `initial_peer_max_participants` well-known ports, `ip:port` stays one
    /// locator, anything else is dropped.
    #[test]
    fn initial_peer_specs_expand_per_the_configured_participant_limit() {
        let specs = alloc::vec![
            "192.168.1.10".to_string(),
            " 192.168.1.11:7500 ".to_string(),
            "not-an-ip".to_string(),
            String::new(),
        ];
        let out = super::expand_initial_peer_specs(&specs, 5, 2, &Default::default());
        assert_eq!(out.len(), 3, "out: {out:?}");
        assert_eq!(out[0].port, super::spdp_unicast_port(5, 0));
        assert_eq!(out[1].port, super::spdp_unicast_port(5, 1));
        assert_eq!(out[2].port, 7500);
        assert_eq!(out[2].address[12..], [192, 168, 1, 11]);
    }

    /// The TSN interface/VLAN/PCP are config fields; a build without the
    /// `tsn-live` feature can still state them, which is what makes the
    /// transport selection configurable rather than env-bound.
    #[test]
    fn tsn_transport_parameters_are_config_fields() {
        let cfg = RuntimeConfig {
            tsn_interface: Some("eth0".to_string()),
            tsn_vlan: 5,
            tsn_pcp: 3,
            ..RuntimeConfig::default()
        };
        assert_eq!(cfg.tsn_interface.as_deref(), Some("eth0"));
        assert_eq!(cfg.tsn_vlan, 5);
        assert_eq!(cfg.tsn_pcp, 3);
    }

