    fn refusal_publication(
        unicast_locators: Vec<Locator>,
        partition: Vec<String>,
    ) -> zerodds_rtps::publication_data::PublicationBuiltinTopicData {
        let remote = GuidPrefix::from_bytes([0xC7; 12]);
        zerodds_rtps::publication_data::PublicationBuiltinTopicData {
            vendor_id: Some(zerodds_rtps::wire_types::VendorId::ZERODDS),
            key: Guid::new(remote, EntityId::user_writer_with_key([0, 0, 1])),
            participant_key: Guid::new(remote, EntityId::PARTICIPANT),
            topic_name: "RefusalTopic".into(),
            type_name: "RefusalType".into(),
            durability: zerodds_qos::DurabilityKind::Volatile,
            durability_service: zerodds_qos::DurabilityServiceQosPolicy::default(),
            // RELIABLE, so this fixture reaches the gates it is about:
            // the default is BEST_EFFORT and a reliable reader refuses it
            // one gate earlier (with a `qos.incompatible.requested` event,
            // which is the path that already had a log).
            reliability: zerodds_qos::ReliabilityQosPolicy {
                kind: zerodds_qos::ReliabilityKind::Reliable,
                ..zerodds_qos::ReliabilityQosPolicy::default()
            },
            ownership: zerodds_qos::OwnershipKind::Shared,
            ownership_strength: 0,
            liveliness: zerodds_qos::LivelinessQosPolicy::default(),
            deadline: zerodds_qos::DeadlineQosPolicy::default(),
            latency_budget: zerodds_qos::LatencyBudgetQosPolicy::default(),
            destination_order: zerodds_qos::DestinationOrderQosPolicy::default(),
            lifespan: zerodds_qos::LifespanQosPolicy::default(),
            presentation: Default::default(),
            partition,
            user_data: Vec::new(),
            topic_data: Vec::new(),
            group_data: Vec::new(),
            type_information: None,
            type_id_v1: None,
            type_object_v1: None,
            data_representation: Vec::new(),
            security_info: None,
            sym_cipher_algo_info: None,
            data_tags: Default::default(),
            properties: Default::default(),
            service_instance_name: None,
            related_entity_guid: None,
            topic_aliases: None,
            type_identifier: zerodds_types::TypeIdentifier::None,
            unicast_locators,
            multicast_locators: Vec::new(),
            group_guid: None,
            data_max_size_serialized: None,
            entity_name: None,
        }
    }

    /// A reader's RESOURCE_LIMITS reaches the reliable receive cache.
    ///
    /// `max_samples_per_proxy` is the capacity of the per-writer-proxy
    /// KEEP_ALL buffer a reliable reader fills while an earlier
    /// SequenceNumber is missing, and for a long time it decided by itself:
    /// `UserReaderConfig` carried no resource limits, so the QoS a
    /// `DataReader` was created with could not reach the number that governs
    /// how much it may hold. A measured 0 %-loss setting existed and could
    /// not be asked for.
    ///
    /// Spec §2.2.3.19. This goes through `register_user_reader` and reads the
    /// number off the reader that was actually built, rather than
    /// recomputing the rule beside it — a test that restates the formula
    /// passes just as happily when nothing hands it through.
    #[test]
    fn a_readers_resource_limits_reach_its_receive_cache() {
        fn capacity_of(max_samples: i32, prefix: u8) -> usize {
            let rt = DcpsRuntime::start(
                7,
                GuidPrefix::from_bytes([prefix; 12]),
                RuntimeConfig::default(),
            )
            .expect("start runtime");
            let (eid, _rx) = rt
                .register_user_reader(UserReaderConfig {
                    resource_limits: zerodds_qos::ResourceLimitsQosPolicy {
                        max_samples,
                        ..Default::default()
                    },
                    topic_name: "LimitsTopic".into(),
                    type_name: "LimitsType".into(),
                    ..Default::default()
                })
                .expect("register the reader");
            let slot = rt.reader_slot(eid).expect("the reader was registered");
            let capacity = slot
                .lock()
                .map(|s| s.reader.max_samples_per_proxy())
                .expect("the slot mutex");
            rt.shutdown();
            capacity
        }

        assert_eq!(
            capacity_of(4096, 0xB1),
            4096,
            "the reader asked for 4096 and has to get it"
        );
        assert_ne!(
            4096, DEFAULT_MAX_SAMPLES_PER_PROXY,
            "the assertion above is worthless if 4096 is already the default"
        );

        let unlimited = zerodds_qos::ResourceLimitsQosPolicy::default().max_samples;
        assert!(
            unlimited < 0,
            "LENGTH_UNLIMITED is the policy's own default"
        );
        assert_eq!(
            capacity_of(unlimited, 0xB2),
            DEFAULT_MAX_SAMPLES_PER_PROXY,
            "a QoS naming no bound must not take away the one the runtime has"
        );
        assert_eq!(
            capacity_of(0, 0xB3),
            DEFAULT_MAX_SAMPLES_PER_PROXY,
            "zero would be a cache that holds nothing — the runtime's bound stands"
        );
    }

    #[test]
    fn observability_sink_records_writer_and_reader_creation() {
        // VecSink injizieren, Writer + Reader erzeugen,
        // check that both events arrive.
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::{Component, Level, VecSink};

        let sink = StdArc::new(VecSink::new());
        let cfg = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt =
            DcpsRuntime::start(7, GuidPrefix::from_bytes([0xAA; 12]), cfg).expect("start runtime");
        let _ = rt.register_user_writer(UserWriterConfig {
            topic_name: "ObsTopic".into(),
            type_name: "ObsType".into(),
            ..Default::default()
        });
        let _ = rt.register_user_reader(UserReaderConfig {
            topic_name: "ObsTopic".into(),
            type_name: "ObsType".into(),
            ..Default::default()
        });
        rt.shutdown();

        let events = sink.snapshot();
        assert!(
            events.iter().any(|e| e.name == "user_writer.created"
                && e.component == Component::Dcps
                && e.level == Level::Info),
            "writer-event missing: got {:?}",
            events.iter().map(|e| e.name).collect::<Vec<_>>()
        );
        assert!(
            events
                .iter()
                .any(|e| e.name == "user_reader.created" && e.component == Component::Dcps),
            "reader-event missing"
        );
        // The topic attribute must hang on the writer.created event.
        let writer_event = events
            .iter()
            .find(|e| e.name == "user_writer.created")
            .expect("writer event");
        assert!(
            writer_event
                .attrs
                .iter()
                .any(|a| a.key == "topic" && a.value == "ObsTopic"),
            "topic attr missing"
        );
    }

    #[test]
    fn user_endpoint_entity_kind_follows_keyedness() {
        // Regression (ROS-2 cross-vendor): the entityKind of a user
        // endpoint MUST follow the type keyedness (Spec §9.3.1.2). A
        // a keyless type yields NoKey (Writer 0x03 / Reader 0x04), a
        // keyed type WithKey (0x02 / 0x07). If this does not match the
        // peer, CycloneDDS/ROS 2 silently rejects the endpoint match
        // (DDS_INVALID_QOS_POLICY_ID, no log). create_datawriter/
        // create_datareader derive `is_keyed` from `DdsType::HAS_KEY`.
        use zerodds_rtps::wire_types::EntityKind;
        let rt = DcpsRuntime::start(
            11,
            GuidPrefix::from_bytes([0xBC; 12]),
            RuntimeConfig::default(),
        )
        .expect("start runtime");
        let mk_w = || UserWriterConfig {
            topic_name: "KindTopic".into(),
            type_name: "KindType".into(),
            ..Default::default()
        };
        let mk_r = || UserReaderConfig {
            topic_name: "KindTopic".into(),
            type_name: "KindType".into(),
            ..Default::default()
        };
        // keyless (HAS_KEY=false) -> NoKey
        let w_nokey = rt.register_user_writer_kind(mk_w(), false).expect("writer");
        assert_eq!(w_nokey.entity_kind, EntityKind::UserWriterNoKey);
        let (r_nokey, _) = rt.register_user_reader_kind(mk_r(), false).expect("reader");
        assert_eq!(r_nokey.entity_kind, EntityKind::UserReaderNoKey);
        // keyed (HAS_KEY=true) -> WithKey
        let w_key = rt.register_user_writer_kind(mk_w(), true).expect("writer");
        assert_eq!(w_key.entity_kind, EntityKind::UserWriterWithKey);
        let (r_key, _) = rt.register_user_reader_kind(mk_r(), true).expect("reader");
        assert_eq!(r_key.entity_kind, EntityKind::UserReaderWithKey);
        rt.shutdown();
    }

    /// Body/encap cannot drift: both the encapsulation header
    /// ([`user_payload_encap`]) and `DataWriter::write`'s body encoder resolve
    /// the emitted representation from ONE source — [`user_writer_offer_first`].
    /// This test proves that a runtime-side override
    /// (`set_user_writer_data_rep_override`) moves that single source, so a
    /// later write picks the matching body encoder for the new encap. There is
    /// no separate cached decision that could produce a header/body mismatch.
    #[test]
    fn writer_offer_first_follows_override_no_body_encap_drift() {
        use zerodds_rtps::publication_data::data_representation as dr;
        let rt = DcpsRuntime::start(
            13,
            GuidPrefix::from_bytes([0xC7; 12]),
            RuntimeConfig::default(),
        )
        .expect("start runtime");
        let cfg = UserWriterConfig {
            topic_name: "OfferTopic".into(),
            type_name: "OfferType".into(),
            data_representation_offer: Some(alloc::vec![dr::XCDR]),
            ..Default::default()
        };
        let eid = rt.register_user_writer(cfg).expect("writer");
        // Unlocked (replay-style) writer: the single source follows the override,
        // so the durability/routing replay writers re-declare a persisted wire.
        assert_eq!(rt.user_writer_offer_first(eid), Some(dr::XCDR));
        rt.set_user_writer_data_rep_override(eid, Some(alloc::vec![dr::XCDR2]))
            .expect("override on unlocked writer");
        assert_eq!(rt.user_writer_offer_first(eid), Some(dr::XCDR2));

        // XML as the first element is an offer the runtime emits; an
        // unknown id is refused, and the offer stays.
        assert!(
            rt.set_user_writer_data_rep_override(eid, Some(alloc::vec![99, dr::XCDR]))
                .is_err(),
            "an unknown first id must be rejected"
        );
        assert_eq!(rt.user_writer_offer_first(eid), Some(dr::XCDR2));
        rt.set_user_writer_data_rep_override(eid, Some(alloc::vec![dr::XML, dr::XCDR]))
            .expect("XML first");
        assert_eq!(rt.user_writer_offer_first(eid), Some(dr::XML));
        rt.set_user_writer_data_rep_override(eid, Some(alloc::vec![dr::XCDR2]))
            .expect("back to XCDR2");

        // A typed DataWriter locks its representation: the override is then
        // rejected, so the body encoder and encap can never diverge across their
        // two separate slot locks.
        rt.lock_user_writer_representation(eid).expect("lock");
        assert!(
            rt.set_user_writer_data_rep_override(eid, Some(alloc::vec![dr::XCDR]))
                .is_err(),
            "override on a locked writer must be rejected"
        );
        // The locked value is unchanged.
        assert_eq!(rt.user_writer_offer_first(eid), Some(dr::XCDR2));
        rt.shutdown();
    }

    /// DDS-XTypes 1.3 Table 60: XML is `{0x00, 0x04}`. A writer registered
    /// with XML as its first representation sends the document and not a
    /// CDR body under a `CDR_LE` header, which it used to be given and then
    /// refused for; an unknown first id is still refused.
    #[test]
    fn a_writer_registered_with_xml_first_is_accepted() {
        use zerodds_rtps::publication_data::data_representation as dr;
        let rt = DcpsRuntime::start(
            13,
            GuidPrefix::from_bytes([0xC8; 12]),
            RuntimeConfig::default(),
        )
        .expect("start runtime");
        let cfg = |offer| UserWriterConfig {
            topic_name: "XmlTopic".into(),
            type_name: "XmlType".into(),
            data_representation_offer: Some(offer),
            ..Default::default()
        };
        assert!(
            rt.register_user_writer(cfg(alloc::vec![dr::XML, dr::XCDR]))
                .is_ok()
        );
        assert!(
            rt.register_user_writer(cfg(alloc::vec![99, dr::XCDR]))
                .is_err()
        );
        assert!(
            rt.register_user_writer(cfg(alloc::vec![dr::XCDR2, dr::XML]))
                .is_ok()
        );
        assert!(rt.register_user_writer(cfg(alloc::vec![])).is_ok());
        rt.shutdown();
    }

    #[test]
    fn incompatible_qos_match_emits_loud_warning() {
        // C2 "loud instead of silent": an incompatible QoS match is logged as a
        // warn event with topic + policy, not silently discarded.
        // Setup: writer Volatile + reader TransientLocal on the same
        // Topic (reader requests more durability than the writer offers)
        // → intra-runtime match fails with policy DURABILITY.
        use std::sync::Arc as StdArc;
        use zerodds_foundation::observability::{Component, Level, VecSink};

        let sink = StdArc::new(VecSink::new());
        let cfg_a = RuntimeConfig {
            observability: sink.clone(),
            tick_period: Duration::from_millis(5),
            ..RuntimeConfig::default()
        };
        let cfg_b = RuntimeConfig {
            tick_period: Duration::from_millis(5),
            ..RuntimeConfig::default()
        };
        // Two same-process runtimes, same domain → inproc discovery.
        let rt = DcpsRuntime::start(13, GuidPrefix::from_bytes([0xCE; 12]), cfg_a)
            .expect("start runtime a");
        let rt_b = DcpsRuntime::start(13, GuidPrefix::from_bytes([0xCF; 12]), cfg_b)
            .expect("start runtime b");
        let _w = rt
            .register_user_writer(UserWriterConfig {
                topic_name: "QT".into(),
                type_name: "QType".into(),
                reliable: false,
                ..Default::default()
            })
            .expect("writer");
        let _r = rt_b
            .register_user_reader(UserReaderConfig {
                topic_name: "QT".into(),
                type_name: "QType".into(),
                reliable: false,
                durability: zerodds_qos::DurabilityKind::TransientLocal,
                ..Default::default()
            })
            .expect("reader");
        // Await the match pass.
        let mut found = false;
        for _ in 0..40 {
            std::thread::sleep(Duration::from_millis(25));
            let events = sink.snapshot();
            if events.iter().any(|e| {
                (e.name == "qos.incompatible.offered" || e.name == "qos.incompatible.requested")
                    && e.component == Component::Dcps
                    && e.level == Level::Warn
                    && e.attrs.iter().any(|a| a.key == "topic" && a.value == "QT")
                    && e.attrs
                        .iter()
                        .any(|a| a.key == "policy" && a.value == "DURABILITY")
            }) {
                found = true;
                break;
            }
        }
        rt.shutdown();
        rt_b.shutdown();
        assert!(
            found,
            "expected a loud qos.incompatible warn event with policy DURABILITY"
        );
    }

    #[test]
    fn spdp_unicast_port_follows_rtps_formula() {
        // Spec §9.6.1.4.1: PB + DG*domain + d1 + PG*pid = 7400+250*d+10+2*pid.
        assert_eq!(super::spdp_unicast_port(0, 0), 7410);
        assert_eq!(spdp_unicast_port(0, 1), 7412);
        assert_eq!(spdp_unicast_port(1, 0), 7660);
        assert_eq!(spdp_unicast_port(7, 0), 9160);
    }

    #[test]
    fn announce_locator_pins_interface_over_route_probe() {
        // Interface pinning: a set interface takes precedence over the
        // route probe (multi-homed robustness, cf. Cyclone NetworkInterface).
        let udp = UdpTransport::bind_v4(Ipv4Addr::UNSPECIFIED, 0).expect("bind");
        let pin = Ipv4Addr::new(10, 11, 12, 13);
        let loc = super::announce_locator(&udp, pin);
        assert_eq!(loc.kind, zerodds_rtps::wire_types::LocatorKind::UdpV4);
        assert_eq!(loc.address[12..], [10, 11, 12, 13]);
        // Without a pin (UNSPECIFIED) → probe/fallback does NOT return the pin IP.
        let auto = super::announce_locator(&udp, Ipv4Addr::UNSPECIFIED);
        assert_ne!(auto.address[12..], [10, 11, 12, 13]);
    }

    #[test]
    fn stage_outbound_merges_until_the_message_is_full() {
        // What LATENCY_BUDGET buys (DDS 1.4 §2.2.3.9): samples handed over in
        // the same window share one datagram, up to the message size.
        let a = Locator::udp_v4([10, 0, 0, 1], 7500);
        let targets = Arc::new(alloc::vec![a]);
        let buffers = super::BatchBuffers::default();
        let mut pending: Vec<super::PendingMessage> = Vec::new();
        let mut msg = alloc::vec![0u8; 20];
        msg.extend_from_slice(&[7u8; 100]);
        let cap = 20 + 3 * 100;
        for i in 0..3 {
            let staged = super::stage_outbound(
                &mut pending,
                &targets,
                &msg,
                cap,
                Duration::from_millis(i),
                &buffers,
            );
            assert!(staged.displaced.is_none(), "nothing is full yet at {i}");
            assert_eq!(staged.opened, i == 0, "only the first datagram opens one");
        }
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].merged, 3);
        assert_eq!(pending[0].bytes.len(), cap);
        assert_eq!(
            pending[0].opened_at,
            Duration::ZERO,
            "the budget runs from the oldest sample in the batch"
        );

        let staged = super::stage_outbound(
            &mut pending,
            &targets,
            &msg,
            cap,
            Duration::from_millis(9),
            &buffers,
        );
        let displaced = staged.displaced.expect("the full message is handed back");
        assert_eq!(displaced.merged, 3);
        assert!(staged.opened, "the fourth datagram opens the next message");
        assert_eq!(pending[0].merged, 1);
        assert_eq!(pending[0].opened_at, Duration::from_millis(9));
    }

    #[test]
    fn stage_outbound_keeps_destinations_apart() {
        // Two reader proxies are two destinations. Merging across them would
        // send each sample to a reader it was not addressed to.
        let a = Arc::new(alloc::vec![Locator::udp_v4([10, 0, 0, 1], 7500)]);
        let b = Arc::new(alloc::vec![Locator::udp_v4([10, 0, 0, 2], 7500)]);
        let buffers = super::BatchBuffers::default();
        let mut pending: Vec<super::PendingMessage> = Vec::new();
        let mut msg = alloc::vec![0u8; 20];
        msg.extend_from_slice(&[7u8; 100]);
        let _ = super::stage_outbound(&mut pending, &a, &msg, 14_720, Duration::ZERO, &buffers);
        let _ = super::stage_outbound(&mut pending, &b, &msg, 14_720, Duration::ZERO, &buffers);
        // The same destinations in another list are the same batch.
        let a_again = Arc::new(alloc::vec![Locator::udp_v4([10, 0, 0, 1], 7500)]);
        let _ = super::stage_outbound(
            &mut pending,
            &a_again,
            &msg,
            14_720,
            Duration::ZERO,
            &buffers,
        );
        assert_eq!(pending.len(), 2, "one batch per destination set");
        assert_eq!(pending[0].merged, 2);
        assert_eq!(pending[0].targets, a);
        assert_eq!(pending[1].targets, b);
    }

    #[test]
    fn drain_due_batches_takes_everything_at_a_zero_budget() {
        // §2.2.3.10.3: a zero LATENCY_BUDGET is "as fast as possible", so no
        // batch may be held over a drain pass.
        let mut pending = alloc::vec![
            super::PendingMessage {
                targets: Arc::new(alloc::vec![Locator::udp_v4([10, 0, 0, 1], 7500)]),
                bytes: alloc::vec![0u8; 40],
                merged: 2,
                opened_at: Duration::from_millis(5),
            },
            super::PendingMessage {
                targets: Arc::new(alloc::vec![Locator::udp_v4([10, 0, 0, 2], 7500)]),
                bytes: alloc::vec![0u8; 40],
                merged: 1,
                opened_at: Duration::from_millis(5),
            },
        ];
        let due = super::drain_due_batches(&mut pending, Duration::ZERO, Duration::from_millis(5));
        assert_eq!(due.len(), 2);
        assert!(pending.is_empty());
    }

    #[test]
    fn drain_due_batches_holds_a_batch_until_its_budget_is_up() {
        let mk = |opened_ms: u64| super::PendingMessage {
            targets: Arc::new(alloc::vec![Locator::udp_v4([10, 0, 0, 1], 7500)]),
            bytes: alloc::vec![0u8; 40],
            merged: 1,
            opened_at: Duration::from_millis(opened_ms),
        };
        let mut pending = alloc::vec![mk(0), mk(9)];
        let due = super::drain_due_batches(
            &mut pending,
            Duration::from_millis(10),
            Duration::from_millis(10),
        );
        assert_eq!(due.len(), 1, "only the batch that has waited 10 ms is due");
        assert_eq!(due[0].opened_at, Duration::ZERO);
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].opened_at, Duration::from_millis(9));
    }

    #[test]
    fn select_transmit_locators_sends_once_per_participant() {
        // The measured case on the Linux test host: one peer announces `eth0` and
        // `docker0`, both of which reach the same process. RTPS 2.5 §8.5.3.2
        // calls the list the addresses at which the endpoint *can* be reached;
        // §8.4.7.1 sends the message to the reader once. Two entries are one
        // peer, not two.
        let eth0 = Locator::udp_v4([192, 168, 178, 61], 7500);
        let docker0 = Locator::udp_v4([172, 17, 0, 1], 7500);
        let picked = super::select_transmit_locators_by(&[docker0, eth0], |l| {
            if l.address[12] == 192 {
                super::LocatorRank::ViaOwnPrimary
            } else {
                super::LocatorRank::ViaOtherInterface
            }
        });
        assert_eq!(
            picked,
            alloc::vec![eth0],
            "the locator reachable over the announced interface is the one transmitted to"
        );
    }

    #[test]
    fn select_transmit_locators_keeps_a_single_candidate_untouched() {
        let only = Locator::udp_v4([10, 0, 0, 7], 7500);
        let picked = super::select_transmit_locators_by(&[only], |_| {
            panic!("a single candidate must not be probed")
        });
        assert_eq!(picked, alloc::vec![only]);
    }

    #[test]
    fn select_transmit_locators_keeps_all_when_no_candidate_has_a_route() {
        // The routing table said nothing usable about either address. Dropping
        // one on that basis would turn "we do not know" into "we do not send".
        let a = Locator::udp_v4([203, 0, 113, 1], 7500);
        let b = Locator::udp_v4([203, 0, 113, 2], 7500);
        let picked =
            super::select_transmit_locators_by(&[a, b], |_| super::LocatorRank::Unroutable);
        assert_eq!(picked, alloc::vec![a, b]);
    }

    #[test]
    fn select_transmit_locators_passes_other_transports_through() {
        // SHM and UDPv4 address the peer over different transports; only the
        // UDPv4 entries are the same peer twice.
        let shm = Locator {
            kind: LocatorKind::Shm,
            port: 0,
            address: [7u8; 16],
        };
        let a = Locator::udp_v4([192, 168, 178, 61], 7500);
        let b = Locator::udp_v4([172, 17, 0, 1], 7500);
        let picked = super::select_transmit_locators_by(&[shm, a, b], |l| {
            if l.address[12] == 192 {
                super::LocatorRank::ViaOwnPrimary
            } else {
                super::LocatorRank::ViaOtherInterface
            }
        });
        assert_eq!(picked, alloc::vec![shm, a]);
    }

    #[test]
    fn select_transmit_locators_drops_a_repeated_locator() {
        let a = Locator::udp_v4([192, 168, 178, 61], 7500);
        let picked =
            super::select_transmit_locators_by(&[a, a], |_| super::LocatorRank::ViaOwnPrimary);
        assert_eq!(
            picked,
            alloc::vec![a],
            "the same address is one destination"
        );
    }

    #[test]
    fn announce_locators_pins_to_single_interface() {
        // #27: an explicit interface keeps the deterministic SINGLE-locator
        // behaviour — no multi-interface fan-out of the announced set.
        let udp = UdpTransport::bind_v4(Ipv4Addr::UNSPECIFIED, 0).expect("bind");
        let pin = Ipv4Addr::new(10, 11, 12, 13);
        let locs = super::announce_locators(&udp, pin);
        assert_eq!(
            locs.len(),
            1,
            "pinned interface announces exactly one locator"
        );
        assert_eq!(locs[0].address[12..], [10, 11, 12, 13]);
        assert_eq!(locs[0], super::announce_locator(&udp, pin));
    }

    #[test]
    fn announce_locators_automatic_is_non_empty_and_includes_probe() {
        // Automatic mode enumerates eligible interfaces; the list is never
        // empty and always contains at least the route-probe address (so the
        // default-route peer stays reachable while extra segments are added).
        let udp = UdpTransport::bind_v4(Ipv4Addr::UNSPECIFIED, 0).expect("bind");
        let locs = super::announce_locators(&udp, Ipv4Addr::UNSPECIFIED);
        assert!(!locs.is_empty(), "automatic announce is never empty");
        let probe = super::announce_locator(&udp, Ipv4Addr::UNSPECIFIED);
        // The probe address is a real interface (or the loopback fallback);
        // either way it must be present in the announced set.
        assert!(
            locs.contains(&probe),
            "announced set includes the route-probe locator"
        );
        // No exact-duplicate locators in the announced set.
        let mut seen = alloc::vec::Vec::new();
        for l in &locs {
            assert!(!seen.contains(l), "no duplicate announced locators");
            seen.push(*l);
        }
    }

    #[test]
    fn expand_initial_peer_ip_only_yields_well_known_port_range() {
        let m = super::INITIAL_PEER_MAX_PARTICIPANTS;
        let mut out = Vec::new();
        super::expand_initial_peer("127.0.0.1", 0, m, &Default::default(), &mut out);
        assert_eq!(out.len(), m as usize);
        assert_eq!(out[0].port, 7410);
        assert_eq!(out[1].port, 7412);
        // Larger limit → more ports (C1 dense multi-robot scenarios).
        let mut wide = Vec::new();
        super::expand_initial_peer("127.0.0.1", 0, 30, &Default::default(), &mut wide);
        assert_eq!(wide.len(), 30);
        assert_eq!(wide[29].port, 7410 + 2 * 29);
        // ip:port -> exactly one exact locator.
        let mut one = Vec::new();
        super::expand_initial_peer("10.0.0.5:7410", 0, m, &Default::default(), &mut one);
        assert_eq!(one.len(), 1);
        assert_eq!(one[0].port, 7410);
        assert_eq!(one[0].address[12..], [10, 0, 0, 5]);
        // Garbage is ignored.
        let mut none = Vec::new();
        super::expand_initial_peer("not-an-ip", 0, m, &Default::default(), &mut none);
        assert!(none.is_empty());
    }

    #[test]
    #[ignore = "heavy multi-runtime scaling test (12 runtimes); explicit: cargo test -- --ignored"]
    #[allow(clippy::print_stdout)]
    fn multicast_free_discovery_scales_to_many_participants() {
        // C1 scaling: N participants, each with its own multicast group
        // (→ separate inproc buckets) AND multicast send off → pure
        // Unicast discovery via an explicit well-known-port peer list. Evidence,
        // that multicast-free all-to-all discovery works beyond 2 participants
        // (the "N²-multicast-storm" pain cluster, but unicast).
        // N via env (ZERODDS_SCALE_N, default 12) for >50 perf demos.
        let n: u32 = std::env::var("ZERODDS_SCALE_N")
            .ok()
            .and_then(|s| s.parse().ok())
            .unwrap_or(12)
            .clamp(2, 120);
        let domain = 21;
        let peers: Vec<Locator> = (0..n)
            .map(|pid| Locator::udp_v4([127, 0, 0, 1], super::spdp_unicast_port(domain, pid)))
            .collect();
        let mut rts = Vec::new();
        for i in 0..n {
            let cfg = RuntimeConfig {
                tick_period: Duration::from_millis(10),
                spdp_period: Duration::from_millis(40),
                // Own group per runtime → no inproc, no multicast.
                spdp_multicast_group: Ipv4Addr::new(239, 255, 21, (i + 1) as u8),
                spdp_multicast_send: false,
                initial_peers: peers.clone(),
                ..RuntimeConfig::default()
            };
            // Unique prefix even for n>47 (two-byte index).
            let mut pb = [0xD0u8; 12];
            pb[0] = (i & 0xff) as u8;
            pb[1] = (i >> 8) as u8;
            let prefix = GuidPrefix::from_bytes(pb);
            rts.push(DcpsRuntime::start(domain as i32, prefix, cfg).expect("start"));
        }
        // Wait until each participant has discovered all n-1 others.
        // Grosszuegiges Fenster: viele Runtimes konkurrieren um CPU; break-early.
        let started = std::time::Instant::now();
        let mut all_full = false;
        for _ in 0..1200 {
            std::thread::sleep(Duration::from_millis(25));
            if rts
                .iter()
                .all(|rt| rt.discovered_participants().len() >= (n as usize - 1))
            {
                all_full = true;
                break;
            }
        }
        let elapsed = started.elapsed();
        let min_seen = rts
            .iter()
            .map(|rt| rt.discovered_participants().len())
            .min()
            .unwrap_or(0);
        for rt in &rts {
            rt.shutdown();
        }
        println!(
            "C1-Scaling: {n} Participants multicast-frei all-to-all in {:.2}s (min={min_seen}/{})",
            elapsed.as_secs_f64(),
            n - 1
        );
        assert!(
            all_full,
            "multicast-free all-to-all discovery does not scale: min seen = {min_seen}/{}",
            n - 1
        );
    }

    #[test]
    fn default_reassembly_cap_is_ros_realistic() {
        // C3 regression: the DCPS reassembly cap must be ROS-PointCloud2/
        // Image-capable (several MB), not the conservative
        // rtps 1-MiB default that silently discards large samples.
        let cfg = RuntimeConfig::default();
        assert!(
            cfg.max_reassembly_sample_bytes >= 8 * 1024 * 1024,
            "reassembly cap too small for ROS PointCloud2/Image: {}",
            cfg.max_reassembly_sample_bytes
        );
    }

    #[test]
    fn ros_defaults_offers_xcdr1_for_ros_writers() {
        // C4: the ROS profile offers [XCDR1, XCDR2] (matches ROS/Cyclone
        // XCDR1 writer) + keeps the ROS-realistic reassembly cap.
        use zerodds_rtps::publication_data::data_representation as dr;
        let cfg = RuntimeConfig::ros_defaults();
        assert_eq!(
            cfg.data_representation_offer,
            alloc::vec![dr::XCDR, dr::XCDR2]
        );
        assert!(cfg.max_reassembly_sample_bytes >= 8 * 1024 * 1024);
    }

    #[test]
    fn multicast_free_discovery_via_initial_peers() {
        // C1: two runtimes with DIFFERENT multicast groups lie
        // in different inproc buckets AND cannot see each other via
        // multicast — so they discover each other EXCLUSIVELY via
        // the unicast initial peers (well-known SPDP ports on 127.0.0.1).
        let domain = 7;
        let mut peers = Vec::new();
        super::expand_initial_peer(
            "127.0.0.1",
            domain as u32,
            super::INITIAL_PEER_MAX_PARTICIPANTS,
            &Default::default(),
            &mut peers,
        );
        let mk = |group: [u8; 4]| RuntimeConfig {
            tick_period: Duration::from_millis(10),
            spdp_period: Duration::from_millis(40),
            spdp_multicast_group: Ipv4Addr::from(group),
            // Multicast send fully off → rigorous unicast-only proof.
            spdp_multicast_send: false,
            initial_peers: peers.clone(),
            ..RuntimeConfig::default()
        };
        let a = DcpsRuntime::start(
            domain,
            GuidPrefix::from_bytes([0xA1; 12]),
            mk([239, 255, 7, 1]),
        )
        .expect("a");
        let b = DcpsRuntime::start(
            domain,
            GuidPrefix::from_bytes([0xB2; 12]),
            mk([239, 255, 7, 2]),
        )
        .expect("b");
        let mut discovered = false;
        for _ in 0..160 {
            std::thread::sleep(Duration::from_millis(25));
            if !a.discovered_participants().is_empty() && !b.discovered_participants().is_empty() {
                discovered = true;
                break;
            }
        }
        a.shutdown();
        b.shutdown();
        assert!(
            discovered,
            "multicast-free discovery via unicast initial peers failed"
        );
    }

    #[test]
    fn multi_robot_profile_is_multicast_free_and_wan_tolerant() {
        // C6: the named profile must be unicast-only with ROS reprs and a
        // WAN-tolerant lease, independent of any env.
        let cfg = RuntimeConfig::multi_robot();
        assert!(
            !cfg.spdp_multicast_send,
            "multi_robot() must disable multicast send"
        );
        assert_eq!(
            cfg.data_representation_offer,
            alloc::vec![
                zerodds_rtps::publication_data::data_representation::XCDR,
                zerodds_rtps::publication_data::data_representation::XCDR2
            ],
            "multi_robot() must offer the ROS XCDR1+XCDR2 reprs"
        );
        assert_eq!(
            cfg.participant_lease_duration,
            Duration::from_secs(300),
            "multi_robot() must use the WAN-tolerant 300s lease"
        );
    }

