    #[test]
    fn assert_liveliness_enqueues_wlp_pulse_without_panic() {
        // Smoke test: assert_liveliness() must not poison the lock
        // and must return synchronously.
        //
        // Isolate discovery: a group no other test uses (239.255.88.1) and
        // multicast send off. peer_count read 1 in about one full run of
        // eight: the tick sent the WLP pulse to the group although
        // multicast send was off, the pulse came back through the multicast
        // loop, and the WLP endpoint counted its own participant (both
        // fixed: `send_spdp_multicast`, `WlpEndpoint::handle_datagram`).
        let cfg = RuntimeConfig {
            spdp_multicast_group: Ipv4Addr::new(239, 255, 88, 1),
            spdp_multicast_send: false,
            ..RuntimeConfig::default()
        };
        let rt = ShutsDown(
            DcpsRuntime::start(8, GuidPrefix::from_bytes([0xF; 12]), cfg).expect("start"),
        );
        rt.assert_liveliness();
        rt.assert_writer_liveliness(alloc::vec![0xDE, 0xAD]);
        // Genuinely isolated now → no peer, and the lock stays usable.
        let count = rt.wlp.lock().map(|w| w.peer_count()).unwrap_or(usize::MAX);
        assert_eq!(count, 0, "isolated runtime: no peer announced itself → 0");
    }

    /// `discovery.no_multicast` (`spdp_multicast_send: false`): not a
    /// single multicast packet (the field's contract). A socket joined to
    /// the participant's group on its SPDP port hears nothing while the
    /// participant announces itself and asserts its liveliness; before, the
    /// flag was never consulted and SPDP and WLP went out anyway.
    #[cfg(target_os = "linux")]
    #[test]
    fn no_multicast_sends_nothing_to_the_group() {
        let lease = zerodds_test_domains::lease_domain();
        let group = Ipv4Addr::new(239, 255, 88, 4);
        let port = u16::try_from(zerodds_rtps::wire_types::spdp_multicast_port(
            lease.id() as u32
        ))
        .unwrap();
        let listener = UdpTransport::bind_multicast_v4(group, port, Ipv4Addr::UNSPECIFIED)
            .expect("listener")
            .with_timeout(Some(Duration::from_millis(1_500)))
            .expect("timeout");
        let rt = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x7b; 12]),
            RuntimeConfig {
                spdp_multicast_group: group,
                spdp_multicast_send: false,
                spdp_period: Duration::from_millis(100),
                ..RuntimeConfig::default()
            },
        )
        .expect("start");
        rt.assert_liveliness();
        let heard = listener.recv();
        assert!(
            matches!(heard, Err(zerodds_transport::RecvError::Timeout)),
            "a datagram reached the group: {heard:?}"
        );
        rt.shutdown();
        // The control: with multicast on, the same listener hears the
        // participant's beacon.
        let loud = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x7c; 12]),
            RuntimeConfig {
                spdp_multicast_group: group,
                spdp_period: Duration::from_millis(100),
                ..RuntimeConfig::default()
            },
        )
        .expect("start");
        assert!(
            listener.recv().is_ok(),
            "the listener hears a multicast beacon"
        );
        loud.shutdown();
    }

    /// DDSI-RTPS 2.5 §8.7.2.2.3: a write, `assert_liveliness`, dispose and
    /// unregister of a MANUAL_BY_PARTICIPANT writer send the participant's
    /// ParticipantMessageData; the same calls of an AUTOMATIC writer do not.
    #[test]
    fn a_manual_by_participant_writer_refreshes_the_participant_liveliness() {
        let lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x7d; 12]),
            RuntimeConfig {
                wlp_period: Duration::from_secs(3600),
                ..RuntimeConfig::default()
            },
        )
        .expect("start");
        let refreshes = |rt: &DcpsRuntime| rt.wlp.lock().unwrap().participant_refreshes();
        let register = |kind: zerodds_qos::LivelinessKind, topic: &str| {
            rt.register_user_writer_kind(
                UserWriterConfig {
                    topic_name: topic.into(),
                    type_name: "Raw".into(),
                    liveliness: zerodds_qos::LivelinessQosPolicy {
                        kind,
                        ..Default::default()
                    },
                    ..Default::default()
                },
                true,
            )
            .expect("writer")
        };
        let automatic = register(zerodds_qos::LivelinessKind::Automatic, "WlpAuto");
        let manual = register(
            zerodds_qos::LivelinessKind::ManualByParticipant,
            "WlpManual",
        );
        let key = [3u8; 16];
        let holder = alloc::vec![0u8, 0, 0, 7];
        let disposed = zerodds_rtps::inline_qos::status_info::DISPOSED;
        rt.write_user_sample_keyed(automatic, &[1], key, None)
            .unwrap();
        rt.assert_writer_liveliness_eid(automatic);
        rt.write_user_lifecycle(automatic, key, Some(&holder), disposed, None)
            .unwrap();
        assert_eq!(refreshes(&rt), 0, "an AUTOMATIC writer refreshes nothing");
        rt.write_user_sample_keyed(manual, &[1], key, None).unwrap();
        assert_eq!(refreshes(&rt), 1, "write");
        rt.assert_writer_liveliness_eid(manual);
        assert_eq!(refreshes(&rt), 2, "assert_liveliness");
        rt.write_user_lifecycle(manual, key, Some(&holder), disposed, None)
            .unwrap();
        assert_eq!(refreshes(&rt), 3, "dispose");
        rt.write_user_lifecycle(
            manual,
            key,
            Some(&holder),
            zerodds_rtps::inline_qos::status_info::UNREGISTERED,
            None,
        )
        .unwrap();
        assert_eq!(refreshes(&rt), 4, "unregister_instance");
        rt.shutdown();
    }

    /// DDSI-RTPS 2.5 §9.6.2.3: the user-traffic unicast socket is bound to
    /// `PB + DG * domainId + d3 + PG * participantId`, with the participantId
    /// of the SPDP unicast socket (`d1`, same `PG`): the two ports differ by
    /// `d3 - d1`, and the announced default unicast locator carries it.
    #[test]
    fn the_user_unicast_socket_takes_the_d3_port_of_its_participant_id() {
        let lease = zerodds_test_domains::lease_domain();
        let mapping = zerodds_rtps::wire_types::PortMapping::default();
        let before = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x62; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let spdp = before.spdp_unicast.local_locator().port;
        let user = before.user_unicast.local_locator().port;
        let announced = before
            .user_announce_locators
            .iter()
            .map(|l| l.port)
            .collect::<Vec<_>>();
        before.shutdown();
        // The well-known ports were free, so the participantId is the same
        // for both sockets.
        assert_eq!(user, spdp - mapping.d1 + mapping.d3, "{spdp} {user}");
        assert!(announced.iter().all(|p| *p == user), "{announced:?}");
    }

    /// DDSI-RTPS 2.5 §9.6.2.3: with `transport.user_multicast` the
    /// participant joins the group on `PB + DG * domainId + d2` and announces
    /// that locator as its default multicast locator; without it, none.
    #[cfg(target_os = "linux")]
    #[test]
    fn the_user_multicast_port_is_d2_and_announced_unless_turned_off() {
        assert!(RuntimeConfig::default().user_multicast);
        let lease = zerodds_test_domains::lease_domain();
        let mapping = zerodds_rtps::wire_types::PortMapping::default();
        let announced = |rt: &DcpsRuntime| {
            rt.spdp_beacon
                .lock()
                .unwrap()
                .data
                .default_multicast_locators
                .clone()
        };
        let off = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x64; 12]),
            RuntimeConfig {
                user_multicast: false,
                ..RuntimeConfig::default()
            },
        )
        .expect("start");
        assert!(announced(&off).is_empty());
        off.shutdown();
        let on = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x65; 12]),
            RuntimeConfig {
                user_multicast: true,
                ..RuntimeConfig::default()
            },
        )
        .expect("start");
        let got = announced(&on);
        on.shutdown();
        assert_eq!(got.len(), 1, "{got:?}");
        assert_eq!(
            got[0].port,
            mapping.user_traffic_multicast_port(lease.id() as u32)
        );
        assert_eq!(got[0].address[12..], [239, 255, 0, 1]);
    }

    /// A port that is taken is counted and the socket takes an ephemeral
    /// port: with `d3 == d1` the user port of the participant is the port
    /// its SPDP unicast socket holds.
    #[test]
    fn a_taken_user_port_is_counted_and_the_socket_takes_an_ephemeral_one() {
        let lease = zerodds_test_domains::lease_domain();
        let cfg = RuntimeConfig {
            port_mapping: zerodds_rtps::wire_types::PortMapping {
                d3: zerodds_rtps::wire_types::PortMapping::SPEC.d1,
                ..Default::default()
            },
            ..RuntimeConfig::default()
        };
        let before = USER_PORT_FALLBACKS.load(Ordering::Relaxed);
        let rt =
            DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([0x63; 12]), cfg).expect("start");
        let spdp = rt.spdp_unicast.local_locator().port;
        let user = rt.user_unicast.local_locator().port;
        let counted = rt.user_port_fallbacks();
        rt.shutdown();
        assert_ne!(spdp, user);
        assert!(counted > before);
    }

    /// DDSI-RTPS 2.5 §9.6.2.3: the port parameters are settings; the SPDP
    /// unicast socket is bound in the range the given PB, DG, d1 and PG give.
    #[test]
    fn the_spdp_unicast_port_follows_the_configured_port_mapping() {
        let mapping = zerodds_rtps::wire_types::PortMapping {
            port_base: 30000,
            domain_gain: 100,
            participant_gain: 4,
            d1: 6,
            ..Default::default()
        };
        let cfg = RuntimeConfig {
            port_mapping: mapping,
            ..RuntimeConfig::default()
        };
        let lease = zerodds_test_domains::lease_domain();
        let domain = u32::try_from(lease.id()).expect("a leased domain is not negative");
        let rt = ShutsDown(
            DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([0x61; 12]), cfg).expect("start"),
        );
        let port = rt.spdp_unicast.local_locator().port;
        let allowed: Vec<u32> = (0..120)
            .map(|pid| mapping.spdp_unicast_port(domain, pid))
            .collect();
        assert!(allowed.contains(&port), "port {port} not in {allowed:?}");
        assert!(port >= 30000 + 300 + 6);
    }

    #[test]
    fn wlp_period_default_is_lease_over_three() {
        // With the default lease of 100 s → wlp_period = 33.33 s.
        // A domain of its own: a fixed domain 9 was shared with another test
        // of this binary, and the pulse of the other runtime's tick came first.
        let lease = zerodds_test_domains::lease_domain();
        let rt = ShutsDown(
            DcpsRuntime::start(
                lease.id(),
                GuidPrefix::from_bytes([0x10; 12]),
                RuntimeConfig::default(),
            )
            .expect("start"),
        );
        // We cannot read the value directly; but we
        // know: tick_period > 30 s means the default lease was
        // used. Enqueue a pulse and tick — it must fire,
        // the next AUTOMATIC comes only in 33 s.
        let mut wlp = rt.wlp.lock().unwrap();
        wlp.assert_participant();
        let now0 = Duration::from_secs(0);
        let _ = wlp.tick(now0).unwrap();
        // The runtime's own tick thread may have written the first pulse
        // already; the writer then holds at least one.
        assert!(
            wlp.last_written_sequence_number() >= zerodds_rtps::wire_types::SequenceNumber(1),
            "pulse is written immediately"
        );
    }

    // Discovery starts from SPDP multicast; the WLP writer then sends to the
    // metatraffic unicast locators of its reader proxies (DDSI-RTPS 2.5
    // §8.4.13.1: the protocol of the application endpoints). On Linux the
    // multicast of the discovery works out of the box; there the test runs.
    #[cfg(target_os = "linux")]
    #[test]
    fn two_runtimes_exchange_wlp_heartbeat() {
        // .D-e: A sends periodic WLP heartbeats. B must
        // know its own WLP endpoint with A's prefix as a peer
        // within ~3 tick periods.
        let cfg = RuntimeConfig {
            tick_period: Duration::from_millis(20),
            spdp_period: Duration::from_millis(100),
            // Aggressive WLP period for fast tests.
            wlp_period: Duration::from_millis(80),
            participant_lease_duration: Duration::from_millis(240),
            nack_response_delay: Duration::ZERO,
            reader_heartbeat_response_delay: Duration::ZERO,
            ..RuntimeConfig::default()
        };
        // A leased domain: the fixed domain 2 was shared with
        // `two_runtimes_e2e_user_data_match_and_transfer`, and the two ran in
        // parallel (measured: 17 of 30 runs of the `two_runtimes_` tests red).
        let lease = zerodds_test_domains::lease_domain();
        let _a = ShutsDown(
            DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([0x40; 12]), cfg.clone())
                .expect("a"),
        );
        let _b = ShutsDown(
            DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([0x41; 12]), cfg).expect("b"),
        );

        let a_prefix = GuidPrefix::from_bytes([0x40; 12]);
        for _ in 0..60 {
            thread::sleep(Duration::from_millis(50));
            if _b.peer_liveliness_last_seen(&a_prefix).is_some() {
                return;
            }
        }
        panic!("B did not see A's WLP heartbeat within 3 s");
    }

    /// A participant that is in the discovery cache without a beacon — same-process
    /// discovery enters it that way — gets a reader proxy of the WLP writer
    /// from the tick, one-sided discovery included.
    #[test]
    fn a_participant_entered_without_a_beacon_gets_a_wlp_reader_proxy() {
        let lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x7a; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let remote = GuidPrefix::from_bytes([0xA2; 12]);
        let mut data = zerodds_discovery::SpdpReader::new()
            .parse_datagram(&make_remote_spdp_beacon(remote))
            .expect("parse")
            .data;
        data.metatraffic_unicast_locators = vec![Locator::udp_v4([127, 0, 0, 1], 9)];
        rt.discovered
            .lock()
            .unwrap()
            .insert(zerodds_discovery::spdp::DiscoveredParticipant {
                sender_prefix: remote,
                sender_vendor: VendorId::ZERODDS,
                data,
            });
        assert_eq!(rt.wlp.lock().unwrap().peer_reader_count(), 0);
        sync_wlp_readers(&rt);
        assert_eq!(rt.wlp.lock().unwrap().peer_reader_count(), 1);
        rt.shutdown();
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn two_runtimes_assert_liveliness_reaches_peer() {
        // The Manual-By-Participant pulse must arrive at the peer, the
        // last-seen timestamp must reset compared to purely Automatic
        // beats. Since the pulse goes out synchronously on the next
        // tick, a short wait suffices.
        let cfg = RuntimeConfig {
            tick_period: Duration::from_millis(20),
            spdp_period: Duration::from_millis(100),
            // WLP period large enough that no AUTOMATIC beat comes
            // in between within the test. The manual pulse queue
            // is processed before the AUTOMATIC slot.
            wlp_period: Duration::from_secs(3600),
            ..RuntimeConfig::default()
        };
        let a = ShutsDown(
            DcpsRuntime::start(4, GuidPrefix::from_bytes([0x50; 12]), cfg.clone()).expect("a"),
        );
        let b =
            ShutsDown(DcpsRuntime::start(4, GuidPrefix::from_bytes([0x51; 12]), cfg).expect("b"));

        a.assert_liveliness();
        let a_prefix = GuidPrefix::from_bytes([0x50; 12]);
        for _ in 0..60 {
            thread::sleep(Duration::from_millis(50));
            if b.peer_liveliness_last_seen(&a_prefix).is_some() {
                return;
            }
        }
        // In case of multicast-loopback problems, at least check A's
        // own pulse counter.
        panic!("B did not see A's manual liveliness assert within 3 s");
    }

    /// DDS 1.4 §2.2.2.5.3.32 `wait_for_historical_data`: a reader waits for
    /// the history of the reliable writers it is matched with, which a writer
    /// announces with its HEARTBEAT. A remote TRANSIENT_LOCAL RELIABLE writer
    /// that is announced by SPDP and SEDP and never sends one keeps the wait
    /// open: it returns TIMEOUT after `max_wait`. The peer is a SEDP stack
    /// built by hand, whose datagrams are the bytes a foreign participant
    /// would send; no HEARTBEAT follows.
    #[cfg(target_os = "linux")]
    #[test]
    fn wait_for_historical_data_times_out_for_a_writer_without_a_heartbeat() {
        use crate::dds_type::DdsType;
        use zerodds_discovery::sedp::SedpStack;
        use zerodds_qos::{DurabilityKind, ReliabilityKind};
        use zerodds_rtps::participant_data::endpoint_flag;
        use zerodds_rtps::publication_data::PublicationBuiltinTopicData;

        let lease = zerodds_test_domains::lease_domain();
        let factory = crate::factory::DomainParticipantFactory::instance();
        let p = factory
            .create_participant_with_config(
                lease.id(),
                crate::qos::DomainParticipantQos::default(),
                RuntimeConfig::default(),
            )
            .expect("participant");
        let rt = Arc::clone(p.runtime().expect("runtime"));
        let topic = p
            .create_topic::<crate::RawBytes>("HistoricalTimeout", crate::qos::TopicQos::default())
            .expect("topic");
        let reader = p
            .create_subscriber(crate::qos::SubscriberQos::default())
            .create_datareader::<crate::RawBytes>(
                &topic,
                crate::qos::DataReaderQos {
                    reliability: zerodds_qos::ReliabilityQosPolicy {
                        kind: ReliabilityKind::Reliable,
                        max_blocking_time: QosDuration::from_millis(100_i32),
                    },
                    durability: zerodds_qos::DurabilityQosPolicy {
                        kind: DurabilityKind::TransientLocal,
                    },
                    ..Default::default()
                },
            )
            .expect("reader");

        // The foreign participant announces itself and its SEDP endpoints.
        let remote = GuidPrefix::from_bytes([0xB7; 12]);
        let flags = endpoint_flag::PARTICIPANT_ANNOUNCER
            | endpoint_flag::PARTICIPANT_DETECTOR
            | endpoint_flag::PUBLICATIONS_ANNOUNCER
            | endpoint_flag::PUBLICATIONS_DETECTOR
            | endpoint_flag::SUBSCRIPTIONS_ANNOUNCER
            | endpoint_flag::SUBSCRIPTIONS_DETECTOR;
        handle_spdp_datagram(
            &rt,
            &make_remote_spdp_beacon_with_flags(remote, flags),
            None,
        );

        // Its SEDP publications writer announces the writer.
        let mut peer = SedpStack::new(remote, VendorId::ZERODDS);
        peer.on_participant_discovered(&rt.self_as_discovered_participant());
        let announcement = PublicationBuiltinTopicData {
            vendor_id: Some(VendorId::ZERODDS),
            key: Guid::new(remote, EntityId::user_writer_with_key([0x0B, 0x07, 0x01])),
            participant_key: Guid::new(remote, EntityId::PARTICIPANT),
            topic_name: "HistoricalTimeout".into(),
            type_name: crate::RawBytes::TYPE_NAME.into(),
            durability: DurabilityKind::TransientLocal,
            durability_service: zerodds_qos::DurabilityServiceQosPolicy::default(),
            reliability: zerodds_qos::ReliabilityQosPolicy {
                kind: ReliabilityKind::Reliable,
                max_blocking_time: QosDuration::from_millis(100_i32),
            },
            ownership: zerodds_qos::OwnershipKind::Shared,
            ownership_strength: 0,
            liveliness: zerodds_qos::LivelinessQosPolicy::default(),
            deadline: zerodds_qos::DeadlineQosPolicy::default(),
            latency_budget: zerodds_qos::LatencyBudgetQosPolicy::default(),
            destination_order: zerodds_qos::DestinationOrderQosPolicy::default(),
            lifespan: zerodds_qos::LifespanQosPolicy::default(),
            presentation: Default::default(),
            partition: Vec::new(),
            user_data: Vec::new(),
            topic_data: Vec::new(),
            group_data: Vec::new(),
            type_information: None,
            type_id_v1: None,
            type_object_v1: None,
            data_representation: Vec::new(),
            security_info: None,
            service_instance_name: None,
            related_entity_guid: None,
            topic_aliases: None,
            type_identifier: zerodds_types::TypeIdentifier::None,
            unicast_locators: vec![Locator::udp_v4([127, 0, 0, 99], 7600)],
            multicast_locators: Vec::new(),
            group_guid: None,
            data_max_size_serialized: None,
            entity_name: None,
            data_tags: Default::default(),
            properties: Default::default(),
            sym_cipher_algo_info: None,
        };
        let datagrams = peer.announce_publication(&announcement).expect("announce");
        assert!(!datagrams.is_empty(), "the peer produced a SEDP datagram");
        for datagram in datagrams {
            handle_sedp_datagram(&rt, &datagram.bytes, None, rt.start_instant.elapsed());
        }
        assert_eq!(
            reader.matched_publications().expect("matched").len(),
            1,
            "the reader matched the announced writer"
        );

        let started = Instant::now();
        let result = reader.wait_for_historical_data(Duration::from_millis(300));
        assert!(
            matches!(result, Err(DdsError::Timeout)),
            "no HEARTBEAT came, so the history is not known: {result:?}"
        );
        assert!(started.elapsed() >= Duration::from_millis(300));
        let _ = factory.delete_participant(&p);
    }

    /// DDS 1.4 §2.2.2.4.2.15 and §2.2.2.4.1.12 `wait_for_acknowledgments`:
    /// a RELIABLE writer with a matched RELIABLE reader that does not
    /// acknowledge returns TIMEOUT after the time given, the Publisher of
    /// the writer too; a BEST_EFFORT writer returns OK at once. The reader is
    /// a SEDP announcement built by hand; no ACKNACK follows.
    #[cfg(target_os = "linux")]
    #[test]
    fn wait_for_acknowledgments_times_out_for_a_reader_that_does_not_acknowledge() {
        use crate::dds_type::DdsType;
        use zerodds_discovery::sedp::SedpStack;
        use zerodds_qos::ReliabilityKind;
        use zerodds_rtps::participant_data::endpoint_flag;

        let lease = zerodds_test_domains::lease_domain();
        let factory = crate::factory::DomainParticipantFactory::instance();
        let p = factory
            .create_participant_with_config(
                lease.id(),
                crate::qos::DomainParticipantQos::default(),
                RuntimeConfig::default(),
            )
            .expect("participant");
        let rt = Arc::clone(p.runtime().expect("runtime"));
        let publisher = p.create_publisher(crate::qos::PublisherQos::default());
        let make_writer = |topic_name: &str, kind: ReliabilityKind| {
            let topic = p
                .create_topic::<crate::RawBytes>(topic_name, crate::qos::TopicQos::default())
                .expect("topic");
            publisher
                .create_datawriter::<crate::RawBytes>(
                    &topic,
                    crate::qos::DataWriterQos {
                        reliability: zerodds_qos::ReliabilityQosPolicy {
                            kind,
                            max_blocking_time: QosDuration::from_millis(100_i32),
                        },
                        ..Default::default()
                    },
                )
                .expect("writer")
        };
        let reliable = make_writer("AckTimeoutReliable", ReliabilityKind::Reliable);
        let best_effort = make_writer("AckTimeoutBestEffort", ReliabilityKind::BestEffort);

        let remote = GuidPrefix::from_bytes([0xB8; 12]);
        let flags = endpoint_flag::PARTICIPANT_ANNOUNCER
            | endpoint_flag::PARTICIPANT_DETECTOR
            | endpoint_flag::PUBLICATIONS_ANNOUNCER
            | endpoint_flag::PUBLICATIONS_DETECTOR
            | endpoint_flag::SUBSCRIPTIONS_ANNOUNCER
            | endpoint_flag::SUBSCRIPTIONS_DETECTOR;
        handle_spdp_datagram(
            &rt,
            &make_remote_spdp_beacon_with_flags(remote, flags),
            None,
        );
        let mut peer = SedpStack::new(remote, VendorId::ZERODDS);
        peer.on_participant_discovered(&rt.self_as_discovered_participant());
        for (topic_name, kind, key) in [
            ("AckTimeoutReliable", ReliabilityKind::Reliable, 0x01),
            ("AckTimeoutBestEffort", ReliabilityKind::BestEffort, 0x02),
        ] {
            let mut sub =
                rxo_remote_sub(zerodds_qos::DestinationOrderKind::ByReceptionTimestamp, 0);
            sub.key = Guid::new(remote, EntityId::user_reader_with_key([0x0B, 0x08, key]));
            sub.participant_key = Guid::new(remote, EntityId::PARTICIPANT);
            sub.topic_name = topic_name.into();
            sub.type_name = crate::RawBytes::TYPE_NAME.into();
            sub.reliability.kind = kind;
            for datagram in peer.announce_subscription(&sub).expect("announce") {
                handle_sedp_datagram(&rt, &datagram.bytes, None, rt.start_instant.elapsed());
            }
        }
        assert_eq!(reliable.matched_subscriptions().expect("matched").len(), 1);
        assert_eq!(
            best_effort.matched_subscriptions().expect("matched").len(),
            1
        );

        reliable
            .write(&crate::RawBytes::new(alloc::vec![1, 2, 3]))
            .expect("write");
        best_effort
            .write(&crate::RawBytes::new(alloc::vec![4, 5, 6]))
            .expect("write");

        let started = Instant::now();
        let result = reliable.wait_for_acknowledgments(Duration::from_millis(300));
        assert!(
            matches!(result, Err(DdsError::Timeout)),
            "the reader acknowledged nothing: {result:?}"
        );
        assert!(started.elapsed() >= Duration::from_millis(300));

        // The Publisher waits for all its writers.
        let started = Instant::now();
        let result = publisher.wait_for_acknowledgments(Duration::from_millis(300));
        assert!(
            matches!(result, Err(DdsError::Timeout)),
            "one of its writers is not acknowledged: {result:?}"
        );
        assert!(started.elapsed() >= Duration::from_millis(300));

        // A BEST_EFFORT writer has no reliable reader to wait for.
        let started = Instant::now();
        best_effort
            .wait_for_acknowledgments(Duration::from_secs(5))
            .expect("best effort returns OK");
        assert!(started.elapsed() < Duration::from_secs(2), "at once");
        let _ = factory.delete_participant(&p);
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn two_runtimes_exchange_sedp_publication_announce() {
        // E2E smoke: A announces a publication, B sees it
        // via SEDP. Assumes SPDP works (so that
        // the SEDP peer proxies get wired).
        use zerodds_qos::{DurabilityKind, ReliabilityKind};
        use zerodds_rtps::publication_data::PublicationBuiltinTopicData;

        let cfg = RuntimeConfig {
            tick_period: Duration::from_millis(20),
            spdp_period: Duration::from_millis(100),
            ..RuntimeConfig::default()
        };
        // Own domain, so the test does not collide with the SPDP-only test
        // on domain 0 over the multicast port.
        let a = ShutsDown(
            DcpsRuntime::start(1, GuidPrefix::from_bytes([0xCC; 12]), cfg.clone()).expect("a"),
        );
        let b =
            ShutsDown(DcpsRuntime::start(1, GuidPrefix::from_bytes([0xDD; 12]), cfg).expect("b"));

        // Wait until both see each other via SPDP.
        for _ in 0..40 {
            thread::sleep(Duration::from_millis(50));
            if !a.discovered_participants().is_empty() && !b.discovered_participants().is_empty() {
                break;
            }
        }
        assert!(
            !a.discovered_participants().is_empty(),
            "no SPDP discovery a"
        );

        // A announces a publication for topic "Chatter" with type "RawBytes".
        let pub_data = PublicationBuiltinTopicData {
            // This announcement is ours, so it carries our vendor id;
            // a foreign one carries the id it was read with.
            vendor_id: Some(zerodds_rtps::wire_types::VendorId::ZERODDS),
            key: Guid::new(
                a.guid_prefix,
                EntityId::user_writer_with_key([0x01, 0x02, 0x03]),
            ),
            participant_key: Guid::new(a.guid_prefix, EntityId::PARTICIPANT),
            topic_name: "Chatter".into(),
            type_name: "zerodds::RawBytes".into(),
            durability: DurabilityKind::Volatile,
            durability_service: zerodds_qos::DurabilityServiceQosPolicy::default(),
            reliability: zerodds_qos::ReliabilityQosPolicy {
                kind: ReliabilityKind::Reliable,
                max_blocking_time: QosDuration::from_millis(100_i32),
            },
            ownership: zerodds_qos::OwnershipKind::Shared,
            ownership_strength: 0,
            liveliness: zerodds_qos::LivelinessQosPolicy::default(),
            deadline: zerodds_qos::DeadlineQosPolicy::default(),
            latency_budget: zerodds_qos::LatencyBudgetQosPolicy::default(),
            destination_order: zerodds_qos::DestinationOrderQosPolicy::default(),
            lifespan: zerodds_qos::LifespanQosPolicy::default(),
            presentation: Default::default(),
            partition: Vec::new(),
            user_data: Vec::new(),
            topic_data: Vec::new(),
            group_data: Vec::new(),
            type_information: None,
            type_id_v1: None,
            type_object_v1: None,
            data_representation: Vec::new(),
            security_info: None,
            sym_cipher_algo_info: None,
            data_tags: Default::default(),
            properties: Default::default(),
            service_instance_name: None,
            related_entity_guid: None,
            topic_aliases: None,
            type_identifier: zerodds_types::TypeIdentifier::None,
            unicast_locators: Vec::new(),
            multicast_locators: Vec::new(),
            group_guid: None,
            data_max_size_serialized: None,
            entity_name: None,
        };
        a.announce_publication(&pub_data).expect("announce");

        // B should have the publication in the cache within ~3 s.
        // CI on shared runners has more jitter, 1 s was too tight.
        for _ in 0..60 {
            thread::sleep(Duration::from_millis(50));
            if b.discovered_publications_count() > 0 {
                return;
            }
        }
        panic!(
            "B did not receive SEDP publication within 3 s (pub_count={})",
            b.discovered_publications_count()
        );
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn two_runtimes_e2e_user_data_match_and_transfer() {
        // E2E smoke: full path
        //   Runtime-A register_user_writer(topic, type)
        //   Runtime-B register_user_reader(topic, type)
        //   SEDP match, writer add_reader_proxy, reader add_writer_proxy
        //   A.write_user_sample(payload) → UDP → B's mpsc::Receiver
        //
        // A leased domain, so that no other test of the binary shares it.
        let cfg = RuntimeConfig {
            tick_period: Duration::from_millis(20),
            spdp_period: Duration::from_millis(100),
            ..RuntimeConfig::default()
        };
        let lease = zerodds_test_domains::lease_domain();
        let a = ShutsDown(
            DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([0xEE; 12]), cfg.clone())
                .expect("a"),
        );
        let b = ShutsDown(
            DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([0xFF; 12]), cfg).expect("b"),
        );

        // SPDP mutual — 3 s Budget.
        let mut spdp_ok = false;
        for _ in 0..60 {
            thread::sleep(Duration::from_millis(50));
            if !a.discovered_participants().is_empty() && !b.discovered_participants().is_empty() {
                spdp_ok = true;
                break;
            }
        }
        assert!(spdp_ok, "SPDP mutual discovery did not complete in 3 s");

        // Register endpoints. A publish, B subscribe.
        let wid = a
            .register_user_writer(UserWriterConfig {
                topic_name: "Chatter".into(),
                type_name: "zerodds::RawBytes".into(),
                ..Default::default()
            })
            .expect("wid");
        let (_rid, rx) = b
            .register_user_reader(UserReaderConfig {
                topic_name: "Chatter".into(),
                type_name: "zerodds::RawBytes".into(),
                ..Default::default()
            })
            .expect("rid");

        // SEDP match + User-Data-Flow. `add_reader_proxy` triggert
        // a heartbeat immediately (RTPS §8.4.15.4), so ~tick_period
        // (20 ms) + response-delay (200 ms) + resend ≈ 300 ms in
        // idle state. A 4 s budget suffices even with CI jitter.
        let mut attempts = 0;
        loop {
            thread::sleep(Duration::from_millis(50));
            let _ = a.write_user_sample(wid, alloc::vec![0xAA, 0xBB, 0xCC]);
            if let Ok(sample) = rx.recv_timeout(Duration::from_millis(50)) {
                match sample {
                    UserSample::Alive { payload, .. } => {
                        assert_eq!(payload.as_slice(), &[0xAA, 0xBB, 0xCC][..]);
                        return;
                    }
                    other => panic!("expected Alive sample, got {other:?}"),
                }
            }
            attempts += 1;
            if attempts > 80 {
                panic!("no sample delivered within 4 s");
            }
        }
    }

    /// A participant that drops its channel to a same-host peer on its
    /// side only (a lease that expired there, say) and opens it again makes
    /// its ring anew. The peer, which never lost it, sees its receive
    /// thread end on the old ring's shutdown flag and attaches to the new
    /// one; samples keep going through the channel. Before, the peer stayed
    /// on the dead ring and the sender's frames reached nobody.
    #[cfg(all(target_os = "linux", feature = "same-host-shm"))]
    #[test]
    fn a_same_host_peer_follows_a_channel_its_peer_makes_anew() {
        use crate::same_host_channel::Port;
        let lease = zerodds_test_domains::lease_domain();
        let cfg = RuntimeConfig {
            tick_period: Duration::from_millis(20),
            spdp_period: Duration::from_millis(100),
            ..RuntimeConfig::default()
        };
        // The host id is octets 2..6, after the vendor id
        // (`GuidPrefix::zerodds`); the test wrote it into 0..4.
        let pa = GuidPrefix::zerodds([0x5A; 4], [0x5A; 6]);
        let pb = GuidPrefix::zerodds([0x5A; 4], [0x5B, 0x5B, 1, 2, 3, 4]);
        assert!(pa.is_same_host(pb));
        let a = ShutsDown(DcpsRuntime::start(lease.id(), pa, cfg.clone()).expect("a"));
        let b = ShutsDown(DcpsRuntime::start(lease.id(), pb, cfg).expect("b"));
        let until = |what: &str, secs: u64, done: &dyn Fn() -> bool| {
            let deadline = std::time::Instant::now() + Duration::from_secs(secs);
            while !done() {
                assert!(
                    std::time::Instant::now() < deadline,
                    "{what} within {secs} s"
                );
                thread::sleep(Duration::from_millis(20));
            }
        };
        let channel = |rt: &DcpsRuntime, peer: GuidPrefix| {
            rt.same_host_channels
                .snapshot()
                .into_iter()
                .find(|(p, c)| *p == peer && c.outbound.peer_attached())
                .map(|(_, c)| c)
        };
        until("the channels both ways", 10, &|| {
            channel(&a, pb).is_some() && channel(&b, pa).is_some()
        });
        let wid = a
            .register_user_writer(UserWriterConfig {
                topic_name: "SameHostRebind".into(),
                type_name: "zerodds::RawBytes".into(),
                reliable: false,
                ..Default::default()
            })
            .expect("wid");
        let (rid, rx) = b
            .register_user_reader(UserReaderConfig {
                topic_name: "SameHostRebind".into(),
                type_name: "zerodds::RawBytes".into(),
                reliable: false,
                ..Default::default()
            })
            .expect("rid");
        until("the match both ways", 10, &|| {
            a.user_writer_matched_count(wid) == 1 && b.user_reader_matched_count(rid) == 1
        });
        let alive = |s: UserSample| match s {
            UserSample::Alive { payload, .. } => payload.as_slice().to_vec(),
            other => panic!("expected Alive, got {other:?}"),
        };
        a.write_user_sample(wid, b"first ring".to_vec()).unwrap();
        assert_eq!(
            alive(rx.recv_timeout(Duration::from_secs(2)).expect("first")),
            b"first ring"
        );
        let old_inbound = Arc::downgrade(&channel(&b, pa).expect("b's channel").inbound);

        // a alone drops the channel and opens it again.
        let peer = a
            .discovered_participants()
            .into_iter()
            .find(|p| p.data.guid.prefix == pb)
            .expect("a knows b");
        a.same_host_channels.remove_peer(pb);
        a.same_host_channels.add_peer(
            pb,
            &peer.data.metatraffic_unicast_locators,
            &peer.data.default_unicast_locators,
        );
        until("b on a's new ring", 5, &|| {
            old_inbound.upgrade().is_none() && channel(&a, pb).is_some()
        });
        let sent = a.same_host_channels.frames_sent(Port::User);
        a.write_user_sample(wid, b"second ring".to_vec()).unwrap();
        assert_eq!(
            alive(rx.recv_timeout(Duration::from_secs(2)).expect("second")),
            b"second ring"
        );
        assert!(
            a.same_host_channels.frames_sent(Port::User) > sent,
            "through the channel"
        );
        assert_eq!(a.same_host_shm_udp_fallbacks(), 0);
    }

    #[cfg(target_os = "linux")]
    #[test]
    fn two_runtimes_discover_each_other_via_spdp() {
        // We use a tight SPDP period so the test does not wait 5 s.
        let cfg = RuntimeConfig {
            tick_period: Duration::from_millis(20),
            spdp_period: Duration::from_millis(100),
            ..RuntimeConfig::default()
        };
        // A leased domain: the fixed domain 3 was shared with another test of
        // this binary, and tests run in parallel.
        let lease = zerodds_test_domains::lease_domain();
        let a = ShutsDown(
            DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([0xAA; 12]), cfg.clone())
                .expect("a"),
        );
        let b = ShutsDown(
            DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([0xBB; 12]), cfg).expect("b"),
        );

        // Give the loop time for 2-3 beacon rounds. Multicast on
        // loopback is somewhat timing-sensitive when parallel tests
        // share the multicast group — hence 60 iterations of 50 ms
        // = 3 s budget instead of 1 s.
        for _ in 0..60 {
            thread::sleep(Duration::from_millis(50));
            let a_sees_b = a
                .discovered_participants()
                .iter()
                .any(|p| p.sender_prefix == GuidPrefix::from_bytes([0xBB; 12]));
            let b_sees_a = b
                .discovered_participants()
                .iter()
                .any(|p| p.sender_prefix == GuidPrefix::from_bytes([0xAA; 12]));
            if a_sees_b && b_sees_a {
                return;
            }
        }
        panic!(
            "mutual SPDP discovery failed within 3 s (a={} b={})",
            a.discovered_participants().len(),
            b.discovered_participants().len()
        );
    }

    /// DDS-Security 1.2 §7.5.1.6 to §7.5.1.8: the discovery data of the secure
    /// channel is told by the writer that sent it, and the secure built-in
    /// readers get the endpoints announced there with their `data_tags`, the
    /// plain readers none from this path.
    #[cfg(feature = "security")]
    #[test]
    fn the_secure_discovery_data_reaches_the_secure_readers() {
        use zerodds_rtps::property_list::{WireDataTags, WireProperty};
        // The datagrams: the secure SPDP writer is not the plain one.
        let lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0xD1; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let data = rt.spdp_beacon.lock().unwrap().data.clone();
        let mut beacon = zerodds_discovery::spdp::SpdpBeacon::new(data);
        let secure_writer = [EntityId::SPDP_RELIABLE_BUILTIN_PARTICIPANTS_SECURE_WRITER];
        assert!(!datagram_has_data_of(
            &beacon.serialize().unwrap(),
            &secure_writer
        ));
        assert!(datagram_has_data_of(
            &beacon.serialize_secure().unwrap(),
            &secure_writer
        ));
        // The endpoints announced there.
        let builtin = crate::builtin_subscriber::BuiltinSubscriber::new();
        rt.attach_builtin_sinks(builtin.sinks());
        let presentation = zerodds_qos::PresentationQosPolicy::default();
        let mut publication = group_remote_pub("Track", "Track", presentation, Vec::new());
        publication.data_tags = WireDataTags {
            tags: alloc::vec![WireProperty::new("level", "secret")],
        };
        let subscription = group_remote_sub("Track", "Track", presentation, Vec::new());
        let events = zerodds_discovery::sedp::SedpEvents {
            new_publications: alloc::vec![publication],
            new_subscriptions: alloc::vec![subscription],
            ..Default::default()
        };
        push_sedp_events_to_secure_readers(&rt, &events);
        let publications = builtin.publications_secure_reader().take().unwrap();
        assert_eq!(publications.len(), 1);
        assert_eq!(publications[0].base.topic_name, "Track");
        assert_eq!(publications[0].data_tags.tags[0].name, "level");
        assert_eq!(
            builtin.subscriptions_secure_reader().take().unwrap().len(),
            1
        );
        assert!(builtin.publication_reader().take().unwrap().is_empty());
        rt.shutdown();
    }

    /// DDS-Security 1.2 §7.5.4.4, §7.5.4.6.2, §7.5.4.6.3: a crypto token whose
    /// `destination_endpoint_guid` names no endpoint of this participant is not
    /// installed, and the refusal is recorded; one that names an endpoint of it,
    /// or GUID_UNKNOWN, is. An unusable token is a recorded failure and not
    /// silence.
    #[cfg(feature = "security")]
    #[test]
    fn a_token_for_an_endpoint_this_participant_lacks_is_not_installed() {
        use zerodds_security::generic_message::{ParticipantGenericMessage, class_id};
        use zerodds_security::token::DataHolder;
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let sink = std::sync::Arc::new(zerodds_foundation::observability::VecSink::new());
        let rt = build_runtime_with_sink(
            GOV,
            std::sync::Arc::new(CapturingLogger::default()),
            sink.clone(),
        );
        let remote = GuidPrefix::from_bytes([0x72; 12]);
        let local_reader = rt
            .register_user_reader(UserReaderConfig {
                topic_name: "Chatter".into(),
                type_name: "zerodds::RawBytes".into(),
                ..Default::default()
            })
            .expect("reader")
            .0;
        let message = |destination: [u8; 16]| ParticipantGenericMessage {
            destination_participant_key: Guid::new(rt.guid_prefix, EntityId::PARTICIPANT)
                .to_bytes(),
            destination_endpoint_key: destination,
            message_class_id: class_id::DATAWRITER_CRYPTO_TOKENS.into(),
            message_data: vec![
                DataHolder::new(CRYPTO_TOKEN_CLASS_ID)
                    .with_binary_property(CRYPTO_TOKEN_PROP, vec![0xFF; 3]),
            ],
            ..Default::default()
        };
        let events = |name: &str| sink.snapshot().iter().filter(|e| e.name == name).count();
        // An endpoint this participant does not have.
        install_crypto_token(
            &rt,
            remote,
            &message(
                Guid::new(rt.guid_prefix, EntityId::user_reader_with_key([9, 9, 9])).to_bytes(),
            ),
        );
        assert_eq!(events("security.token.not_addressed"), 1);
        // An endpoint of another participant.
        install_crypto_token(
            &rt,
            remote,
            &message(Guid::new(remote, local_reader).to_bytes()),
        );
        assert_eq!(events("security.token.not_addressed"), 2);
        // The endpoint of this participant is addressed; the token itself is
        // garbage, which is recorded as a failure.
        install_crypto_token(
            &rt,
            remote,
            &message(Guid::new(rt.guid_prefix, local_reader).to_bytes()),
        );
        assert_eq!(events("security.token.not_addressed"), 2);
        assert_eq!(events("security.token.install_failed"), 1);
        rt.shutdown();
    }

    /// DDS-Security 1.2 §7.5.2: the liveliness heartbeat of a MANUAL_BY_TOPIC
    /// writer is the HEARTBEAT of the writer itself (the liveliness flag set),
    /// "protected using the same means as the regular DataWriter heartbeats":
    /// under a metadata protection kind it goes out in a SEC_PREFIX envelope
    /// and its HEARTBEAT submessage is not in the clear.
    #[cfg(feature = "security")]
    #[test]
    fn the_liveliness_heartbeat_of_a_manual_writer_is_protected_like_its_heartbeats() {
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control><topic_access_rules><topic_rule><topic_expression>*</topic_expression><metadata_protection_kind>ENCRYPT</metadata_protection_kind><data_protection_kind>NONE</data_protection_kind></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let rt = build_runtime_with(GOV, std::sync::Arc::new(CapturingLogger::default()));
        let writer = rt
            .register_user_writer(UserWriterConfig {
                topic_name: "Chatter".into(),
                type_name: "zerodds::RawBytes".into(),
                liveliness: zerodds_qos::LivelinessQosPolicy {
                    kind: zerodds_qos::LivelinessKind::ManualByTopic,
                    lease_duration: zerodds_qos::Duration::from_millis(1000_i32),
                },
                ..Default::default()
            })
            .expect("writer");
        let at = Locator::udp_v4([127, 0, 0, 1], 40300);
        let remote_reader = Guid::new(
            GuidPrefix::from_bytes([0x73; 12]),
            EntityId::user_reader_with_key([0, 0, 4]),
        );
        let slot = rt.writer_slot(writer).expect("slot");
        let heartbeats = {
            let mut slot = slot.lock().unwrap();
            slot.writer
                .add_reader_proxy(zerodds_rtps::reader_proxy::ReaderProxy::new(
                    remote_reader,
                    alloc::vec![at],
                    Vec::new(),
                    true,
                ));
            slot.writer.liveliness_heartbeat().expect("heartbeats")
        };
        let clear = &heartbeats.first().expect("a heartbeat").bytes;
        let ids = |bytes: &[u8]| -> Vec<u8> {
            walk_submessages(bytes)
                .into_iter()
                .map(|(id, _, _)| id)
                .collect()
        };
        assert!(ids(clear).contains(&SMID_HEARTBEAT), "the clear datagram");
        let protected = secure_outbound_for_target(&rt, writer, clear, &at).expect("protected");
        let sent = ids(&protected);
        assert!(sent.contains(&SMID_SEC_PREFIX), "a SEC_PREFIX envelope");
        assert!(!sent.contains(&SMID_HEARTBEAT), "no HEARTBEAT in the clear");
        rt.shutdown();
    }

    /// DDS-Security 1.2 §7.5.13: "if ParticipantSecurityConfig member
    /// is_access_protected is true, then access to the secure builtin topics is
    /// protected": a peer that authenticated and whose permissions the gate has
    /// none of (here: no `c.perm` in the handshake) does not get that access.
    /// The refusal is recorded with its reason.
    #[cfg(feature = "security")]
    #[test]
    fn a_peer_the_join_access_control_does_not_admit_gets_no_access() {
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>true</enable_join_access_control><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let sink = std::sync::Arc::new(zerodds_foundation::observability::VecSink::new());
        let rt = build_runtime_with_sink(
            GOV,
            std::sync::Arc::new(CapturingLogger::default()),
            sink.clone(),
        );
        assert!(
            rt.config
                .security
                .as_ref()
                .unwrap()
                .is_access_protected()
                .unwrap()
        );
        let stack = zerodds_discovery::security::SecurityBuiltinStack::new(
            rt.guid_prefix,
            VendorId::ZERODDS,
        );
        let remote = GuidPrefix::from_bytes([0x74; 12]);
        assert!(!store_remote_permissions(&rt, &stack, remote));
        let refused: Vec<String> = sink
            .snapshot()
            .iter()
            .filter(|e| e.name == "security.remote_permissions.refused")
            .map(|e| {
                e.attrs
                    .iter()
                    .find(|a| a.key == "reason")
                    .map(|a| a.value.clone())
                    .unwrap_or_default()
            })
            .collect();
        assert_eq!(refused.len(), 1, "{refused:?}");
        assert!(refused[0].contains("c.perm"), "{refused:?}");
        rt.shutdown();
    }

    /// DDS-Security 1.2 §7.5.4.3, §7.5.4.6.1 to §7.5.4.6.3: the messages of
    /// ParticipantVolatileMessageSecure that carry crypto tokens. All name the
    /// participant at their destination (`destination_participant_guid`) and
    /// relate to no other message; the participant token leaves both endpoint
    /// GUIDs at GUID_UNKNOWN; the DataWriter token has the writer as source and
    /// the matched reader as destination, the DataReader token the reader as
    /// source and the matched writer as destination.
    #[cfg(feature = "security")]
    #[test]
    fn volatile_messages_carry_the_fields_of_the_spec() {
        use zerodds_security::generic_message::{MessageIdentity, class_id};
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control><discovery_protection_kind>ENCRYPT</discovery_protection_kind><rtps_protection_kind>ENCRYPT</rtps_protection_kind><topic_access_rules><topic_rule><topic_expression>*</topic_expression><metadata_protection_kind>ENCRYPT</metadata_protection_kind><data_protection_kind>ENCRYPT</data_protection_kind></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let rt = build_runtime_with(GOV, std::sync::Arc::new(CapturingLogger::default()));
        let remote = GuidPrefix::from_bytes([0x71; 12]);
        let remote_participant = Guid::new(remote, EntityId::PARTICIPANT).to_bytes();
        let writer = rt
            .register_user_writer(UserWriterConfig {
                topic_name: "Chatter".into(),
                type_name: "zerodds::RawBytes".into(),
                ..Default::default()
            })
            .expect("writer");
        let (reader, _samples) = rt
            .register_user_reader(UserReaderConfig {
                topic_name: "Chatter".into(),
                type_name: "zerodds::RawBytes".into(),
                ..Default::default()
            })
            .expect("reader");
        let at = Locator::udp_v4([127, 0, 0, 1], 40200);
        let remote_reader = Guid::new(remote, EntityId::user_reader_with_key([0, 0, 9]));
        let remote_writer = Guid::new(remote, EntityId::user_writer_with_key([0, 0, 8]));
        rt.writer_slot(writer)
            .expect("slot")
            .lock()
            .unwrap()
            .writer
            .add_reader_proxy(zerodds_rtps::reader_proxy::ReaderProxy::new(
                remote_reader,
                alloc::vec![at],
                Vec::new(),
                true,
            ));
        rt.reader_slot(reader)
            .expect("slot")
            .lock()
            .unwrap()
            .reader
            .add_writer_proxy(zerodds_rtps::writer_proxy::WriterProxy::new(
                remote_writer,
                alloc::vec![at],
                Vec::new(),
                true,
            ));
        let messages = prepare_endpoint_crypto_tokens(&rt, remote);
        let local = |eid| Guid::new(rt.guid_prefix, eid).to_bytes();
        let find = |class: &str, source: [u8; 16]| {
            messages
                .iter()
                .find(|m| m.message_class_id == class && m.source_endpoint_key == source)
                .unwrap_or_else(|| panic!("no {class} message from {source:02x?}"))
        };
        let writer_token = find(class_id::DATAWRITER_CRYPTO_TOKENS, local(writer));
        assert_eq!(
            writer_token.destination_endpoint_key,
            remote_reader.to_bytes()
        );
        let reader_token = find(class_id::DATAREADER_CRYPTO_TOKENS, local(reader));
        assert_eq!(
            reader_token.destination_endpoint_key,
            remote_writer.to_bytes()
        );
        for m in &messages {
            assert_eq!(m.destination_participant_key, remote_participant, "{m:?}");
            assert_eq!(m.related_message_identity, MessageIdentity::default());
        }
        let participant = build_crypto_token_message(&rt, remote, vec![1, 2, 3]);
        assert_eq!(
            participant.message_class_id,
            class_id::PARTICIPANT_CRYPTO_TOKENS
        );
        assert_eq!(participant.destination_participant_key, remote_participant);
        assert_eq!(participant.destination_endpoint_key, [0; 16]);
        assert_eq!(participant.source_endpoint_key, [0; 16]);
        assert_eq!(
            participant.related_message_identity,
            MessageIdentity::default()
        );
        rt.shutdown();
    }

    /// DDS-Security 1.2 §7.5.5.2, §7.5.13 Table 21, §6.1: the TypeLookup service
    /// on the secure builtin endpoints. A request that leaves the secure
    /// request writer is protected per submessage with that endpoint's key (the
    /// secure writer id is not in the clear), the receiver opens it with the
    /// token of the endpoint and its secure transport takes the sample from
    /// the secure writer; without the token the datagram is not opened, and the
    /// plain service does not take a secure writer's sample.
    #[cfg(feature = "security")]
    #[test]
    fn the_secure_type_lookup_service_is_protected_per_submessage() {
        use zerodds_security::authentication::{IdentityHandle, SharedSecretHandle};
        use zerodds_security_crypto::AesGcmCryptoPlugin;
        use zerodds_security_permissions::parse_governance_xml;
        use zerodds_security_runtime::SharedSecurityGate;
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let gate = || {
            std::sync::Arc::new(SharedSecurityGate::new(
                0,
                parse_governance_xml(GOV).unwrap(),
                Box::new(AesGcmCryptoPlugin::new()),
            ))
        };
        let (a_prefix, b_prefix) = (
            GuidPrefix::from_bytes([0xA9; 12]),
            GuidPrefix::from_bytes([0xB9; 12]),
        );
        let (gate_a, gate_b, gate_c) = (gate(), gate(), gate());
        let start = |prefix: GuidPrefix, gate: &std::sync::Arc<SharedSecurityGate>| {
            let lease = zerodds_test_domains::lease_domain();
            let rt = DcpsRuntime::start(
                lease.id(),
                prefix,
                RuntimeConfig {
                    security: Some(std::sync::Arc::clone(gate)),
                    security_guid_prefix: Some(prefix),
                    spdp_multicast_send: false,
                    ..RuntimeConfig::default()
                },
            )
            .expect("start");
            LeasedRuntime { rt, _lease: lease }
        };
        let (rt_a, rt_b, rt_c) = (
            start(a_prefix, &gate_a),
            start(b_prefix, &gate_b),
            start(GuidPrefix::from_bytes([0xC9; 12]), &gate_c),
        );
        // B and C know A as a peer.
        for peer in [&gate_b, &gate_c] {
            peer.register_remote_by_guid(
                a_prefix.to_bytes(),
                IdentityHandle(1),
                SharedSecretHandle(1),
                &gate_a.local_token().unwrap(),
            )
            .unwrap();
        }
        // A writes a request on the secure request writer, to B.
        let at = Locator::udp_v4([127, 0, 0, 1], 40100);
        let request = rt_a
            .type_lookup_transport_secure
            .lock()
            .unwrap()
            .write(true, b_prefix, at, &[0, 7, 0, 0], None, Duration::ZERO)
            .unwrap();
        let clear = &request.first().expect("a request DATA").bytes;
        let writer_octets = EntityId::TL_SVC_REQ_SECURE_WRITER.to_bytes();
        assert!(clear.windows(4).any(|w| w == writer_octets));
        let protected = protect_type_lookup_outbound(&rt_a, clear).expect("protected");
        let sec_prefix = SMID_SEC_PREFIX;
        assert!(
            walk_submessages(&protected)
                .iter()
                .any(|(id, _, _)| *id == sec_prefix),
            "a SEC_PREFIX submessage"
        );
        assert!(
            !protected.windows(4).any(|w| w == writer_octets),
            "the secure writer id is not in the clear"
        );
        // C has no token of A's endpoint: it opens nothing.
        assert_eq!(
            unprotect_user_datagram(&rt_c, &protected, &a_prefix.to_bytes()),
            None
        );
        // B gets the token of the secure request writer and opens the request.
        let handle = local_endpoint_crypto_handle(&rt_a, EntityId::TL_SVC_REQ_SECURE_WRITER, true)
            .expect("key material of the endpoint");
        let token = gate_a.create_endpoint_token(handle).unwrap();
        gate_b
            .install_remote_endpoint_token(&a_prefix.to_bytes(), &token)
            .unwrap();
        let opened = unprotect_user_datagram(&rt_b, &protected, &a_prefix.to_bytes())
            .expect("opened with the token of the endpoint");
        let (taken, samples) = rt_b
            .type_lookup_transport_secure
            .lock()
            .unwrap()
            .receive(&opened, at, Duration::ZERO)
            .unwrap();
        assert!(taken);
        assert_eq!(samples.len(), 1);
        assert_eq!(
            samples[0].writer_guid.entity_id,
            EntityId::TL_SVC_REQ_SECURE_WRITER
        );
        // The plain service does not take it.
        assert!(
            !rt_b
                .type_lookup_transport
                .lock()
                .unwrap()
                .receive(&opened, at, Duration::ZERO)
                .unwrap()
                .0
        );
        // A peer that does not announce the secure endpoints is served plain.
        assert!(!rt_a.type_lookup_secure_with(b_prefix));
    }

    /// The crypto-token preparation runs with the lock of the security
    /// builtin stack held; the decision whether a peer is served on the
    /// secure TypeLookup endpoints must not take the locks of the stack
    /// (here: of its holder) again.
    #[cfg(feature = "security")]
    #[test]
    fn the_secure_type_lookup_decision_does_not_take_the_stack_lock() {
        use zerodds_security_permissions::parse_governance_xml;
        use zerodds_security_runtime::SharedSecurityGate;
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let prefix = GuidPrefix::from_bytes([0xA8; 12]);
        let gate = std::sync::Arc::new(SharedSecurityGate::new(
            0,
            parse_governance_xml(GOV).unwrap(),
            Box::new(zerodds_security_crypto::AesGcmCryptoPlugin::new()),
        ));
        let lease = zerodds_test_domains::lease_domain();
        let started = DcpsRuntime::start(
            lease.id(),
            prefix,
            RuntimeConfig {
                security: Some(gate),
                security_guid_prefix: Some(prefix),
                spdp_multicast_send: false,
                ..RuntimeConfig::default()
            },
        )
        .expect("start");
        let rt = LeasedRuntime {
            rt: started,
            _lease: lease,
        };
        let (done, result) = std::sync::mpsc::channel();
        let runtime = Arc::clone(&rt.rt);
        std::thread::spawn(move || {
            let held = runtime.security_builtin.lock().unwrap();
            let decided = runtime.type_lookup_secure_with(GuidPrefix::from_bytes([0xB8; 12]));
            drop(held);
            let _ = done.send(decided);
        });
        assert_eq!(
            result.recv_timeout(std::time::Duration::from_secs(10)),
            Ok(false),
            "the decision returns while the stack lock is held"
        );
    }

    /// OpenDDS bundles the blocks of several endpoints of its in one datagram,
    /// the block of a volatile message with the Kx key among them. The
    /// submessages of a datagram are independent: the block of an endpoint
    /// key is opened, the block of the Kx key stays for the volatile layer,
    /// and neither is a refusal.
    #[cfg(feature = "security")]
    #[test]
    fn a_datagram_with_a_volatile_block_among_the_endpoint_blocks_is_opened_block_by_block() {
        use zerodds_security::authentication::{
            IdentityHandle, SharedSecretHandle, SharedSecretProvider,
        };
        use zerodds_security_crypto::{AesGcmCryptoPlugin, Suite};
        use zerodds_security_permissions::parse_governance_xml;
        use zerodds_security_runtime::SharedSecurityGate;
        struct FixedSecret;
        impl SharedSecretProvider for FixedSecret {
            fn get_shared_secret(&self, _: SharedSecretHandle) -> Option<Vec<u8>> {
                Some(vec![0x33; 32])
            }
        }
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let gate = || {
            std::sync::Arc::new(SharedSecurityGate::new(
                0,
                parse_governance_xml(GOV).unwrap(),
                Box::new(AesGcmCryptoPlugin::with_secret_provider(
                    Suite::Aes128Gcm,
                    std::sync::Arc::new(FixedSecret) as std::sync::Arc<dyn SharedSecretProvider>,
                )),
            ))
        };
        let (a_prefix, b_prefix) = (
            GuidPrefix::from_bytes([0xA7; 12]),
            GuidPrefix::from_bytes([0xB7; 12]),
        );
        let (gate_a, gate_b) = (gate(), gate());
        gate_a
            .register_remote_by_guid_from_secret(
                b_prefix.to_bytes(),
                IdentityHandle(2),
                SharedSecretHandle(1),
            )
            .unwrap();
        gate_b
            .register_remote_by_guid_from_secret(
                a_prefix.to_bytes(),
                IdentityHandle(1),
                SharedSecretHandle(1),
            )
            .unwrap();
        let start = |prefix: GuidPrefix, gate: &std::sync::Arc<SharedSecurityGate>| {
            let lease = zerodds_test_domains::lease_domain();
            let rt = DcpsRuntime::start(
                lease.id(),
                prefix,
                RuntimeConfig {
                    security: Some(std::sync::Arc::clone(gate)),
                    security_guid_prefix: Some(prefix),
                    spdp_multicast_send: false,
                    ..RuntimeConfig::default()
                },
            )
            .expect("start");
            LeasedRuntime { rt, _lease: lease }
        };
        let (rt_a, rt_b) = (start(a_prefix, &gate_a), start(b_prefix, &gate_b));
        // A block under the key of A's secure request writer, B holds its token.
        let at = Locator::udp_v4([127, 0, 0, 1], 40200);
        let request = rt_a
            .type_lookup_transport_secure
            .lock()
            .unwrap()
            .write(true, b_prefix, at, &[0, 7, 0, 0], None, Duration::ZERO)
            .unwrap();
        let clear = &request.first().expect("a request DATA").bytes;
        let mut mixed = protect_type_lookup_outbound(&rt_a, clear)
            .expect("protected")
            .into_owned();
        let handle = local_endpoint_crypto_handle(&rt_a, EntityId::TL_SVC_REQ_SECURE_WRITER, true)
            .expect("key material of the endpoint");
        let token = gate_a.create_endpoint_token(handle).unwrap();
        gate_b
            .install_remote_endpoint_token(&a_prefix.to_bytes(), &token)
            .unwrap();
        // A block under the Kx key: a DATA of the volatile writer.
        let mut volatile = vec![SMID_DATA, 0x01, 20, 0, 0, 0, 16, 0];
        volatile.extend_from_slice(
            &EntityId::BUILTIN_PARTICIPANT_VOLATILE_MESSAGE_SECURE_READER.to_bytes(),
        );
        volatile.extend_from_slice(
            &EntityId::BUILTIN_PARTICIPANT_VOLATILE_MESSAGE_SECURE_WRITER.to_bytes(),
        );
        volatile.extend_from_slice(&[0, 0, 0, 0, 1, 0, 0, 0]);
        mixed.extend_from_slice(
            &gate_a
                .encode_kx_datawriter_for(&b_prefix.to_bytes(), &volatile)
                .expect("Kx block"),
        );
        // The endpoint block is opened; the Kx block is still there.
        let opened = unprotect_user_datagram(&rt_b, &mixed, &a_prefix.to_bytes())
            .expect("the endpoint block is opened");
        let writer_octets = EntityId::TL_SVC_REQ_SECURE_WRITER.to_bytes();
        assert!(opened.windows(4).any(|w| w == writer_octets));
        assert!(
            walk_submessages(&opened)
                .iter()
                .any(|(id, _, _)| *id == SMID_SEC_PREFIX),
            "the Kx block stays"
        );
        // The volatile layer opens the rest.
        let rest = unprotect_volatile_datagram(&rt_b, &opened, &a_prefix.to_bytes())
            .expect("the Kx block is opened");
        let volatile_writer =
            EntityId::BUILTIN_PARTICIPANT_VOLATILE_MESSAGE_SECURE_WRITER.to_bytes();
        assert!(rest.windows(4).any(|w| w == volatile_writer));
    }

    /// DDS-Security 1.2 §7.3.21, §7.5.1.4: the entries of the participant's
    /// PropertyQosPolicy with `propagate = TRUE` reach a peer in the
    /// `PID_PROPERTY_LIST` of the SPDP data, the others do not; a change goes
    /// out at once; a list the wire cannot carry is refused.
    #[test]
    fn the_propagated_participant_properties_reach_the_peer() {
        let property = zerodds_qos::PropertyQosPolicy::new()
            .with("local.only", "1")
            .with_propagated("com.example.shared", "2");
        let lease = zerodds_test_domains::lease_domain();
        let tight = |properties| RuntimeConfig {
            tick_period: Duration::from_millis(20),
            spdp_period: Duration::from_millis(100),
            participant_properties: properties,
            ..RuntimeConfig::default()
        };
        let a = ShutsDown(
            DcpsRuntime::start(
                lease.id(),
                GuidPrefix::from_bytes([0xA7; 12]),
                tight(crate::qos::propagated_properties(&property)),
            )
            .expect("a"),
        );
        let b = ShutsDown(
            DcpsRuntime::start(
                lease.id(),
                GuidPrefix::from_bytes([0xB7; 12]),
                tight(Default::default()),
            )
            .expect("b"),
        );
        let seen_by_b = |key: &str| {
            b.discovered_participants()
                .iter()
                .find(|p| p.sender_prefix == GuidPrefix::from_bytes([0xA7; 12]))
                .and_then(|p| p.data.properties.get(key).map(ToString::to_string))
        };
        let until = |what: &dyn Fn() -> bool| {
            for _ in 0..80 {
                if what() {
                    return true;
                }
                thread::sleep(Duration::from_millis(50));
            }
            false
        };
        assert!(until(
            &|| seen_by_b("com.example.shared").as_deref() == Some("2")
        ));
        assert_eq!(seen_by_b("local.only"), None);
        let changed =
            zerodds_qos::PropertyQosPolicy::new().with_propagated("com.example.shared", "3");
        a.update_participant_properties(crate::qos::propagated_properties(&changed))
            .expect("a list the wire carries");
        assert!(until(
            &|| seen_by_b("com.example.shared").as_deref() == Some("3")
        ));
        let mut too_many = zerodds_qos::PropertyQosPolicy::new();
        for n in 0..1025 {
            too_many.set_propagated(alloc::format!("p{n}"), "v", true);
        }
        assert!(matches!(
            a.update_participant_properties(crate::qos::propagated_properties(&too_many)),
            Err(DdsError::BadParameter { .. })
        ));
    }

