    /// DDS-Security 1.2 §9.4.2.4 `is_rtps_psk_protected`, §10.9: with a
    /// pre-shared key the bootstrapping messages (SPDP) go out with the
    /// flag P, are read back with `decode_rtps_message`, and a plain one is
    /// refused and recorded; a message under another passphrase is refused.
    #[cfg(feature = "security")]
    #[test]
    fn a_pre_shared_key_protects_the_bootstrapping_messages() {
        use zerodds_security_crypto::psk_rtps::{Passphrase, PskConfig, PskProtection};
        use zerodds_security_runtime::SharedSecurityGate;
        const GOV_ENCRYPT: &str = r#"
<dds><domain_access_rules>
  <domain_rule>
    <domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control>
    <rtps_protection_kind>ENCRYPT</rtps_protection_kind>
    <topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules>
  </domain_rule>
</domain_access_rules></dds>
"#;
        let psk = |passphrase: &str| PskConfig {
            domain_id: 0,
            domain_tag: String::new(),
            passphrase: Passphrase::parse(passphrase).unwrap(),
            alternatives: Vec::new(),
            key_bits: 256,
            protection: PskProtection::Encrypt,
        };
        let sink = std::sync::Arc::new(zerodds_foundation::observability::VecSink::new());
        let logger = std::sync::Arc::new(CapturingLogger::default());
        let rt = build_runtime_with_sink(GOV_ENCRYPT, logger, sink.clone());
        let gate = rt.config.security.as_ref().expect("a gate");
        gate.set_rtps_psk(psk("5612:Open Sesame")).unwrap();
        let beacon = make_remote_spdp_beacon(GuidPrefix::from_bytes([0x99; 12]));
        // Out: the SPDP beacon, a bootstrapping message, goes under the key.
        let wire = secure_outbound_bytes(&rt, &beacon)
            .expect("protected")
            .into_owned();
        assert_ne!(wire, beacon);
        assert!(SharedSecurityGate::is_psk_protected(&wire));
        // In: it is read back as it was.
        let back = secure_inbound_bytes(&rt, &wire, &NetInterface::Wan).expect("accepted");
        assert_eq!(&back[..], &beacon[..]);
        // In: a bootstrapping message without the protection is refused.
        assert!(secure_inbound_bytes(&rt, &beacon, &NetInterface::Wan).is_none());
        let refused = inbound_refusals(&sink);
        assert_eq!(refused.len(), 1, "{refused:?}");
        assert_eq!(refused[0].0, "inbound.psk");
        // In: another passphrase does not open it.
        gate.set_rtps_psk(psk("5612:Another passphrase")).unwrap();
        assert!(secure_inbound_bytes(&rt, &wire, &NetInterface::Wan).is_none());
        assert_eq!(inbound_refusals(&sink).len(), 2);
        // Without a pre-shared key nothing of this applies: the beacon goes
        // out as it is (the exchanged key does not cover it).
        let plain_rt =
            build_runtime_with(GOV_ENCRYPT, std::sync::Arc::new(CapturingLogger::default()));
        let out = secure_outbound_bytes(&plain_rt, &beacon).expect("sent");
        assert_eq!(&out[..], &beacon[..]);
        plain_rt.shutdown();
        rt.shutdown();
    }

    /// An encrypted SerializedPayload (N flag) that decodes with no key
    /// is dropped, and the drop is recorded; it was dropped without a
    /// trace.
    #[cfg(feature = "security")]
    #[test]
    fn an_undecodable_encrypted_payload_is_recorded() {
        // The payload layer is the reader's (`GatePayloadOpener`): a flagged
        // payload no key of its writer opens is refused, so the change stays
        // MISSING and is asked for again, and the refusal is recorded.
        use zerodds_rtps::reliable_reader::{PayloadOpener, PayloadOpening};
        const GOV_NONE: &str = r#"
<dds><domain_access_rules>
  <domain_rule>
    <domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control>
    <rtps_protection_kind>NONE</rtps_protection_kind>
    <topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules>
  </domain_rule>
</domain_access_rules></dds>
"#;
        let sink = std::sync::Arc::new(zerodds_foundation::observability::VecSink::new());
        let logger = std::sync::Arc::new(CapturingLogger::default());
        let rt = build_runtime_with_sink(GOV_NONE, logger, sink.clone());
        let mut payload = std::vec![0x00, 0x00, 0x00, 0x02];
        payload.extend_from_slice(&[0x11; 40]);
        let writer = Guid::new(
            GuidPrefix::from_bytes([0x66; 12]),
            EntityId::user_writer_with_key([0, 0, 2]),
        );
        let opener = GatePayloadOpener::of(&rt).expect("a gate");
        let opened = opener.open(
            writer,
            None,
            &zerodds_rtps::payload::Payload::from(payload.as_slice()),
            true,
        );
        assert!(matches!(opened, PayloadOpening::Refused), "{opened:?}");
        let refused = inbound_refusals(&sink);
        assert_eq!(refused.len(), 1, "{refused:?}");
        assert_eq!(refused[0].0, "inbound.payload");
        assert!(refused[0].1.contains("no key"), "{refused:?}");
        // Unflagged and not shaped like a CryptoHeader: a plaintext payload.
        let plain = opener.open(
            writer,
            None,
            &zerodds_rtps::payload::Payload::from(&[0x00, 0x01, 0x00, 0x00, 7][..]),
            false,
        );
        assert!(matches!(plain, PayloadOpening::AsIs), "{plain:?}");
        rt.shutdown();
    }

    /// DDS-Security 1.2 §9.5.1.10.9: a reader whose topic protects the
    /// payload decodes every payload of its writers. A writer that sets no
    /// NonStandardPayloadFlag (Cyclone DDS, Fast DDS) is recognised by the
    /// CryptoHeader. Such a payload that does not open was handed to the
    /// application as it was, as a plaintext CDR_BE payload (measured with
    /// Fast DDS, profile oa-enc: the CryptoContent reached the application).
    /// On a reader of a protected topic it is refused; on another reader it
    /// stays a plaintext payload, and the hand-out is recorded.
    #[cfg(feature = "security")]
    #[test]
    fn an_unflagged_payload_that_does_not_open_is_refused_on_a_protected_topic() {
        use zerodds_rtps::reliable_reader::{PayloadOpener, PayloadOpening};
        const GOV_NONE: &str = r#"
<dds><domain_access_rules>
  <domain_rule>
    <domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control>
    <rtps_protection_kind>NONE</rtps_protection_kind>
    <topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules>
  </domain_rule>
</domain_access_rules></dds>
"#;
        let sink = std::sync::Arc::new(zerodds_foundation::observability::VecSink::new());
        let logger = std::sync::Arc::new(CapturingLogger::default());
        let rt = build_runtime_with_sink(GOV_NONE, logger, sink.clone());
        // CryptoHeader: AES256_GCM, a key id no key of the writer has.
        let mut payload = std::vec![0x00, 0x00, 0x00, 0x04];
        payload.extend_from_slice(&[0x22; 44]);
        let payload = zerodds_rtps::payload::Payload::from(payload.as_slice());
        let writer = Guid::new(
            GuidPrefix::from_bytes([0x67; 12]),
            EntityId::user_writer_with_key([0, 0, 2]),
        );
        let opener = GatePayloadOpener::of(&rt).expect("a gate");
        let unprotected = opener.open(writer, None, &payload, false);
        assert!(
            matches!(unprotected, PayloadOpening::AsIs),
            "{unprotected:?}"
        );
        let as_is = sink
            .snapshot()
            .iter()
            .filter(|e| e.name == "security.inbound.payload_as_is")
            .count();
        assert_eq!(as_is, 1, "the hand-out is recorded");
        let protected = opener.for_reader(true).open(writer, None, &payload, false);
        assert!(
            matches!(protected, PayloadOpening::Refused),
            "{protected:?}"
        );
        let refused = inbound_refusals(&sink);
        assert_eq!(refused.len(), 1, "{refused:?}");
        assert_eq!(refused[0].0, "inbound.payload");
        rt.shutdown();
    }

    #[cfg(feature = "security")]
    #[test]
    fn inbound_plain_on_encrypt_domain_drops_with_error_event() {
        // DoD plan §stage 5: writer sends plain, policy expects
        // ENCRYPT → reader drops. Without allow_unauthenticated this
        // is a "LegacyBlocked" → error level (not warning) per
        // the plan spec "missing-caps = Error".
        const GOV_ENCRYPT: &str = r#"
<dds><domain_access_rules>
  <domain_rule>
    <domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control>
    <rtps_protection_kind>ENCRYPT</rtps_protection_kind>
    <topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules>
  </domain_rule>
</domain_access_rules></dds>
"#;
        let logger = std::sync::Arc::new(CapturingLogger::default());
        let rt = build_runtime_with(GOV_ENCRYPT, std::sync::Arc::clone(&logger));

        // Plain-RTPS-Datagram (header + body).
        let mut plain = Vec::new();
        plain.extend_from_slice(b"RTPS\x02\x05\x01\x02");
        plain.extend_from_slice(&[0x77; 12]); // attacker guid_prefix
        plain.extend_from_slice(b"plaintext-on-encrypted-domain");

        let out = secure_inbound_bytes(&rt, &plain, &NetInterface::Wan);
        assert!(out.is_none(), "tampering packet must be dropped");

        let events = logger.events();
        assert_eq!(
            events.len(),
            1,
            "exactly one log event expected: {events:?}"
        );
        let (level, category, _msg) = &events[0];
        assert_eq!(
            *level,
            zerodds_security_runtime::LogLevel::Error,
            "plain-on-protected-domain without allow_unauth = Error (LegacyBlocked)"
        );
        assert_eq!(category, "inbound.legacy_blocked");
        rt.shutdown();
    }

    #[cfg(feature = "security")]
    #[test]
    fn inbound_legacy_peer_accepted_when_governance_allows_unauth() {
        // A legacy peer keeps talking to the reader on a domain whose
        // governance allows unauthenticated participants; such a domain has
        // no RTPS protection (§9.4.2.4 Table 33).
        const GOV: &str = r#"
<dds><domain_access_rules>
  <domain_rule>
    <domains><id>0</id></domains><enable_join_access_control>false</enable_join_access_control>
    <allow_unauthenticated_participants>TRUE</allow_unauthenticated_participants>
    <rtps_protection_kind>NONE</rtps_protection_kind>
    <topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules>
  </domain_rule>
</domain_access_rules></dds>
"#;
        let logger = std::sync::Arc::new(CapturingLogger::default());
        let rt = build_runtime_with(GOV, std::sync::Arc::clone(&logger));

        let mut plain = Vec::new();
        plain.extend_from_slice(b"RTPS\x02\x05\x01\x02");
        plain.extend_from_slice(&[0x88; 12]);
        plain.extend_from_slice(b"legacy-but-allowed");

        let out = secure_inbound_bytes(&rt, &plain, &NetInterface::Wan)
            .expect("legacy peer must be accepted");
        assert_eq!(out, plain, "output is byte-identical (no crypto unwrap)");
        assert!(
            logger.events().is_empty(),
            "no log event on the accept path: {:?}",
            logger.events()
        );
        rt.shutdown();
    }

