    /// Minimal auth plugin for the FU2 wiring tests (Gap 4/7).
    /// Crypto correctness is verified in the stack.rs driver test; here
    /// it is only about the runtime wiring path.
    #[cfg(feature = "security")]
    struct FakeAuth;
    #[cfg(feature = "security")]
    impl zerodds_security::authentication::AuthenticationExtensions for FakeAuth {
        fn plugin_class_id(&self) -> &str {
            "FAKE:Auth:1.0"
        }
        fn get_permissions_token(&self) -> Vec<u8> {
            // Non-empty PermissionsToken, so the beacon-populate path
            // (S4 point 1) has something to announce (format irrelevant).
            zerodds_security::token::DataHolder::new("DDS:Access:Permissions:1.0").to_cdr_le()
        }
    }
    #[cfg(feature = "security")]
    impl zerodds_security::authentication::AuthenticationPlugin for FakeAuth {
        fn validate_local_identity(
            &mut self,
            _: u32,
            _: &zerodds_security::properties::PropertyList,
            guid: [u8; 16],
        ) -> zerodds_security::error::SecurityResult<
            zerodds_security::authentication::LocalIdentityValidation,
        > {
            Ok(zerodds_security::authentication::LocalIdentityValidation {
                result: zerodds_security::authentication::ValidationResult::Ok,
                identity: zerodds_security::authentication::IdentityHandle(1),
                adjusted_participant_guid: guid,
            })
        }
        fn get_identity_token(
            &mut self,
            _: zerodds_security::authentication::IdentityHandle,
        ) -> zerodds_security::error::SecurityResult<Vec<u8>> {
            // Non-empty Token (Format irrelevant — FakeAuth.validate_remote_
            // identity accepts everything); only so the beacon-populate path
            // (Gap 7c) has something to announce.
            Ok(alloc::vec![0xAB, 0xCD, 0xEF, 0x01])
        }
        fn get_identity_status_token(
            &mut self,
            _: zerodds_security::authentication::IdentityHandle,
        ) -> zerodds_security::error::SecurityResult<Vec<u8>> {
            Ok(zerodds_security::token::DataHolder::new("FAKE:Auth:Status:1.0").to_cdr_le())
        }
        fn set_participant_security_config(
            &mut self,
            _: zerodds_security::authentication::IdentityHandle,
            config: &zerodds_security::authentication::ParticipantSecurityConfig,
        ) -> zerodds_security::error::SecurityResult<zerodds_security::authentication::AlgorithmMasks>
        {
            Ok(config.algorithm_info)
        }
        fn set_permissions_credential_and_token(
            &mut self,
            _: zerodds_security::authentication::IdentityHandle,
            _: &[u8],
            _: &[u8],
        ) -> zerodds_security::error::SecurityResult<()> {
            Ok(())
        }
        fn validate_remote_identity(
            &mut self,
            _: zerodds_security::authentication::IdentityHandle,
            remote_guid: [u8; 16],
            _: &[u8],
            _remote_auth_request_token: Option<&[u8]>,
        ) -> zerodds_security::error::SecurityResult<
            zerodds_security::authentication::RemoteIdentityValidation,
        > {
            // The test runtimes have the prefixes 0x40 to 0x4B; the remote
            // participants of the tests are 0x99 and the like: greater, so
            // the local side starts the handshake (Table 59).
            let result = if remote_guid[0] >= 0x60 {
                zerodds_security::authentication::ValidationResult::PendingHandshakeRequest
            } else {
                zerodds_security::authentication::ValidationResult::PendingHandshakeMessage
            };
            Ok(zerodds_security::authentication::RemoteIdentityValidation {
                result,
                identity: zerodds_security::authentication::IdentityHandle(2),
                local_auth_request_token: None,
            })
        }
        fn begin_handshake_request(
            &mut self,
            _: zerodds_security::authentication::IdentityHandle,
            _: zerodds_security::authentication::IdentityHandle,
            _: &[u8],
        ) -> zerodds_security::error::SecurityResult<(
            zerodds_security::authentication::HandshakeHandle,
            zerodds_security::authentication::HandshakeStepOutcome,
        )> {
            Ok((
                zerodds_security::authentication::HandshakeHandle(1),
                zerodds_security::authentication::HandshakeStepOutcome::SendMessage {
                    token: zerodds_security::token::DataHolder::new("DDS:Auth:PKI-DH:1.2+AuthReq")
                        .to_cdr_le(),
                },
            ))
        }
        fn begin_handshake_reply(
            &mut self,
            _: zerodds_security::authentication::IdentityHandle,
            _: zerodds_security::authentication::IdentityHandle,
            _: &[u8],
            _: &[u8],
        ) -> zerodds_security::error::SecurityResult<(
            zerodds_security::authentication::HandshakeHandle,
            zerodds_security::authentication::HandshakeStepOutcome,
        )> {
            Ok((
                zerodds_security::authentication::HandshakeHandle(2),
                zerodds_security::authentication::HandshakeStepOutcome::WaitingForPeer,
            ))
        }
        fn process_handshake(
            &mut self,
            _: zerodds_security::authentication::HandshakeHandle,
            _: &[u8],
        ) -> zerodds_security::error::SecurityResult<
            zerodds_security::authentication::HandshakeStepOutcome,
        > {
            Ok(zerodds_security::authentication::HandshakeStepOutcome::WaitingForPeer)
        }
        fn shared_secret(
            &self,
            _: zerodds_security::authentication::HandshakeHandle,
        ) -> zerodds_security::error::SecurityResult<
            zerodds_security::authentication::SharedSecretHandle,
        > {
            Err(zerodds_security::error::SecurityError::new(
                zerodds_security::error::SecurityErrorKind::BadArgument,
                "fake: handshake not complete",
            ))
        }
        fn get_authenticated_peer_credential_token(
            &mut self,
            _: zerodds_security::authentication::HandshakeHandle,
        ) -> zerodds_security::error::SecurityResult<Vec<u8>> {
            Ok(Vec::new())
        }
        fn set_listener(
            &mut self,
            _: Option<Arc<dyn zerodds_security::authentication::AuthenticationListener>>,
        ) -> zerodds_security::error::SecurityResult<()> {
            Ok(())
        }
        fn return_identity_token(
            &mut self,
            _: &[u8],
        ) -> zerodds_security::error::SecurityResult<()> {
            Ok(())
        }
        fn return_identity_status_token(
            &mut self,
            _: &[u8],
        ) -> zerodds_security::error::SecurityResult<()> {
            Ok(())
        }
        fn return_authenticated_peer_credential_token(
            &mut self,
            _: &[u8],
        ) -> zerodds_security::error::SecurityResult<()> {
            Ok(())
        }
        fn return_handshake_handle(
            &mut self,
            _: zerodds_security::authentication::HandshakeHandle,
        ) -> zerodds_security::error::SecurityResult<()> {
            Ok(())
        }
        fn return_identity_handle(
            &mut self,
            _: zerodds_security::authentication::IdentityHandle,
        ) -> zerodds_security::error::SecurityResult<()> {
            Ok(())
        }
        fn return_sharedsecret_handle(
            &mut self,
            _: zerodds_security::authentication::SharedSecretHandle,
        ) -> zerodds_security::error::SecurityResult<()> {
            Ok(())
        }
    }

    /// Consolidated test for the wiring. A single
    /// runtime walks all paths — snapshot API, idempotency of
    /// `enable_security_builtins`, SPDP hot path with security bits,
    /// without bits, plus the wire-demux hook. We bundle this into one
    /// test body, because each `DcpsRuntime::start` binds a multicast socket
    /// and parallel tests could brush against the OS resource caps.
    #[test]
    fn c34c_security_builtin_wiring_end_to_end() {
        use zerodds_discovery::security::SecurityBuiltinStack;
        use zerodds_security::generic_message::{
            MessageIdentity, ParticipantGenericMessage, class_id,
        };
        use zerodds_security::token::DataHolder;

        let local_prefix = GuidPrefix::from_bytes([0x75; 12]);
        let rt = DcpsRuntime::start(75, local_prefix, RuntimeConfig::default()).expect("start");

        // 1. Snapshot is None before enable
        assert!(rt.security_builtin_snapshot().is_none());

        // 2. enable is idempotent
        let h1 = rt.enable_security_builtins(VendorId::ZERODDS);
        let h2 = rt.enable_security_builtins(VendorId::ZERODDS);
        assert!(Arc::ptr_eq(&h1, &h2));
        assert!(rt.security_builtin_snapshot().is_some());

        // 3. SPDP beacon with all security-builtin bits → the stack has the
        //    two stateless proxies; the volatile secure ones follow the
        //    authentication (DDS-Security 1.2 §9.8.3.2), which this
        //    auth-less stack never completes
        let remote_a = GuidPrefix::from_bytes([0x99; 12]);
        let flags_all = endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER
            | endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_READER
            | endpoint_flag::PARTICIPANT_VOLATILE_MESSAGE_SECURE_WRITER
            | endpoint_flag::PARTICIPANT_VOLATILE_MESSAGE_SECURE_READER;
        handle_spdp_datagram(
            &rt,
            &make_remote_spdp_beacon_with_flags(remote_a, flags_all),
            None,
        );
        {
            let s = h1.lock().unwrap();
            assert_eq!(s.stateless_writer.reader_proxy_count(), 1);
            assert_eq!(s.stateless_reader.writer_proxy_count(), 1);
            assert_eq!(s.volatile_writer.reader_proxy_count(), 0);
            assert_eq!(s.volatile_reader.writer_proxy_count(), 0);
        }

        // 4. SPDP beacon without security bits → the stack stays unchanged
        let remote_b = GuidPrefix::from_bytes([0x88; 12]);
        handle_spdp_datagram(
            &rt,
            &make_remote_spdp_beacon_with_flags(remote_b, endpoint_flag::ALL_STANDARD),
            None,
        );
        {
            let s = h1.lock().unwrap();
            assert_eq!(
                s.stateless_writer.reader_proxy_count(),
                1,
                "a peer without security bits must not touch existing proxies"
            );
        }

        // 5. Wire-demux hook with a valid stateless DATA: remote-stack
        //    mirror sends a message → the demux hook routes it through
        //    the local reader without panic.
        let mut remote_stack = SecurityBuiltinStack::new(remote_a, VendorId::ZERODDS);
        let local_peer = make_remote_spdp_beacon_with_flags(local_prefix, flags_all);
        let parsed_local = zerodds_discovery::spdp::SpdpReader::new()
            .parse_datagram(&local_peer)
            .unwrap();
        remote_stack.handle_remote_endpoints(&parsed_local);
        let msg = ParticipantGenericMessage {
            message_identity: MessageIdentity {
                source_guid: [0xCD; 16],
                sequence_number: 1,
            },
            related_message_identity: MessageIdentity::default(),
            destination_participant_key: Guid::new(local_prefix, EntityId::PARTICIPANT).to_bytes(),
            destination_endpoint_key: [0; 16],
            source_endpoint_key: [0xFE; 16],
            message_class_id: class_id::AUTH_REQUEST.into(),
            message_data: alloc::vec![DataHolder::new("DDS:Auth:PKI-DH:1.2+AuthReq")],
        };
        let dgs = remote_stack.stateless_writer.write(&msg).unwrap();
        assert_eq!(dgs.len(), 1);
        dispatch_security_builtin_datagram(&rt, &dgs[0].bytes, Duration::from_secs(1));

        // 6. The demux hook does not panic on garbage bytes
        dispatch_security_builtin_datagram(&rt, &[0u8; 32], Duration::from_secs(1));

        rt.shutdown();
    }

    /// FU2 Gap 4: `enable_security_builtins_with_auth` builds the stack with
    /// an active handshake driver — `begin_handshake_with` sends, as
    /// the initiator actually sends an AUTH_REQUEST (instead of a no-op like with
    /// the auth-less `enable_security_builtins`).
    #[cfg(feature = "security")]
    #[test]
    fn enable_security_builtins_with_auth_activates_handshake_driver() {
        use zerodds_security::authentication::{AuthenticationPlugin, IdentityHandle};

        let local_prefix = GuidPrefix::from_bytes([0x40; 12]);
        let rt = DcpsRuntime::start(40, local_prefix, RuntimeConfig::default()).expect("start");

        let auth: Arc<Mutex<dyn AuthenticationPlugin>> = Arc::new(Mutex::new(FakeAuth));
        let stack =
            rt.enable_security_builtins_with_auth(VendorId::ZERODDS, auth, IdentityHandle(1));

        // Discover a peer with stateless bits (WITHOUT identity_token → the
        // discovery trigger starts no handshake yet) → proxies
        // are wired. The remote prefix is LARGER than local ([0x40]),
        // so that local is the initiator under the cyclone convention (smaller GUID
        // initiates) and actually sends.
        let remote = GuidPrefix::from_bytes([0x99; 12]);
        let flags = endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER
            | endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_READER;
        handle_spdp_datagram(
            &rt,
            &make_remote_spdp_beacon_with_flags(remote, flags),
            None,
        );

        let dgs = {
            let mut s = stack.lock().unwrap();
            let remote_guid = Guid::new(remote, EntityId::PARTICIPANT).to_bytes();
            s.begin_handshake_with(remote, remote_guid, b"fake-remote-cert-der")
                .expect("begin_handshake_with")
        };
        assert_eq!(
            dgs.len(),
            1,
            "auth driver active → the initiator sends exactly one AUTH_REQUEST"
        );

        rt.shutdown();
    }

    /// DDS-Security 1.2 §9.4.2.9.22, Table 70 (`algorithm_info`): the
    /// algorithms the participant announces as supported are those of its
    /// plugins that the AccessControl plugin allows (`allowed_crypto_algorithms`
    /// of the governance); what the plugins require stays as it is.
    #[cfg(feature = "security")]
    #[test]
    fn the_allowed_algorithms_cut_the_announced_ones() {
        use zerodds_security::access_control::{
            CryptoAlgorithmRequirements as Req, DigitalSignatureAlgorithmInfo,
            KeyEstablishmentAlgorithmInfo, ParticipantSecurityAlgorithmInfo,
            SymmetricCipherAlgorithmInfo,
        };
        use zerodds_security::authentication::AlgorithmMasks;
        let masks = AlgorithmMasks {
            trust_chain: (0b1111, 0b0100),
            message_auth: (0b0101, 0b0100),
            key_establishment: (0b0111, 0b0010),
        };
        let allowed = ParticipantSecurityAlgorithmInfo {
            digital_signature: DigitalSignatureAlgorithmInfo {
                trust_chain: Req {
                    supported_mask: 0b0110,
                    required_mask: 0,
                },
                message_auth: Req {
                    supported_mask: 0b0100,
                    required_mask: 0,
                },
            },
            key_establishment: KeyEstablishmentAlgorithmInfo {
                shared_secret: Req {
                    supported_mask: 0b0010,
                    required_mask: 0,
                },
            },
            symmetric_cipher: SymmetricCipherAlgorithmInfo {
                supported_mask: 0b10,
                ..Default::default()
            },
        };
        let (sig, kx, sym) = local_algorithm_infos(Some(masks), 256, Some(&allowed));
        let sig = sig.expect("signature info");
        assert_eq!(
            (sig.trust_chain.supported, sig.trust_chain.required),
            (0b0110, 0b0100)
        );
        assert_eq!(
            (sig.message_auth.supported, sig.message_auth.required),
            (0b0100, 0b0100)
        );
        let kx = kx.expect("key establishment info");
        assert_eq!(
            (kx.shared_secret.supported, kx.shared_secret.required),
            (0b0010, 0b0010)
        );
        assert_eq!(sym.supported_mask, 0b10, "AES256 only");
        // Without an allowed set the plugins' own masks are announced.
        let (sig, _, sym) = local_algorithm_infos(Some(masks), 256, None);
        assert_eq!(sig.expect("signature info").trust_chain.supported, 0b1111);
        assert_eq!(sym.supported_mask, 0b11);
    }

    /// DDS-Security 1.2 §9.4.2.5 Tables 34, 35 and §10.4.2.4 Table 67: the
    /// masks of `PID_PARTICIPANT_SECURITY_INFO` are those of the
    /// `ParticipantSecurityConfig` the AccessControl plugin gives (§9.4.2.9.22):
    /// the key revision and the pre-shared-key bits too, and the optional
    /// attributes with `allow_unauthenticated_participants` and
    /// `is_access_protected`. The PermissionsToken is the plugin's
    /// (§9.4.2.9.17), of the class `DDS:Access:Permissions:1.2`.
    #[cfg(feature = "security")]
    #[test]
    fn the_participant_security_info_is_the_config_of_the_access_control_plugin() {
        use zerodds_rtps::participant_security_info::{attrs, opt_attrs, plugin_attrs};
        use zerodds_security::authentication::{AuthenticationPlugin, IdentityHandle};
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>true</enable_join_access_control><enable_key_revision>true</enable_key_revision><discovery_protection_kind>ENCRYPT</discovery_protection_kind><liveliness_protection_kind>SIGN_WITH_ORIGIN_AUTHENTICATION</liveliness_protection_kind><rtps_protection_kind>ENCRYPT</rtps_protection_kind><rtps_psk_protection_kind>ENCRYPT</rtps_psk_protection_kind><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        const PERMISSIONS: &str = r#"<dds><permissions><grant name="g"><subject_name>CN=a</subject_name><validity><not_before>1970-01-01T00:00:00</not_before><not_after>2100-01-01T00:00:00</not_after></validity><allow_rule><domains><id>0</id></domains><publish><topics><topic>*</topic></topics></publish></allow_rule><default>DENY</default></grant></permissions></dds>"#;
        let rt = build_runtime_with(GOV, std::sync::Arc::new(CapturingLogger::default()));
        rt.config
            .security
            .as_ref()
            .expect("gate")
            .set_permissions(
                zerodds_security_permissions::parse_permissions_xml(PERMISSIONS).unwrap(),
            )
            .expect("arm");
        let auth: Arc<Mutex<dyn AuthenticationPlugin>> = Arc::new(Mutex::new(FakeAuth));
        rt.enable_security_builtins_with_auth(VendorId::ZERODDS, auth, IdentityHandle(1));
        let beacon = rt.spdp_beacon.lock().unwrap().data.clone();
        let info = beacon.participant_security_info.expect("the info");
        assert_eq!(
            info.participant_security_attributes,
            attrs::IS_VALID
                | attrs::IS_RTPS_AXK_PROTECTED
                | attrs::IS_DISCOVERY_PROTECTED
                | attrs::IS_LIVELINESS_PROTECTED
                | attrs::IS_KEY_REVISION_ENABLED
                | attrs::IS_RTPS_PSK_PROTECTED
        );
        assert_eq!(
            info.plugin_participant_security_attributes,
            plugin_attrs::IS_VALID
                | plugin_attrs::IS_RTPS_AXK_ENCRYPTED
                | plugin_attrs::IS_DISCOVERY_ENCRYPTED
                | plugin_attrs::IS_LIVELINESS_ORIGIN_AUTHENTICATED
                | plugin_attrs::IS_RTPS_PSK_ENCRYPTED
        );
        assert_eq!(
            (
                info.optional_attributes.is_set,
                info.optional_attributes.value
            ),
            (
                opt_attrs::ALLOW_UNAUTHENTICATED_PARTICIPANTS | opt_attrs::IS_ACCESS_PROTECTED,
                opt_attrs::IS_ACCESS_PROTECTED
            )
        );
        let token = zerodds_security::token::DataHolder::from_cdr_le(
            &beacon.permissions_token.expect("the token"),
        )
        .expect("a DataHolder");
        assert_eq!(token.class_id, "DDS:Access:Permissions:1.2");
    }

    /// FU2 Gap 7c/d: `enable_security_builtins_with_auth` announces the
    /// local `identity_token` in the SPDP beacon (+ stateless/volatile bits),
    /// and an incoming peer beacon WITH an `identity_token` kicks off the
    /// Auth-Handshake an (Discovery-Trigger).
    #[cfg(feature = "security")]
    #[test]
    fn spdp_beacon_announces_identity_token_and_discovery_triggers_handshake() {
        use zerodds_security::authentication::{AuthenticationPlugin, IdentityHandle};

        let local_prefix = GuidPrefix::from_bytes([0x41; 12]);
        let rt = DcpsRuntime::start(41, local_prefix, RuntimeConfig::default()).expect("start");
        let auth: Arc<Mutex<dyn AuthenticationPlugin>> = Arc::new(Mutex::new(FakeAuth));
        let stack =
            rt.enable_security_builtins_with_auth(VendorId::ZERODDS, auth, IdentityHandle(1));

        // Gap 7c: the beacon now announces identity_token + secure bits.
        let beacon_bytes = rt.spdp_beacon.lock().unwrap().serialize().unwrap();
        let parsed = zerodds_discovery::spdp::SpdpReader::new()
            .parse_datagram(&beacon_bytes)
            .unwrap();
        assert!(
            parsed.data.identity_token.is_some(),
            "the beacon must announce PID_IDENTITY_TOKEN"
        );
        // Cross-vendor: secure vendors validate a remote only when
        // SPDP carries **both** tokens. Without PID_PERMISSIONS_TOKEN they treat
        // cyclone treats us as non-secure and never starts validate_remote_identity.
        assert!(
            parsed.data.permissions_token.is_some(),
            "the beacon must announce PID_PERMISSIONS_TOKEN (cross-vendor mandatory)"
        );
        assert_ne!(
            parsed.data.builtin_endpoint_set & endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER,
            0,
            "the beacon must announce the stateless-auth bit"
        );
        // §9.3.2.2: the IdentityStatusToken, from get_identity_status_token,
        // is "included in the DCPSParticipantSecure builtin Topic" — not in
        // DCPSParticipants.
        assert!(
            parsed.data.identity_status_token.is_none(),
            "the plain SPDP carries no IdentityStatusToken"
        );
        let secure_bytes = rt.spdp_beacon.lock().unwrap().serialize_secure().unwrap();
        let secure = zerodds_discovery::spdp::SpdpReader::new()
            .parse_datagram(&secure_bytes)
            .unwrap();
        let status = secure
            .data
            .identity_status_token
            .as_deref()
            .expect("DCPSParticipantsSecure carries the IdentityStatusToken");
        assert_eq!(
            zerodds_security::token::DataHolder::from_cdr_le(status)
                .unwrap()
                .class_id,
            "FAKE:Auth:Status:1.0"
        );

        // Gap 7d: peer beacon WITH identity_token + stateless bits → the
        // discovery path kicks off begin_handshake_with.
        let remote = GuidPrefix::from_bytes([0x99; 12]);
        let flags = endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER
            | endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_READER;
        let peer_beacon =
            make_secure_beacon_with_identity_token(remote, flags, alloc::vec![0x11, 0x22, 0x33]);
        handle_spdp_datagram(&rt, &peer_beacon, None);

        // Proof that the discovery trigger fired: the peer is now
        // registered in the stack's handshake state. (The earlier length
        // probe via a repeated begin_handshake_with no longer applies since the resend path
        // resends as the initiator on a repeated call.)
        let started = {
            let s = stack.lock().unwrap();
            s.handshake_peer_count()
        };
        assert_eq!(
            started, 1,
            "the discovery trigger must have started the handshake (peer registered)"
        );

        rt.shutdown();
    }

    /// FU2 S3: two secure runtimes in the same process MUST find each other via
    /// in-process participant discovery and kick off the auth handshake
    /// — WITHOUT a single multicast beacon. That was exactly missing:
    /// `inproc_inject_publication`/`_subscription` inject only SEDP, the
    /// SPDP participant discovery (identity_token + `begin_handshake_with`)
    /// ran exclusively over the flaky multicast path.
    #[cfg(feature = "security")]
    #[test]
    fn inproc_participant_discovery_triggers_handshake_without_multicast() {
        use zerodds_security::authentication::{AuthenticationPlugin, IdentityHandle};

        let a_prefix = GuidPrefix::from_bytes([0x4A; 12]);
        let b_prefix = GuidPrefix::from_bytes([0x4B; 12]);
        let rt_a = DcpsRuntime::start(47, a_prefix, RuntimeConfig::default()).expect("start a");
        let rt_b = DcpsRuntime::start(47, b_prefix, RuntimeConfig::default()).expect("start b");
        let auth_a: Arc<Mutex<dyn AuthenticationPlugin>> = Arc::new(Mutex::new(FakeAuth));
        let auth_b: Arc<Mutex<dyn AuthenticationPlugin>> = Arc::new(Mutex::new(FakeAuth));
        let stack_a =
            rt_a.enable_security_builtins_with_auth(VendorId::ZERODDS, auth_a, IdentityHandle(1));
        let stack_b =
            rt_b.enable_security_builtins_with_auth(VendorId::ZERODDS, auth_b, IdentityHandle(1));

        // KEIN handle_spdp_datagram / Multicast — rein in-process.
        let a_peers = stack_a.lock().unwrap().handshake_peer_count();
        let b_peers = stack_b.lock().unwrap().handshake_peer_count();
        assert!(
            a_peers >= 1,
            "A must have discovered B in-process + started the handshake (got {a_peers})"
        );
        assert!(
            b_peers >= 1,
            "B must have discovered A in-process + started the handshake (got {b_peers})"
        );

        rt_a.shutdown();
        rt_b.shutdown();
    }

    /// DDSI-RTPS 2.5 §8.5.3.2: a participant this runtime learned in-process
    /// is held under the lease it announces, as one learned from its SPDP,
    /// and its periodic announcement renews it. The in-process path stored it
    /// without an observation time, so its lease never ran out: a participant
    /// of the process that ended without notice stayed discovered and its
    /// writers matched (measured: `liveliness_qos::linux::
    /// a_writer_lost_with_its_participant_counts_as_not_alive`, 7 of 100 runs
    /// on a loaded host). Here A announces nothing and B sends no multicast,
    /// so A knows B from the in-process path alone.
    #[test]
    fn a_participant_learned_in_process_lives_and_ends_with_its_lease() {
        let lease = zerodds_test_domains::lease_domain();
        let a = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x5A; 12]),
            RuntimeConfig {
                discoverable: false,
                ..RuntimeConfig::default()
            },
        )
        .expect("a");
        let b = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0x5B; 12]),
            RuntimeConfig {
                participant_lease_duration: Duration::from_millis(800),
                spdp_period: Duration::from_millis(100),
                spdp_multicast_send: false,
                ..RuntimeConfig::default()
            },
        )
        .expect("b");
        b.register_user_writer(UserWriterConfig {
            topic_name: "InProcessLease".into(),
            type_name: "zerodds::RawBytes".into(),
            ..Default::default()
        })
        .expect("writer");
        let knows_b = |a: &DcpsRuntime| {
            a.discovered_participants()
                .iter()
                .any(|p| p.data.guid.prefix == GuidPrefix::from_bytes([0x5B; 12]))
        };
        assert!(knows_b(&a), "a learned b in-process");
        // More than two leases: b's announcements renew it at a.
        thread::sleep(Duration::from_secs(2));
        assert!(knows_b(&a), "b's lease ran out at a while b was announcing");
        b.__vanish();
        let deadline = Instant::now() + Duration::from_secs(3);
        while knows_b(&a) && Instant::now() < deadline {
            thread::sleep(Duration::from_millis(20));
        }
        assert!(
            !knows_b(&a),
            "b's lease did not run out at a after b vanished"
        );
        a.shutdown();
    }

    /// A participant GUID prefix bound to the identity in `cert_pem`
    /// (DDS-Security 1.2 §10.3.3 Table 59) for the candidate `seed`.
    #[cfg(feature = "security")]
    fn bound_prefix(cert_pem: &[u8], seed: u8) -> GuidPrefix {
        let der = zerodds_security_pki::first_cert_der(cert_pem).unwrap();
        GuidPrefix::from_bytes(
            zerodds_security_pki::adjust_participant_guid_prefix(&[seed; 16], &der).unwrap(),
        )
    }

    /// The identities of `mint_handshake_identities` as (A, B) with
    /// B's bound prefix the smaller one — B, the in-test stack, initiates
    /// (cyclone convention: the smaller GUID sends the request).
    #[cfg(feature = "security")]
    #[allow(clippy::type_complexity)]
    fn handshake_identities_b_smaller() -> (
        ((Vec<u8>, Vec<u8>), GuidPrefix),
        ((Vec<u8>, Vec<u8>), GuidPrefix),
    ) {
        let (mut a, mut b) = mint_handshake_identities();
        if bound_prefix(&b.0, 0x10).to_bytes() > bound_prefix(&a.0, 0x20).to_bytes() {
            core::mem::swap(&mut a, &mut b);
        }
        let a_prefix = bound_prefix(&a.0, 0x20);
        let b_prefix = bound_prefix(&b.0, 0x10);
        assert!(b_prefix.to_bytes() < a_prefix.to_bytes());
        ((a, a_prefix), (b, b_prefix))
    }

    /// The datagrams of `out` with a handshake message (`dds.sec.auth`),
    /// without the AuthRequestMessageToken that goes out ahead of them on
    /// discovery (DDS-Security 1.2 §9.3.2.11.3).
    #[cfg(feature = "security")]
    fn handshake_only(
        out: Vec<zerodds_rtps::message_builder::OutboundDatagram>,
    ) -> Vec<zerodds_rtps::message_builder::OutboundDatagram> {
        out.into_iter()
            .filter(|d| {
                zerodds_discovery::security::StatelessMessageReader::new(
                    GuidPrefix::from_bytes([0xEE; 12]),
                    VendorId::ZERODDS,
                )
                .handle_datagram(&d.bytes)
                .is_ok_and(|m| {
                    m.first().is_some_and(|m| {
                        m.message_class_id == zerodds_security::generic_message::class_id::AUTH
                    })
                })
            })
            .collect()
    }

    /// A `c.pdata`: PL_CDR_BE with PID_PARTICIPANT_GUID and PID_SENTINEL.
    #[cfg(feature = "security")]
    fn pdata_of(guid: [u8; 16]) -> Vec<u8> {
        let mut pdata = std::vec![0x00, 0x02, 0x00, 0x00, 0x00, 0x50, 0x00, 0x10];
        pdata.extend_from_slice(&guid);
        pdata.extend_from_slice(&[0x00, 0x01, 0x00, 0x00]);
        pdata
    }

    /// Mints a shared CA + two leaf identities (PEM) for the
    /// FU2-Handshake-e2e-Test.
    #[cfg(feature = "security")]
    #[allow(clippy::type_complexity)]
    fn mint_handshake_identities() -> ((Vec<u8>, Vec<u8>), (Vec<u8>, Vec<u8>)) {
        use rcgen::{CertificateParams, KeyPair};
        let mut ca_params =
            CertificateParams::new(alloc::vec![alloc::string::String::from("FU2 CA")]).unwrap();
        ca_params.is_ca = rcgen::IsCa::Ca(rcgen::BasicConstraints::Unconstrained);
        let ca_key = KeyPair::generate().unwrap();
        let ca_cert = ca_params.self_signed(&ca_key).unwrap();
        let ca_pem = ca_cert.pem().into_bytes();
        let mint = |name: &str| -> (Vec<u8>, Vec<u8>) {
            let mut p =
                CertificateParams::new(alloc::vec![alloc::string::String::from(name)]).unwrap();
            // The SubjectName, not only the alternative name: the bound GUID
            // prefix starts with its hash (DDS-Security 1.2 §10.3.3 Table
            // 59); with the default subject both identities had one head.
            let mut dn = rcgen::DistinguishedName::new();
            dn.push(rcgen::DnType::CommonName, name);
            p.distinguished_name = dn;
            p.is_ca = rcgen::IsCa::NoCa;
            let k = KeyPair::generate().unwrap();
            let c = p.signed_by(&k, &ca_cert, &ca_key).unwrap();
            (c.pem().into_bytes(), k.serialize_pem().into_bytes())
        };
        let alice = {
            let (cert, key) = mint("alice");
            (cert, key)
        };
        let bob = {
            let (cert, key) = mint("bob");
            (cert, key)
        };
        // attach ca_pem to both, so the caller has the trust anchor.
        (
            ([alice.0, b"\n".to_vec(), ca_pem.clone()].concat(), alice.1),
            ([bob.0, b"\n".to_vec(), ca_pem].concat(), bob.1),
        )
    }

    /// FU2 Gap 5 (e2e): a runtime replier (A) and an in-test initiator
    /// stack (B) complete a real PKI 3-round handshake via the dispatch path
    /// and BOTH derive the same SharedSecret.
    /// Verifies the dispatch wiring (`on_stateless_message` →
    /// reply/final → completion) in the real runtime context.
    #[cfg(feature = "security")]
    #[test]
    fn handshake_completes_through_runtime_dispatch_e2e() {
        use zerodds_discovery::security::SecurityBuiltinStack;
        use zerodds_security::authentication::AuthenticationPlugin;
        use zerodds_security_pki::{IdentityConfig, PkiAuthenticationPlugin};

        // cert_pem here contains Leaf || CA (mint_handshake_identities),
        // identity_ca_pem = the same bundle (CA is included).
        // A = Runtime (Replier, higher prefix). B = in-test Stack
        // (initiator, lower prefix) — cyclone convention: the smaller
        // GUID initiates. Both prefixes are bound to the identities.
        let (((a_cert, a_key), a_prefix), ((b_cert, b_key), b_prefix)) =
            handshake_identities_b_smaller();
        let a_guid = Guid::new(a_prefix, EntityId::PARTICIPANT).to_bytes();
        let b_guid = Guid::new(b_prefix, EntityId::PARTICIPANT).to_bytes();

        // --- A: runtime with a real PKI plugin ---
        let a_pki = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        let a_local = a_pki
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: a_cert.clone(),
                    identity_ca_pem: a_cert.clone(),
                    identity_key_pem: Some(a_key),
                },
                a_guid,
            )
            .unwrap();
        let a_token = a_pki.lock().unwrap().get_identity_token(a_local).unwrap();
        let rt = DcpsRuntime::start(42, a_prefix, RuntimeConfig::default()).expect("start");
        let a_auth: Arc<Mutex<dyn AuthenticationPlugin>> = a_pki.clone();
        let a_stack = rt.enable_security_builtins_with_auth(VendorId::ZERODDS, a_auth, a_local);

        // --- B: in-test initiator stack with a real PKI plugin ---
        let b_pki = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        let b_local = b_pki
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: b_cert.clone(),
                    identity_ca_pem: b_cert.clone(),
                    identity_key_pem: Some(b_key),
                },
                b_guid,
            )
            .unwrap();
        let b_token = b_pki.lock().unwrap().get_identity_token(b_local).unwrap();
        let b_auth: Arc<Mutex<dyn AuthenticationPlugin>> = b_pki.clone();
        let mut b_stack =
            SecurityBuiltinStack::with_auth(b_prefix, VendorId::ZERODDS, b_auth, b_local, b_guid);
        b_stack.set_local_participant_data(pdata_of(b_guid));

        let stateless = endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER
            | endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_READER;

        // B discovers A (wired proxies) — via the parsed A beacon.
        let a_beacon = make_secure_beacon_with_identity_token(a_prefix, stateless, a_token.clone());
        let a_parsed = zerodds_discovery::spdp::SpdpReader::new()
            .parse_datagram(&a_beacon)
            .unwrap();
        b_stack.handle_remote_endpoints(&a_parsed);

        // A discovers B → the discovery trigger creates A's peer state (A is
        // the replier, sends nothing).
        let b_beacon = make_secure_beacon_with_identity_token(b_prefix, stateless, b_token);
        handle_spdp_datagram(&rt, &b_beacon, None);

        // B (initiator) starts → AUTH_REQUEST.
        let req = handshake_only(
            b_stack
                .begin_handshake_with(a_prefix, a_guid, &a_token)
                .unwrap(),
        );
        assert_eq!(req.len(), 1, "B sends AUTH_REQUEST");

        // Pump: REQUEST → A.dispatch → REPLY.
        let reply = dispatch_security_builtin_datagram(&rt, &req[0].bytes, Duration::from_secs(1));
        assert_eq!(reply.len(), 1, "A (replier) answers with AUTH reply");

        // REPLY → B verarbeitet → FINAL (+ B erreicht Complete).
        let b_msgs = b_stack
            .stateless_reader
            .handle_datagram(&reply[0].bytes)
            .unwrap();
        assert_eq!(b_msgs.len(), 1);
        let (final_dgs, _b_complete) = b_stack.on_stateless_message(a_prefix, &b_msgs[0]).unwrap();
        assert_eq!(final_dgs.len(), 1, "B sends AUTH-Final");

        // FINAL → A.dispatch → A erreicht Complete.
        let _ =
            dispatch_security_builtin_datagram(&rt, &final_dgs[0].bytes, Duration::from_secs(1));

        // Both sides must now have derived the same SharedSecret.
        let a_secret = {
            let s = a_stack.lock().unwrap();
            s.peer_secret(b_prefix)
                .expect("A must have authenticated B")
        };
        let b_secret = b_stack
            .peer_secret(a_prefix)
            .expect("B must have authenticated A");
        let a_bytes = a_pki
            .lock()
            .unwrap()
            .secret_bytes(a_secret)
            .unwrap()
            .to_vec();
        let b_bytes = b_pki
            .lock()
            .unwrap()
            .secret_bytes(b_secret)
            .unwrap()
            .to_vec();
        assert_eq!(a_bytes.len(), 32);
        assert_eq!(
            a_bytes, b_bytes,
            "runtime dispatch + in-test stack derive the same secret"
        );

        rt.shutdown();
    }

    /// DDS-Security 1.2 §9.3.2.12.2: a revoked identity ends the
    /// authentication of its participant: the plugin tells the listener of
    /// the stack, the tick takes the event, and the participant is
    /// unauthenticated and not authenticated again.
    #[cfg(feature = "security")]
    #[test]
    fn a_revoked_identity_ends_the_authentication_through_the_runtime_tick() {
        use zerodds_discovery::security::SecurityBuiltinStack;
        use zerodds_discovery::security::stack::{PeerAuthentication, UnauthenticatedReason};
        use zerodds_security::authentication::AuthenticationPlugin;
        use zerodds_security_pki::{IdentityConfig, PkiAuthenticationPlugin};

        let (((a_cert, a_key), a_prefix), ((b_cert, b_key), b_prefix)) =
            handshake_identities_b_smaller();
        let a_guid = Guid::new(a_prefix, EntityId::PARTICIPANT).to_bytes();
        let b_guid = Guid::new(b_prefix, EntityId::PARTICIPANT).to_bytes();
        let a_pki = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        let a_local = a_pki
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: a_cert.clone(),
                    identity_ca_pem: a_cert.clone(),
                    identity_key_pem: Some(a_key),
                },
                a_guid,
            )
            .unwrap();
        let a_token = a_pki.lock().unwrap().get_identity_token(a_local).unwrap();
        let rt = DcpsRuntime::start(43, a_prefix, RuntimeConfig::default()).expect("start");
        let a_auth: Arc<Mutex<dyn AuthenticationPlugin>> = a_pki.clone();
        let a_stack = rt.enable_security_builtins_with_auth(VendorId::ZERODDS, a_auth, a_local);

        let b_pki = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        let b_local = b_pki
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: b_cert.clone(),
                    identity_ca_pem: b_cert.clone(),
                    identity_key_pem: Some(b_key),
                },
                b_guid,
            )
            .unwrap();
        let b_token = b_pki.lock().unwrap().get_identity_token(b_local).unwrap();
        let b_auth: Arc<Mutex<dyn AuthenticationPlugin>> = b_pki.clone();
        let mut b_stack =
            SecurityBuiltinStack::with_auth(b_prefix, VendorId::ZERODDS, b_auth, b_local, b_guid);
        b_stack.set_local_participant_data(pdata_of(b_guid));
        let stateless = endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER
            | endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_READER;
        let a_beacon = make_secure_beacon_with_identity_token(a_prefix, stateless, a_token.clone());
        let a_parsed = zerodds_discovery::spdp::SpdpReader::new()
            .parse_datagram(&a_beacon)
            .unwrap();
        b_stack.handle_remote_endpoints(&a_parsed);
        let b_beacon = make_secure_beacon_with_identity_token(b_prefix, stateless, b_token);
        handle_spdp_datagram(&rt, &b_beacon, None);
        let req = handshake_only(
            b_stack
                .begin_handshake_with(a_prefix, a_guid, &a_token)
                .unwrap(),
        );
        let reply = dispatch_security_builtin_datagram(&rt, &req[0].bytes, Duration::from_secs(1));
        let b_msgs = b_stack
            .stateless_reader
            .handle_datagram(&reply[0].bytes)
            .unwrap();
        let (final_dgs, _) = b_stack.on_stateless_message(a_prefix, &b_msgs[0]).unwrap();
        let _ =
            dispatch_security_builtin_datagram(&rt, &final_dgs[0].bytes, Duration::from_secs(1));
        assert!(a_stack.lock().unwrap().is_authenticated(b_prefix));

        // The plugin of A revokes the identity of B.
        let b_identity = a_stack.lock().unwrap().peer_identity(b_prefix).unwrap();
        a_pki.lock().unwrap().revoke_identity(b_identity).unwrap();
        // The tick: the stack takes the event, the runtime ends the
        // communication.
        let now = Duration::from_secs(2);
        let _ = a_stack.lock().unwrap().poll_stateless(now).unwrap();
        process_authentication_events(&rt, &a_stack, now);
        {
            let s = a_stack.lock().unwrap();
            assert!(!s.is_authenticated(b_prefix));
            assert_eq!(
                s.authentication_status(b_prefix),
                PeerAuthentication::Unauthenticated(UnauthenticatedReason::Revoked)
            );
            assert!(s.peer_secret(b_prefix).is_none());
        }
        // B is not authenticated again while it is known.
        let again = a_stack
            .lock()
            .unwrap()
            .begin_handshake_with(b_prefix, b_guid, &a_token)
            .unwrap();
        assert!(again.is_empty());
        rt.shutdown();
    }

    /// A handshake request the replier refuses ends the authentication of
    /// that peer (DDS-Security 1.2 §8.3.2.9, `VALIDATION_FAILED`); the
    /// runtime records the failure and its reason. Here B's `c.pdata`
    /// names a GUID that is not derived from B's SubjectName (§10.3.3
    /// Table 59). The runtime dropped the error without a trace.
    #[cfg(feature = "security")]
    #[test]
    fn a_refused_handshake_request_is_recorded_with_its_reason() {
        use zerodds_discovery::security::SecurityBuiltinStack;
        use zerodds_foundation::observability::VecSink;
        use zerodds_security::authentication::AuthenticationPlugin;
        use zerodds_security_pki::{IdentityConfig, PkiAuthenticationPlugin};

        let (((a_cert, a_key), a_prefix), ((b_cert, b_key), b_prefix)) =
            handshake_identities_b_smaller();
        let a_guid = Guid::new(a_prefix, EntityId::PARTICIPANT).to_bytes();
        let b_guid = Guid::new(b_prefix, EntityId::PARTICIPANT).to_bytes();

        let a_pki = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        let a_local = a_pki
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: a_cert.clone(),
                    identity_ca_pem: a_cert.clone(),
                    identity_key_pem: Some(a_key),
                },
                a_guid,
            )
            .unwrap();
        let a_token = a_pki.lock().unwrap().get_identity_token(a_local).unwrap();
        let sink = Arc::new(VecSink::new());
        let config = RuntimeConfig {
            observability: sink.clone(),
            ..RuntimeConfig::default()
        };
        let rt = DcpsRuntime::start(42, a_prefix, config).expect("start");
        let a_auth: Arc<Mutex<dyn AuthenticationPlugin>> = a_pki.clone();
        let _a_stack = rt.enable_security_builtins_with_auth(VendorId::ZERODDS, a_auth, a_local);

        let b_pki = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        // A GUID whose head is not B's: its SubjectName hash is not in it.
        let mut squatted = b_guid;
        squatted[1] ^= 0xFF;
        let b_local = b_pki
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: b_cert.clone(),
                    identity_ca_pem: b_cert.clone(),
                    identity_key_pem: Some(b_key),
                },
                b_guid,
            )
            .unwrap();
        let b_auth: Arc<Mutex<dyn AuthenticationPlugin>> = b_pki.clone();
        let mut b_stack =
            SecurityBuiltinStack::with_auth(b_prefix, VendorId::ZERODDS, b_auth, b_local, b_guid);
        b_stack.set_local_participant_data(pdata_of(squatted));
        let stateless = endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER
            | endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_READER;
        let a_beacon = make_secure_beacon_with_identity_token(a_prefix, stateless, a_token.clone());
        let a_parsed = zerodds_discovery::spdp::SpdpReader::new()
            .parse_datagram(&a_beacon)
            .unwrap();
        b_stack.handle_remote_endpoints(&a_parsed);

        let req = handshake_only(
            b_stack
                .begin_handshake_with(a_prefix, a_guid, &a_token)
                .unwrap(),
        );
        assert_eq!(req.len(), 1, "B sends AUTH_REQUEST");
        let reply = dispatch_security_builtin_datagram(&rt, &req[0].bytes, Duration::from_secs(1));
        assert!(reply.is_empty(), "A refuses the request");

        let events = sink.snapshot();
        let failed: Vec<_> = events
            .iter()
            .filter(|e| e.name == "security.handshake.failed")
            .collect();
        assert_eq!(failed.len(), 1, "{events:?}");
        let reason = failed[0]
            .attrs
            .iter()
            .find(|a| a.key == "reason")
            .map(|a| a.value.clone())
            .unwrap_or_default();
        assert!(
            reason.contains("not derived from the SubjectName"),
            "{reason}"
        );
        rt.shutdown();
    }

    /// A secured runtime A with governance `gov` gets the SPDP of a peer B
    /// with SEDP and secure endpoints, then B's handshake. Returns which of
    /// B's DCPSPublications readers A's SEDP matched (regular, secure)
    /// after the SPDP and after the authentication.
    #[cfg(feature = "security")]
    fn sedp_matched_before_and_after_authentication(gov: &str) -> ((bool, bool), (bool, bool)) {
        sedp_matched_with_peer(gov, PeerKind::Trusted)
    }

    /// The peer of [`sedp_matched_with_peer`].
    #[cfg(feature = "security")]
    #[derive(Clone, Copy, PartialEq, Eq)]
    enum PeerKind {
        /// Secured, its identity issued by the CA of the runtime.
        Trusted,
        /// Secured, its identity issued by another CA: the authentication fails.
        Foreign,
        /// Not secured: no tokens, no secure endpoints.
        NoSecurity,
    }

    /// [`sedp_matched_before_and_after_authentication`] for a peer of `kind`.
    #[cfg(feature = "security")]
    fn sedp_matched_with_peer(gov: &str, kind: PeerKind) -> ((bool, bool), (bool, bool)) {
        use zerodds_discovery::security::SecurityBuiltinStack;
        use zerodds_security::authentication::{AuthenticationPlugin, SharedSecretProvider};
        use zerodds_security_crypto::{AesGcmCryptoPlugin, Suite};
        use zerodds_security_pki::{IdentityConfig, PkiAuthenticationPlugin};
        use zerodds_security_runtime::SharedSecurityGate;

        struct PkiProvider(Arc<Mutex<PkiAuthenticationPlugin>>);
        impl SharedSecretProvider for PkiProvider {
            fn get_shared_secret(
                &self,
                h: zerodds_security::authentication::SharedSecretHandle,
            ) -> Option<Vec<u8>> {
                self.0.lock().ok()?.get_shared_secret(h)
            }
        }
        let (((a_cert, a_key), a_prefix), ((mut b_cert, mut b_key), mut b_prefix)) =
            handshake_identities_b_smaller();
        if kind == PeerKind::Foreign {
            let (_, (foreign_cert, foreign_key)) = mint_handshake_identities();
            b_prefix = bound_prefix(&foreign_cert, 0x10);
            b_cert = foreign_cert;
            b_key = foreign_key;
        }
        let a_guid = Guid::new(a_prefix, EntityId::PARTICIPANT).to_bytes();
        let b_guid = Guid::new(b_prefix, EntityId::PARTICIPANT).to_bytes();

        let pki_a = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        let a_local = pki_a
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: a_cert.clone(),
                    identity_ca_pem: a_cert.clone(),
                    identity_key_pem: Some(a_key),
                },
                a_guid,
            )
            .unwrap();
        let a_token = pki_a.lock().unwrap().get_identity_token(a_local).unwrap();
        let gate = SharedSecurityGate::new(
            0,
            zerodds_security_permissions::parse_governance_xml(gov).unwrap(),
            Box::new(AesGcmCryptoPlugin::with_secret_provider(
                Suite::Aes128Gcm,
                Arc::new(PkiProvider(pki_a.clone())) as Arc<dyn SharedSecretProvider>,
            )),
        );
        let lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(
            lease.id(),
            a_prefix,
            RuntimeConfig {
                security: Some(Arc::new(gate)),
                security_guid_prefix: Some(a_prefix),
                spdp_multicast_send: false,
                ..RuntimeConfig::default()
            },
        )
        .expect("start");
        let a_auth: Arc<Mutex<dyn AuthenticationPlugin>> = pki_a.clone();
        let _a_stack = rt.enable_security_builtins_with_auth(VendorId::ZERODDS, a_auth, a_local);

        let pki_b = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        let b_local = pki_b
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: b_cert.clone(),
                    identity_ca_pem: b_cert.clone(),
                    identity_key_pem: Some(b_key),
                },
                b_guid,
            )
            .unwrap();
        let b_token = pki_b.lock().unwrap().get_identity_token(b_local).unwrap();
        let b_auth: Arc<Mutex<dyn AuthenticationPlugin>> = pki_b.clone();
        let mut b_stack =
            SecurityBuiltinStack::with_auth(b_prefix, VendorId::ZERODDS, b_auth, b_local, b_guid);
        b_stack.set_local_participant_data(pdata_of(b_guid));
        let stateless = endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER
            | endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_READER;
        let a_beacon = make_secure_beacon_with_identity_token(a_prefix, stateless, a_token.clone());
        b_stack.handle_remote_endpoints(
            &zerodds_discovery::spdp::SpdpReader::new()
                .parse_datagram(&a_beacon)
                .unwrap(),
        );
        let b_flags = stateless
            | endpoint_flag::PARTICIPANT_VOLATILE_MESSAGE_SECURE_WRITER
            | endpoint_flag::PARTICIPANT_VOLATILE_MESSAGE_SECURE_READER
            | endpoint_flag::PUBLICATIONS_ANNOUNCER
            | endpoint_flag::PUBLICATIONS_DETECTOR
            | endpoint_flag::PUBLICATIONS_SECURE_WRITER
            | endpoint_flag::PUBLICATIONS_SECURE_READER;
        let b_beacon = if kind == PeerKind::NoSecurity {
            make_remote_spdp_beacon_with_flags(
                b_prefix,
                endpoint_flag::PUBLICATIONS_ANNOUNCER | endpoint_flag::PUBLICATIONS_DETECTOR,
            )
        } else {
            make_secure_beacon_with_identity_token(b_prefix, b_flags, b_token)
        };
        handle_spdp_datagram(&rt, &b_beacon, None);
        let matched = |rt: &DcpsRuntime| {
            rt.sedp
                .lock()
                .unwrap()
                .publications_readers_matched(b_prefix)
        };
        let before = matched(&rt);

        // The authentication does not happen (a participant without security),
        // or fails (an identity of another CA): nothing completes.
        let outcome = (|| {
            if kind == PeerKind::NoSecurity {
                return None;
            }
            let req = handshake_only(
                b_stack
                    .begin_handshake_with(a_prefix, a_guid, &a_token)
                    .ok()?,
            );
            let reply = handshake_only(dispatch_security_builtin_datagram(
                &rt,
                req.first()?.bytes.as_slice(),
                Duration::from_secs(1),
            ));
            let m = b_stack
                .stateless_reader
                .handle_datagram(&reply.first()?.bytes)
                .ok()?;
            let (fin, _) = b_stack.on_stateless_message(a_prefix, m.first()?).ok()?;
            Some(dispatch_security_builtin_datagram(
                &rt,
                &fin.first()?.bytes,
                Duration::from_secs(1),
            ))
        })();
        assert_eq!(
            outcome.is_some(),
            kind == PeerKind::Trusted,
            "only the trusted identity completes the authentication"
        );
        let after = matched(&rt);
        rt.shutdown();
        (before, after)
    }

    /// DDS-Security 1.2 §9.8.3.2: with `allow_unauthenticated_participants`
    /// FALSE a participant that is to authenticate is matched with the
    /// ParticipantStatelessMessage endpoints only, and with all its builtin
    /// endpoints once it authenticated. The SEDP endpoints were matched by
    /// the SPDP announcement, before any authentication.
    #[cfg(feature = "security")]
    #[test]
    fn the_sedp_of_a_peer_is_matched_once_it_authenticated() {
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><enable_join_access_control>false</enable_join_access_control><allow_unauthenticated_participants>FALSE</allow_unauthenticated_participants><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let (before, after) = sedp_matched_before_and_after_authentication(GOV);
        assert_eq!(
            before,
            (false, false),
            "nothing of SEDP before the handshake"
        );
        assert_eq!(after, (true, true), "all of SEDP after it");
    }

    /// §9.8.3.1: with `allow_unauthenticated_participants` TRUE an
    /// unauthenticated participant is matched with the regular builtin
    /// endpoints only; the secure ones follow its authentication.
    #[cfg(feature = "security")]
    #[test]
    fn an_unauthenticated_peer_gets_the_regular_sedp_only() {
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><enable_join_access_control>false</enable_join_access_control><allow_unauthenticated_participants>TRUE</allow_unauthenticated_participants><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let (before, after) = sedp_matched_before_and_after_authentication(GOV);
        assert_eq!(before, (true, false), "the regular SEDP only");
        assert_eq!(after, (true, true));
    }

    #[cfg(feature = "security")]
    const GOV_UNAUTH: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><enable_join_access_control>false</enable_join_access_control><allow_unauthenticated_participants>TRUE</allow_unauthenticated_participants><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
    #[cfg(feature = "security")]
    const GOV_AUTH_ONLY: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><enable_join_access_control>false</enable_join_access_control><allow_unauthenticated_participants>FALSE</allow_unauthenticated_participants><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;

    /// DDS-Security 1.2 §9.8.3.1: with `allow_unauthenticated_participants`
    /// TRUE a discovered participant that does not implement DDS Security is
    /// "matched without the DomainParticipant attempting to authenticate
    /// [it] and [...] treated as 'Unauthenticated'": the regular builtin
    /// endpoints (DCPSPublications here) and not the secure ones. One that
    /// implements DDS Security and fails the authentication is matched and
    /// treated as unauthenticated as well: it has the regular endpoints, and
    /// the secure ones are not matched.
    #[cfg(feature = "security")]
    #[test]
    fn unauthenticated_participants_get_the_regular_builtin_endpoints_only() {
        assert_eq!(
            sedp_matched_with_peer(GOV_UNAUTH, PeerKind::NoSecurity),
            ((true, false), (true, false)),
            "a participant without DDS Security"
        );
        assert_eq!(
            sedp_matched_with_peer(GOV_UNAUTH, PeerKind::Foreign),
            ((true, false), (true, false)),
            "a participant whose authentication fails"
        );
    }

    /// DDS-Security 1.2 §9.8.3.2: with `allow_unauthenticated_participants`
    /// FALSE a participant that does not implement DDS Security "shall be
    /// rejected without the DomainParticipant attempting to authenticate
    /// [it]", and one that fails the authentication "shall be rejected": none
    /// of its builtin endpoints but the ParticipantStatelessMessage ones is
    /// matched, before and after the attempt.
    #[cfg(feature = "security")]
    #[test]
    fn unauthenticated_participants_are_rejected_where_they_are_not_allowed() {
        assert_eq!(
            sedp_matched_with_peer(GOV_AUTH_ONLY, PeerKind::NoSecurity),
            ((false, false), (false, false)),
            "a participant without DDS Security"
        );
        assert_eq!(
            sedp_matched_with_peer(GOV_AUTH_ONLY, PeerKind::Foreign),
            ((false, false), (false, false)),
            "a participant whose authentication fails"
        );
    }

    /// DDS-Security 1.2 §9.8.7: "Local DomainParticipant will not perform any
    /// further participant AccessControl validation with unauthenticated
    /// participants (i.e., validate_remote_permissions and
    /// check_remote_participant will not be called)." The domain is access
    /// protected and allows unauthenticated participants; a participant
    /// without security joins it, is neither refused nor ignored for want of
    /// permissions, and its endpoints stay matched.
    #[cfg(feature = "security")]
    #[test]
    fn an_unauthenticated_participant_is_not_checked_for_permissions() {
        use zerodds_security::authentication::AuthenticationPlugin;
        use zerodds_security::mock::MockAuthenticationPlugin;
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>TRUE</allow_unauthenticated_participants><enable_join_access_control>TRUE</enable_join_access_control><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let sink = Arc::new(zerodds_foundation::observability::VecSink::new());
        let rt = build_runtime_with_sink(
            GOV,
            std::sync::Arc::new(CapturingLogger::default()),
            sink.clone(),
        );
        assert!(
            rt.config
                .security
                .as_ref()
                .unwrap()
                .is_access_protected()
                .unwrap()
        );
        let auth: Arc<Mutex<dyn AuthenticationPlugin>> =
            Arc::new(Mutex::new(MockAuthenticationPlugin::new()));
        let local = auth
            .lock()
            .unwrap()
            .validate_local_identity(
                0,
                &zerodds_security::properties::PropertyList::new(),
                [0xE7; 16],
            )
            .unwrap()
            .identity;
        rt.enable_security_builtins_with_auth(VendorId::ZERODDS, auth, local);
        let peer = GuidPrefix::from_bytes([0x72; 12]);
        handle_spdp_datagram(
            &rt,
            &make_remote_spdp_beacon_with_flags(
                peer,
                endpoint_flag::PUBLICATIONS_ANNOUNCER | endpoint_flag::PUBLICATIONS_DETECTOR,
            ),
            None,
        );
        assert_eq!(builtin_match(&rt, peer), BuiltinMatch::Regular);
        assert!(
            rt.discovered_participants()
                .iter()
                .any(|p| p.sender_prefix == peer),
            "the unauthenticated participant is discovered"
        );
        assert!(
            sink.snapshot()
                .iter()
                .all(|e| e.name != "security.remote_permissions.refused"),
            "no permissions check was made for it"
        );
    }

    /// DDS-Security 1.2 §9.8.8.1: with `allow_unauthenticated_participants`
    /// TRUE the endpoints of a participant that did not authenticate are
    /// matched on topics that are neither read nor write protected, "without
    /// checking with the AccessControl plugin"; local endpoints of a topic
    /// with `is_read_protected` or `is_write_protected` are rejected ("do not
    /// try to match"), whichever of the two it is.
    #[cfg(feature = "security")]
    #[test]
    fn a_participant_that_is_not_authenticated_gets_no_endpoint_on_a_protected_topic() {
        use zerodds_security::authentication::AuthenticationPlugin;
        use zerodds_security::mock::MockAuthenticationPlugin;
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>TRUE</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control><topic_access_rules><topic_rule><topic_expression>Guarded*</topic_expression><enable_read_access_control>TRUE</enable_read_access_control><enable_write_access_control>TRUE</enable_write_access_control></topic_rule><topic_rule><topic_expression>ReadGuarded*</topic_expression><enable_read_access_control>TRUE</enable_read_access_control><enable_write_access_control>FALSE</enable_write_access_control></topic_rule><topic_rule><topic_expression>*</topic_expression><enable_read_access_control>FALSE</enable_read_access_control><enable_write_access_control>FALSE</enable_write_access_control></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let sink = Arc::new(zerodds_foundation::observability::VecSink::new());
        let rt = build_runtime_with_sink(
            GOV,
            std::sync::Arc::new(CapturingLogger::default()),
            sink.clone(),
        );
        rt.config
            .security
            .as_ref()
            .unwrap()
            .set_permissions(
                zerodds_security_permissions::parse_permissions_xml(
                    r#"<dds><permissions><grant name="g">
                     <subject_name>/C=DE/CN=T</subject_name><validity><not_before>1970-01-01T00:00:00</not_before><not_after>2100-01-01T00:00:00</not_after></validity>
                     <allow_rule><domains><id>0</id></domains>
                       <publish><topics><topic>Guarded*</topic><topic>ReadGuarded*</topic><topic>Open*</topic></topics></publish>
                       <subscribe><topics><topic>Guarded*</topic><topic>ReadGuarded*</topic><topic>Open*</topic></topics></subscribe>
                     </allow_rule>
                     <default>DENY</default>
                   </grant></permissions></dds>"#,
                )
                .unwrap(),
            )
            .unwrap();
        let auth: Arc<Mutex<dyn AuthenticationPlugin>> =
            Arc::new(Mutex::new(MockAuthenticationPlugin::new()));
        let local = auth
            .lock()
            .unwrap()
            .validate_local_identity(
                0,
                &zerodds_security::properties::PropertyList::new(),
                [0xE7; 16],
            )
            .unwrap()
            .identity;
        rt.enable_security_builtins_with_auth(VendorId::ZERODDS, auth, local);

        // A participant without security is discovered and gets the regular
        // builtin endpoints.
        let peer = GuidPrefix::from_bytes([0x71; 12]);
        handle_spdp_datagram(
            &rt,
            &make_remote_spdp_beacon_with_flags(
                peer,
                endpoint_flag::PUBLICATIONS_ANNOUNCER
                    | endpoint_flag::PUBLICATIONS_DETECTOR
                    | endpoint_flag::SUBSCRIPTIONS_ANNOUNCER
                    | endpoint_flag::SUBSCRIPTIONS_DETECTOR,
            ),
            None,
        );
        assert_eq!(builtin_match(&rt, peer), BuiltinMatch::Regular);

        // The peer's own SEDP stack announces its endpoints over the plain
        // SEDP writers; the datagrams go through the runtime's metatraffic
        // path, as they would from the wire.
        let mut peer_sedp = zerodds_discovery::sedp::SedpStack::new(peer, VendorId::ZERODDS);
        let local_dp = DiscoveredParticipant {
            sender_prefix: rt.guid_prefix,
            sender_vendor: VendorId::ZERODDS,
            data: rt.spdp_beacon.lock().unwrap().data.clone(),
        };
        peer_sedp.on_participant_discovered(&local_dp);
        let source = Locator::udp_v4([127, 0, 0, 99], 7501);
        let mut next_key = 0u8;
        let deliver = |datagrams: Vec<zerodds_rtps::message_builder::OutboundDatagram>| {
            assert!(!datagrams.is_empty(), "the peer's SEDP produced a datagram");
            for dg in datagrams {
                dispatch_metatraffic_datagram(&rt, &dg.bytes, &source, rt.start_instant.elapsed());
            }
        };
        let mut matched_writer = |topic: &str| {
            let writer = rt
                .register_user_writer(UserWriterConfig {
                    topic_name: topic.into(),
                    type_name: "zerodds::RawBytes".into(),
                    reliable: false,
                    ..Default::default()
                })
                .expect("local writer");
            next_key += 1;
            let remote_reader = build_subscription_data(
                peer,
                EntityId::user_reader_with_key([0, 0, next_key]),
                &UserReaderConfig {
                    topic_name: topic.into(),
                    type_name: "zerodds::RawBytes".into(),
                    reliable: false,
                    ..Default::default()
                },
                &[0, 2],
                &[Locator::udp_v4([127, 0, 0, 99], 7500)],
            );
            deliver(peer_sedp.announce_subscription(&remote_reader).unwrap());
            rt.user_writer_matched_count(writer)
        };
        assert_eq!(matched_writer("GuardedT"), 0, "read and write protected");
        assert_eq!(
            matched_writer("ReadGuardedT"),
            0,
            "read protected, write not: the topic is protected all the same"
        );
        let open_writer = matched_writer("OpenT");
        assert_eq!(
            open_writer,
            1,
            "neither: matched without an access control check; events: {:?}",
            sink.snapshot()
                .iter()
                .map(|e| (
                    e.name,
                    e.attrs.iter().map(|a| a.value.clone()).collect::<Vec<_>>()
                ))
                .collect::<Vec<_>>()
        );

        let mut matched_reader = |topic: &str| {
            let (reader, _rx) = rt
                .register_user_reader(UserReaderConfig {
                    topic_name: topic.into(),
                    type_name: "zerodds::RawBytes".into(),
                    reliable: false,
                    ..Default::default()
                })
                .expect("local reader");
            next_key += 1;
            let remote_writer = build_publication_data(
                peer,
                EntityId::user_writer_with_key([0, 0, next_key]),
                &UserWriterConfig {
                    topic_name: topic.into(),
                    type_name: "zerodds::RawBytes".into(),
                    reliable: false,
                    ..Default::default()
                },
                &[0, 2],
                &[Locator::udp_v4([127, 0, 0, 99], 7500)],
            );
            deliver(peer_sedp.announce_publication(&remote_writer).unwrap());
            rt.user_reader_matched_count(reader)
        };
        assert_eq!(matched_reader("GuardedU"), 0);
        assert_eq!(matched_reader("ReadGuardedU"), 0);
        assert_eq!(matched_reader("OpenU"), 1);
    }

    /// DDS-Security 1.2 §9.8.8.1 and §9.8.8.2 with an AccessControl plugin of
    /// the application, whose TopicSecurityConfig says what is protected: the
    /// endpoints of a participant that did not authenticate are matched on a
    /// topic that is not read or write protected without asking the plugin,
    /// and not matched on a protected one; the endpoints of an authenticated
    /// participant are asked of the plugin
    /// (`check_remote_datareader`, `check_remote_datawriter`) with the topic
    /// and the partitions, and matched only where the plugin permits.
    #[cfg(feature = "security")]
    #[test]
    fn the_plugin_is_asked_about_the_endpoints_of_authenticated_participants_only() {
        use zerodds_security::access_control::PermissionsHandle;
        use zerodds_security::authentication::{
            AuthenticationPlugin, IdentityHandle, SharedSecretHandle,
        };
        use zerodds_security::mock::{MockAccessControlPlugin, MockAuthenticationPlugin};
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>TRUE</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let sink = Arc::new(zerodds_foundation::observability::VecSink::new());
        let rt = build_runtime_with_sink(
            GOV,
            std::sync::Arc::new(CapturingLogger::default()),
            sink.clone(),
        );
        // The plugin protects the topics `Guarded*` and `Denied` and refuses
        // the remote endpoints on `Denied`.
        let (plugin, calls) = MockAccessControlPlugin::deciding(|call| {
            !((call.operation == "check_remote_datareader"
                && call.topic.as_deref() == Some("Denied"))
                || (call.operation == "check_remote_topic"
                    && call.topic.as_deref() == Some("TopicDenied")))
        });
        let plugin = plugin
            .with_participant_config(|config| config.allow_unauthenticated_participants = true)
            .with_topic_config(|topic, config| {
                let protected = topic.starts_with("Guarded") || topic == "Denied";
                config.is_read_protected = protected;
                config.is_write_protected = protected;
            });
        let gate = rt.config.security.as_ref().unwrap();
        gate.set_access_control(Box::new(plugin), PermissionsHandle(7))
            .unwrap();
        let auth: Arc<Mutex<dyn AuthenticationPlugin>> =
            Arc::new(Mutex::new(MockAuthenticationPlugin::new()));
        let local = auth
            .lock()
            .unwrap()
            .validate_local_identity(
                0,
                &zerodds_security::properties::PropertyList::new(),
                [0xE7; 16],
            )
            .unwrap()
            .identity;
        rt.enable_security_builtins_with_auth(VendorId::ZERODDS, auth, local);

        let flags = endpoint_flag::PUBLICATIONS_ANNOUNCER
            | endpoint_flag::PUBLICATIONS_DETECTOR
            | endpoint_flag::SUBSCRIPTIONS_ANNOUNCER
            | endpoint_flag::SUBSCRIPTIONS_DETECTOR;
        let unauthenticated = GuidPrefix::from_bytes([0x71; 12]);
        let authenticated = GuidPrefix::from_bytes([0x72; 12]);
        for peer in [unauthenticated, authenticated] {
            handle_spdp_datagram(&rt, &make_remote_spdp_beacon_with_flags(peer, flags), None);
        }
        gate.register_remote_by_guid_from_secret(
            authenticated.0,
            IdentityHandle(2),
            SharedSecretHandle(1),
        )
        .expect("the peer authenticated");

        let local_dp = DiscoveredParticipant {
            sender_prefix: rt.guid_prefix,
            sender_vendor: VendorId::ZERODDS,
            data: rt.spdp_beacon.lock().unwrap().data.clone(),
        };
        let source = Locator::udp_v4([127, 0, 0, 99], 7501);
        let mut next_key = 0u8;
        // One SEDP stack per peer: its writer numbers its samples on.
        let mut peers: std::collections::BTreeMap<[u8; 12], zerodds_discovery::sedp::SedpStack> =
            std::collections::BTreeMap::new();
        let mut matched_writer = |peer: GuidPrefix, topic: &str| {
            let peer_sedp = peers.entry(peer.0).or_insert_with(|| {
                let mut stack = zerodds_discovery::sedp::SedpStack::new(peer, VendorId::ZERODDS);
                stack.on_participant_discovered(&local_dp);
                stack
            });
            let writer = rt
                .register_user_writer(UserWriterConfig {
                    topic_name: topic.into(),
                    type_name: "zerodds::RawBytes".into(),
                    reliable: false,
                    partition: vec!["p1".into()],
                    ..Default::default()
                })
                .expect("local writer");
            next_key += 1;
            let remote_reader = build_subscription_data(
                peer,
                EntityId::user_reader_with_key([0, 0, next_key]),
                &UserReaderConfig {
                    topic_name: topic.into(),
                    type_name: "zerodds::RawBytes".into(),
                    reliable: false,
                    partition: vec!["p1".into()],
                    ..Default::default()
                },
                &[0, 2],
                &[Locator::udp_v4([127, 0, 0, 99], 7500)],
            );
            for dg in peer_sedp.announce_subscription(&remote_reader).unwrap() {
                dispatch_metatraffic_datagram(&rt, &dg.bytes, &source, rt.start_instant.elapsed());
            }
            rt.user_writer_matched_count(writer)
        };
        let remote_checks = |topic: &str| {
            calls
                .lock()
                .unwrap()
                .iter()
                .filter(|c| {
                    c.operation == "check_remote_datareader" && c.topic.as_deref() == Some(topic)
                })
                .cloned()
                .collect::<Vec<_>>()
        };

        // Not authenticated: an open topic is matched, no check; a protected
        // one is not matched, no check.
        let open = matched_writer(unauthenticated, "Open1");
        assert_eq!(
            open,
            1,
            "events: {:?}",
            sink.snapshot()
                .iter()
                .map(|e| (
                    e.name,
                    e.attrs.iter().map(|a| a.value.clone()).collect::<Vec<_>>()
                ))
                .collect::<Vec<_>>()
        );
        assert_eq!(matched_writer(unauthenticated, "GuardedUnauth"), 0);
        assert!(remote_checks("Open1").is_empty(), "not asked for Open1");
        assert!(
            remote_checks("GuardedUnauth").is_empty(),
            "not asked for GuardedUnauth"
        );
        // Authenticated: the plugin is asked, with the partitions of the
        // remote reader, and decides.
        assert_eq!(matched_writer(authenticated, "GuardedAllowed"), 1);
        let asked = remote_checks("GuardedAllowed");
        assert_eq!(asked.len(), 1, "asked once");
        assert_eq!(asked[0].partitions, ["p1"]);
        assert_eq!(matched_writer(authenticated, "Denied"), 0);
        assert!(
            !remote_checks("Denied").is_empty(),
            "asked for Denied; events: {:?}",
            sink.snapshot()
                .iter()
                .filter(|e| e.name == "match.refused")
                .map(|e| e.attrs.iter().map(|a| a.value.clone()).collect::<Vec<_>>())
                .collect::<Vec<_>>()
        );
        // Figure 25 step 5, `check_remote_topic`: the endpoints of a topic the
        // plugin refuses are not matched.
        assert_eq!(matched_writer(authenticated, "TopicDenied"), 0);
        assert!(
            sink.snapshot().iter().any(|e| {
                e.name == "match.refused" && e.attrs.iter().any(|a| a.value.contains("§9.4.2.9.12"))
            }),
            "the refusal of the topic names its reason"
        );
        assert!(
            sink.snapshot().iter().any(|e| {
                e.name == "match.refused"
                    && e.attrs.iter().any(|a| {
                        a.value.contains("check_remote_datareader")
                            || a.value.contains("§9.4.2.9.11")
                    })
            }),
            "the refusal names its reason"
        );
    }

    /// FU2 S1.5 (e2e): after the auth handshake the runtime dispatch
    /// (A, replier) and a reference peer (B, stack+gate, initiator) over
    /// the Kx-protected VolatileSecure channel automatically exchange their data
    /// crypto tokens — afterwards secured user DATA round-trips in BOTH
    /// directions. **The secured-DATA proof via the runtime dispatch.**
    #[cfg(feature = "security")]
    #[test]
    #[serial_test::serial(dcps_security_e2e)]
    fn secured_data_round_trips_through_runtime_dispatch_e2e() {
        use zerodds_discovery::security::SecurityBuiltinStack;
        use zerodds_security::authentication::{AuthenticationPlugin, SharedSecretProvider};
        use zerodds_security::generic_message::{
            MessageIdentity, ParticipantGenericMessage, class_id,
        };
        use zerodds_security::token::DataHolder;
        use zerodds_security_crypto::{AesGcmCryptoPlugin, Suite};
        use zerodds_security_pki::{IdentityConfig, PkiAuthenticationPlugin};
        use zerodds_security_runtime::{ProtectionLevel, SharedSecurityGate};

        // Couples the pki plugin (behind a mutex) as the SharedSecretProvider to
        // the crypto plugin — like SecurityProfile in the FFI (Gap 1).
        struct PkiProvider(Arc<Mutex<PkiAuthenticationPlugin>>);
        impl SharedSecretProvider for PkiProvider {
            fn get_shared_secret(
                &self,
                h: zerodds_security::authentication::SharedSecretHandle,
            ) -> Option<Vec<u8>> {
                self.0.lock().ok()?.get_shared_secret(h)
            }
        }
        const GOV: &str = r#"<dds><domain_access_rules><domain_rule><domains><id>0</id></domains><allow_unauthenticated_participants>false</allow_unauthenticated_participants><enable_join_access_control>false</enable_join_access_control><rtps_protection_kind>ENCRYPT</rtps_protection_kind><topic_access_rules><topic_rule><topic_expression>*</topic_expression></topic_rule></topic_access_rules></domain_rule></domain_access_rules></dds>"#;
        let gov = || zerodds_security_permissions::parse_governance_xml(GOV).unwrap();
        let gate_with = |pki: &Arc<Mutex<PkiAuthenticationPlugin>>| {
            SharedSecurityGate::new(
                0,
                gov(),
                Box::new(AesGcmCryptoPlugin::with_secret_provider(
                    Suite::Aes128Gcm,
                    Arc::new(PkiProvider(pki.clone())) as Arc<dyn SharedSecretProvider>,
                )),
            )
        };
        let fake_rtps = |prefix: GuidPrefix, body: &[u8]| -> Vec<u8> {
            let mut m = Vec::new();
            m.extend_from_slice(b"RTPS\x02\x05\x01\x02");
            m.extend_from_slice(&prefix.to_bytes());
            m.extend_from_slice(body);
            m
        };

        // B < A → B initiator (cyclone convention); both bound to the
        // identities.
        let (((a_cert, a_key), a_prefix), ((b_cert, b_key), b_prefix)) =
            handshake_identities_b_smaller();
        let a_guid = Guid::new(a_prefix, EntityId::PARTICIPANT).to_bytes();
        let b_guid = Guid::new(b_prefix, EntityId::PARTICIPANT).to_bytes();
        let a_key_pk = a_prefix.to_bytes();
        let b_key_pk = b_prefix.to_bytes();

        // --- A: runtime with auth + gate (sharing pki_a) ---
        let pki_a = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        let a_local = pki_a
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: a_cert.clone(),
                    identity_ca_pem: a_cert.clone(),
                    identity_key_pem: Some(a_key),
                },
                a_guid,
            )
            .unwrap();
        let a_token = pki_a.lock().unwrap().get_identity_token(a_local).unwrap();
        let gate_a = Arc::new(gate_with(&pki_a));
        let rt = DcpsRuntime::start(
            43,
            a_prefix,
            RuntimeConfig {
                security: Some(gate_a.clone()),
                security_guid_prefix: Some(a_prefix),
                ..RuntimeConfig::default()
            },
        )
        .expect("start");
        let a_auth: Arc<Mutex<dyn AuthenticationPlugin>> = pki_a.clone();
        let a_stack = rt.enable_security_builtins_with_auth(VendorId::ZERODDS, a_auth, a_local);

        // --- B: in-test Stack + Gate (sharing pki_b), Initiator ---
        let pki_b = Arc::new(Mutex::new(PkiAuthenticationPlugin::new()));
        let b_local = pki_b
            .lock()
            .unwrap()
            .validate_with_config(
                IdentityConfig {
                    identity_cert_pem: b_cert.clone(),
                    identity_ca_pem: b_cert.clone(),
                    identity_key_pem: Some(b_key),
                },
                b_guid,
            )
            .unwrap();
        let b_token = pki_b.lock().unwrap().get_identity_token(b_local).unwrap();
        let gate_b = gate_with(&pki_b);
        let b_auth: Arc<Mutex<dyn AuthenticationPlugin>> = pki_b.clone();
        let mut stack_b =
            SecurityBuiltinStack::with_auth(b_prefix, VendorId::ZERODDS, b_auth, b_local, b_guid);
        stack_b.set_local_participant_data(pdata_of(b_guid));

        let flags = endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER
            | endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_READER
            | endpoint_flag::PARTICIPANT_VOLATILE_MESSAGE_SECURE_WRITER
            | endpoint_flag::PARTICIPANT_VOLATILE_MESSAGE_SECURE_READER;
        let a_beacon = make_secure_beacon_with_identity_token(a_prefix, flags, a_token.clone());
        stack_b.handle_remote_endpoints(
            &zerodds_discovery::spdp::SpdpReader::new()
                .parse_datagram(&a_beacon)
                .unwrap(),
        );
        // Wire A's stack deterministically (no handle_spdp_datagram —
        // a running runtime + trigger otherwise produces non-deterministic
        // proxy wirings via parallel/loopback beacons). A is the replier:
        // begin_handshake_with only sets up the peer state.
        let b_beacon = make_secure_beacon_with_identity_token(b_prefix, flags, b_token.clone());
        let b_parsed = zerodds_discovery::spdp::SpdpReader::new()
            .parse_datagram(&b_beacon)
            .unwrap();
        {
            let mut s = a_stack.lock().unwrap();
            s.handle_remote_endpoints(&b_parsed);
            s.begin_handshake_with(b_prefix, b_guid, &b_token).unwrap();
        }

        // --- Stateless-Handshake pumpen (B initiiert) ---
        // A is the replier. DDS-Security 1.2 §10.3.3 Table 59: it has the
        // shared secret once B's final is verified, so its response to the
        // request is the AUTH reply alone, and its Kx-protected crypto
        // token (volatile, automatically via the dispatch) answers the
        // final. A derived the secret with the reply and sent the token
        // with it, before B had proved its identity.
        let decode_route = |dgs: &[zerodds_rtps::message_builder::OutboundDatagram]| {
            let mut stateless = Vec::new();
            let mut volatile = Vec::new();
            for dg in dgs {
                let parsed = zerodds_rtps::datagram::decode_datagram(&dg.bytes).unwrap();
                let is_vol = parsed.submessages.iter().any(|frame| {
                    let sub = &frame.submessage;
                    // Cleartext path (unprotected): DATA to the VolatileSecure reader.
                    matches!(sub, zerodds_rtps::datagram::ParsedSubmessage::Data(d)
                        if d.reader_id == EntityId::BUILTIN_PARTICIPANT_VOLATILE_MESSAGE_SECURE_READER)
                    // Cross-vendor path (protected): the volatile crypto-token DATA
                    // is SEC_*-protected (protect_volatile_outbound) -> the inner
                    // DATA is encrypted and recognizable only by the prepended SEC_PREFIX
                    // submessage (id 0x31). Stateless AUTH stays plaintext.
                    || matches!(sub, zerodds_rtps::datagram::ParsedSubmessage::Unknown { id: 0x31, .. })
                });
                if is_vol {
                    volatile.push(dg.bytes.clone());
                } else {
                    stateless.push(dg.bytes.clone());
                }
            }
            (stateless, volatile)
        };

        let req = handshake_only(
            stack_b
                .begin_handshake_with(a_prefix, a_guid, &a_token)
                .unwrap(),
        );
        let a_resp = dispatch_security_builtin_datagram(&rt, &req[0].bytes, Duration::from_secs(1));
        let (a_stateless, a_early) = decode_route(&a_resp);
        assert!(
            a_early.is_empty(),
            "A has no crypto token to send before B's final"
        );

        // B verarbeitet A's AUTH-Reply → Final + B completes.
        let mut b_remote_id = None;
        let mut b_secret = None;
        let mut b_final = Vec::new();
        for sl in &a_stateless {
            for m in stack_b.stateless_reader.handle_datagram(sl).unwrap() {
                let (out, comp) = stack_b.on_stateless_message(a_prefix, &m).unwrap();
                b_final.extend(out);
                if let Some((id, sec)) = comp {
                    b_remote_id = Some(id);
                    b_secret = Some(sec);
                }
            }
        }
        let b_remote_id = b_remote_id.expect("B remote identity");
        let b_secret = b_secret.expect("B completes");

        // B's final completes A, and A answers with its crypto token.
        let mut a_after_final = Vec::new();
        for f in &b_final {
            a_after_final.extend(dispatch_security_builtin_datagram(
                &rt,
                &f.bytes,
                Duration::from_secs(1),
            ));
        }
        let (_, a_volatile) = decode_route(&a_after_final);
        assert!(
            !a_volatile.is_empty(),
            "A dispatch must send A's crypto token once the final completes it"
        );

        // B registers A's Kx, installs A's crypto token (from a_volatile).
        gate_b
            .register_remote_by_guid_from_secret(a_key_pk, b_remote_id, b_secret)
            .unwrap();
        // A's volatile crypto token is cross-vendor SEC_*-protected
        // (protect_volatile_outbound). B must decrypt the SEC_PREFIX/BODY/POSTFIX sequence
        // with A's Kx key to the inner DATA submessage before the
        // volatile_reader can process it — mirrors unprotect_volatile_
        // datagram im Live-Dispatch.
        let unprotect_vol_b = |bytes: &[u8]| -> Option<Vec<u8>> {
            let subs = walk_submessages(bytes);
            let prefix_pos = subs.iter().position(|(id, _, _)| *id == SMID_SEC_PREFIX)?;
            let postfix_idx = subs[prefix_pos..]
                .iter()
                .position(|(id, _, _)| *id == SMID_SEC_POSTFIX)
                .map(|i| prefix_pos + i)?;
            let (_, p_start, _) = subs[prefix_pos];
            let (_, q_start, q_total) = subs[postfix_idx];
            let data_submsg = gate_b
                .decode_kx_datawriter_from(&a_key_pk, &bytes[p_start..q_start + q_total])
                .ok()?;
            let mut out = Vec::with_capacity(bytes.len());
            out.extend_from_slice(&bytes[..20]);
            for (i, &(_, start, total)) in subs.iter().enumerate() {
                if i < prefix_pos || i > postfix_idx {
                    out.extend_from_slice(&bytes[start..start + total]);
                } else if i == prefix_pos {
                    out.extend_from_slice(&data_submsg);
                }
            }
            Some(out)
        };
        let mut b_installed = 0;
        for vol in &a_volatile {
            let vol_plain = unprotect_vol_b(vol).unwrap_or_else(|| vol.clone());
            let parsed = zerodds_rtps::datagram::decode_datagram(&vol_plain).unwrap();
            let vol_src = parsed.header.guid_prefix;
            for frame in parsed.submessages {
                if let zerodds_rtps::datagram::ParsedSubmessage::Data(d) = frame.submessage {
                    if d.reader_id == EntityId::BUILTIN_PARTICIPANT_VOLATILE_MESSAGE_SECURE_READER {
                        for m in stack_b.volatile_reader.handle_data(vol_src, &d).unwrap() {
                            if m.message_class_id == class_id::PARTICIPANT_CRYPTO_TOKENS {
                                // plaintext keymat (confidentiality was provided by the SEC_*
                                // protection of the volatile DATA, decrypted above) —
                                // install directly, no transform_kx_inbound.
                                let token = m.message_data[0]
                                    .binary_property(CRYPTO_TOKEN_PROP)
                                    .unwrap();
                                gate_b
                                    .set_remote_data_token_by_guid(&a_key_pk, token)
                                    .unwrap();
                                b_installed += 1;
                            }
                        }
                    }
                }
            }
        }
        assert!(b_installed >= 1, "B must install A's crypto token");

        // B builds + sends its crypto token — plaintext keymat in the
        // ParticipantGenericMessage (cross-vendor: confidentiality via SEC_*
        // protection of the transporting volatile DATA, not via token-internal
        // Kx encryption).
        let b_data_token = gate_b.local_token().unwrap();
        let b_crypto_msg = ParticipantGenericMessage {
            message_identity: MessageIdentity {
                source_guid: b_guid,
                sequence_number: 1,
            },
            related_message_identity: MessageIdentity::default(),
            destination_participant_key: a_guid,
            destination_endpoint_key: [0; 16],
            source_endpoint_key: [0; 16],
            message_class_id: class_id::PARTICIPANT_CRYPTO_TOKENS.into(),
            message_data: alloc::vec![
                DataHolder::new("DDS:Crypto:AES_GCM_GMAC")
                    .with_binary_property(CRYPTO_TOKEN_PROP, b_data_token)
            ],
        };
        let b_volatile = stack_b.volatile_writer.write(&b_crypto_msg).unwrap();
        // SEC_* submessage protection with A's Kx key (mirrors protect_volatile_
        // datagram in the live path): B encrypts the DATA submessage, A's
        // dispatch decrypts it via unprotect_volatile_datagram.
        let protect_vol_b = |bytes: &[u8]| -> Vec<u8> {
            let subs = walk_submessages(bytes);
            if !subs.iter().any(|(id, _, _)| *id == SMID_DATA) {
                return bytes.to_vec();
            }
            let mut out = Vec::with_capacity(bytes.len() + 64);
            out.extend_from_slice(&bytes[..20]);
            for (id, start, total) in subs {
                let submsg = &bytes[start..start + total];
                if id == SMID_DATA {
                    out.extend_from_slice(
                        &gate_b.encode_kx_datawriter_for(&a_key_pk, submsg).unwrap(),
                    );
                } else {
                    out.extend_from_slice(submsg);
                }
            }
            out
        };
        let b_vol_protected = protect_vol_b(&b_volatile[0].bytes);

        // B's crypto token to A's dispatch: A installs B's data token
        // (automatically via install_crypto_token); B's final went first.
        dispatch_security_builtin_datagram(&rt, &b_vol_protected, Duration::from_secs(1));

        // --- Secured DATA in both directions ---
        let msg_ab = fake_rtps(a_prefix, b"[A->B secured payload]");
        let wire_ab = gate_a
            .transform_outbound_for(&b_key_pk, &msg_ab, ProtectionLevel::Encrypt)
            .unwrap();
        assert_eq!(
            gate_b.transform_inbound_from(&a_key_pk, &wire_ab).unwrap(),
            msg_ab,
            "A->B secured DATA must round-trip"
        );
        let msg_ba = fake_rtps(b_prefix, b"[B->A secured payload]");
        let wire_ba = gate_b
            .transform_outbound_for(&a_key_pk, &msg_ba, ProtectionLevel::Encrypt)
            .unwrap();
        assert_eq!(
            gate_a.transform_inbound_from(&b_key_pk, &wire_ba).unwrap(),
            msg_ba,
            "B->A secured DATA must round-trip (A's dispatch installed B's token)"
        );

        // DDS-Security 1.2 §7.5.1.6: B is authenticated; a change of its
        // participant data on the plain SPDP writer is ignored (it only
        // keeps B alive), the changes come over the secure SPDP writer.
        handle_spdp_datagram(&rt, &b_beacon, None);
        let known = |rt: &DcpsRuntime| {
            rt.discovered_participants()
                .into_iter()
                .find(|p| p.sender_prefix == b_prefix)
                .expect("B discovered")
        };
        let before = known(&rt);
        let mut moved = before.data.clone();
        moved.metatraffic_unicast_locators = vec![Locator::udp_v4([127, 0, 0, 77], 7599)];
        let plain_change = zerodds_discovery::spdp::SpdpBeacon::new(moved.clone())
            .serialize()
            .unwrap();
        handle_spdp_datagram(&rt, &plain_change, None);
        assert_eq!(
            known(&rt).data.metatraffic_unicast_locators,
            before.data.metatraffic_unicast_locators,
            "a change on the plain SPDP writer is ignored for an authenticated participant"
        );
        let secure_change = zerodds_discovery::spdp::SpdpBeacon::new(moved)
            .serialize_secure()
            .unwrap();
        handle_spdp_datagram(&rt, &secure_change, None);
        assert_eq!(
            known(&rt).data.metatraffic_unicast_locators,
            vec![Locator::udp_v4([127, 0, 0, 77], 7599)],
            "the change over the secure SPDP writer is taken"
        );

        rt.shutdown();
    }

    #[test]
    fn c34c_enable_security_builtins_replays_known_peers() {
        // Order reversed: SPDP discovery first, plugin-
        // activation afterward. enable_security_builtins must catch up on already-
        // known peers. Plus: demux without a plugin (before enable)
        // is a no-op + does not panic.
        let rt = DcpsRuntime::start(
            76,
            GuidPrefix::from_bytes([0x76; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");

        // Demux without a plugin: silent no-op
        dispatch_security_builtin_datagram(&rt, &[0u8; 16], Duration::from_secs(1));

        let remote = GuidPrefix::from_bytes([0x77; 12]);
        let flags = endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_WRITER
            | endpoint_flag::PARTICIPANT_STATELESS_MESSAGE_READER;
        let dg = make_remote_spdp_beacon_with_flags(remote, flags);
        handle_spdp_datagram(&rt, &dg, None);

        let stack = rt.enable_security_builtins(VendorId::ZERODDS);
        {
            let s = stack.lock().unwrap();
            assert_eq!(
                s.stateless_writer.reader_proxy_count(),
                1,
                "late plugin activation must catch up on known peers"
            );
        }

        rt.shutdown();
    }

    /// #29 regression: the earlier per-peer once-guard blocked late-matched
    /// user-endpoint tokens. `pending_endpoint_tokens` must, with already-sent
    /// builtin tokens, let through EXACTLY the new user token — not treat the whole
    /// peer as "done".
    #[cfg(feature = "security")]
    #[test]
    fn pending_endpoint_tokens_keeps_late_user_token_after_builtins_sent() {
        use zerodds_security::generic_message::ParticipantGenericMessage;
        // An early-sent builtin token (secure-SEDP) ...
        let builtin = ParticipantGenericMessage {
            source_endpoint_key: [0xff; 16],
            destination_endpoint_key: [0xfe; 16],
            ..Default::default()
        };
        // ... and a late-matched user-endpoint token.
        let user = ParticipantGenericMessage {
            source_endpoint_key: [0x03; 16],
            destination_endpoint_key: [0x04; 16],
            ..Default::default()
        };
        let mut sent = alloc::collections::BTreeSet::new();
        sent.insert(endpoint_token_key(&builtin));

        let pending = pending_endpoint_tokens(vec![builtin.clone(), user.clone()], &sent);

        assert_eq!(pending.len(), 1, "only the new user token may be pending");
        assert_eq!(
            pending[0].source_endpoint_key, user.source_endpoint_key,
            "the let-through token must be the user-endpoint token"
        );
        // Idempotency: after sending, nothing is pending anymore.
        let mut sent2 = sent.clone();
        sent2.insert(endpoint_token_key(&user));
        assert!(
            pending_endpoint_tokens(vec![builtin, user], &sent2).is_empty(),
            "already-sent tokens must not become pending again"
        );
    }

    /// QT (#76, FOUNDATIONAL): a writer and reader of the SAME type whose
    /// TypeIdentifier is a *complete* hash (EquivalenceHashComplete) absent from
    /// any registry must still match and exchange data. Before the fix the
    /// runtime type-consistency check resolved against a fresh empty registry
    /// and rejected the match with TYPE_CONSISTENCY_ENFORCEMENT.
    #[test]
    fn qt_same_complete_type_identifier_matches_and_exchanges() {
        let rt = DcpsRuntime::start(
            60,
            GuidPrefix::from_bytes([0x60; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let complete = zerodds_types::TypeIdentifier::EquivalenceHashComplete(
            zerodds_types::type_identifier::EquivalenceHash([0xC0; 14]),
        );
        let mut w_cfg = qr_writer_cfg(
            "QtTopic",
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            zerodds_qos::LivelinessKind::Automatic,
        );
        w_cfg.type_identifier = complete.clone();
        let mut r_cfg = qr_reader_cfg(
            "QtTopic",
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            zerodds_qos::LivelinessKind::Automatic,
        );
        r_cfg.type_identifier = complete;
        let w = rt.register_user_writer(w_cfg).expect("writer");
        let (_r, rx) = rt.register_user_reader(r_cfg).expect("reader");
        rt.write_user_sample(w, b"complete-typed".to_vec())
            .expect("write");
        let s = rx
            .recv_timeout(core::time::Duration::from_millis(200))
            .expect("complete-TypeIdentifier writer+reader must match + exchange");
        match s {
            UserSample::Alive { payload, .. } => assert_eq!(payload.as_ref(), b"complete-typed"),
            other => panic!("expected Alive, got {other:?}"),
        }
        rt.shutdown();
    }

    /// A `CompleteTypeObject` and its identifier, registered in `rt`.
    ///
    /// `TypeObjectBuilder` is the one place in this crate that builds a
    /// type without an IDL model, and the object it returns is what
    /// codegen's `DdsType::type_object()` hands the same registration path
    /// in `Publisher::create_datawriter`.
    #[cfg(test)]
    fn register_complete_robot(rt: &DcpsRuntime) -> zerodds_types::TypeIdentifier {
        use zerodds_types::builder::{Extensibility, TypeObjectBuilder};
        let complete = TypeObjectBuilder::struct_type("::interop::Robot")
            .extensibility(Extensibility::Appendable)
            .member(
                "id",
                zerodds_types::TypeIdentifier::Primitive(zerodds_types::PrimitiveKind::UInt32),
                |m| m,
            )
            .member(
                "label",
                zerodds_types::TypeIdentifier::Primitive(zerodds_types::PrimitiveKind::UInt32),
                |m| m,
            )
            .build_complete();
        let hash = rt
            .register_type_object(zerodds_types::TypeObject::Complete(
                zerodds_types::CompleteTypeObject::Struct(complete),
            ))
            .expect("register type object");
        zerodds_types::TypeIdentifier::EquivalenceHashComplete(hash)
    }

    /// Issue #42, send direction: a ZeroDDS endpoint whose type has a
    /// `TypeObject` announces the STANDARD `PID_TYPE_INFORMATION`
    /// (0x0075) — the parameter every other vendor reads — and not only
    /// the ZeroDDS `PID_ZERODDS_TYPE_ID` no one else reads.
    ///
    /// The receive direction has
    /// `issue30_type_identifier_from_standard_type_information` in
    /// `zerodds-rtps`; this is its counterpart. It checks the announced
    /// SEDP record, the octets that record serialises to, and the two
    /// equivalence hashes a peer reads back out of them — the complete one
    /// has to be the identifier the endpoint itself advertises, or the
    /// endpoint would name two different types in one announcement.
    #[test]
    fn issue42_publication_announces_standard_type_information() {
        let rt = DcpsRuntime::start(
            64,
            GuidPrefix::from_bytes([0x64; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let id = register_complete_robot(&rt);
        let mut cfg = qr_writer_cfg(
            "Issue42Pub",
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            zerodds_qos::LivelinessKind::Automatic,
        );
        cfg.type_identifier = id.clone();
        let _eid = rt.register_user_writer(cfg).expect("writer");

        let announced = rt
            .announced_pubs
            .lock()
            .expect("announced_pubs")
            .last()
            .cloned()
            .expect("the writer announced a publication");
        let blob = announced
            .type_information
            .clone()
            .expect("PID_TYPE_INFORMATION on the announcement (#42)");

        // On the wire, not merely in the record: `to_pl_cdr_le` is what the
        // SEDP writer serialises, and the parameter is only announced if it
        // survives that.
        let bytes = announced.to_pl_cdr_le().expect("PL_CDR_LE");
        let decoded =
            zerodds_rtps::publication_data::PublicationBuiltinTopicData::from_pl_cdr_le(&bytes)
                .expect("the announcement parses");
        assert_eq!(decoded.type_information.as_ref(), Some(&blob));

        let ti = zerodds_types::TypeInformation::from_bytes_le(&blob)
            .expect("a spec-framed TypeInformation");
        assert_eq!(
            ti.complete.typeid_with_size.type_id, id,
            "the complete half must name the very type the endpoint advertises"
        );
        assert!(
            matches!(
                ti.minimal.typeid_with_size.type_id,
                zerodds_types::TypeIdentifier::EquivalenceHashMinimal(_)
            ),
            "both equivalence forms are required: a peer's validity check \
             (XTypes 1.3 §7.6.3.2.1) reads the minimal one first, got {:?}",
            ti.minimal.typeid_with_size.type_id
        );
        assert!(ti.minimal.typeid_with_size.typeobject_serialized_size > 0);
        assert!(ti.complete.typeid_with_size.typeobject_serialized_size > 0);
        rt.shutdown();
    }

    /// The same for the subscription side. It is the half that decides the
    /// `@final`-writer / `@appendable`-reader case: the foreign WRITER runs
    /// the assignability check (XTypes 1.3 §7.6.3.4) and can only run it on
    /// a reader that declared its type.
    #[test]
    fn issue42_subscription_announces_standard_type_information() {
        let rt = DcpsRuntime::start(
            65,
            GuidPrefix::from_bytes([0x65; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let id = register_complete_robot(&rt);
        let mut cfg = qr_reader_cfg(
            "Issue42Sub",
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            zerodds_qos::LivelinessKind::Automatic,
        );
        cfg.type_identifier = id.clone();
        let (_eid, _rx) = rt.register_user_reader(cfg).expect("reader");

        let announced = rt
            .announced_subs
            .lock()
            .expect("announced_subs")
            .last()
            .cloned()
            .expect("the reader announced a subscription");
        let blob = announced
            .type_information
            .clone()
            .expect("PID_TYPE_INFORMATION on the announcement (#42)");
        let ti = zerodds_types::TypeInformation::from_bytes_le(&blob)
            .expect("a spec-framed TypeInformation");
        assert_eq!(ti.complete.typeid_with_size.type_id, id);
        rt.shutdown();
    }

    /// A topic type in a strongly connected component announces the
    /// `TypeInformation` of the component (XTypes 1.3 §7.6.3.2.1): its own
    /// `TI_STRONGLY_CONNECTED_COMPONENT` identifier on both sides, the
    /// `SCCIdentifier` of the component as the first dependency, and the
    /// registry serves the component whole. A recursive type announced
    /// none before: its identifier is not a hash and nothing in the
    /// registry answered for it.
    #[test]
    fn a_recursive_topic_type_announces_the_type_information_of_its_component() {
        use zerodds_types::type_identifier::kinds::{EK_COMPLETE, EK_MINIMAL};
        let rt = DcpsRuntime::start(
            67,
            GuidPrefix::from_bytes([0x67; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");

        let parsed = zerodds_idl_parse::parse(
            "module m { @appendable struct Node { long value; sequence<Node> children; }; };",
        );
        assert!(!parsed.has_errors(), "{:?}", parsed.diagnostics());
        let lowered = zerodds_idl_lower::lower(&parsed.syntax(), "recursive.idl");
        let mut ast = lowered.ast;
        ast.resolve_all_by_name().expect("resolve");
        let node = ast
            .find_by_scoped_name(&zerodds_ast_core::ScopedName::absolute(alloc::vec![
                "m".to_string(),
                "Node".to_string(),
            ]))
            .ok()
            .and_then(zerodds_ast::AnyId::as_type)
            .expect("m::Node");
        let component = zerodds_types::from_ast::type_component(&ast, node)
            .expect("the component builds")
            .expect("Node reaches itself");
        rt.register_type_component(&component).expect("registered");
        let identifier = zerodds_types::from_ast::type_identifier(
            &ast,
            node,
            zerodds_types::from_ast::Form::Complete,
        )
        .expect("the identifier");
        let zerodds_types::TypeIdentifier::StronglyConnectedComponent(own) = identifier.clone()
        else {
            panic!("a recursive type is identified by its component: {identifier:?}");
        };

        let mut cfg = qr_writer_cfg(
            "RecursiveInfo",
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            zerodds_qos::LivelinessKind::Automatic,
        );
        cfg.type_identifier = identifier.clone();
        let _eid = rt.register_user_writer(cfg).expect("writer");

        let announced = rt
            .announced_pubs
            .lock()
            .expect("announced_pubs")
            .last()
            .cloned()
            .expect("the writer announced a publication");
        let blob = announced
            .type_information
            .clone()
            .expect("PID_TYPE_INFORMATION for a type in a component");
        let ti = zerodds_types::TypeInformation::from_bytes_le(&blob)
            .expect("a spec-framed TypeInformation");
        assert_eq!(ti.complete.typeid_with_size.type_id, identifier);
        let zerodds_types::TypeIdentifier::StronglyConnectedComponent(minimal) =
            ti.minimal.typeid_with_size.type_id.clone()
        else {
            panic!("the minimal side is a component too");
        };
        assert_eq!(minimal.equivalence_kind, EK_MINIMAL);
        assert_eq!(minimal.scc_index, own.scc_index);
        for (side, kind) in [(&ti.complete, EK_COMPLETE), (&ti.minimal, EK_MINIMAL)] {
            let first = &side.dependent_typeids[0];
            assert!(
                matches!(
                    &first.type_id,
                    zerodds_types::TypeIdentifier::StronglyConnectedComponent(scc)
                        if scc.scc_index == 0 && scc.equivalence_kind == kind
                ),
                "{first:?}"
            );
        }

        // The component is served whole under either identifier.
        let server = rt.type_lookup_server.lock().expect("server");
        assert!(server.registry.holds_component(&own));
        assert!(server.registry.holds_component(&minimal));
        rt.shutdown();
    }

    /// A type with no `TypeObject` — the normal case for a hand-written
    /// `DdsType`, whose `type_object()` defaults to `None` — announces NO
    /// `PID_TYPE_INFORMATION` at all.
    ///
    /// The alternative would be a parameter with an empty or invented
    /// hash, and both are worse than its absence: XTypes 1.3 §7.6.3.2.1
    /// gives `TypeInformation` two equivalence forms or none, every
    /// vendor's validity check reads both, and a value that fails it is
    /// rejected as a malformed parameter — which costs the endpoint its
    /// whole announcement, not just its type identity.
    #[test]
    fn issue42_a_type_without_a_type_object_announces_no_type_information() {
        let rt = DcpsRuntime::start(
            66,
            GuidPrefix::from_bytes([0x66; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let cfg = qr_writer_cfg(
            "Issue42NoObject",
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            zerodds_qos::LivelinessKind::Automatic,
        );
        assert_eq!(cfg.type_identifier, zerodds_types::TypeIdentifier::None);
        let _eid = rt.register_user_writer(cfg).expect("writer");

        let announced = rt
            .announced_pubs
            .lock()
            .expect("announced_pubs")
            .last()
            .cloned()
            .expect("the writer announced a publication");
        assert_eq!(announced.type_information, None);
        let bytes = announced.to_pl_cdr_le().expect("PL_CDR_LE");
        let parsed = zerodds_rtps::parameter_list::ParameterList::from_bytes(&bytes[4..], true)
            .expect("the parameter list parses");
        assert!(
            parsed
                .find(zerodds_rtps::parameter_list::pid::TYPE_INFORMATION)
                .is_none(),
            "no PID_TYPE_INFORMATION may be written for a type without a TypeObject"
        );
        rt.shutdown();
    }

    /// An endpoint whose type identifier is an equivalence hash the local
    /// registry does not hold announces nothing either: the parameter is
    /// built out of the registry, so a hash with no object behind it has no
    /// sizes and no minimal counterpart to state.
    #[test]
    fn issue42_an_unregistered_hash_announces_no_type_information() {
        let rt = DcpsRuntime::start(
            67,
            GuidPrefix::from_bytes([0x67; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let stranger = zerodds_types::TypeIdentifier::EquivalenceHashComplete(
            zerodds_types::EquivalenceHash([0x5A; 14]),
        );
        assert_eq!(rt.announced_type_information(&stranger), None);
        rt.shutdown();
    }

    /// Gap 2 (#24): a writer and reader of STRUCTURALLY-DIFFERENT but
    /// assignable types (distinct EquivalenceHashes) match + exchange ONLY
    /// because the runtime resolves them against its POPULATED TypeLookup
    /// registry. With the pre-fix empty `TypeRegistry::new()` at the match
    /// sites the differing hashes cannot resolve → the reader rejects
    /// (TYPE_CONSISTENCY_ENFORCEMENT) and the sample never arrives.
    ///
    /// Evolution direction: the WRITER carries the superset (V2 = V1 + a
    /// trailing @optional member), the READER the prefix (V1). This is the
    /// direction the appendable assignability rule supports
    /// (`assignability.rs`: writer ⊇ reader prefix, XTypes §7.2.4.4.4.4).
    #[test]
    fn gap2_structural_evolution_matches_via_populated_registry() {
        use zerodds_types::builder::{Extensibility, TypeObjectBuilder};
        let rt = DcpsRuntime::start(
            63,
            GuidPrefix::from_bytes([0x63; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");

        // Build + register both TypeObjects in the runtime's TypeLookup
        // registry (the same path `register_type_object` fills for local
        // codegen types). Returns the endpoint TypeIdentifier.
        let register =
            |rt: &DcpsRuntime, st: zerodds_types::type_object::minimal::MinimalStructType| {
                let obj = zerodds_types::TypeObject::Minimal(
                    zerodds_types::MinimalTypeObject::Struct(st),
                );
                let hash = rt.register_type_object(obj).expect("register type object");
                zerodds_types::TypeIdentifier::EquivalenceHashMinimal(hash)
            };
        let writer_v2 = TypeObjectBuilder::struct_type("::gap2::Evo")
            .extensibility(Extensibility::Appendable)
            .member(
                "a",
                zerodds_types::TypeIdentifier::Primitive(zerodds_types::PrimitiveKind::Int32),
                |m| m,
            )
            .member(
                "b",
                zerodds_types::TypeIdentifier::Primitive(zerodds_types::PrimitiveKind::Int32),
                |m| m,
            )
            .member(
                "c",
                zerodds_types::TypeIdentifier::Primitive(zerodds_types::PrimitiveKind::Int32),
                |m| m.optional(),
            )
            .build_minimal();
        let reader_v1 = TypeObjectBuilder::struct_type("::gap2::Evo")
            .extensibility(Extensibility::Appendable)
            .member(
                "a",
                zerodds_types::TypeIdentifier::Primitive(zerodds_types::PrimitiveKind::Int32),
                |m| m,
            )
            .member(
                "b",
                zerodds_types::TypeIdentifier::Primitive(zerodds_types::PrimitiveKind::Int32),
                |m| m,
            )
            .build_minimal();
        let w_id = register(&rt, writer_v2);
        let r_id = register(&rt, reader_v1);
        assert_ne!(
            w_id, r_id,
            "the two evolutions must carry distinct TypeIdentifiers (else the \
             equal-hash short-circuit — not the registry path — would decide)"
        );

        let mut w_cfg = qr_writer_cfg(
            "Gap2Evo",
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            zerodds_qos::LivelinessKind::Automatic,
        );
        w_cfg.type_identifier = w_id;
        let mut r_cfg = qr_reader_cfg(
            "Gap2Evo",
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            zerodds_qos::LivelinessKind::Automatic,
        );
        r_cfg.type_identifier = r_id;

        let w = rt.register_user_writer(w_cfg).expect("writer");
        let (_r, rx) = rt.register_user_reader(r_cfg).expect("reader");
        rt.write_user_sample(w, b"evolved".to_vec()).expect("write");
        let s = rx
            .recv_timeout(core::time::Duration::from_millis(500))
            .expect(
                "structurally-assignable typed endpoints must match via the populated registry",
            );
        match s {
            UserSample::Alive { payload, .. } => assert_eq!(payload.as_ref(), b"evolved"),
            other => panic!("expected Alive, got {other:?}"),
        }
        rt.shutdown();
    }

    // ===================================================================
    // QR-cluster (#77) — same-runtime QoS behavioral regression tests.
    // ===================================================================

    fn qr_writer_cfg(
        topic: &str,
        durability: zerodds_qos::DurabilityKind,
        partition: Vec<String>,
        liveliness: zerodds_qos::LivelinessKind,
    ) -> UserWriterConfig {
        UserWriterConfig {
            topic_name: topic.into(),
            type_name: "QrType".into(),
            durability,
            liveliness: zerodds_qos::LivelinessQosPolicy {
                kind: liveliness,
                lease_duration: QosDuration::INFINITE,
            },
            partition,
            ..Default::default()
        }
    }

    /// Real UDP child processes: hard death cannot send endpoint disposals and
    /// the second process deliberately reuses its GUID and sequence number one.
    #[test]
    fn participant_lease_lifecycle_hard_death_and_same_prefix() {
        const CHILD: &str = "ZERODDS_TEST_LEASE_CHILD";
        const DOMAIN: &str = "ZERODDS_TEST_LEASE_DOMAIN";
        const TOPIC: &str = "ParticipantLeaseLifecycle";
        let config = || RuntimeConfig {
            spdp_period: Duration::from_millis(50),
            participant_lease_duration: Duration::from_millis(600),
            tick_period: Duration::from_millis(20),
            ..RuntimeConfig::default()
        };
        if let Ok(generation) = std::env::var(CHILD) {
            let domain = std::env::var(DOMAIN)
                .expect("parent domain")
                .parse::<i32>()
                .expect("valid domain");
            let rt = DcpsRuntime::start(domain, GuidPrefix::from_bytes([0x52; 12]), config())
                .expect("child runtime");
            let writer = rt
                .register_user_writer(qr_writer_cfg(
                    TOPIC,
                    zerodds_qos::DurabilityKind::Volatile,
                    Vec::new(),
                    zerodds_qos::LivelinessKind::Automatic,
                ))
                .expect("child writer");
            let deadline = Instant::now() + Duration::from_secs(10);
            while rt.user_writer_matched_count(writer) == 0 {
                assert!(Instant::now() < deadline, "child match timeout");
                std::thread::sleep(Duration::from_millis(20));
            }
            rt.write_user_sample(writer, vec![generation.parse::<u8>().unwrap(), 0, 0, 0])
                .expect("child sample sequence one");
            std::thread::sleep(Duration::from_secs(60));
            panic!("parent did not terminate child");
        }
        struct OwnedChild(std::process::Child);
        impl Drop for OwnedChild {
            fn drop(&mut self) {
                let _ = self.0.kill();
                let _ = self.0.wait();
            }
        }
        let domain_lease = zerodds_test_domains::lease_domain();
        let domain = domain_lease.id();
        let spawn = |generation: u8| {
            OwnedChild(
                std::process::Command::new(std::env::current_exe().expect("test executable"))
                    .args([
                        "--exact",
                        "runtime::tests::participant_lease_lifecycle_hard_death_and_same_prefix",
                        "--test-threads=1",
                        "--nocapture",
                    ])
                    .env(CHILD, generation.to_string())
                    .env(DOMAIN, domain.to_string())
                    .spawn()
                    .expect("spawn peer"),
            )
        };
        let rt = DcpsRuntime::start(domain, GuidPrefix::from_bytes([0x51; 12]), config())
            .expect("receiver runtime");
        let builtins = crate::builtin_subscriber::BuiltinSubscriber::new();
        let sinks = builtins.sinks();
        rt.attach_builtin_sinks(sinks.clone());
        let (reader, samples) = rt
            .register_user_reader(qr_reader_cfg(
                TOPIC,
                zerodds_qos::DurabilityKind::Volatile,
                Vec::new(),
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("receiver");
        let remote = GuidPrefix::from_bytes([0x52; 12]);
        for generation in [1_u8, 2] {
            let child = spawn(generation);
            let sample = samples
                .recv_timeout(Duration::from_secs(10))
                .expect("live sample");
            assert!(
                matches!(sample, UserSample::Alive { payload, source_sequence_number: 1, .. }
                if payload.as_slice() == [generation, 0, 0, 0])
            );
            assert_eq!(rt.user_reader_matched_count(reader), 1);
            assert!(
                rt.discovered_participants()
                    .iter()
                    .any(|p| p.data.guid.prefix == remote)
            );
            drop(child);
            let deadline = Instant::now() + Duration::from_secs(10);
            while rt
                .discovered_participants()
                .iter()
                .any(|p| p.data.guid.prefix == remote)
                || rt.discovered_publications_count() != 0
                || rt.user_reader_matched_count(reader) != 0
            {
                assert!(Instant::now() < deadline, "lease cleanup timeout");
                std::thread::sleep(Duration::from_millis(20));
            }
            assert_eq!(rt.take_reader_unmatched_writers(reader).len(), 1);
        }
        assert!(
            sinks
                .participant
                .lock()
                .unwrap()
                .iter()
                .any(|sample| matches!(sample,
            UserSample::Lifecycle { key_hash, .. }
                if *key_hash == Guid::new(remote, EntityId::PARTICIPANT).to_bytes()))
        );
        assert!(
            sinks
                .publication
                .lock()
                .unwrap()
                .iter()
                .any(|sample| matches!(sample, UserSample::Lifecycle { .. }))
        );
        rt.shutdown();
    }

    fn qr_reader_cfg(
        topic: &str,
        durability: zerodds_qos::DurabilityKind,
        partition: Vec<String>,
        liveliness: zerodds_qos::LivelinessKind,
    ) -> UserReaderConfig {
        UserReaderConfig {
            topic_name: topic.into(),
            type_name: "QrType".into(),
            durability,
            liveliness: zerodds_qos::LivelinessQosPolicy {
                kind: liveliness,
                lease_duration: QosDuration::INFINITE,
            },
            partition,
            ..Default::default()
        }
    }

    /// QR (a) HISTORY KeepLast: a TransientLocal writer with depth=2 retains
    /// only the last 2 samples per instance; a late-joining reader replays
    /// exactly those 2 (not all 3 written).
    #[test]
    fn qr_history_keep_last_depth_enforced_on_replay() {
        let rt = DcpsRuntime::start(
            61,
            GuidPrefix::from_bytes([0x61; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let w = rt
            .register_user_writer(qr_writer_cfg(
                "QrHistory",
                zerodds_qos::DurabilityKind::TransientLocal,
                alloc::vec![],
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("writer");
        rt.set_user_writer_history_depth(w, 2).expect("set depth");

        // Three writes BEFORE any reader exists.
        rt.write_user_sample(w, b"s1".to_vec()).expect("w1");
        rt.write_user_sample(w, b"s2".to_vec()).expect("w2");
        rt.write_user_sample(w, b"s3".to_vec()).expect("w3");
        assert_eq!(
            rt.user_writer_retained_len(w),
            2,
            "KeepLast(2) must retain only the 2 most recent samples"
        );

        // Late-joining reader replays exactly the last 2 (s2, s3).
        let (_r, rx) = rt
            .register_user_reader(qr_reader_cfg(
                "QrHistory",
                zerodds_qos::DurabilityKind::TransientLocal,
                alloc::vec![],
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("reader");

        let mut got: Vec<Vec<u8>> = Vec::new();
        while let Ok(s) = rx.recv_timeout(core::time::Duration::from_millis(200)) {
            if let UserSample::Alive { payload, .. } = s {
                got.push(payload.as_ref().to_vec());
            }
            if got.len() == 2 {
                break;
            }
        }
        assert_eq!(got, alloc::vec![b"s2".to_vec(), b"s3".to_vec()]);
        rt.shutdown();
    }

    /// QR (b) DURABILITY TRANSIENT_LOCAL: a late-joining reader receives the
    /// retained sample written before it matched. A VOLATILE writer replays
    /// nothing.
    #[test]
    fn qr_transient_local_late_join_replay_vs_volatile() {
        // TransientLocal: late joiner sees the prior sample.
        let rt = DcpsRuntime::start(
            62,
            GuidPrefix::from_bytes([0x62; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let w = rt
            .register_user_writer(qr_writer_cfg(
                "QrTL",
                zerodds_qos::DurabilityKind::TransientLocal,
                alloc::vec![],
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("writer");
        rt.write_user_sample(w, b"retained".to_vec())
            .expect("write");
        let (_r, rx) = rt
            .register_user_reader(qr_reader_cfg(
                "QrTL",
                zerodds_qos::DurabilityKind::TransientLocal,
                alloc::vec![],
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("reader");
        let s = rx
            .recv_timeout(core::time::Duration::from_millis(200))
            .expect("TransientLocal late joiner must replay the retained sample");
        match s {
            UserSample::Alive { payload, .. } => assert_eq!(payload.as_ref(), b"retained"),
            other => panic!("expected Alive, got {other:?}"),
        }
        rt.shutdown();

        // Volatile: late joiner gets nothing for the pre-match write.
        let rt2 = DcpsRuntime::start(
            63,
            GuidPrefix::from_bytes([0x63; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let w2 = rt2
            .register_user_writer(qr_writer_cfg(
                "QrVol",
                zerodds_qos::DurabilityKind::Volatile,
                alloc::vec![],
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("writer");
        rt2.write_user_sample(w2, b"lost".to_vec()).expect("write");
        assert_eq!(
            rt2.user_writer_retained_len(w2),
            0,
            "Volatile retains nothing"
        );
        let (_r2, rx2) = rt2
            .register_user_reader(qr_reader_cfg(
                "QrVol",
                zerodds_qos::DurabilityKind::Volatile,
                alloc::vec![],
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("reader");
        assert!(
            rx2.recv_timeout(core::time::Duration::from_millis(120))
                .is_err(),
            "Volatile late joiner must NOT replay a pre-match sample"
        );
        rt2.shutdown();
    }

    /// QR (c) PARTITION: a writer in partition ["A"] and a reader in ["B"]
    /// must NOT match (no intra-runtime route); a matching partition delivers.
    #[test]
    fn qr_partition_gates_intra_runtime_match() {
        let rt = DcpsRuntime::start(
            64,
            GuidPrefix::from_bytes([0x64; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        // Mismatched partitions.
        let w = rt
            .register_user_writer(qr_writer_cfg(
                "QrPart",
                zerodds_qos::DurabilityKind::Volatile,
                alloc::vec!["A".into()],
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("writer");
        let (_r_mismatch, rx_mismatch) = rt
            .register_user_reader(qr_reader_cfg(
                "QrPart",
                zerodds_qos::DurabilityKind::Volatile,
                alloc::vec!["B".into()],
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("reader");
        rt.write_user_sample(w, b"x".to_vec()).expect("write");
        assert!(
            rx_mismatch
                .recv_timeout(core::time::Duration::from_millis(120))
                .is_err(),
            "partitions [A] vs [B] must not match"
        );

        // Matching partition reader added → now delivers.
        let (_r_match, rx_match) = rt
            .register_user_reader(qr_reader_cfg(
                "QrPart",
                zerodds_qos::DurabilityKind::Volatile,
                alloc::vec!["A".into()],
                zerodds_qos::LivelinessKind::Automatic,
            ))
            .expect("reader");
        rt.write_user_sample(w, b"y".to_vec()).expect("write");
        let s = rx_match
            .recv_timeout(core::time::Duration::from_millis(200))
            .expect("partition [A] vs [A] must match");
        match s {
            UserSample::Alive { payload, .. } => assert_eq!(payload.as_ref(), b"y"),
            other => panic!("expected Alive, got {other:?}"),
        }
        rt.shutdown();
    }

    /// QR (d) KEYED LIFECYCLE: dispose(key) delivers a Lifecycle marker to a
    /// matched same-runtime reader; a later late joiner observes the terminal
    /// NOT_ALIVE_DISPOSED state.
    #[test]
    fn qr_dispose_delivers_lifecycle_to_intra_reader() {
        use zerodds_rtps::history_cache::ChangeKind;
        use zerodds_rtps::inline_qos::status_info;
        let rt = DcpsRuntime::start(
            65,
            GuidPrefix::from_bytes([0x65; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let w = rt
            .register_user_writer_kind(
                qr_writer_cfg(
                    "QrLifecycle",
                    zerodds_qos::DurabilityKind::TransientLocal,
                    alloc::vec![],
                    zerodds_qos::LivelinessKind::Automatic,
                ),
                true,
            )
            .expect("writer");
        let (_r, rx) = rt
            .register_user_reader_kind(
                qr_reader_cfg(
                    "QrLifecycle",
                    zerodds_qos::DurabilityKind::TransientLocal,
                    alloc::vec![],
                    zerodds_qos::LivelinessKind::Automatic,
                ),
                true,
            )
            .expect("reader");

        let key = [0xAB_u8; 16];
        rt.write_user_sample_keyed(w, b"alive", key, None)
            .expect("write");
        // First the alive sample.
        let first = rx
            .recv_timeout(core::time::Duration::from_millis(200))
            .expect("alive sample");
        assert!(matches!(first, UserSample::Alive { key_hash: Some(found), .. } if found == key));

        // dispose(key) → Lifecycle marker NOT_ALIVE_DISPOSED.
        rt.write_user_lifecycle(w, key, None, status_info::DISPOSED, None)
            .expect("dispose");
        let life = rx
            .recv_timeout(core::time::Duration::from_millis(200))
            .expect("dispose must deliver a Lifecycle marker to the matched reader");
        match life {
            UserSample::Lifecycle { key_hash, kind, .. } => {
                assert_eq!(key_hash, key);
                assert_eq!(kind, ChangeKind::NotAliveDisposed);
            }
            other => panic!("expected Lifecycle, got {other:?}"),
        }

        // A brand-new late joiner replays the alive sample AND the terminal
        // disposed marker, so it learns the instance is NOT_ALIVE_DISPOSED.
        let (_r2, rx2) = rt
            .register_user_reader_kind(
                qr_reader_cfg(
                    "QrLifecycle",
                    zerodds_qos::DurabilityKind::TransientLocal,
                    alloc::vec![],
                    zerodds_qos::LivelinessKind::Automatic,
                ),
                true,
            )
            .expect("reader2");
        let mut saw_disposed = false;
        let mut saw_keyed_alive = false;
        while let Ok(s) = rx2.recv_timeout(core::time::Duration::from_millis(200)) {
            if let UserSample::Alive { key_hash, .. } = &s {
                assert_eq!(*key_hash, Some(key));
                saw_keyed_alive = true;
            }
            if let UserSample::Lifecycle { kind, .. } = s {
                if kind == ChangeKind::NotAliveDisposed {
                    saw_disposed = true;
                    break;
                }
            }
        }
        assert!(
            saw_keyed_alive,
            "retained alive must preserve its instance key"
        );
        assert!(
            saw_disposed,
            "late joiner must observe the terminal NOT_ALIVE_DISPOSED state"
        );
        rt.shutdown();
    }

    /// QR (d) KEYED LIFECYCLE — unregister(key) maps to NOT_ALIVE (NO_WRITERS).
    #[test]
    fn qr_unregister_delivers_no_writers_lifecycle() {
        use zerodds_rtps::history_cache::ChangeKind;
        use zerodds_rtps::inline_qos::status_info;
        let rt = DcpsRuntime::start(
            66,
            GuidPrefix::from_bytes([0x66; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let w = rt
            .register_user_writer_kind(
                qr_writer_cfg(
                    "QrUnreg",
                    zerodds_qos::DurabilityKind::Volatile,
                    alloc::vec![],
                    zerodds_qos::LivelinessKind::Automatic,
                ),
                true,
            )
            .expect("writer");
        let (_r, rx) = rt
            .register_user_reader_kind(
                qr_reader_cfg(
                    "QrUnreg",
                    zerodds_qos::DurabilityKind::Volatile,
                    alloc::vec![],
                    zerodds_qos::LivelinessKind::Automatic,
                ),
                true,
            )
            .expect("reader");
        let key = [0x11_u8; 16];
        rt.write_user_lifecycle(w, key, None, status_info::UNREGISTERED, None)
            .expect("unregister");
        let life = rx
            .recv_timeout(core::time::Duration::from_millis(200))
            .expect("unregister must deliver a Lifecycle marker");
        match life {
            UserSample::Lifecycle { key_hash, kind, .. } => {
                assert_eq!(key_hash, key);
                assert_eq!(kind, ChangeKind::NotAliveUnregistered);
            }
            other => panic!("expected Lifecycle, got {other:?}"),
        }
        rt.shutdown();
    }

    /// `reader.dispose_with_unregister` holds for a reader of the same
    /// runtime too: off, a marker that disposes and unregisters reaches it
    /// as an unregister (DDSI-RTPS 2.5 §9.6.3.9).
    #[test]
    fn a_dispose_unregister_marker_reaches_a_local_reader_as_the_setting_says() {
        use zerodds_rtps::history_cache::ChangeKind;
        use zerodds_rtps::inline_qos::status_info;
        for (setting, expected) in [
            (true, ChangeKind::NotAliveDisposedUnregistered),
            (false, ChangeKind::NotAliveUnregistered),
        ] {
            let rt = DcpsRuntime::start(
                66,
                GuidPrefix::from_bytes([0x66; 12]),
                RuntimeConfig {
                    reader_dispose_with_unregister: setting,
                    ..RuntimeConfig::default()
                },
            )
            .expect("start");
            let w = rt
                .register_user_writer_kind(
                    qr_writer_cfg(
                        "QrDisposeUnreg",
                        zerodds_qos::DurabilityKind::Volatile,
                        alloc::vec![],
                        zerodds_qos::LivelinessKind::Automatic,
                    ),
                    true,
                )
                .expect("writer");
            let (_r, rx) = rt
                .register_user_reader_kind(
                    qr_reader_cfg(
                        "QrDisposeUnreg",
                        zerodds_qos::DurabilityKind::Volatile,
                        alloc::vec![],
                        zerodds_qos::LivelinessKind::Automatic,
                    ),
                    true,
                )
                .expect("reader");
            let key = [0x12_u8; 16];
            rt.write_user_lifecycle(
                w,
                key,
                None,
                status_info::DISPOSED | status_info::UNREGISTERED,
                None,
            )
            .expect("unregister with dispose");
            match rx
                .recv_timeout(core::time::Duration::from_millis(200))
                .expect("the marker must reach the reader")
            {
                UserSample::Lifecycle { key_hash, kind, .. } => {
                    assert_eq!(key_hash, key);
                    assert_eq!(kind, expected, "reader.dispose_with_unregister={setting}");
                }
                other => panic!("expected Lifecycle, got {other:?}"),
            }
            rt.shutdown();
        }
    }

    /// A writer config of kind `kind` and lease `lease_ms` (0: INFINITE).
    fn live_writer_cfg(
        topic: &str,
        kind: zerodds_qos::LivelinessKind,
        lease_ms: i32,
    ) -> UserWriterConfig {
        let mut cfg = qr_writer_cfg(
            topic,
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            kind,
        );
        if lease_ms != 0 {
            cfg.liveliness.lease_duration = QosDuration::from_millis(lease_ms);
        }
        cfg
    }

    /// A reader config accepting any writer whose lease is at most
    /// `lease_ms` (LIVELINESS is RxO, DDS 1.4 §2.2.3.11).
    fn live_reader_cfg(topic: &str, lease_ms: i32) -> UserReaderConfig {
        let mut cfg = qr_reader_cfg(
            topic,
            zerodds_qos::DurabilityKind::Volatile,
            alloc::vec![],
            zerodds_qos::LivelinessKind::Automatic,
        );
        if lease_ms != 0 {
            cfg.liveliness.lease_duration = QosDuration::from_millis(lease_ms);
        }
        cfg
    }

    /// A runtime on a leased domain. The lease is released when the test
    /// drops it, after `shutdown`: `unique_domain` would hold it for the
    /// life of the test binary, whose band of free domains is small.
    fn live_runtime(prefix: u8) -> (zerodds_test_domains::DomainLease, Arc<DcpsRuntime>) {
        let lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([prefix; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        (lease, rt)
    }

    /// DDS 1.4 §2.2.4.1: `alive_count` is "the total number of currently
    /// active DataWriters". An AUTOMATIC writer is alive from its match; two
    /// are two; unmatching one takes it out of the count.
    #[test]
    fn alive_count_is_the_number_of_alive_matched_writers() {
        let (_lease, rt) = live_runtime(0x71);
        let (r, _rx) = rt
            .register_user_reader(live_reader_cfg("LiveCount", 0))
            .expect("reader");
        let a = rt
            .register_user_writer(live_writer_cfg(
                "LiveCount",
                zerodds_qos::LivelinessKind::Automatic,
                0,
            ))
            .expect("writer a");
        assert_eq!(
            rt.user_reader_liveliness_status(r),
            (true, 1, 0),
            "an AUTOMATIC writer is alive from its match, before it writes"
        );
        let b = rt
            .register_user_writer(live_writer_cfg(
                "LiveCount",
                zerodds_qos::LivelinessKind::Automatic,
                0,
            ))
            .expect("writer b");
        rt.write_user_sample(a, b"a".to_vec()).expect("write a");
        rt.write_user_sample(b, b"b".to_vec()).expect("write b");
        assert_eq!(
            rt.user_reader_liveliness_status(r),
            (true, 2, 0),
            "two writers are two"
        );
        let st = rt.take_user_reader_liveliness_changed(r).expect("status");
        assert_eq!((st.alive_count_change, st.not_alive_count_change), (2, 0));
        assert_eq!(
            st.last_publication_handle,
            crate::instance_handle::InstanceHandle::from_guid(Guid::new(rt.guid_prefix, b))
        );
        rt.remove_user_writer(a);
        assert_eq!(rt.user_reader_liveliness_status(r), (true, 1, 0));
        let st = rt.take_user_reader_liveliness_changed(r).expect("status");
        assert_eq!((st.alive_count_change, st.not_alive_count_change), (-1, 0));
        rt.shutdown();
    }

    /// A MANUAL_BY_TOPIC writer counts from its first assertion, is not
    /// alive once its lease runs out, and alive again when it writes.
    #[test]
    fn a_manual_writer_goes_not_alive_when_silent_and_back_when_it_writes() {
        let (_lease, rt) = live_runtime(0x72);
        let (r, _rx) = rt
            .register_user_reader(live_reader_cfg("LiveManual", 100))
            .expect("reader");
        let w = rt
            .register_user_writer(live_writer_cfg(
                "LiveManual",
                zerodds_qos::LivelinessKind::ManualByTopic,
                100,
            ))
            .expect("writer");
        assert_eq!(
            rt.user_reader_liveliness_status(r),
            (false, 0, 0),
            "nothing asserted yet"
        );
        rt.write_user_sample(w, b"x".to_vec()).expect("write");
        assert_eq!(rt.user_reader_liveliness_status(r), (true, 1, 0));
        std::thread::sleep(core::time::Duration::from_millis(400));
        assert_eq!(
            rt.user_reader_liveliness_status(r),
            (false, 0, 1),
            "lease ran out"
        );
        rt.write_user_sample(w, b"y".to_vec()).expect("write");
        assert_eq!(rt.user_reader_liveliness_status(r), (true, 1, 0));
        let st = rt.take_user_reader_liveliness_changed(r).expect("status");
        // unasserted → alive, alive → not alive, not alive → alive.
        assert_eq!((st.alive_count_change, st.not_alive_count_change), (1, 0));
        rt.shutdown();
    }

    /// `DataWriter::assert_liveliness` keeps a MANUAL_BY_TOPIC writer alive
    /// without a write, at the reader and at the writer.
    #[test]
    fn assert_liveliness_keeps_a_manual_writer_alive_without_writing() {
        let (_lease, rt) = live_runtime(0x73);
        let (r, _rx) = rt
            .register_user_reader(live_reader_cfg("LiveAssert", 150))
            .expect("reader");
        let w = rt
            .register_user_writer(live_writer_cfg(
                "LiveAssert",
                zerodds_qos::LivelinessKind::ManualByTopic,
                150,
            ))
            .expect("writer");
        for _ in 0..10 {
            rt.assert_writer_liveliness_eid(w);
            std::thread::sleep(core::time::Duration::from_millis(40));
        }
        assert_eq!(rt.user_reader_liveliness_status(r), (true, 1, 0));
        assert_eq!(rt.user_writer_liveliness_lost(w), 0);
        rt.shutdown();
    }

    /// LIVELINESS_LOST (DDS 1.4 §2.2.4.1): an AUTOMATIC writer is asserted
    /// by the service and is never lost for not writing; a silent manual
    /// writer is lost once, not once per lease.
    #[test]
    fn liveliness_lost_counts_a_silent_manual_writer_once_and_no_automatic_one() {
        let (_lease, rt) = live_runtime(0x74);
        let auto = rt
            .register_user_writer(live_writer_cfg(
                "LiveLostA",
                zerodds_qos::LivelinessKind::Automatic,
                100,
            ))
            .expect("automatic writer");
        let manual = rt
            .register_user_writer(live_writer_cfg(
                "LiveLostM",
                zerodds_qos::LivelinessKind::ManualByTopic,
                100,
            ))
            .expect("manual writer");
        std::thread::sleep(core::time::Duration::from_millis(550));
        assert_eq!(rt.user_writer_liveliness_lost(auto), 0);
        assert_eq!(rt.user_writer_liveliness_lost(manual), 1);
        // Asserting and falling silent again is the second loss.
        rt.write_user_sample(manual, b"x".to_vec()).expect("write");
        std::thread::sleep(core::time::Duration::from_millis(300));
        assert_eq!(rt.user_writer_liveliness_lost(manual), 2);
        rt.shutdown();
    }

    // ========================================================================
    // RxO matching for DESTINATION_ORDER (§2.2.3.18) + LATENCY_BUDGET
    // (§2.2.3.10) in the runtime matcher (`wire_writer_to_remote_reader` /
    // `wire_reader_to_remote_writer`). Semantics come from
    // `zerodds_qos::{DestinationOrderQosPolicy,LatencyBudgetQosPolicy}
    // ::is_compatible_with` — offered.kind >= requested.kind and
    // offered.duration <= requested.duration.
    // ========================================================================

    fn rxo_writer_cfg(
        dest: zerodds_qos::DestinationOrderKind,
        latency_ms: i32,
    ) -> UserWriterConfig {
        UserWriterConfig {
            property: Default::default(),
            data_tags: Default::default(),
            topic_name: "RxOTopic".into(),
            type_name: "RxOType".into(),
            // BestEffort so RELIABILITY never masks the policy under test.
            reliable: false,
            durability: zerodds_qos::DurabilityKind::Volatile,
            durability_service: zerodds_qos::DurabilityServiceQosPolicy::default(),
            deadline: zerodds_qos::DeadlineQosPolicy::default(),
            latency_budget: zerodds_qos::LatencyBudgetQosPolicy {
                duration: zerodds_qos::Duration::from_millis(latency_ms),
            },
            destination_order: zerodds_qos::DestinationOrderQosPolicy { kind: dest },
            lifespan: zerodds_qos::LifespanQosPolicy::default(),
            liveliness: zerodds_qos::LivelinessQosPolicy::default(),
            ownership: zerodds_qos::OwnershipKind::Shared,
            ownership_strength: 0,
            transport_priority: 0,
            presentation: Default::default(),
            partition: alloc::vec![],
            user_data: alloc::vec![],
            topic_data: alloc::vec![],
            group_data: alloc::vec![],
            type_identifier: zerodds_types::TypeIdentifier::None,
            data_representation_offer: None,
            group_entity_id: None,
            data_max_size_serialized: None,
            entity_name: None,
        }
    }

    fn rxo_reader_cfg(
        dest: zerodds_qos::DestinationOrderKind,
        latency_ms: i32,
    ) -> UserReaderConfig {
        UserReaderConfig {
            topic_name: "RxOTopic".into(),
            type_name: "RxOType".into(),
            reliable: false,
            latency_budget: zerodds_qos::LatencyBudgetQosPolicy {
                duration: zerodds_qos::Duration::from_millis(latency_ms),
            },
            destination_order: zerodds_qos::DestinationOrderQosPolicy { kind: dest },
            ..Default::default()
        }
    }

    /// A remote reader (subscription) with a non-empty unicast locator so the
    /// matcher does not early-return on missing locators before the QoS chain.
    fn rxo_remote_sub(
        dest: zerodds_qos::DestinationOrderKind,
        latency_ms: i32,
    ) -> zerodds_rtps::subscription_data::SubscriptionBuiltinTopicData {
        let prefix = GuidPrefix::from_bytes([0x9A; 12]);
        zerodds_rtps::subscription_data::SubscriptionBuiltinTopicData {
            content_filter_unreadable: false,
            vendor_id: Some(zerodds_rtps::wire_types::VendorId::ZERODDS),
            key: Guid::new(prefix, EntityId::user_reader_with_key([0x0A, 0x0B, 0x0C])),
            participant_key: Guid::new(prefix, EntityId::PARTICIPANT),
            topic_name: "RxOTopic".into(),
            type_name: "RxOType".into(),
            durability: zerodds_qos::DurabilityKind::Volatile,
            reliability: zerodds_qos::ReliabilityQosPolicy {
                kind: zerodds_qos::ReliabilityKind::BestEffort,
                max_blocking_time: QosDuration::from_millis(100_i32),
            },
            ownership: zerodds_qos::OwnershipKind::Shared,
            liveliness: zerodds_qos::LivelinessQosPolicy::default(),
            deadline: zerodds_qos::DeadlineQosPolicy::default(),
            time_based_filter: zerodds_qos::TimeBasedFilterQosPolicy::default(),
            latency_budget: zerodds_qos::LatencyBudgetQosPolicy {
                duration: zerodds_qos::Duration::from_millis(latency_ms),
            },
            destination_order: zerodds_qos::DestinationOrderQosPolicy { kind: dest },
            presentation: Default::default(),
            partition: alloc::vec![],
            user_data: alloc::vec![],
            topic_data: alloc::vec![],
            group_data: alloc::vec![],
            type_consistency: zerodds_types::qos::TypeConsistencyEnforcement::default(),
            type_information: None,
            type_id_v1: None,
            type_object_v1: None,
            // Both representations. These fixtures exist to isolate one QoS
            // policy at a time, so the remote reader must accept whatever the
            // writer emits — an XCDR2-only list would make every case here fail
            // on DATA_REPRESENTATION before reaching the policy under test.
            data_representation: alloc::vec![0, 2],
            content_filter: None,
            security_info: None,
            sym_cipher_algo_info: None,
            data_tags: Default::default(),
            properties: Default::default(),
            service_instance_name: None,
            related_entity_guid: None,
            topic_aliases: None,
            type_identifier: zerodds_types::TypeIdentifier::None,
            unicast_locators: alloc::vec![Locator::udp_v4([127, 0, 0, 1], 7411)],
            multicast_locators: alloc::vec![],
            expects_inline_qos: false,
            group_guid: None,
            type_consistency_announced: true,
            entity_name: None,
        }
    }

