    /// A single-runtime harness on a UNIQUE domain per test — otherwise the
    /// same-process in-process discovery cross-matches the "RxOTopic"
    /// endpoints of the sibling RxO tests and inflates the matched count.
    fn rxo_runtime(seed: u8) -> Arc<DcpsRuntime> {
        DcpsRuntime::start(
            i32::from(seed),
            GuidPrefix::from_bytes([seed; 12]),
            RuntimeConfig::default(),
        )
        .expect("start runtime")
    }

    /// DDS 1.4 §2.2.4.1 InconsistentTopicStatus.total_count: "Total
    /// cumulative count of the Topics discovered whose name matches the
    /// Topic to which this status is attached and whose type is
    /// inconsistent with the Topic." Two refused endpoints of one remote
    /// participant are one Topic; another participant's is a second; the
    /// first participant left and came back is a third. Each refused pair
    /// counted.
    #[test]
    fn an_inconsistent_topic_counts_once_per_remote_participant() {
        let lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([0xC7; 12]),
            RuntimeConfig::default(),
        )
        .expect("start");
        let a = GuidPrefix::from_bytes([0xA1; 12]);
        let b = GuidPrefix::from_bytes([0xB2; 12]);
        let writer = |p: GuidPrefix, k: u8| Guid::new(p, EntityId::user_writer_with_key([k, 0, 0]));
        let reader = |p: GuidPrefix, k: u8| Guid::new(p, EntityId::user_reader_with_key([k, 0, 0]));
        rt.record_inconsistent_topic("Clash", writer(a, 1));
        rt.record_inconsistent_topic("Clash", reader(a, 2));
        assert_eq!(rt.inconsistent_topic_count_for("Clash"), 1);
        rt.record_inconsistent_topic("Clash", writer(b, 1));
        assert_eq!(rt.inconsistent_topic_count_for("Clash"), 2);
        rt.record_inconsistent_topic("Other", writer(a, 3));
        assert_eq!(rt.inconsistent_topic_count_for("Clash"), 2);
        assert_eq!(rt.inconsistent_topic_count_for("Other"), 1);
        rt.forget_inconsistent_topics_of(a);
        rt.record_inconsistent_topic("Clash", writer(a, 1));
        assert_eq!(rt.inconsistent_topic_count_for("Clash"), 3);
        rt.shutdown();
    }

    /// DDS 1.4 §2.2.3.7: an INFINITE offer satisfies only an INFINITE request.
    #[test]
    fn an_infinite_offer_satisfies_only_an_infinite_request() {
        assert!(deadline_compat(None, None));
        assert!(deadline_compat(Some(5), None));
        assert!(!deadline_compat(None, Some(5)));
        assert!(deadline_compat(Some(5), Some(5)));
        assert!(!deadline_compat(Some(6), Some(5)));
    }

    /// DDS 1.4 §2.2.3.7, §2.2.3.11: "offered deadline period <= requested
    /// deadline period". A period of 0 is the shortest: a request of 0 is
    /// met by an offer of 0 only. It counted as INFINITE and accepted every
    /// offer.
    #[test]
    fn a_request_of_zero_is_met_by_an_offer_of_zero_only() {
        let zero = zerodds_qos::Duration::from_secs(0);
        let one = zerodds_qos::Duration::from_secs(1);
        let inf = zerodds_qos::Duration::INFINITE;
        assert!(deadline_compat(rxo_nanos(zero), rxo_nanos(zero)));
        assert!(!deadline_compat(rxo_nanos(one), rxo_nanos(zero)));
        assert!(!deadline_compat(rxo_nanos(inf), rxo_nanos(zero)));
        assert!(deadline_compat(rxo_nanos(zero), rxo_nanos(one)));
        assert!(deadline_compat(rxo_nanos(zero), rxo_nanos(inf)));
    }

    /// A BEST_EFFORT writer and a RELIABLE reader of the same runtime do not
    /// match (DDS 1.4 §2.2.3.14), and both report RELIABILITY once — not
    /// again when another endpoint makes the runtime recompute its routes.
    #[test]
    fn a_same_runtime_pair_is_refused_for_an_rxo_policy_and_counted_once() {
        use crate::psm_constants::qos_policy_id as qid;
        let rt = rxo_runtime(0x3C);
        let writer = rt
            .register_user_writer(rxo_writer_cfg(
                zerodds_qos::DestinationOrderKind::ByReceptionTimestamp,
                0,
            ))
            .expect("writer");
        let (reader, _rx) = rt
            .register_user_reader(UserReaderConfig {
                reliable: true,
                ..rxo_reader_cfg(zerodds_qos::DestinationOrderKind::ByReceptionTimestamp, 0)
            })
            .expect("reader");
        assert_eq!(rt.user_writer_matched_count(writer), 0);
        assert_eq!(rt.user_reader_matched_count(reader), 0);
        let offered = rt.user_writer_offered_incompatible_qos(writer);
        let requested = rt.user_reader_requested_incompatible_qos(reader);
        assert_eq!(
            (offered.total_count, offered.last_policy_id),
            (1, qid::RELIABILITY)
        );
        assert_eq!(
            (requested.total_count, requested.last_policy_id),
            (1, qid::RELIABILITY)
        );

        let (_other, _rx2) = rt
            .register_user_reader(UserReaderConfig {
                topic_name: "OtherTopic".into(),
                ..Default::default()
            })
            .expect("another reader");
        assert_eq!(
            rt.user_writer_offered_incompatible_qos(writer).total_count,
            1
        );
        assert_eq!(
            rt.user_reader_requested_incompatible_qos(reader)
                .total_count,
            1
        );
        rt.shutdown();
    }

    // ---- set_qos once enabled: the changeable policies ----

    /// A runtime on a leased domain for the QoS-change tests; the lease
    /// lives as long as the test holds it.
    /// A runtime on a domain of its own, shut down when the test ends: a
    /// test that failed before its `shutdown` left the runtime running
    /// while the lease went back, so the next test on that domain could
    /// meet its endpoints.
    fn qos_change_runtime(seed: u8) -> (zerodds_test_domains::DomainLease, ShutsDown) {
        let lease = zerodds_test_domains::lease_domain();
        let rt = DcpsRuntime::start(
            lease.id(),
            GuidPrefix::from_bytes([seed; 12]),
            RuntimeConfig::default(),
        )
        .expect("start runtime");
        (lease, ShutsDown(rt))
    }

    /// A cached reader that the writer refuses for an RxO policy is counted
    /// once. Each matching pass meets every cached reader again, and DDS
    /// 1.4 §2.2.4.1 counts the times the writer discovered an incompatible
    /// reader.
    #[test]
    fn an_incompatible_remote_endpoint_is_counted_once() {
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x73);
        let w = rt
            .register_user_writer(rxo_writer_cfg(DO::ByReceptionTimestamp, 0))
            .expect("writer");
        let (r, _rx) = rt
            .register_user_reader(UserReaderConfig {
                topic_name: "RxOReaderSide".into(),
                ..rxo_reader_cfg(DO::BySourceTimestamp, 0)
            })
            .expect("reader");
        let now = rt.start_instant.elapsed();
        let mut remote_pub = rxo_remote_pub(DO::ByReceptionTimestamp, 0);
        remote_pub.topic_name = "RxOReaderSide".into();
        {
            let mut sedp = rt.sedp.lock().expect("sedp");
            sedp.cache_mut()
                .insert_subscription(rxo_remote_sub(DO::BySourceTimestamp, 0), now);
            sedp.cache_mut().insert_publication(remote_pub, now);
        }
        for _ in 0..3 {
            rt.match_local_writer_against_cache(w);
            rt.match_local_reader_against_cache(r);
        }
        assert_eq!(rt.user_writer_offered_incompatible_qos(w).total_count, 1);
        assert_eq!(rt.user_reader_requested_incompatible_qos(r).total_count, 1);
        rt.shutdown();
    }

    /// DDSI-RTPS 2.5 §8.4.7.5 Table 8.61 and §8.4.10.4 Table 8.72: the proxy
    /// of a matched remote endpoint carries `remoteGroupEntityId`, the
    /// entity id of the group in the endpoint's `PID_GROUP_GUID`.
    #[test]
    fn the_proxies_of_a_match_carry_the_remote_group_entity_id() {
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x7B);
        let w = rt
            .register_user_writer(rxo_writer_cfg(DO::ByReceptionTimestamp, 0))
            .expect("writer");
        let (r, _rx) = rt
            .register_user_reader(UserReaderConfig {
                topic_name: "RxOReaderSide".into(),
                ..rxo_reader_cfg(DO::ByReceptionTimestamp, 0)
            })
            .expect("reader");
        let sub_group = EntityId::user_reader_with_key([0x5A, 0x5B, 0x5C]);
        let pub_group = EntityId::user_writer_with_key([0x6A, 0x6B, 0x6C]);
        let mut remote_sub = rxo_remote_sub(DO::ByReceptionTimestamp, 0);
        remote_sub.group_guid = Some(Guid::new(remote_sub.key.prefix, sub_group));
        let mut remote_pub = rxo_remote_pub(DO::ByReceptionTimestamp, 0);
        remote_pub.topic_name = "RxOReaderSide".into();
        remote_pub.group_guid = Some(Guid::new(remote_pub.key.prefix, pub_group));
        let now = rt.start_instant.elapsed();
        {
            let mut sedp = rt.sedp.lock().expect("sedp");
            sedp.cache_mut().insert_subscription(remote_sub, now);
            sedp.cache_mut().insert_publication(remote_pub, now);
        }
        rt.match_local_writer_against_cache(w);
        rt.match_local_reader_against_cache(r);
        let slot = rt.writer_slot(w).expect("writer slot");
        let slot = slot.lock().expect("lock");
        assert_eq!(slot.writer.reader_proxies().len(), 1);
        assert_eq!(
            slot.writer.reader_proxies()[0].remote_group_entity_id,
            sub_group
        );
        drop(slot);
        let slot = rt.reader_slot(r).expect("reader slot");
        let slot = slot.lock().expect("lock");
        assert_eq!(slot.reader.writer_proxies().len(), 1);
        assert_eq!(
            slot.reader.writer_proxies()[0].proxy.remote_group_entity_id,
            pub_group
        );
        drop(slot);
        rt.shutdown();
    }

    /// DDSI-RTPS 2.5 §8.4.14.1: the fragment size of a user writer follows the
    /// maximum message size of the transport it sends over, fixed at its
    /// creation: 1344 at the UDP default of 1472, 8872 for 9000.
    #[test]
    fn a_writers_fragment_size_follows_the_message_size_of_its_transport() {
        let size_of = |seed: u8, max_message_size: Option<usize>| {
            let lease = zerodds_test_domains::lease_domain();
            let mut config = RuntimeConfig::default();
            if let Some(n) = max_message_size {
                config.udp.max_message_size = n;
            }
            let rt = DcpsRuntime::start(lease.id(), GuidPrefix::from_bytes([seed; 12]), config)
                .expect("start runtime");
            let w = rt
                .register_user_writer(UserWriterConfig {
                    topic_name: "FragmentSizeTopic".into(),
                    type_name: "FragmentSizeType".into(),
                    ..Default::default()
                })
                .expect("writer");
            let slot = rt.writer_slot(w).expect("slot");
            let size = slot.lock().expect("lock").writer.fragment_size();
            rt.shutdown();
            size
        };
        assert_eq!(
            size_of(0x7C, None),
            zerodds_rtps::reliable_writer::DEFAULT_FRAGMENT_SIZE
        );
        assert_eq!(size_of(0x7D, Some(9000)), 8872);
    }

    /// A writer that raises its LATENCY_BUDGET past what a matched reader
    /// requests is unmatched, and the reader is counted (DDS 1.4 §2.2.3:
    /// RxO and changeable). Lowering it again matches the pair again.
    #[test]
    fn a_writer_qos_change_is_decided_again_against_a_matched_reader() {
        use crate::psm_constants::qos_policy_id as qid;
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x74);
        let w = rt
            .register_user_writer(rxo_writer_cfg(DO::ByReceptionTimestamp, 0))
            .expect("writer");
        let now = rt.start_instant.elapsed();
        rt.sedp
            .lock()
            .expect("sedp")
            .cache_mut()
            .insert_subscription(rxo_remote_sub(DO::ByReceptionTimestamp, 10), now);
        rt.match_local_writer_against_cache(w);
        assert_eq!(rt.user_writer_matched_count(w), 1);

        let mut update = rt.user_writer_qos(w).expect("announced writer");
        update.latency_budget.duration = zerodds_qos::Duration::from_millis(50);
        rt.update_user_writer_qos(w, &update).expect("raise");
        assert_eq!(rt.user_writer_matched_count(w), 0);
        let status = rt.user_writer_offered_incompatible_qos(w);
        assert_eq!(
            (status.total_count, status.last_policy_id),
            (1, qid::LATENCY_BUDGET)
        );

        update.latency_budget.duration = zerodds_qos::Duration::from_millis(0);
        rt.update_user_writer_qos(w, &update).expect("lower");
        assert_eq!(rt.user_writer_matched_count(w), 1);
        assert_eq!(rt.user_writer_offered_incompatible_qos(w).total_count, 1);
        rt.shutdown();
    }

    /// A writer that moves to a partition its matched reader is not in is
    /// unmatched without a status (DDS 1.4 §2.2.3.13), and its next
    /// announcement carries the move and the other changed values.
    #[test]
    fn a_partition_change_unmatches_without_a_status_and_is_announced() {
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x75);
        let w = rt
            .register_user_writer(rxo_writer_cfg(DO::ByReceptionTimestamp, 0))
            .expect("writer");
        let now = rt.start_instant.elapsed();
        rt.sedp
            .lock()
            .expect("sedp")
            .cache_mut()
            .insert_subscription(rxo_remote_sub(DO::ByReceptionTimestamp, 0), now);
        rt.match_local_writer_against_cache(w);
        assert_eq!(rt.user_writer_matched_count(w), 1);

        let mut update = rt.user_writer_qos(w).expect("announced writer");
        update.own.partition = alloc::vec!["Elsewhere".to_string()];
        update.user_data = alloc::vec![1, 2, 3];
        update.ownership_strength = 4;
        rt.update_user_writer_qos(w, &update).expect("update");
        assert_eq!(rt.user_writer_matched_count(w), 0);
        assert_eq!(rt.user_writer_offered_incompatible_qos(w).total_count, 0);
        let announced = rt.latest_announced_publication(w).expect("announced");
        assert_eq!(announced.partition, alloc::vec!["Elsewhere".to_string()]);
        assert_eq!(announced.user_data, alloc::vec![1, 2, 3]);
        assert_eq!(announced.ownership_strength, 4);
        assert_eq!(rt.user_writer_qos(w), Some(update));
        rt.shutdown();
    }

    /// PARTITION, GROUP_DATA and TOPIC_DATA come from the writer where it
    /// sets them and from its publisher and topic where not, and a change
    /// on the publisher or the topic reaches the announcement.
    #[test]
    fn group_and_topic_values_reach_a_writer_that_sets_none_of_its_own() {
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x76);
        let w = rt
            .register_user_writer_inheriting(
                rxo_writer_cfg(DO::ByReceptionTimestamp, 0),
                true,
                GroupTopicQos {
                    partition: alloc::vec!["G".to_string()],
                    group_data: alloc::vec![7],
                    topic_data: alloc::vec![9],
                },
            )
            .expect("writer");
        let shared = |rt: &DcpsRuntime| {
            let a = rt.latest_announced_publication(w).expect("announced");
            (a.partition, a.group_data, a.topic_data)
        };
        assert_eq!(
            shared(&rt),
            (alloc::vec!["G".to_string()], alloc::vec![7], alloc::vec![9])
        );
        rt.update_user_group_qos(w, &["H".to_string()], &[8])
            .expect("group");
        rt.update_user_topic_data("RxOTopic", &[10]).expect("topic");
        assert_eq!(
            shared(&rt),
            (
                alloc::vec!["H".to_string()],
                alloc::vec![8],
                alloc::vec![10]
            )
        );
        // The writer's own value wins over the publisher's.
        let mut update = rt.user_writer_qos(w).expect("announced writer");
        update.own.partition = alloc::vec!["Own".to_string()];
        rt.update_user_writer_qos(w, &update).expect("own");
        rt.update_user_group_qos(w, &["I".to_string()], &[8])
            .expect("group again");
        assert_eq!(shared(&rt).0, alloc::vec!["Own".to_string()]);
        rt.shutdown();
    }

    /// A matched writer that announces a new OWNERSHIP_STRENGTH and
    /// LIFESPAN is taken up by the reader; the first match alone used to
    /// set them.
    #[test]
    fn a_matched_writer_announcing_new_strength_and_lifespan_is_taken_up() {
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x77);
        let (r, _rx) = rt
            .register_user_reader(rxo_reader_cfg(DO::ByReceptionTimestamp, 10))
            .expect("reader");
        let mut remote = rxo_remote_pub(DO::ByReceptionTimestamp, 0);
        remote.ownership_strength = 1;
        let now = rt.start_instant.elapsed();
        rt.sedp
            .lock()
            .expect("sedp")
            .cache_mut()
            .insert_publication(remote.clone(), now);
        rt.match_local_reader_against_cache(r);
        assert_eq!(rt.user_reader_matched_count(r), 1);

        remote.ownership_strength = 9;
        remote.lifespan.duration = zerodds_qos::Duration::from_millis(300);
        rt.sedp
            .lock()
            .expect("sedp")
            .cache_mut()
            .insert_publication(remote.clone(), now);
        rt.match_local_reader_against_cache(r);
        let slot = rt.reader_slot(r).expect("reader slot");
        let slot = slot.lock().expect("reader slot lock");
        let key = remote.key.to_bytes();
        assert_eq!(slot.writer_strengths.get(&key), Some(&9));
        assert_eq!(slot.writer_lifespans.get(&key), Some(&300_000_000));
        drop(slot);
        rt.shutdown();
    }

    /// Announces the participant `prefix` to `rt` with a default unicast
    /// locator, so a remote endpoint of it that announces no locator of its
    /// own is reached through the participant cache (DDSI-RTPS 2.5 §8.5.5).
    fn announce_participant_with_a_default_locator(rt: &Arc<DcpsRuntime>, prefix: GuidPrefix) {
        let participant = zerodds_rtps::participant_data::ParticipantBuiltinTopicData {
            guid: Guid::new(prefix, EntityId::PARTICIPANT),
            protocol_version: zerodds_rtps::wire_types::ProtocolVersion::V2_5,
            vendor_id: VendorId::ZERODDS,
            default_unicast_locators: alloc::vec![Locator::udp_v4([127, 0, 0, 1], 27511)],
            default_multicast_locators: Vec::new(),
            metatraffic_unicast_locators: Vec::new(),
            metatraffic_multicast_locators: Vec::new(),
            domain_id: None,
            domain_tag: Default::default(),
            builtin_endpoint_set: 0,
            lease_duration: zerodds_rtps::participant_data::Duration::from_secs(100),
            user_data: Vec::new(),
            properties: Default::default(),
            identity_token: None,
            permissions_token: None,
            identity_status_token: None,
            sig_algo_info: None,
            kx_algo_info: None,
            sym_cipher_algo_info: None,
            available_builtin_endpoints_ext: 0,
            participant_security_info: None,
            expects_inline_qos: false,
            manual_liveliness_count: None,
            builtin_endpoint_qos: None,
            entity_name: None,
        };
        let beacon = zerodds_discovery::spdp::SpdpBeacon::new(participant)
            .serialize()
            .expect("serialize SPDP");
        handle_spdp_datagram_for_test(rt, &beacon);
    }

    /// DDS 1.4 §2.2.2.2.1.16: once `ignore_publication` returned, "any data
    /// received related to that publication will be ignored". A matching
    /// pass that was under way when the call came had looked at the filter
    /// before it and waited for the participant cache; the call took the
    /// match out, and the pass then wired the writer anew, until its second
    /// look at the filter took it out again. In that window the ignored
    /// writer's samples were delivered — measured in
    /// `ignore_entities.rs::ignore_topic_unmatches_the_endpoints_of_the_topic`
    /// on the Linux test host, 2 of 200 runs: a valid sample, then the
    /// NOT_ALIVE_NO_WRITERS marker of the second departure. Here the test
    /// holds the participant cache, so the pass waits exactly there.
    #[test]
    fn a_writer_ignored_while_a_matching_pass_waits_is_not_matched_by_that_pass() {
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x7C);
        let filter = crate::participant::IgnoreFilter::default();
        rt.attach_ignore_filter(filter.clone());
        let (r, _rx) = rt
            .register_user_reader(rxo_reader_cfg(DO::ByReceptionTimestamp, 10))
            .expect("reader");
        let mut remote = rxo_remote_pub(DO::ByReceptionTimestamp, 0);
        remote.unicast_locators = Vec::new();
        announce_participant_with_a_default_locator(&rt, remote.key.prefix);
        let now = rt.start_instant.elapsed();
        rt.sedp
            .lock()
            .expect("sedp")
            .cache_mut()
            .insert_publication(remote.clone(), now);
        rt.match_local_reader_against_cache(r);
        let handle = crate::instance_handle::InstanceHandle::from_guid(remote.key);
        assert!(
            rt.user_reader_matched_publication_handles(r)
                .contains(&handle)
        );

        let held = rt.discovered.lock().expect("participant cache");
        let pass = {
            let (rt, remote) = (Arc::clone(&rt), remote.clone());
            std::thread::spawn(move || rt.wire_reader_to_remote_writer(r, &remote))
        };
        std::thread::sleep(core::time::Duration::from_millis(100));
        filter
            .inner
            .publications
            .lock()
            .expect("filter")
            .insert(handle);
        rt.disconnect_ignored(Ignored::Publication(handle));
        assert!(
            !rt.user_reader_matched_publication_handles(r)
                .contains(&handle)
        );
        let departures = |rt: &DcpsRuntime| {
            rt.reader_slot(r)
                .expect("reader slot")
                .lock()
                .expect("reader slot lock")
                .departures_noted
        };
        let after_the_ignore = departures(&rt);
        let matched_again = {
            let rt = Arc::clone(&rt);
            std::thread::spawn(move || rt.wait_match_event(core::time::Duration::from_millis(500)))
        };
        std::thread::sleep(core::time::Duration::from_millis(50));
        drop(held);
        pass.join().expect("matching pass");
        assert!(
            !matched_again.join().expect("watcher"),
            "the pass matched the ignored writer again"
        );
        assert_eq!(
            departures(&rt),
            after_the_ignore,
            "the ignored writer departed a second time"
        );
        assert!(
            !rt.user_reader_matched_publication_handles(r)
                .contains(&handle)
        );
    }

    /// The writer's half of
    /// [`a_writer_ignored_while_a_matching_pass_waits_is_not_matched_by_that_pass`]:
    /// `ignore_subscription` (§2.2.2.2.1.17) while a pass waits.
    #[test]
    fn a_reader_ignored_while_a_matching_pass_waits_is_not_matched_by_that_pass() {
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x7D);
        let filter = crate::participant::IgnoreFilter::default();
        rt.attach_ignore_filter(filter.clone());
        let w = rt
            .register_user_writer(rxo_writer_cfg(DO::ByReceptionTimestamp, 10))
            .expect("writer");
        let mut remote = rxo_remote_sub(DO::ByReceptionTimestamp, 10);
        remote.unicast_locators = Vec::new();
        announce_participant_with_a_default_locator(&rt, remote.key.prefix);
        let now = rt.start_instant.elapsed();
        rt.sedp
            .lock()
            .expect("sedp")
            .cache_mut()
            .insert_subscription(remote.clone(), now);
        rt.match_local_writer_against_cache(w);
        let handle = crate::instance_handle::InstanceHandle::from_guid(remote.key);
        assert!(
            rt.user_writer_matched_subscription_handles(w)
                .contains(&handle)
        );

        let held = rt.discovered.lock().expect("participant cache");
        let pass = {
            let (rt, remote) = (Arc::clone(&rt), remote.clone());
            std::thread::spawn(move || rt.wire_writer_to_remote_reader(w, &remote))
        };
        std::thread::sleep(core::time::Duration::from_millis(100));
        filter
            .inner
            .subscriptions
            .lock()
            .expect("filter")
            .insert(handle);
        rt.disconnect_ignored(Ignored::Subscription(handle));
        assert!(
            !rt.user_writer_matched_subscription_handles(w)
                .contains(&handle)
        );
        let matched_again = {
            let rt = Arc::clone(&rt);
            std::thread::spawn(move || rt.wait_match_event(core::time::Duration::from_millis(500)))
        };
        std::thread::sleep(core::time::Duration::from_millis(50));
        drop(held);
        pass.join().expect("matching pass");
        assert!(
            !matched_again.join().expect("watcher"),
            "the pass matched the ignored reader again"
        );
        assert!(
            !rt.user_writer_matched_subscription_handles(w)
                .contains(&handle)
        );
    }

    /// A reader that asks for a shorter DEADLINE than its matched writer
    /// offers is unmatched and counts the writer (DDS 1.4 §2.2.3.7).
    #[test]
    fn a_reader_qos_change_is_decided_again_against_a_matched_writer() {
        use crate::psm_constants::qos_policy_id as qid;
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x78);
        let (r, _rx) = rt
            .register_user_reader(rxo_reader_cfg(DO::ByReceptionTimestamp, 10))
            .expect("reader");
        let mut remote = rxo_remote_pub(DO::ByReceptionTimestamp, 0);
        remote.deadline.period = zerodds_qos::Duration::from_millis(100);
        let now = rt.start_instant.elapsed();
        rt.sedp
            .lock()
            .expect("sedp")
            .cache_mut()
            .insert_publication(remote, now);
        rt.match_local_reader_against_cache(r);
        assert_eq!(rt.user_reader_matched_count(r), 1);

        let mut update = rt.user_reader_qos(r).expect("announced reader");
        update.deadline.period = zerodds_qos::Duration::from_millis(50);
        rt.update_user_reader_qos(r, &update).expect("update");
        assert_eq!(rt.user_reader_matched_count(r), 0);
        let status = rt.user_reader_requested_incompatible_qos(r);
        assert_eq!(
            (status.total_count, status.last_policy_id),
            (1, qid::DEADLINE)
        );
        rt.shutdown();
    }

    /// TIME_BASED_FILTER goes out in the subscription (DDS 1.4 §2.2.5),
    /// and a change of it is announced again.
    #[test]
    fn a_readers_time_based_filter_is_announced_and_follows_a_change() {
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x7A);
        let tbf = |ms| zerodds_qos::TimeBasedFilterQosPolicy {
            minimum_separation: zerodds_qos::Duration::from_millis(ms),
        };
        let (r, _rx) = rt
            .register_user_reader(UserReaderConfig {
                time_based_filter: tbf(40),
                ..rxo_reader_cfg(DO::ByReceptionTimestamp, 0)
            })
            .expect("reader");
        let announced = |rt: &DcpsRuntime| {
            rt.latest_announced_subscription(r)
                .expect("announced")
                .time_based_filter
        };
        assert_eq!(announced(&rt), tbf(40));
        let mut update = rt.user_reader_qos(r).expect("announced reader");
        update.time_based_filter = tbf(80);
        rt.update_user_reader_qos(r, &update).expect("update");
        assert_eq!(announced(&rt), tbf(80));
        rt.shutdown();
    }

    /// A writer and a reader of one runtime follow the same rules: a
    /// partition change on either side rebuilds their route.
    #[test]
    fn a_partition_change_moves_a_same_runtime_pair_apart_and_together() {
        use zerodds_qos::DestinationOrderKind as DO;
        let (_lease, rt) = qos_change_runtime(0x79);
        let w = rt
            .register_user_writer(rxo_writer_cfg(DO::ByReceptionTimestamp, 0))
            .expect("writer");
        let (r, _rx) = rt
            .register_user_reader(rxo_reader_cfg(DO::ByReceptionTimestamp, 0))
            .expect("reader");
        assert_eq!(rt.user_writer_matched_count(w), 1);

        let mut reader_update = rt.user_reader_qos(r).expect("announced reader");
        reader_update.own.partition = alloc::vec!["B".to_string()];
        rt.update_user_reader_qos(r, &reader_update)
            .expect("reader moves");
        assert_eq!(rt.user_writer_matched_count(w), 0);

        let mut writer_update = rt.user_writer_qos(w).expect("announced writer");
        writer_update.own.partition = alloc::vec!["B".to_string()];
        rt.update_user_writer_qos(w, &writer_update)
            .expect("writer follows");
        assert_eq!(rt.user_writer_matched_count(w), 1);
        rt.shutdown();
    }

    // ---- offered side (writer matcher) — DESTINATION_ORDER ----

    #[test]
    fn rxo_offered_destination_order_incompatible_rejects_match() {
        use zerodds_qos::DestinationOrderKind as DO;
        let rt = rxo_runtime(0x40);
        // Writer offers BY_RECEPTION, remote reader requests BY_SOURCE:
        // offered(0) >= requested(1) is false → incompatible.
        let w = rt
            .register_user_writer(rxo_writer_cfg(DO::ByReceptionTimestamp, 0))
            .expect("writer");
        let sub = rxo_remote_sub(DO::BySourceTimestamp, 0);
        let now = rt.start_instant.elapsed();
        {
            let mut sedp = rt.sedp.lock().expect("sedp");
            sedp.cache_mut().insert_subscription(sub, now);
        }
        rt.match_local_writer_against_cache(w);

        let status = rt.user_writer_offered_incompatible_qos(w);
        assert_eq!(
            rt.user_writer_matched_count(w),
            0,
            "incompatible DESTINATION_ORDER must not match"
        );
        assert!(status.total_count >= 1, "expected an incompatible-qos bump");
        assert_eq!(
            status.last_policy_id,
            crate::psm_constants::qos_policy_id::DESTINATION_ORDER
        );
        rt.shutdown();
    }

