    // ========================================================================
    // RxO matching for PRESENTATION (DDS 1.4 §2.2.3.6) and the deliberate
    // non-RxO handling of PARTITION (§2.2.3.13) in the same matcher.
    //
    // §2.2.3.6, "The value offered is considered compatible with the value
    // requested if and only if":
    //   1. "offered access_scope >= requested access_scope" … "the values of
    //      PRESENTATION access_scope are considered ordered such that
    //      INSTANCE < TOPIC < GROUP";
    //   2. "Requested coherent_access is FALSE, or else both offered and
    //      requested coherent_access are TRUE";
    //   3. "Requested ordered_access is FALSE, or else both offered and
    //      requested ordered_access are TRUE".
    // On failure §2.2.4.1 requires OFFERED_INCOMPATIBLE_QOS /
    // REQUESTED_INCOMPATIBLE_QOS carrying "the QosPolicyId_t of one of the
    // policies that was found to be incompatible" — and no match.
    //
    // §2.2.3.13 for PARTITION: "Failure to match partitions is not considered
    // an 'incompatible' QoS and does not trigger any listeners nor
    // conditions." The listener bubble-up is delta-driven off
    // `total_count` (`Publisher::poll_offered_incompatible_qos` /
    // `Subscriber::poll_requested_incompatible_qos`), so `total_count == 0`
    // is exactly "no event fired".
    // ========================================================================

    fn presentation(
        scope: zerodds_qos::PresentationAccessScope,
        coherent: bool,
        ordered: bool,
    ) -> zerodds_qos::PresentationQosPolicy {
        zerodds_qos::PresentationQosPolicy {
            access_scope: scope,
            coherent_access: coherent,
            ordered_access: ordered,
        }
    }

    /// Writer offering `offered`, remote reader requesting `requested`.
    /// Returns `(matched_count, status)`.
    fn rxo_presentation_offered(
        seed: u8,
        offered: zerodds_qos::PresentationQosPolicy,
        requested: zerodds_qos::PresentationQosPolicy,
    ) -> (usize, crate::status::OfferedIncompatibleQosStatus) {
        use zerodds_qos::DestinationOrderKind as DO;
        let rt = rxo_runtime(seed);
        let mut wcfg = rxo_writer_cfg(DO::ByReceptionTimestamp, 0);
        wcfg.presentation = offered;
        let w = rt.register_user_writer(wcfg).expect("writer");
        let mut sub = rxo_remote_sub(DO::ByReceptionTimestamp, 0);
        sub.presentation = requested;
        let now = rt.start_instant.elapsed();
        {
            let mut sedp = rt.sedp.lock().expect("sedp");
            sedp.cache_mut().insert_subscription(sub, now);
        }
        rt.match_local_writer_against_cache(w);
        let out = (
            rt.user_writer_matched_count(w),
            rt.user_writer_offered_incompatible_qos(w),
        );
        rt.shutdown();
        out
    }

    /// Reader requesting `requested`, remote writer offering `offered`.
    fn rxo_presentation_requested(
        seed: u8,
        offered: zerodds_qos::PresentationQosPolicy,
        requested: zerodds_qos::PresentationQosPolicy,
    ) -> (usize, crate::status::RequestedIncompatibleQosStatus) {
        use zerodds_qos::DestinationOrderKind as DO;
        let rt = rxo_runtime(seed);
        let mut rcfg = rxo_reader_cfg(DO::ByReceptionTimestamp, 0);
        rcfg.presentation = requested;
        let (r, _rx) = rt.register_user_reader(rcfg).expect("reader");
        let mut pubd = rxo_remote_pub(DO::ByReceptionTimestamp, 0);
        pubd.presentation = offered;
        let now = rt.start_instant.elapsed();
        {
            let mut sedp = rt.sedp.lock().expect("sedp");
            sedp.cache_mut().insert_publication(pubd, now);
        }
        rt.match_local_reader_against_cache(r);
        let out = (
            rt.user_reader_matched_count(r),
            rt.user_reader_requested_incompatible_qos(r),
        );
        rt.shutdown();
        out
    }

    fn policy_count(policies: &[crate::status::QosPolicyCount], pid: u32) -> i32 {
        policies
            .iter()
            .find(|p| p.policy_id == pid)
            .map_or(0, |p| p.count)
    }

    // ---- axis 1: access_scope (INSTANCE < TOPIC < GROUP) ----

    /// §2.2.3.6 condition 1 violated: offered INSTANCE < requested TOPIC.
    #[test]
    fn rxo_presentation_access_scope_below_request_rejects_on_both_sides() {
        use zerodds_qos::PresentationAccessScope as S;
        let pid = crate::psm_constants::qos_policy_id::PRESENTATION;
        let offered = presentation(S::Instance, false, false);
        let requested = presentation(S::Topic, false, false);

        let (matched, offered_status) = rxo_presentation_offered(0x47, offered, requested);
        assert_eq!(
            matched, 0,
            "offered INSTANCE < requested TOPIC must not match"
        );
        assert!(offered_status.total_count >= 1);
        assert_eq!(offered_status.last_policy_id, pid);
        assert!(policy_count(&offered_status.policies, pid) >= 1);

        let (matched, requested_status) = rxo_presentation_requested(0x48, offered, requested);
        assert_eq!(matched, 0, "the reader side must reject symmetrically");
        assert!(requested_status.total_count >= 1);
        assert_eq!(requested_status.last_policy_id, pid);
        assert!(policy_count(&requested_status.policies, pid) >= 1);
    }

    /// §2.2.3.6 condition 1 satisfied: offered GROUP >= requested TOPIC.
    #[test]
    fn rxo_presentation_access_scope_above_request_matches() {
        use zerodds_qos::PresentationAccessScope as S;
        let offered = presentation(S::Group, false, false);
        let requested = presentation(S::Topic, false, false);

        let (matched, status) = rxo_presentation_offered(0x49, offered, requested);
        assert_eq!(matched, 1, "offered GROUP >= requested TOPIC must match");
        assert_eq!(status.total_count, 0);

        let (matched, status) = rxo_presentation_requested(0x4A, offered, requested);
        assert_eq!(matched, 1);
        assert_eq!(status.total_count, 0);
    }

    // ---- axis 2: coherent_access ----

    /// §2.2.3.6 condition 2 violated: requested coherent_access is TRUE while
    /// the offered one is FALSE.
    #[test]
    fn rxo_presentation_coherent_access_unoffered_rejects_on_both_sides() {
        use zerodds_qos::PresentationAccessScope as S;
        let pid = crate::psm_constants::qos_policy_id::PRESENTATION;
        let offered = presentation(S::Topic, false, false);
        let requested = presentation(S::Topic, true, false);

        let (matched, offered_status) = rxo_presentation_offered(0x4B, offered, requested);
        assert_eq!(matched, 0, "requested coherent_access must be offered");
        assert_eq!(offered_status.last_policy_id, pid);
        assert!(policy_count(&offered_status.policies, pid) >= 1);

        let (matched, requested_status) = rxo_presentation_requested(0x4C, offered, requested);
        assert_eq!(matched, 0);
        assert_eq!(requested_status.last_policy_id, pid);
        assert!(policy_count(&requested_status.policies, pid) >= 1);
    }

    /// §2.2.3.6 condition 2 satisfied: both TRUE.
    #[test]
    fn rxo_presentation_coherent_access_offered_matches() {
        use zerodds_qos::PresentationAccessScope as S;
        let both = presentation(S::Topic, true, false);
        let (matched, status) = rxo_presentation_offered(0x4D, both, both);
        assert_eq!(matched, 1);
        assert_eq!(status.total_count, 0);
        let (matched, status) = rxo_presentation_requested(0x4E, both, both);
        assert_eq!(matched, 1);
        assert_eq!(status.total_count, 0);
    }

    // ---- axis 3: ordered_access ----

    /// §2.2.3.6 condition 3 violated: requested ordered_access is TRUE while
    /// the offered one is FALSE.
    #[test]
    fn rxo_presentation_ordered_access_unoffered_rejects_on_both_sides() {
        use zerodds_qos::PresentationAccessScope as S;
        let pid = crate::psm_constants::qos_policy_id::PRESENTATION;
        let offered = presentation(S::Topic, false, false);
        let requested = presentation(S::Topic, false, true);

        let (matched, offered_status) = rxo_presentation_offered(0x50, offered, requested);
        assert_eq!(matched, 0, "requested ordered_access must be offered");
        assert_eq!(offered_status.last_policy_id, pid);
        assert!(policy_count(&offered_status.policies, pid) >= 1);

        let (matched, requested_status) = rxo_presentation_requested(0x51, offered, requested);
        assert_eq!(matched, 0);
        assert_eq!(requested_status.last_policy_id, pid);
        assert!(policy_count(&requested_status.policies, pid) >= 1);
    }

    /// §2.2.3.6 condition 3 satisfied: both TRUE.
    #[test]
    fn rxo_presentation_ordered_access_offered_matches() {
        use zerodds_qos::PresentationAccessScope as S;
        let both = presentation(S::Topic, false, true);
        let (matched, status) = rxo_presentation_offered(0x52, both, both);
        assert_eq!(matched, 1);
        assert_eq!(status.total_count, 0);
        let (matched, status) = rxo_presentation_requested(0x53, both, both);
        assert_eq!(matched, 1);
        assert_eq!(status.total_count, 0);
    }

    // ---- PARTITION: no match, and explicitly NO event ----

    /// §2.2.3.13: disjoint partitions must not associate — and must not
    /// report an incompatible QoS. A `bump()` here would raise `total_count`,
    /// which is precisely what makes the listener fire, so the assertion on
    /// `total_count == 0` is the assertion that no event is dispatched.
    #[test]
    fn partition_mismatch_blocks_match_without_any_incompatible_qos_event() {
        use zerodds_qos::DestinationOrderKind as DO;
        let pid = crate::psm_constants::qos_policy_id::PARTITION;

        // Offered side: local writer in ["A"], remote reader in ["B"].
        let rt = rxo_runtime(0x54);
        let mut wcfg = rxo_writer_cfg(DO::ByReceptionTimestamp, 0);
        wcfg.partition = alloc::vec!["A".into()];
        let w = rt.register_user_writer(wcfg).expect("writer");
        let mut sub = rxo_remote_sub(DO::ByReceptionTimestamp, 0);
        sub.partition = alloc::vec!["B".into()];
        let now = rt.start_instant.elapsed();
        {
            let mut sedp = rt.sedp.lock().expect("sedp");
            sedp.cache_mut().insert_subscription(sub, now);
        }
        rt.match_local_writer_against_cache(w);
        let status = rt.user_writer_offered_incompatible_qos(w);
        assert_eq!(
            rt.user_writer_matched_count(w),
            0,
            "partitions [A] vs [B] must not associate"
        );
        assert_eq!(
            status.total_count, 0,
            "PARTITION is not an RxO policy — no OFFERED_INCOMPATIBLE_QOS"
        );
        assert_eq!(status.last_policy_id, 0);
        assert_eq!(policy_count(&status.policies, pid), 0);
        rt.shutdown();

        // Requested side: local reader in ["B"], remote writer in ["A"].
        let rt = rxo_runtime(0x55);
        let mut rcfg = rxo_reader_cfg(DO::ByReceptionTimestamp, 0);
        rcfg.partition = alloc::vec!["B".into()];
        let (r, _rx) = rt.register_user_reader(rcfg).expect("reader");
        let mut pubd = rxo_remote_pub(DO::ByReceptionTimestamp, 0);
        pubd.partition = alloc::vec!["A".into()];
        let now = rt.start_instant.elapsed();
        {
            let mut sedp = rt.sedp.lock().expect("sedp");
            sedp.cache_mut().insert_publication(pubd, now);
        }
        rt.match_local_reader_against_cache(r);
        let status = rt.user_reader_requested_incompatible_qos(r);
        assert_eq!(rt.user_reader_matched_count(r), 0);
        assert_eq!(
            status.total_count, 0,
            "PARTITION is not an RxO policy — no REQUESTED_INCOMPATIBLE_QOS"
        );
        assert_eq!(status.last_policy_id, 0);
        assert_eq!(policy_count(&status.policies, pid), 0);
        rt.shutdown();
    }

    // ========================================================================
    // The announced value is the GROUP's (DDS 1.4 §2.2.3.6 / §2.2.3.13).
    //
    // PRESENTATION and PARTITION are Publisher/Subscriber policies; the value
    // the RxO check above compares is the one this endpoint put into its
    // `PublicationBuiltinTopicData` / `SubscriptionBuiltinTopicData`
    // (DDSI-RTPS 2.5 §8.5.3.2/§8.5.3.3). These tests drive the real DCPS API
    // (`Publisher::create_datawriter` / `Subscriber::create_datareader`) and
    // then run the matcher against an injected remote endpoint, so they fail
    // if the group's value never reaches the announcement.
    //
    // `Test_OrderedAccess_1` and `Test_CoherentSets_1` of the OMG `dds-rtps`
    // suite are exactly `presentation_from_subscriber_is_what_the_reader_
    // requests`: a publisher at INSTANCE scope and a subscriber at TOPIC
    // scope, expected to report INCOMPATIBLE_QOS on both ends.
    // ========================================================================

    /// A remote reader on `(topic, type)` requesting `requested`.
    fn group_remote_sub(
        topic: &str,
        type_name: &str,
        requested: zerodds_qos::PresentationQosPolicy,
        partition: Vec<String>,
    ) -> zerodds_rtps::subscription_data::SubscriptionBuiltinTopicData {
        let mut sub = rxo_remote_sub(zerodds_qos::DestinationOrderKind::ByReceptionTimestamp, 0);
        sub.topic_name = topic.into();
        sub.type_name = type_name.into();
        sub.presentation = requested;
        sub.partition = partition;
        sub
    }

    /// A remote writer on `(topic, type)` offering `offered`.
    fn group_remote_pub(
        topic: &str,
        type_name: &str,
        offered: zerodds_qos::PresentationQosPolicy,
        partition: Vec<String>,
    ) -> zerodds_rtps::publication_data::PublicationBuiltinTopicData {
        let mut pubd = rxo_remote_pub(zerodds_qos::DestinationOrderKind::ByReceptionTimestamp, 0);
        pubd.topic_name = topic.into();
        pubd.type_name = type_name.into();
        pubd.presentation = offered;
        pubd.partition = partition;
        pubd
    }

    fn group_test_config() -> RuntimeConfig {
        RuntimeConfig {
            tick_period: core::time::Duration::from_millis(20),
            spdp_period: core::time::Duration::from_millis(100),
            ..RuntimeConfig::default()
        }
    }

    /// §2.2.3.6: the offered value is the **Publisher's**. A DataWriter
    /// created with a default `DataWriterQos` on a GROUP-scope Publisher
    /// offers GROUP, which satisfies a remote reader requesting TOPIC.
    /// Announcing the `DataWriterQos` default (INSTANCE) instead rejects the
    /// match — that is the failure this test pins.
    #[test]
    fn presentation_from_publisher_is_what_the_writer_offers() {
        use zerodds_qos::PresentationAccessScope as S;
        let domain_lease = zerodds_test_domains::lease_domain();
        let participant = crate::DomainParticipantFactory::instance()
            .create_participant_with_config(
                domain_lease.id(),
                crate::DomainParticipantQos::default(),
                group_test_config(),
            )
            .expect("participant");
        let topic = participant
            .create_topic::<crate::interop::ShapeType>(
                "GroupPresentationOffer",
                crate::TopicQos::default(),
            )
            .expect("topic");
        let publisher = participant.create_publisher(crate::PublisherQos {
            presentation: presentation(S::Group, false, false),
            ..crate::PublisherQos::default()
        });
        let writer = publisher
            .create_datawriter::<crate::interop::ShapeType>(&topic, crate::DataWriterQos::default())
            .expect("writer");
        let (rt, eid) = writer.runtime_handle().expect("live writer");

        let sub = group_remote_sub(
            "GroupPresentationOffer",
            <crate::interop::ShapeType as crate::dds_type::DdsType>::TYPE_NAME,
            presentation(S::Topic, false, false),
            alloc::vec![],
        );
        let now = rt.start_instant.elapsed();
        {
            let mut sedp = rt.sedp.lock().expect("sedp");
            sedp.cache_mut().insert_subscription(sub, now);
        }
        rt.match_local_writer_against_cache(eid);

        assert_eq!(
            rt.user_writer_matched_count(eid),
            1,
            "the Publisher's GROUP scope must reach the announcement, \
             otherwise the default INSTANCE loses against the requested TOPIC"
        );
        assert_eq!(rt.user_writer_offered_incompatible_qos(eid).total_count, 0);
    }

    /// §2.2.3.6 the other way round: a TOPIC-scope Subscriber requests TOPIC,
    /// a remote writer offers INSTANCE — INSTANCE < TOPIC, so no match and
    /// `REQUESTED_INCOMPATIBLE_QOS` names PRESENTATION. Announcing the
    /// `DataReaderQos` default (INSTANCE) instead would match silently.
    #[test]
    fn presentation_from_subscriber_is_what_the_reader_requests() {
        use zerodds_qos::PresentationAccessScope as S;
        let domain_lease = zerodds_test_domains::lease_domain();
        let participant = crate::DomainParticipantFactory::instance()
            .create_participant_with_config(
                domain_lease.id(),
                crate::DomainParticipantQos::default(),
                group_test_config(),
            )
            .expect("participant");
        let topic = participant
            .create_topic::<crate::interop::ShapeType>(
                "GroupPresentationRequest",
                crate::TopicQos::default(),
            )
            .expect("topic");
        let subscriber = participant.create_subscriber(crate::SubscriberQos {
            presentation: presentation(S::Topic, false, true),
            ..crate::SubscriberQos::default()
        });
        let reader = subscriber
            .create_datareader::<crate::interop::ShapeType>(&topic, crate::DataReaderQos::default())
            .expect("reader");
        let (rt, eid) = reader.runtime_handle().expect("live reader");

        let pubd = group_remote_pub(
            "GroupPresentationRequest",
            <crate::interop::ShapeType as crate::dds_type::DdsType>::TYPE_NAME,
            presentation(S::Instance, false, true),
            alloc::vec![],
        );
        let now = rt.start_instant.elapsed();
        {
            let mut sedp = rt.sedp.lock().expect("sedp");
            sedp.cache_mut().insert_publication(pubd, now);
        }
        rt.match_local_reader_against_cache(eid);

        let status = rt.user_reader_requested_incompatible_qos(eid);
        assert_eq!(
            rt.user_reader_matched_count(eid),
            0,
            "offered INSTANCE < requested TOPIC must not match"
        );
        assert!(status.total_count >= 1);
        assert_eq!(
            status.last_policy_id,
            crate::psm_constants::qos_policy_id::PRESENTATION
        );
    }

    /// The `coherent_access`/`ordered_access` flags travel with the same
